function ngApplyTeachingAccessReconciliation(db = {}, {
  dryRun = false,
  source = "lms_database_write",
  updateState = true,
} = {}) {
  const result = reconcileConfirmedTeachingPlanAccess(db, {
    dryRun,
    source,
  });
  const publicResult = ngPublicTeachingAccessReconciliation(result);

  if (updateState) {
    ngTeachingAccessReconciliationState.last_result = publicResult;
    if (
      publicResult.plans_updated > 0
      || publicResult.enrollments_updated > 0
      || publicResult.auto_expired_restored > 0
    ) {
      ngTeachingAccessReconciliationState.last_material_result = publicResult;
    }
  }

  return result;
}

async function writeLiveDb(db, { teachingAccessSource = "lms_database_write" } = {}) {
  const task = writeQueue
    .catch((error) => {
      console.error("Previous LMS write failed; queue recovered:", error.message);
    })
    .then(async () => {
    await ensureDataDir();
    const teachingAccess = ngApplyTeachingAccessReconciliation(db, {
      source: teachingAccessSource,
    });
    const nextDb = {
      ...DEFAULT_LIVE_DB,
      ...db,
      featureCatalog: { ...DEFAULT_FEATURE_CATALOG, ...(db.featureCatalog || {}) },
      demoSettings: { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) },
      emailSettings: { ...DEFAULT_EMAIL_SETTINGS, ...(db.emailSettings || {}) },
      emailTemplates: ngMergeEmailTemplates(db.emailTemplates || {}),
      emailLogs: safeArray(db.emailLogs),
      emailBroadcasts: safeArray(db.emailBroadcasts),
      emailAutomationState: db.emailAutomationState || {},
      updatedAt: new Date().toISOString(),
    };
    await ngWriteJsonAtomicStreaming(LIVE_DB_PATH, nextDb, "LMS database");
    liveDbCache = nextDb;
    liveDbReadInFlight = null;
    return teachingAccess;
  });
  writeQueue = task;
  return task;
}

async function mutateLiveDb(mutator, { teachingAccessSource = "lms_atomic_database_write" } = {}) {
  const task = writeQueue
    .catch((error) => {
      console.error("Previous LMS write failed; atomic mutation queue recovered:", error.message);
    })
    .then(async () => {
      const source = liveDbCache || await readLiveDbFromDisk();
      const mutation = await mutateJsonCopyOnWrite(source, mutator);
      const current = mutation.value;
      ngApplyTeachingAccessReconciliation(current, {
        source: teachingAccessSource,
      });
      const nextDb = {
        ...DEFAULT_LIVE_DB,
        ...current,
        featureCatalog: { ...DEFAULT_FEATURE_CATALOG, ...(current.featureCatalog || {}) },
        demoSettings: { ...DEFAULT_DEMO_SETTINGS, ...(current.demoSettings || {}) },
        emailSettings: { ...DEFAULT_EMAIL_SETTINGS, ...(current.emailSettings || {}) },
        emailTemplates: ngMergeEmailTemplates(current.emailTemplates || {}),
        emailLogs: safeArray(current.emailLogs),
        emailBroadcasts: safeArray(current.emailBroadcasts),
        emailAutomationState: current.emailAutomationState || {},
        updatedAt: new Date().toISOString(),
      };
      await ensureDataDir();
      await ngWriteJsonAtomicStreaming(LIVE_DB_PATH, nextDb, "LMS atomic database mutation");
      liveDbCache = nextDb;
      liveDbReadInFlight = null;
      return mutation.result;
    });
  writeQueue = task;
  return task;
}

async function ngRunTeachingAccessStartupReconciliation() {
  if (ngTeachingAccessReconciliationState.running) {
    return ngTeachingAccessReconciliationState.last_result;
  }

  const startedAt = new Date().toISOString();
  ngTeachingAccessReconciliationState.running = true;
  ngTeachingAccessReconciliationState.last_started_at = startedAt;
  ngTeachingAccessReconciliationState.last_error = null;

  try {
    const db = await readLiveDb();
    const result = ngApplyTeachingAccessReconciliation(db, {
      source: "startup_teaching_access_reconciliation",
    });
    if (result.changed) {
      await writeLiveDb(db, {
        teachingAccessSource: "startup_teaching_access_reconciliation_persist",
      });
    }
    ngTeachingAccessReconciliationState.last_success_at = new Date().toISOString();
    return ngPublicTeachingAccessReconciliation(result);
  } catch (error) {
    ngTeachingAccessReconciliationState.last_error = error.message;
    throw error;
  } finally {
    ngTeachingAccessReconciliationState.running = false;
    ngTeachingAccessReconciliationState.last_finished_at = new Date().toISOString();
  }
}

async function ngRunSessionNotesStartupReconciliation() {
  if (ngSessionNotesReconciliationState.running) {
    return ngSessionNotesReconciliationState.last_result;
  }

  ngSessionNotesReconciliationState.running = true;
  ngSessionNotesReconciliationState.last_started_at = new Date().toISOString();
  ngSessionNotesReconciliationState.last_error = null;

  try {
    const db = await readLiveDb();
    const result = reconcileLmsSessionNoteInvariants(db, {
      autoPublish: lmsAutoPublishSessionNotesEnabled(),
    });

    for (const sessionId of result.session_ids || []) {
      const note = db.notes?.[sessionId] || Object.values(db.notes || {}).find((item) => (
        String(item?.session_id || "") === String(sessionId)
      ));
      const session = db.liveSessions?.[sessionId] || null;
      const day = session ? ngFindRoadmapDayForLiveSession(db, session) : null;
      const published = Boolean(
        note &&
        (note.published === true || note.is_published === true) &&
        !["draft", "unpublished", "archived", "hidden"].includes(String(note.status || "").trim().toLowerCase())
      );

      if (day && published) {
        day.session_notes_id = sessionId;
        day.session_notes_draft_ready = true;
        day.session_notes_ready = true;
        day.notes_status = "published";
        ngEnsureTaskItemOnDay(day, "read_session_notes", "Read the session notes after class.");
      }
    }

    if (result.changed) {
      await writeLiveDb(db, {
        teachingAccessSource: "startup_session_notes_reconciliation",
      });
    }

    ngSessionNotesReconciliationState.last_result = result;
    ngSessionNotesReconciliationState.last_success_at = new Date().toISOString();
    return result;
  } catch (error) {
    ngSessionNotesReconciliationState.last_error = error.message;
    throw error;
  } finally {
    ngSessionNotesReconciliationState.running = false;
    ngSessionNotesReconciliationState.last_finished_at = new Date().toISOString();
  }
}

