app.get("/admin/enrollments", async (req, res) => {
  try {
    await requireAdmin(req);
    const db = await readLiveDb();
    let enrollments = Object.values(db.enrollments || {}).map((item) => sanitizeAdminEnrollment(item, db));

    if (req.query.course_id) {
      enrollments = enrollments.filter((item) => String(item.course_id) === String(req.query.course_id));
    }

    if (req.query.status) {
      enrollments = enrollments.filter((item) => String(item.status) === String(req.query.status));
    }

    if (req.query.type) {
      enrollments = enrollments.filter((item) => String(item.type) === String(req.query.type));
    }

    enrollments.sort(sortNewestFirst);

    res.json({
      success: true,
      count: enrollments.length,
      enrollments,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to load enrollments",
    });
  }
});

app.get("/admin/enrollments/access-priority-audit", async (req, res) => {
  try {
    await requireAdmin(req);
    const db = await readLiveDb();
    const requestedEmail = normalizeEmail(req.query.email || "");
    const rows = [];

    const pairs = new Map();
    for (const enrollment of Object.values(db.enrollments || {})) {
      if (!enrollment?.user_id || !enrollment?.course_id) continue;
      const user = db.users?.[String(enrollment.user_id)] || null;
      if (requestedEmail && normalizeEmail(user?.email) !== requestedEmail) continue;
      const key = `${enrollment.user_id}:${enrollment.course_id}`;
      pairs.set(key, { userId: enrollment.user_id, courseId: enrollment.course_id, user });
    }

    for (const pair of pairs.values()) {
      const resolved = ngResolveCourseAccessRecord(db, { id: pair.userId }, pair.courseId);
      const paidCandidates = ngFindCourseEnrollmentCandidates(db, { userId: pair.userId, courseId: pair.courseId, type: "paid" });
      const demoCandidates = ngFindCourseEnrollmentCandidates(db, { userId: pair.userId, courseId: pair.courseId, type: "demo" });
      if (!paidCandidates.length || !demoCandidates.length) continue;

      rows.push({
        user_id: pair.userId,
        email: pair.user?.email || "",
        name: pair.user?.name || "Student",
        course_id: pair.courseId,
        course_name: db.courses?.[String(pair.courseId)]?.name || "Course",
        resolved_status: resolved.status,
        resolved_enrollment_id: resolved.enrollment?.id || null,
        paid: paidCandidates.map(({ storageKey, enrollment }) => ({
          storage_key: storageKey,
          id: enrollment.id,
          access_granted: enrollment.access_granted !== false,
          active: isPaidEnrollmentActive(enrollment, enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null, db),
          plan_id: enrollment.plan_id || null,
          access_expires_at: ngPaidAccessExpiresAt(
            enrollment,
            enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null,
            db,
          )?.toISOString() || null,
        })),
        demo: demoCandidates.map(({ storageKey, enrollment }) => ({
          storage_key: storageKey,
          id: enrollment.id,
          access_granted: enrollment.access_granted !== false,
          active: isDemoEnrollmentActive(enrollment, { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) }),
          demo_expiry: enrollment.demo_expiry || null,
        })),
      });
    }

    res.json({
      success: true,
      build: NEXTGEN_BACKEND_BUILD,
      count: rows.length,
      rows,
      read_only: true,
      message: "Active paid access always wins; otherwise an active demo wins before expired/revoked history.",
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/enrollments", async (req, res) => {
  try {
    await requireAdmin(req);
    const db = await readLiveDb();

    const courseId = String(req.body.course_id || "").trim();
    const email = normalizeEmail(req.body.email || req.body.student_email || req.body.user_email);
    const name = String(req.body.name || req.body.student_name || "Student").trim();
    const isDemo = Boolean(req.body.is_demo || req.body.type === "demo");

    if (!courseId) return res.status(400).json({ success: false, error: "course_id is required" });
    if (!email && !req.body.user_id) return res.status(400).json({ success: false, error: "Student email or user_id is required" });
    if (!db.courses[courseId]) return res.status(404).json({ success: false, error: "Course not found" });

    let user = req.body.user_id ? db.users[String(req.body.user_id)] : findUserByEmail(db, email);
    let studentWasCreated = false;
    let temporaryPassword = "";

    if (!user) {
      temporaryPassword = ngGenerateTemporaryPassword();
      user = createBackendUser({
        email,
        name: name || email.split("@")[0],
        password: temporaryPassword,
        role: "student",
      });
      user.must_change_password = true;
      db.users[user.id] = user;
      studentWasCreated = true;
    } else if (req.body.force_password_reset === true || req.body.reset_password === true) {
      temporaryPassword = ngGenerateTemporaryPassword();
      const hashed = hashPassword(temporaryPassword);
      user.salt = hashed.salt;
      user.password_hash = hashed.password_hash;
      user.must_change_password = true;
      user.updated_at = nowIso();
      db.users[user.id] = user;
    }

    const resolvedPaidPlan = !isDemo && req.body.access_granted !== false
      ? ngResolveAdminPaidPlan(db, { courseId, requestedPlanId: req.body.plan_id || "" })
      : null;

    if (!isDemo && req.body.access_granted !== false && !resolvedPaidPlan) {
      return res.status(400).json({
        success: false,
        error: "A paid enrollment requires an active paid plan. Create/activate a plan first.",
      });
    }

    const enrollment = createBackendEnrollment(db, {
      userId: user.id,
      userName: user.name || name || user.email || "Student",
      courseId,
      isDemo,
      accessGranted: req.body.access_granted !== false,
      demoExpiry: req.body.demo_expiry || null,
      planId: resolvedPaidPlan?.id || null,
    });

    if (!isDemo && enrollment.access_granted !== false) {
      const plan = resolvedPaidPlan || (enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null);
      if (plan) {
        enrollment.plan_id = plan.id;
        if (!enrollment.access_expires_at) {
          ngApplyPaidAccessWindow(db, enrollment, {
            plan,
            paidAt: new Date().toISOString(),
            source: "admin_manual_enrollment",
          });
        }
      }
    }

    if (req.body.progress_percentage !== undefined) {
      enrollment.progress_percentage = Number(req.body.progress_percentage || 0) || 0;
    }

    enrollment.updated_at = new Date().toISOString();
    db.enrollments[enrollment.id] = enrollment;

    let credentialEmail = { attempted: false, sent: false, skipped: true, reason: "send_credentials_disabled" };
    if (req.body.send_credentials !== false) {
      credentialEmail = await ngSendStudentAccessEmailSafe({
        db,
        req,
        user,
        enrollment,
        course: db.courses[courseId],
        temporaryPassword,
        reason: studentWasCreated ? "admin_enrollment_new_student" : temporaryPassword ? "admin_enrollment_password_reset" : "admin_enrollment_existing_student",
      });
    }

    await writeLiveDb(db);

    res.json({
      success: true,
      enrollment: sanitizeAdminEnrollment(enrollment, db),
      created: true,
      student_created: studentWasCreated,
      credentials_email: credentialEmail,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to create enrollment",
    });
  }
});

app.patch("/admin/enrollments/:enrollmentId", async (req, res) => {
  try {
    await requireAdmin(req);
    const db = await readLiveDb();
    let enrollment = findEnrollmentById(db, req.params.enrollmentId);

    if (!enrollment) {
      return res.status(404).json({ success: false, error: "Enrollment not found" });
    }

    const now = new Date().toISOString();
    const requestedStatus = String(req.body.status || req.body.access_status || "").trim().toLowerCase();
    const demoSettings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };

    // v190n: Converting a demo card to paid access must create/update the canonical
    // :paid record. The original demo record remains untouched as history. This
    // prevents paid access from being stored under a :demo key and then ignored by
    // student access checks when the demo expires.
    if (["active", "paid", "approved"].includes(requestedStatus)) {
      const paidKey = backendEnrollmentKey(enrollment.course_id, enrollment.user_id, "paid");
      if (String(enrollment.id) !== String(paidKey)) {
        const sourceEnrollment = enrollment;
        const existingPaid = db.enrollments?.[paidKey] || {};
        enrollment = {
          ...existingPaid,
          id: paidKey,
          backend_owned: true,
          user_id: sourceEnrollment.user_id,
          user_name: sourceEnrollment.user_name || existingPaid.user_name || "Student",
          course_id: sourceEnrollment.course_id,
          plan_id: existingPaid.plan_id || sourceEnrollment.plan_id || null,
          access_granted: existingPaid.access_granted !== false,
          is_demo: false,
          demo_expiry: null,
          progress_percentage: Number(existingPaid.progress_percentage ?? sourceEnrollment.progress_percentage ?? 0) || 0,
          created_at: existingPaid.created_at || new Date().toISOString(),
          updated_at: new Date().toISOString(),
          canonicalized_from_enrollment_id: sourceEnrollment.id,
          canonicalized_at: new Date().toISOString(),
        };
        db.enrollments[paidKey] = enrollment;
      }
    }

    // v171: Admin Enrollments UI sends { status } from the dropdown.
    // Older backend builds ignored that field, so "Save Access" appeared to work
    // but the record stayed revoked/expired because access_granted was unchanged.
    // Interpret status as the source of truth while still supporting explicit fields.
    if (requestedStatus) {
      if (["active", "paid", "approved"].includes(requestedStatus)) {
        enrollment.is_demo = false;
        enrollment.access_granted = true;
        enrollment.revoked_at = null;
        enrollment.revoked_reason = null;
        enrollment.paid_at = enrollment.paid_at || now;
        enrollment.access_starts_at = enrollment.access_starts_at || now;

        const plan = ngResolveAdminPaidPlan(db, {
          courseId: enrollment.course_id,
          requestedPlanId: req.body.plan_id || enrollment.plan_id || "",
        });

        if (!plan) {
          return res.status(400).json({
            success: false,
            error: "A paid enrollment requires an active paid plan. Create/activate a plan first.",
          });
        }

        enrollment.plan_id = plan.id;
        if (!enrollment.access_expires_at) {
          ngApplyPaidAccessWindow(db, enrollment, {
            plan,
            paidAt: enrollment.paid_at || now,
            source: "admin_enrollment_status_patch",
          });
        }
      } else if (requestedStatus === "demo_active") {
        enrollment.is_demo = true;
        enrollment.access_granted = true;
        enrollment.revoked_at = null;
        enrollment.revoked_reason = null;
        const days = Math.max(1, Number(demoSettings.duration_days || 7));
        enrollment.demo_expiry = req.body.demo_expiry || req.body.expires_at || new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString();
      } else if (requestedStatus === "demo_expired") {
        enrollment.is_demo = true;
        enrollment.access_granted = true;
        enrollment.demo_expiry = req.body.demo_expiry || req.body.expires_at || new Date(Date.now() - 60 * 1000).toISOString();
      } else if (requestedStatus === "expired") {
        enrollment.is_demo = false;
        enrollment.access_granted = true;
        enrollment.access_expires_at = req.body.access_expires_at || req.body.expires_at || new Date(Date.now() - 60 * 1000).toISOString();
        enrollment.renewal_due_at = enrollment.access_expires_at;
      } else if (["pending", "inactive", "cancelled", "canceled", "revoked"].includes(requestedStatus)) {
        enrollment.access_granted = false;
        enrollment.revoked_at = enrollment.revoked_at || now;
        enrollment.revoked_reason = req.body.revoked_reason || req.body.reason || `admin_set_${requestedStatus}`;
      }
    }

    if (req.body.access_granted !== undefined) enrollment.access_granted = Boolean(req.body.access_granted);
    if (req.body.is_active !== undefined) enrollment.access_granted = Boolean(req.body.is_active);
    if (req.body.is_demo !== undefined) enrollment.is_demo = Boolean(req.body.is_demo);
    if (req.body.demo_expiry !== undefined) enrollment.demo_expiry = req.body.demo_expiry || null;
    if (req.body.plan_id !== undefined) {
      if (req.body.plan_id) {
        const selectedPlan = ngResolveAdminPaidPlan(db, {
          courseId: enrollment.course_id,
          requestedPlanId: req.body.plan_id,
        });
        enrollment.plan_id = selectedPlan.id;
      } else if (enrollment.is_demo === true || enrollment.access_granted === false) {
        enrollment.plan_id = null;
      }
    }
    if (req.body.paid_at !== undefined) enrollment.paid_at = req.body.paid_at || null;
    if (req.body.access_starts_at !== undefined) enrollment.access_starts_at = req.body.access_starts_at || null;
    if (req.body.access_expires_at !== undefined) { enrollment.access_expires_at = req.body.access_expires_at || null; enrollment.renewal_due_at = enrollment.access_expires_at; }
    if (req.body.access_days !== undefined) enrollment.access_days = req.body.access_days ? Number(req.body.access_days) : null;

    if (enrollment.access_granted !== false) {
      enrollment.revoked_at = null;
      enrollment.revoked_reason = null;
    }

    if (enrollment.is_demo !== true && enrollment.access_granted !== false && req.body.access_expires_at === undefined) {
      const plan = ngResolveAdminPaidPlan(db, {
        courseId: enrollment.course_id,
        requestedPlanId: enrollment.plan_id || "",
      });

      if (!plan) {
        return res.status(400).json({
          success: false,
          error: "A paid enrollment requires an active paid plan. Create/activate a plan first.",
        });
      }

      enrollment.plan_id = plan.id;
      if (!enrollment.access_expires_at) {
        ngApplyPaidAccessWindow(db, enrollment, {
          plan,
          paidAt: enrollment.paid_at || now,
          source: "admin_enrollment_patch",
        });
      }
      enrollment.paid_at = enrollment.paid_at || now;
      enrollment.access_starts_at = enrollment.access_starts_at || now;
    }

    if (req.body.progress_percentage !== undefined) enrollment.progress_percentage = Number(req.body.progress_percentage || 0) || 0;
    if (req.body.user_name !== undefined || req.body.student_name !== undefined || req.body.name !== undefined) {
      enrollment.user_name = String(req.body.user_name || req.body.student_name || req.body.name || enrollment.user_name || "Student").trim();
    }

    enrollment.updated_at = now;
    db.enrollments[enrollment.id] = enrollment;

    await writeLiveDb(db);

    res.json({
      success: true,
      enrollment: sanitizeAdminEnrollment(enrollment, db),
      source: "admin_enrollment_status_patch_v171",
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to update enrollment",
    });
  }
});
