app.patch("/admin/payments/:paymentId", async (req, res) => {
  try {
    await requireAdmin(req);
    const db = await readLiveDb();
    db.payments = db.payments || {};
    const payment = db.payments[String(req.params.paymentId)];

    if (!payment) {
      return res.status(404).json({ success: false, error: "Payment not found" });
    }

    const allowed = ["status", "payment_status", "amount_cents", "currency", "metadata", "paid_at", "stripe_payment_intent", "failure_message"];
    for (const key of allowed) {
      if (req.body[key] !== undefined) payment[key] = req.body[key];
    }

    if (payment.amount_cents !== undefined) payment.amount_cents = Number(payment.amount_cents || 0) || 0;
    payment.updated_at = new Date().toISOString();

    db.payments[payment.id] = payment;
    await writeLiveDb(db);

    res.json({
      success: true,
      payment: sanitizePayment(payment, db),
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to update payment",
    });
  }
});

function ngBuildBillingIssues(db = {}) {
  const payments = buildDerivedPayments(db);
  const enrollments = Object.values(db.enrollments || {}).map((item) => sanitizeAdminEnrollment(item, db));
  const byEnrollmentId = Object.fromEntries(enrollments.map((item) => [String(item.id), item]));
  const issues = [];
  const now = Date.now();

  for (const payment of payments) {
    const status = String(payment.status || payment.payment_status || "").toLowerCase();
    const enrollment = payment.enrollment_id ? byEnrollmentId[String(payment.enrollment_id)] : null;
    const ageMinutes = payment.created_at ? Math.round((now - new Date(payment.created_at).getTime()) / 60000) : null;
    const amount = Number(payment.amount_cents || 0);
    const method = String(payment.payment_method || "").toLowerCase();

    if (status === "pending" && method === "stripe" && ageMinutes !== null && ageMinutes >= 30) {
      issues.push({ severity: "warning", type: "stripe_pending_30m", message: "Stripe checkout is pending for more than 30 minutes; student should remain blocked unless Stripe shows paid.", payment, enrollment, age_minutes: ageMinutes });
    }

    if (["completed", "paid", "succeeded"].includes(status) && amount > 0 && !enrollment) {
      issues.push({ severity: "critical", type: "completed_payment_no_enrollment", message: "Paid payment exists but no enrollment is attached.", payment });
    }

    if (["completed", "paid", "succeeded"].includes(status) && amount > 0 && enrollment && enrollment.access_granted === false) {
      issues.push({ severity: "critical", type: "completed_payment_access_blocked", message: "Paid payment exists but enrollment access is revoked/blocked.", payment, enrollment });
    }
  }

  for (const enrollment of enrollments) {
    if (enrollment.type !== "paid") continue;
    const raw = db.enrollments?.[String(enrollment.id)] || null;
    const plan = raw?.plan_id ? db.plans?.[String(raw.plan_id)] || null : null;
    if (raw?.access_granted !== false && !isPaidEnrollmentActive(raw, plan, db)) {
      issues.push({ severity: "critical", type: "paid_access_expired_but_not_revoked", message: "Paid access expiry date has passed but access_granted is still true.", enrollment });
    }
  }

  return {
    success: true,
    ok: issues.filter((item) => item.severity === "critical").length === 0,
    build: NEXTGEN_BACKEND_BUILD,
    stripe_secret_configured: Boolean(process.env.STRIPE_SECRET_KEY),
    stripe_webhook_secret_configured: Boolean(process.env.STRIPE_WEBHOOK_SECRET),
    email_configured: Boolean(process.env.RESEND_API_KEY || process.env.SENDGRID_API_KEY || (process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS)),
    counts: { payments: payments.length, enrollments: enrollments.length, issues: issues.length },
    issues,
  };
}

async function ngSendBillingNoticeSafe({ db, user, enrollment, course, subject, text, reason }) {
  const result = { attempted: true, sent: false, error: null, reason };
  try {
    if (!user?.email) throw new Error("Student email is missing");
    const provider = await sendEmailMessage({ to: user.email, subject, text });
    result.sent = true;
    result.provider = provider?.provider || provider?.messageId || provider?.id || "email";
    ngLogStudentEmail(db, { to: user.email, subject, status: "sent", provider_response: provider, reason, user_id: user.id, enrollment_id: enrollment?.id || null });
  } catch (error) {
    result.error = error.message;
    ngLogStudentEmail(db, { to: user?.email || "", subject, status: "failed", error: error.message, reason, user_id: user?.id || null, enrollment_id: enrollment?.id || null });
  }
  return result;
}

async function ngRunPaidAccessExpiryCheck({ db, dryRun = false, sendEmails = true, source = "manual" } = {}) {
  const now = new Date();
  const result = { source, dry_run: dryRun, checked: 0, reminders: [], revoked: [], changed: false };
  const teachingAccess = ngApplyTeachingAccessReconciliation(db, {
    dryRun,
    source: `${source}_pre_expiry_protection`,
    updateState: !dryRun,
  });
  result.teaching_access = ngPublicTeachingAccessReconciliation(teachingAccess);
  if (teachingAccess.changed) result.changed = true;

  for (const enrollment of Object.values(db.enrollments || {})) {
    if (!enrollment?.id || enrollment.is_demo === true) continue;
    const plan = enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null;
    if (enrollment.access_granted === false && !isPaidEnrollmentActive(enrollment, plan, db)) continue;
    const expiresAt = ngPaidAccessExpiresAt(enrollment, plan, db);
    if (!expiresAt) continue;
    result.checked += 1;
    const days = Math.ceil((expiresAt.getTime() - now.getTime()) / (24 * 60 * 60 * 1000));
    const user = db.users?.[String(enrollment.user_id)] || null;
    const course = enrollment.course_id ? db.courses?.[String(enrollment.course_id)] || null : null;
    enrollment.billing_notifications_sent = enrollment.billing_notifications_sent || {};

    for (const target of [7, 3, 1]) {
      const key = `renewal_${target}_days`;
      if (days === target && !enrollment.billing_notifications_sent[key]) {
        result.reminders.push({ enrollment_id: enrollment.id, days_remaining: target, user_email: user?.email || "" });
        if (!dryRun) {
          if (sendEmails) {
            await ngSendConfiguredEmailSafe({
              db,
              templateKey: "subscription_expiring",
              to: user?.email,
              variables: ngEmailBaseVariables(db, user || {}, {
                course_name: course?.name || "",
                course_phrase: ngEmailCoursePhrase(course?.name || ""),
                days_remaining: target,
                days_suffix: target === 1 ? "" : "s",
                expiry_date: dateOnly(expiresAt),
              }),
              reason: key,
              userId: user?.id || null,
              enrollmentId: enrollment?.id || null,
            });
          }
          enrollment.billing_notifications_sent[key] = new Date().toISOString();
          enrollment.updated_at = new Date().toISOString();
          db.enrollments[enrollment.id] = enrollment;
          result.changed = true;
        }
      }
    }

    if (expiresAt.getTime() < now.getTime()) {
      result.revoked.push({ enrollment_id: enrollment.id, user_email: user?.email || "", expired_at: expiresAt.toISOString() });
      if (!dryRun) {
        enrollment.access_granted = false;
        enrollment.revoked_at = new Date().toISOString();
        enrollment.revoked_reason = "access_expired";
        enrollment.updated_at = new Date().toISOString();
        db.enrollments[enrollment.id] = enrollment;
        result.changed = true;
        if (sendEmails && !enrollment.billing_notifications_sent.access_expired) {
          await ngSendConfiguredEmailSafe({
            db,
            templateKey: "subscription_expired",
            to: user?.email,
            variables: ngEmailBaseVariables(db, user || {}, {
              course_name: course?.name || "",
              course_phrase: ngEmailCoursePhrase(course?.name || ""),
              expiry_date: dateOnly(expiresAt),
            }),
            reason: "access_expired",
            userId: user?.id || null,
            enrollmentId: enrollment?.id || null,
          });
          enrollment.billing_notifications_sent.access_expired = new Date().toISOString();
        }
      }
    }
  }

  return result;
}


async function ngRunDemoEmailLifecycleCheck({ db, source = "automatic_runner" } = {}) {
  const settings = ngGetEmailSettings(db);
  db.emailAutomationState = db.emailAutomationState || {};
  const result = { source, checked: 0, expiring: 0, expired: 0, changed: false };
  const now = Date.now();
  const expiringDays = Math.max(1, Number(settings.demo_expiring_days || 1));

  for (const enrollment of Object.values(db.enrollments || {})) {
    if (!enrollment?.id || enrollment.is_demo !== true || !enrollment.demo_expiry) continue;
    result.checked += 1;

    const expiry = getDemoExpiryDateTime(enrollment.demo_expiry);
    if (!expiry) continue;

    const user = db.users?.[String(enrollment.user_id)] || null;
    if (!user?.email) continue;

    const course = enrollment.course_id
      ? db.courses?.[String(enrollment.course_id)] || null
      : null;
    const remainingMs = expiry.getTime() - now;
    const daysRemaining = Math.max(0, Math.ceil(remainingMs / (24 * 60 * 60 * 1000)));

    if (remainingMs > 0 && daysRemaining <= expiringDays) {
      const stateKey = `demo_expiring:${enrollment.id}:${enrollment.demo_expiry}`;
      if (!db.emailAutomationState[stateKey]) {
        const send = await ngSendConfiguredEmailSafe({
          db,
          templateKey: "demo_expiring",
          to: user.email,
          variables: ngEmailBaseVariables(db, user, {
            course_name: course?.name || "",
            course_phrase: ngEmailCoursePhrase(course?.name || ""),
            days_remaining: Math.max(1, daysRemaining),
            days_suffix: Math.max(1, daysRemaining) === 1 ? "" : "s",
            expiry_date: enrollment.demo_expiry,
          }),
          reason: "demo_expiring",
          userId: user.id,
          enrollmentId: enrollment.id,
        });

        if (send.sent) {
          db.emailAutomationState[stateKey] = {
            sent_at: new Date().toISOString(),
            template_key: "demo_expiring",
            user_id: user.id,
            enrollment_id: enrollment.id,
          };
          result.expiring += 1;
          result.changed = true;
        }
      }
    }

    if (remainingMs <= 0) {
      const stateKey = `demo_expired:${enrollment.id}:${enrollment.demo_expiry}`;
      if (!db.emailAutomationState[stateKey]) {
        const send = await ngSendConfiguredEmailSafe({
          db,
          templateKey: "demo_expired",
          to: user.email,
          variables: ngEmailBaseVariables(db, user, {
            course_name: course?.name || "",
            course_phrase: ngEmailCoursePhrase(course?.name || ""),
            expiry_date: enrollment.demo_expiry,
          }),
          reason: "demo_expired",
          userId: user.id,
          enrollmentId: enrollment.id,
        });

        if (send.sent) {
          db.emailAutomationState[stateKey] = {
            sent_at: new Date().toISOString(),
            template_key: "demo_expired",
            user_id: user.id,
            enrollment_id: enrollment.id,
          };
          result.expired += 1;
          result.changed = true;
        }
      }
    }
  }

  return result;
}

function ngFormatSessionEtTime(session = {}) {
  const timezone =
    session.scheduled_timezone ||
    session.timezone ||
    session.timezone_str ||
    DEFAULT_TIMEZONE;
  const start = getSessionStartUtc(
    session.scheduled_date,
    session.scheduled_time,
    timezone
  );

  if (!start) {
    return {
      start: null,
      date: session.scheduled_date || "",
      time: session.scheduled_time || "",
    };
  }

  const date = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(start);
  const time = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    hour: "numeric",
    minute: "2-digit",
    timeZoneName: "short",
  })
    .format(start)
    .replace("EDT", "ET")
    .replace("EST", "ET");

  return { start, date, time };
}

async function ngRunLiveClassReminderCheck({ db, source = "automatic_runner" } = {}) {
  const settings = ngGetEmailSettings(db);
  db.emailAutomationState = db.emailAutomationState || {};
  const reminderMinutes = Math.max(
    5,
    Math.min(1440, Number(settings.live_class_reminder_minutes || 60))
  );
  const now = Date.now();
  const result = { source, checked: 0, queued: 0, changed: false };

  for (const session of Object.values(db.liveSessions || {})) {
    if (!session?.id) continue;
    if (
      session.cancelled === true ||
      ["cancelled", "canceled"].includes(String(session.status || "").toLowerCase())
    ) {
      continue;
    }

    const formatted = ngFormatSessionEtTime(session);
    if (!formatted.start) continue;

    const diffMinutes = (formatted.start.getTime() - now) / 60000;
    if (diffMinutes < 0 || diffMinutes > reminderMinutes) continue;

    result.checked += 1;
    const stateKey = `live_class_reminder:${session.id}:${session.scheduled_date}:${session.scheduled_time}`;
    if (db.emailAutomationState[stateKey]) continue;

    const course = session.course_id
      ? db.courses?.[String(session.course_id)] || null
      : null;
    const queue = ngQueueCourseTemplateEmail(db, {
      templateKey: "live_class_reminder",
      courseId: session.course_id,
      reason: "live_class_reminder",
      commonVariables: {
        class_title: session.topic || session.title || "Live Class",
        course_name: course?.name || "Course",
        class_date: formatted.date,
        class_time: formatted.time,
        live_class_url: `https://live.nextgenusmlelms.com/student/live-class/${encodeURIComponent(session.id)}`,
      },
      dedupeKey: stateKey,
      createdBy: "system",
    });

    db.emailAutomationState[stateKey] = {
      queued_at: new Date().toISOString(),
      job_id: queue.job?.id || null,
      template_key: "live_class_reminder",
    };
    result.queued += 1;
    result.changed = true;
  }

  return result;
}

