function getDemoCourseCandidates(db, body = {}) {
  const requestedIds = uniqueList([
    ...normalizeIdList(body.course_ids),
    ...normalizeIdList(body.courseIds),
    ...normalizeIdList(body.track_ids),
    ...normalizeIdList(body.trackIds),
  ]);

  const allCoursesRequested =
    body.all_courses === true ||
    body.all_tracks === true ||
    body.activate_all_demo_tracks === true ||
    body.course_scope === "all_active" ||
    body.mode === "all_courses";

  const courses = Object.values(db.courses || {}).filter((course) => {
    if (!course?.id) return false;
    if (course.status && String(course.status).toLowerCase() !== "active") return false;
    if (course.demo_access_enabled === false) return false;
    if (requestedIds.length) return requestedIds.includes(String(course.id));
    if (allCoursesRequested) return true;
    return body.course_id && String(course.id) === String(body.course_id);
  });

  return courses;
}

function enrichDemoEnrollment(enrollment, body = {}, activationSource = "demo_start") {
  if (!enrollment) return enrollment;
  enrollment.demo_source = body.source || body.demo_source || activationSource;
  enrollment.source = enrollment.source || body.source || activationSource;
  enrollment.campaign = body.campaign || body.source_campaign || enrollment.campaign || null;
  enrollment.intent = body.intent || enrollment.intent || "demo_interest";
  enrollment.demo_activation_mode = body.all_courses || body.all_tracks || body.activate_all_demo_tracks || body.course_scope === "all_active" ? "all_demo_courses" : "single_course";
  enrollment.demo_started_at = enrollment.demo_started_at || new Date().toISOString();
  enrollment.updated_at = new Date().toISOString();
  return enrollment;
}



// v177l: Demo access self-heal for students who can log in but have no course enrollment.
// Additive-only: never deletes users/payments/enrollments and never downgrades paid access.
function ngActiveDemoEnabledCourses(db = {}, requestedCourseId = null) {
  const cleanRequested = String(requestedCourseId || "").trim();
  return Object.values(db.courses || {}).filter((course) => {
    if (!course?.id) return false;
    if (cleanRequested && String(course.id) !== cleanRequested) return false;
    if (String(course.status || "active").toLowerCase() !== "active") return false;
    if (course.demo_access_enabled === false) return false;
    return true;
  });
}

function ngCourseHasPublishedBaseline(db = {}, courseId = "") {
  const cleanCourseId = String(courseId || "").trim();
  if (!cleanCourseId) return false;
  return Object.values(db.assessments || {}).some((assessment) => {
    if (String(assessment.course_id || "") !== cleanCourseId) return false;
    if (assessment.is_published === false) return false;
    const text = `${assessment.title || ""} ${assessment.source_type || ""} ${assessment.assessment_type || ""}`;
    return /baseline|diagnostic/i.test(text);
  });
}

function ngPickDemoSelfHealCourses(db = {}, { courseId = null, allCourses = false } = {}) {
  const cleanCourseId = String(courseId || "").trim();
  const candidates = ngActiveDemoEnabledCourses(db, cleanCourseId || null);
  if (cleanCourseId) return candidates;
  const sorted = candidates.sort((a, b) => {
    const aBaseline = ngCourseHasPublishedBaseline(db, a.id) ? 1 : 0;
    const bBaseline = ngCourseHasPublishedBaseline(db, b.id) ? 1 : 0;
    if (aBaseline !== bBaseline) return bBaseline - aBaseline;
    return String(b.created_at || b.updated_at || "").localeCompare(String(a.created_at || a.updated_at || ""));
  });
  return allCourses ? sorted : sorted.slice(0, 1);
}

function ngAnyActiveStudentAccess(db = {}, user = {}, { courseId = null } = {}) {
  const cleanCourseId = String(courseId || "").trim();
  const settings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };
  return Object.values(db.enrollments || {}).some((enrollment) => {
    if (String(enrollment.user_id || "") !== String(user?.id || "")) return false;
    if (cleanCourseId && String(enrollment.course_id || "") !== cleanCourseId) return false;
    if (enrollment.is_demo === true) {
      if (enrollment.access_granted === false) return false;
      const course = enrollment.course_id ? db.courses?.[String(enrollment.course_id)] || null : null;
      return course?.demo_access_enabled !== false && isDemoEnrollmentActive(enrollment, settings);
    }
    const plan = enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null;
    return isPaidEnrollmentActive(enrollment, plan, db);
  });
}

function ngMaybeSelfHealDemoEnrollment(db = {}, user = {}, options = {}) {
  const result = {
    success: true,
    changed: false,
    source: options.source || "demo_self_heal",
    reason: null,
    checked_course_ids: [],
    created_count: 0,
    reused_count: 0,
    skipped_count: 0,
    created_enrollment_ids: [],
    details: [],
  };

  if (!user?.id) {
    result.reason = "missing_user";
    return result;
  }

  if (user.role && user.role !== "student") {
    result.reason = "staff_user_skipped";
    return result;
  }

  // v190k safety: demo access must only be created by the explicit /demo/start flow
  // or an admin-approved repair. Login, signup, auth/me, feature checks, dashboard
  // reads, assessment reads, and enrollment-status reads are strictly read-only.
  const source = String(options.source || "demo_self_heal").trim().toLowerCase();
  const explicitRepairAllowed =
    options.explicitRepair === true ||
    options.explicit_repair === true ||
    source.startsWith("admin_demo_");

  if (!explicitRepairAllowed) {
    result.reason = "implicit_demo_creation_disabled";
    return result;
  }

  const settings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };
  if (settings.enabled === false) {
    result.reason = "demo_disabled";
    return result;
  }

  db.enrollments = db.enrollments || {};

  const courseId = String(options.courseId || options.course_id || "").trim();
  const allCourses = options.allCourses === true || options.all_courses === true;
  const repairExpired = options.repairExpired === true || options.repair_expired === true;
  const dryRun = options.dryRun === true || options.dry_run === true;

  if (!courseId && !allCourses && ngAnyActiveStudentAccess(db, user)) {
    result.reason = "student_already_has_active_access";
    return result;
  }

  const courses = ngPickDemoSelfHealCourses(db, { courseId, allCourses });
  result.checked_course_ids = courses.map((course) => String(course.id));

  if (!courses.length) {
    result.reason = courseId ? "course_missing_or_demo_disabled" : "no_active_demo_enabled_course";
    return result;
  }

  const demoExpiry = dateOnly(addDays(new Date(), Number(settings.duration_days || 7)));

  for (const course of courses) {
    const cleanCourseId = String(course.id);
    const paid = db.enrollments?.[backendEnrollmentKey(cleanCourseId, user.id, "paid")];
    const paidPlan = paid?.plan_id ? db.plans?.[String(paid.plan_id)] || null : null;

    if (isPaidEnrollmentActive(paid, paidPlan, db)) {
      result.skipped_count += 1;
      result.details.push({ course_id: cleanCourseId, status: "skipped_paid_active", enrollment_id: paid.id });
      continue;
    }

    const demoKey = backendEnrollmentKey(cleanCourseId, user.id, "demo");
    const demo = db.enrollments?.[demoKey] || null;

    if (demo?.access_granted !== false && demo?.is_demo === true && isDemoEnrollmentActive(demo, settings)) {
      result.reused_count += 1;
      result.details.push({ course_id: cleanCourseId, status: "already_demo_active", enrollment_id: demo.id, demo_expiry: demo.demo_expiry || null });
      continue;
    }

    if (demo?.id && !repairExpired) {
      result.skipped_count += 1;
      result.details.push({
        course_id: cleanCourseId,
        status: demo.access_granted === false ? "skipped_demo_revoked" : "skipped_demo_expired",
        enrollment_id: demo.id,
        demo_expiry: demo.demo_expiry || null,
      });
      continue;
    }

    if (dryRun) {
      result.created_count += 1;
      result.details.push({ course_id: cleanCourseId, status: "would_create_demo", demo_expiry: demoExpiry });
      continue;
    }

    const enrollment = createBackendEnrollment(db, {
      userId: user.id,
      userName: user.name || user.email || "Student",
      courseId: cleanCourseId,
      isDemo: true,
      accessGranted: true,
      demoExpiry,
    });

    enrichDemoEnrollment(enrollment, {
      source: options.source || "demo_self_heal",
      course_scope: allCourses ? "all_active" : "single_course",
      intent: "access_repair",
    }, options.source || "demo_self_heal");

    enrollment.self_healed = true;
    enrollment.self_heal_source = options.source || "demo_self_heal";
    enrollment.self_healed_at = new Date().toISOString();
    enrollment.updated_at = new Date().toISOString();
    db.enrollments[enrollment.id] = enrollment;

    result.changed = true;
    result.created_count += 1;
    result.created_enrollment_ids.push(enrollment.id);
    result.details.push({ course_id: cleanCourseId, status: demo?.id ? "repaired_demo_expired" : "created_demo", enrollment_id: enrollment.id, demo_expiry: enrollment.demo_expiry || null });
  }

  result.reason = result.changed ? "demo_enrollment_created" : "no_change_needed";
  return result;
}

function ngBuildDemoAccessAudit(db = {}, { courseId = null, includeUsersWithAnyEnrollment = false, repairExpired = false } = {}) {
  const cleanCourseId = String(courseId || "").trim();
  const courses = ngPickDemoSelfHealCourses(db, { courseId: cleanCourseId, allCourses: false });
  const course = courses[0] || null;
  const settings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };
  const rows = [];

  if (!course) {
    return {
      success: true,
      course_id: cleanCourseId || null,
      course_name: null,
      missing_count: 0,
      expired_count: 0,
      active_demo_count: 0,
      paid_count: 0,
      skipped_count: 0,
      repairable_count: 0,
      rows,
      message: cleanCourseId ? "Course missing or demo disabled" : "No active demo-enabled course found",
    };
  }

  for (const user of Object.values(db.users || {})) {
    if (!user?.id || (user.role && user.role !== "student")) continue;
    const paid = db.enrollments?.[backendEnrollmentKey(course.id, user.id, "paid")];
    const paidPlan = paid?.plan_id ? db.plans?.[String(paid.plan_id)] || null : null;
    const demo = db.enrollments?.[backendEnrollmentKey(course.id, user.id, "demo")];
    const activePaid = isPaidEnrollmentActive(paid, paidPlan, db);
    const activeDemo = demo?.access_granted !== false && demo?.is_demo === true && isDemoEnrollmentActive(demo, settings);
    const hasAnyEnrollment = Object.values(db.enrollments || {}).some((enrollment) => String(enrollment.user_id || "") === String(user.id));

    if (!includeUsersWithAnyEnrollment && hasAnyEnrollment && !paid?.id && !demo?.id) continue;

    let status = "missing_demo";
    if (activePaid) status = "paid_active";
    else if (activeDemo) status = "demo_active";
    else if (demo?.id && demo.access_granted === false) status = "demo_revoked";
    else if (demo?.id) status = "demo_expired";

    const repairable = status === "missing_demo" || (repairExpired && status === "demo_expired");
    rows.push({
      user_id: user.id,
      name: user.name || user.email || "Student",
      email: user.email || "",
      course_id: course.id,
      course_name: course.name || "Course",
      status,
      repairable,
      enrollment_id: (paid || demo)?.id || null,
      demo_expiry: demo?.demo_expiry || null,
      created_at: user.created_at || null,
    });
  }

  return {
    success: true,
    course_id: course.id,
    course_name: course.name || "Course",
    missing_count: rows.filter((row) => row.status === "missing_demo").length,
    expired_count: rows.filter((row) => row.status === "demo_expired").length,
    active_demo_count: rows.filter((row) => row.status === "demo_active").length,
    paid_count: rows.filter((row) => row.status === "paid_active").length,
    skipped_count: rows.filter((row) => row.status === "demo_revoked").length,
    repairable_count: rows.filter((row) => row.repairable).length,
    rows,
  };
}

function getDemoExpiryDateTime(demoExpiry) {
  if (!demoExpiry) return null;
  const raw = String(demoExpiry || "").trim();
  const date = raw.includes("T") ? new Date(raw) : new Date(`${raw}T23:59:59`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function buildStudentDemoStatus(db, user) {
  const settings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };
  const enrollments = Object.values(db.enrollments || {}).filter((enrollment) => String(enrollment.user_id) === String(user.id) && enrollment.access_granted !== false);

  const paidEnrollments = enrollments.filter((enrollment) => enrollment.is_demo !== true);
  const paidCourseIds = new Set(paidEnrollments.map((enrollment) => String(enrollment.course_id || "")).filter(Boolean));

  const demoEnrollments = enrollments.filter((enrollment) => {
    if (enrollment.is_demo !== true) return false;
    if (!isDemoEnrollmentActive(enrollment, settings)) return false;
    const course = enrollment.course_id ? db.courses?.[String(enrollment.course_id)] || null : null;
    if (!course) return false;
    if (course.demo_access_enabled === false) return false;
    if (paidCourseIds.has(String(course.id))) return false;
    return true;
  });

  const expiryDates = demoEnrollments
    .map((enrollment) => getDemoExpiryDateTime(enrollment.demo_expiry))
    .filter(Boolean)
    .sort((a, b) => a.getTime() - b.getTime());

  const nearestExpiry = expiryDates[0] || null;
  const secondsRemaining = nearestExpiry ? Math.max(0, Math.floor((nearestExpiry.getTime() - Date.now()) / 1000)) : 0;
  const daysRemaining = secondsRemaining ? Math.floor(secondsRemaining / 86400) : 0;
  const hoursRemaining = secondsRemaining ? Math.floor((secondsRemaining % 86400) / 3600) : 0;
  const minutesRemaining = secondsRemaining ? Math.floor((secondsRemaining % 3600) / 60) : 0;

  const courseRows = demoEnrollments.map((enrollment) => {
    const course = enrollment.course_id ? db.courses?.[String(enrollment.course_id)] || null : null;
    const expiry = getDemoExpiryDateTime(enrollment.demo_expiry);
    const courseSeconds = expiry ? Math.max(0, Math.floor((expiry.getTime() - Date.now()) / 1000)) : 0;
    return {
      enrollment_id: enrollment.id,
      course_id: enrollment.course_id || null,
      course_name: course?.name || enrollment.course_name || "Course",
      category: course?.category || null,
      course_type: course?.course_type || null,
      demo_expiry: enrollment.demo_expiry || null,
      seconds_remaining: courseSeconds,
      status: courseSeconds > 0 ? "demo_active" : "demo_expired",
    };
  });

  return {
    success: true,
    is_demo: demoEnrollments.length > 0,
    has_paid_access: paidEnrollments.length > 0,
    demo_enabled: settings.enabled !== false,
    demo_expiry: nearestExpiry ? nearestExpiry.toISOString() : null,
    seconds_remaining: secondsRemaining,
    days_remaining: daysRemaining,
    hours_remaining: hoursRemaining,
    minutes_remaining: minutesRemaining,
    courses: courseRows,
    demo_settings: settings,
    features: getStudentFeatureAccess(db, user),
    upgrade_url: "/plans",
    mentor_url: "/#contact",
    live_classroom_url: "/student/live-sessions",
  };
}

app.post("/demo/start", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const settings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };

    if (!settings.enabled) {
      return res.status(403).json({ success: false, error: "Demo access is disabled" });
    }

    const allCoursesRequested =
      req.body?.all_courses === true ||
      req.body?.all_tracks === true ||
      req.body?.activate_all_demo_tracks === true ||
      req.body?.course_scope === "all_active" ||
      req.body?.mode === "all_courses";

    const courses = getDemoCourseCandidates(db, req.body || {});

    if (!allCoursesRequested && !req.body?.course_id && !normalizeIdList(req.body?.course_ids).length) {
      return res.status(400).json({ success: false, error: "course_id is required unless all_courses is true" });
    }

    if (!courses.length) {
      return res.status(404).json({
        success: false,
        error: allCoursesRequested
          ? "No active demo-enabled courses found"
          : "Course not found or demo access is disabled for this course",
      });
    }

    const demoExpiry = dateOnly(addDays(new Date(), Number(settings.duration_days || 2)));
    const enrollments = [];
    let createdCount = 0;
    let reusedCount = 0;
    let paidCount = 0;

    for (const course of courses) {
      const courseId = String(course.id);
      const paid = db.enrollments[backendEnrollmentKey(courseId, user.id, "paid")];

      if (paid?.access_granted) {
        paidCount += 1;
        enrollments.push({
          ...paid,
          course_name: course.name || "Course",
          status: "paid",
          already_paid: true,
        });
        continue;
      }

      const existingDemo = db.enrollments[backendEnrollmentKey(courseId, user.id, "demo")];

      if (existingDemo?.access_granted && isDemoEnrollmentActive(existingDemo, settings)) {
        reusedCount += 1;
        enrichDemoEnrollment(existingDemo, req.body || {}, "website_demo_reused");
        enrollments.push({
          ...existingDemo,
          course_name: course.name || "Course",
          status: "demo_active",
          created: false,
        });
        continue;
      }

      const enrollment = createBackendEnrollment(db, {
        userId: user.id,
        userName: user.name || user.email || "Student",
        courseId,
        isDemo: true,
        accessGranted: true,
        demoExpiry,
      });

      createdCount += 1;
      enrichDemoEnrollment(enrollment, req.body || {}, "website_demo_created");
      enrollments.push({
        ...enrollment,
        course_name: course.name || "Course",
        status: "demo_active",
        created: true,
      });
    }

    let demoEmail = { attempted: false, sent: false, skipped: true, reason: "demo_not_newly_created" };
    if (createdCount > 0 && user?.email) {
      const courseNames = enrollments
        .filter((item) => item.status === "demo_active")
        .map((item) => item.course_name || "Course")
        .filter(Boolean)
        .join(", ");
      demoEmail = await ngSendConfiguredEmailSafe({
        db,
        templateKey: "demo_activated",
        to: user.email,
        variables: ngEmailBaseVariables(db, user, {
          course_name: courseNames,
          course_phrase: ngEmailCoursePhrase(courseNames),
          expiry_date: demoExpiry,
        }),
        reason: "student_demo_activated",
        userId: user.id,
        enrollmentId: enrollments[0]?.id || null,
      });
    }

    await writeLiveDb(db);

    const status = buildStudentDemoStatus(db, user);

    res.json({
      success: true,
      type: allCoursesRequested ? "all_demo_courses" : "single_course_demo",
      all_courses: allCoursesRequested,
      created: createdCount > 0,
      created_count: createdCount,
      reused_count: reusedCount,
      already_paid_count: paidCount,
      count: enrollments.length,
      enrollments,
      enrollment: enrollments[0] || null,
      demo_settings: settings,
      demo_expiry: status.demo_expiry || demoExpiry,
      demo_status: status,
      transactional_email: demoEmail,
      source: "backend",
      message: allCoursesRequested
        ? "Demo access granted for all active demo-enabled courses"
        : createdCount > 0
          ? "Demo access granted"
          : reusedCount > 0
            ? "Demo access already active"
            : "You already have full access",
    });
  } catch (e) {
    res.status(e.statusCode || e.response?.status || 500).json({
      success: false,
      error: e.response?.data?.message || e.message || "Failed to start demo",
      details: e.response?.data || null,
    });
  }
});

