function ngVerifyZoomWebhookRequest(req) {
  const secret = String(process.env.ZOOM_WEBHOOK_SECRET_TOKEN || "").trim();
  if (!secret) return { valid: false, status: 503, error: "ZOOM_WEBHOOK_SECRET_TOKEN is not configured." };
  const timestamp = String(req.headers["x-zm-request-timestamp"] || "").trim();
  const provided = String(req.headers["x-zm-signature"] || "").trim();
  const rawBody = Buffer.isBuffer(req.zoomRawBody) ? req.zoomRawBody.toString("utf8") : "";
  const timestampMs = Number(timestamp) * 1000;
  if (!timestamp || !provided || !rawBody || !Number.isFinite(timestampMs)) {
    return { valid: false, status: 401, error: "Zoom webhook signature headers are missing." };
  }
  if (Math.abs(Date.now() - timestampMs) > 5 * 60 * 1000) {
    return { valid: false, status: 401, error: "Zoom webhook timestamp is outside the allowed window." };
  }
  const expected = `v0=${crypto.createHmac("sha256", secret).update(`v0:${timestamp}:${rawBody}`).digest("hex")}`;
  const expectedBuffer = Buffer.from(expected);
  const providedBuffer = Buffer.from(provided);
  const valid = expectedBuffer.length === providedBuffer.length && crypto.timingSafeEqual(expectedBuffer, providedBuffer);
  return valid ? { valid: true } : { valid: false, status: 401, error: "Invalid Zoom webhook signature." };
}

app.post("/zoom/webhook", async (req, res) => {
  try {
    const verification = ngVerifyZoomWebhookRequest(req);
    if (!verification.valid) {
      return res.status(verification.status || 401).json({ success: false, error: verification.error });
    }
    const event = req.body.event;

    if (event === "endpoint.url_validation") {
      const plainToken = req.body.payload.plainToken;
      const encryptedToken = crypto
        .createHmac("sha256", process.env.ZOOM_WEBHOOK_SECRET_TOKEN)
        .update(plainToken)
        .digest("hex");

      return res.status(200).json({ plainToken, encryptedToken });
    }

    if (event === "recording.completed") {
      const object = req.body.payload.object;
      const meetingId = String(object.id);
      const db = await readLiveDb();

      const result = await upsertZoomRecordingFromObject({
        db,
        object,
        forceImportTranscript: true,
      });

      await writeLiveDb(db);

      return res.status(200).json({
        received: true,
        saved: true,
        meeting_id: meetingId,
        transcript_found: Boolean(result.transcriptFile),
        transcript_imported: Boolean(result.transcriptText),
        transcript_url: result.recordingPayload.transcript_url,
        session_id: result.sessionId,
        exact_session_match: result.exactMatch?.exact === true,
        exact_session_match_reason: result.exactMatch?.reason || null,
        auto_published: result.autoPublished === true,
      });
    }

    res.status(200).json({ received: true });
  } catch (e) {
    console.error("Zoom webhook error:", e.response?.data || e.message);

    // A non-2xx response lets Zoom retry temporary processing failures.
    res.status(e.statusCode || 500).json({
      success: false,
      error: e.response?.data || e.message,
    });
  }
});

app.get("/zoom/recordings", async (req, res) => {
  try {
    const token = await getZoomAccessToken();
    const to = todayKey();
    const from = todayKey(addDays(new Date(), -30));

    const response = await axios.get(
      `https://api.zoom.us/v2/users/me/recordings?from=${from}&to=${to}&page_size=100`,
      { headers: { Authorization: `Bearer ${token}` } }
    );

    const db = await readLiveDb();

    const recordings = (response.data?.meetings || []).map((meeting) => {
      const files = meeting.recording_files || [];
      const videoFile = findVideoFile(files);
      const transcriptFile = findTranscriptFile(files);
      const meetingId = String(meeting.id || "");
      const recordingUrl = videoFile?.play_url || meeting.share_url || videoFile?.download_url || null;
      const computedRecordingKey = buildRecordingStorageKey({
        meeting_id: meetingId,
        uuid: meeting.uuid,
        start_time: meeting.start_time,
        file_id: videoFile?.id,
        recording_type: videoFile?.recording_type,
        file_type: videoFile?.file_type,
        recording_url: recordingUrl,
      });
      const storedOccurrence = ngFindStoredZoomRecordingOccurrence(db, meeting);
      const recordingKey = storedOccurrence.key || computedRecordingKey;
      const saved = storedOccurrence.recording || {};
      if (saved.hidden_from_recordings === true) return null;
      const exactMatch = ngResolveExactSessionForZoomRecording(db, meeting, saved);
      const matchedSession = saved.session_id
        ? db.liveSessions?.[String(saved.session_id)] || null
        : exactMatch.exact
          ? exactMatch.session
          : null;
      const matchedDay = matchedSession ? ngFindRoadmapDayForLiveSession(db, matchedSession) : null;

      return sanitizePublicRecording({
        session_id: saved.session_id || matchedSession?.id || null,
        course_id: saved.course_id || matchedSession?.course_id || null,
        id: recordingKey,
        recording_key: recordingKey,
        meeting_id: meetingId,
        uuid: meeting.uuid,
        topic: saved.topic || matchedSession?.topic || matchedSession?.title || meeting.topic,
        corrected_topic: saved.corrected_topic || null,
        corrected_day_number: saved.corrected_day_number || null,
        corrected_system_day: saved.corrected_system_day || null,
        label_correction_locked: saved.label_correction_locked === true,
        label_correction_reason: saved.label_correction_reason || null,
        missed_holiday_date: saved.missed_holiday_date || null,
        roadmap_day_id: saved.roadmap_day_id || matchedDay?.id || matchedSession?.roadmap_day_id || null,
        day_number: saved.day_number || matchedDay?.day_number || matchedSession?.day_number || null,
        instructional_day_number: saved.instructional_day_number || matchedDay?.instructional_day_number || matchedDay?.day_number || matchedSession?.instructional_day_number || null,
        system_day: saved.system_day || matchedDay?.system_day || matchedDay?.day_in_system || matchedSession?.system_day || null,
        system: saved.system || matchedDay?.system || matchedSession?.system || null,
        start_time: meeting.start_time,
        duration: meeting.duration,
        share_url: meeting.share_url,
        recording_url: recordingUrl,
        download_url: videoFile?.download_url || null,
        transcript_url: saved.transcript_url || transcriptFile?.play_url || transcriptFile?.download_url || null,
        transcript_download_url: saved.transcript_download_url || transcriptFile?.download_url || null,
        transcript_imported: saved.transcript_imported,
        file_type: videoFile?.file_type || null,
        recording_type: videoFile?.recording_type || null,
        status: videoFile?.status || "completed",
        published: Boolean(saved.published),
      });
    }).filter(Boolean);

    res.json({ success: true, from, to, count: recordings.length, recordings });
  } catch (e) {
    res.status(500).json({ success: false, error: e.response?.data || e.message });
  }
});

app.post("/zoom/recordings/:meetingId/refresh-transcript", async (req, res) => {
  try {
    await requireLmsPermission(req, "lms.recordings.manage");

    const meetingId = String(req.params.meetingId || req.body.meeting_id || "").trim();

    if (!meetingId) {
      return res.status(400).json({
        success: false,
        error: "meeting_id is required",
      });
    }

    const { recording, accessToken } = await fetchZoomRecordingByMeetingId(meetingId);
    const db = await readLiveDb();

    const result = await upsertZoomRecordingFromObject({
      db,
      object: recording,
      accessToken,
      forceImportTranscript: true,
    });

    await writeLiveDb(db);

    res.json({
      success: true,
      meeting_id: meetingId,
      transcript_found: Boolean(result.transcriptFile),
      transcript_imported: Boolean(result.transcriptText),
      transcript_url: result.recordingPayload.transcript_url,
      transcript_download_url: result.recordingPayload.transcript_download_url,
      session_id: result.sessionId,
      recording: sanitizePublicRecording(result.recordingPayload),
    });
  } catch (e) {
    res.status(e.statusCode || 500).json({
      success: false,
      error: e.response?.data || e.message,
    });
  }
});
app.post("/live/recordings/publish", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.recordings.publish");
    const db = await readLiveDb();

    const meetingId = String(req.body.meeting_id || "").trim();
    const key = buildRecordingStorageKey(req.body);

    if (!key) {
      return res.status(400).json({
        success: false,
        error: "recording_key, uuid/start_time, or meeting_id is required",
      });
    }

    const legacyKey = getLegacyRecordingMeetingKey(req.body);
    const previous = db.recordings[key] || {};
    const legacy = legacyKey ? db.recordings[legacyKey] || {} : {};

    const requestedSessionId = String(req.body.session_id || "").trim();
    const previousSessionId = String(previous.session_id || legacy.session_id || "").trim();
    const resolvedSessionId = requestedSessionId || previousSessionId || null;
    const session = resolvedSessionId
      ? db.liveSessions?.[resolvedSessionId] ||
        Object.values(db.liveSessions || {}).find((item) => String(item.id || "") === String(resolvedSessionId)) ||
        null
      : null;

    if (requestedSessionId && !session) {
      return res.status(400).json({
        success: false,
        error: "Selected live session was not found. Refresh recordings and select the session again.",
      });
    }

    const explicitSessionSelection = Boolean(requestedSessionId);
    const sessionReassigned = Boolean(
      explicitSessionSelection &&
      previousSessionId &&
      requestedSessionId !== previousSessionId
    );

    const requestedCourseId = String(req.body.course_id || "").trim();
    const sessionCourseId = String(session?.course_id || "").trim();

    if (requestedCourseId && sessionCourseId && requestedCourseId !== sessionCourseId) {
      return res.status(400).json({
        success: false,
        error: "Selected course does not match the selected live session.",
      });
    }

    const resolvedCourseId =
      requestedCourseId ||
      sessionCourseId ||
      String(previous.course_id || legacy.course_id || "").trim() ||
      null;

    // Permanent safety: students only see published recordings that are linked to a course.
    // Do not allow the admin publish action to create another published row with course_id: null.
    if (!resolvedCourseId) {
      return res.status(400).json({
        success: false,
        error: "Select a course before publishing. Published recordings must be linked to a course so students can see them.",
      });
    }

    const now = new Date().toISOString();
    const wasAlreadyPublished = previous.published === true || legacy.published === true;
    const recordingUrl = req.body.recording_url || previous.recording_url || legacy.recording_url || req.body.share_url || previous.share_url || legacy.share_url || null;
    const shareUrl = req.body.share_url || previous.share_url || legacy.share_url || recordingUrl || null;
    const roadmapDay = session ? ngFindRoadmapDayForLiveSession(db, session) : null;
    const keepPreviousAssignmentMetadata = !sessionReassigned;
    const previousRoadmapDayId = keepPreviousAssignmentMetadata
      ? previous.roadmap_day_id || legacy.roadmap_day_id || null
      : null;
    const previousDayNumber = keepPreviousAssignmentMetadata
      ? previous.day_number || legacy.day_number || null
      : null;
    const previousInstructionalDayNumber = keepPreviousAssignmentMetadata
      ? previous.instructional_day_number || legacy.instructional_day_number || null
      : null;
    const previousSystemDay = keepPreviousAssignmentMetadata
      ? previous.system_day || legacy.system_day || null
      : null;
    const previousSystem = keepPreviousAssignmentMetadata
      ? previous.system || legacy.system || null
      : null;
    const previousAssignmentHistory = Array.isArray(previous.assignment_history)
      ? previous.assignment_history
      : Array.isArray(legacy.assignment_history)
        ? legacy.assignment_history
        : [];
    const assignmentHistory = explicitSessionSelection
      ? [
          ...previousAssignmentHistory,
          {
            from_session_id: previousSessionId || null,
            to_session_id: resolvedSessionId,
            assigned_at: now,
            assigned_by: user.id,
          },
        ]
      : previousAssignmentHistory;
    const requestedTopic = explicitSessionSelection && session
      ? session.topic || session.title || req.body.topic
      : req.body.topic || session?.topic || session?.title;
    const cleanTopic = ngDayFirstContentTitle(
      requestedTopic || previous.topic || legacy.topic || "Live Session Recording",
      {
        systemDay: roadmapDay?.system_day || roadmapDay?.day_in_system || session?.system_day,
        dayNumber: roadmapDay?.day_number || session?.day_number,
        system: roadmapDay?.system || session?.system,
      }
    );

    db.recordings[key] = {
      ...previous,
      id: key,
      recording_key: key,
      meeting_id: meetingId || previous.meeting_id || legacy.meeting_id || null,
      uuid: req.body.uuid || previous.uuid || legacy.uuid || null,
      session_id: resolvedSessionId,
      course_id: resolvedCourseId,
      roadmap_day_id: roadmapDay?.id || session?.roadmap_day_id || previousRoadmapDayId,
      day_number: roadmapDay?.day_number || session?.day_number || previousDayNumber,
      instructional_day_number: roadmapDay?.instructional_day_number || roadmapDay?.day_number || session?.instructional_day_number || previousInstructionalDayNumber,
      system_day: roadmapDay?.system_day || roadmapDay?.day_in_system || session?.system_day || previousSystemDay,
      system: roadmapDay?.system || session?.system || previousSystem,
      topic: cleanTopic,
      start_time: req.body.start_time || previous.start_time || legacy.start_time || null,
      duration: req.body.duration || previous.duration || legacy.duration || null,
      recording_url: recordingUrl,
      share_url: shareUrl,
      download_url: req.body.download_url || previous.download_url || legacy.download_url || null,
      file_type: req.body.file_type || previous.file_type || legacy.file_type || null,
      recording_type: req.body.recording_type || previous.recording_type || legacy.recording_type || null,
      status: req.body.status || previous.status || legacy.status || null,
      published: req.body.published !== false,
      published_at: wasAlreadyPublished ? previous.published_at || legacy.published_at || now : now,
      published_by: wasAlreadyPublished ? previous.published_by || legacy.published_by || user.id : user.id,
      assignment_source: explicitSessionSelection
        ? "admin_explicit_session"
        : previous.assignment_source || legacy.assignment_source || "existing_recording_mapping",
      assignment_locked: explicitSessionSelection
        ? true
        : previous.assignment_locked === true || legacy.assignment_locked === true,
      assigned_at: explicitSessionSelection ? now : previous.assigned_at || legacy.assigned_at || null,
      assigned_by: explicitSessionSelection ? user.id : previous.assigned_by || legacy.assigned_by || null,
      reassigned_from_session_id: sessionReassigned
        ? previousSessionId
        : previous.reassigned_from_session_id || legacy.reassigned_from_session_id || null,
      assignment_history: assignmentHistory,
      updated_at: now,
    };

    if (resolvedSessionId && db.liveSessions?.[resolvedSessionId]) {
      db.liveSessions[resolvedSessionId] = {
        ...(db.liveSessions[resolvedSessionId] || {}),
        recording_key: key,
        recording_url: recordingUrl,
        recording_published: req.body.published !== false,
        recording_published_at: now,
        updated_at: now,
      };

      db.notes[resolvedSessionId] = {
        ...(db.notes[resolvedSessionId] || {}),
        session_id: resolvedSessionId,
        course_id: resolvedCourseId,
        roadmap_day_id: roadmapDay?.id || session?.roadmap_day_id || null,
        day_number: roadmapDay?.day_number || session?.day_number || null,
        instructional_day_number: roadmapDay?.instructional_day_number || roadmapDay?.day_number || session?.instructional_day_number || null,
        system_day: roadmapDay?.system_day || roadmapDay?.day_in_system || session?.system_day || null,
        system: roadmapDay?.system || session?.system || null,
        recording_key: key,
        recording_url: recordingUrl,
        meeting_id: meetingId || previous.meeting_id || legacy.meeting_id || null,
        recording_published: req.body.published !== false,
        updated_at: now,
      };
    }

    if (
      legacyKey &&
      legacyKey !== key &&
      db.recordings[legacyKey]?.published &&
      ngZoomRecordingOccurrenceMatches(db.recordings[legacyKey], req.body)
    ) {
      db.recordings[legacyKey] = {
        ...(db.recordings[legacyKey] || {}),
        published: false,
        migrated_to_recording_key: key,
        migrated_at: now,
      };
    }

    let email_notification = null;
    if (db.recordings[key].published === true && !wasAlreadyPublished) {
      const course = db.courses?.[String(resolvedCourseId)] || null;
      email_notification = ngQueueCourseTemplateEmail(db, {
        templateKey: "new_recording_published",
        courseId: resolvedCourseId,
        reason: "new_recording_published",
        commonVariables: {
          recording_title: cleanTopic || "New Class Recording",
          course_name: course?.name || "Course",
          recording_url: "https://live.nextgenusmlelms.com/student/recordings",
        },
        dedupeKey: `new_recording_published:${key}:${now}`,
        createdBy: user.id,
      });
    }

    await writeLiveDb(db);
    res.json({ success: true, recording: sanitizePublicRecording(db.recordings[key]), email_notification });
  } catch (e) {
    res.status(e.statusCode || 500).json({ success: false, error: e.message });
  }
});

app.post("/live/recordings/unpublish", async (req, res) => {
  try {
    await requireLmsPermission(req, "lms.recordings.unpublish");
    const db = await readLiveDb();
    const key = buildRecordingStorageKey(req.body);

    if (!key) {
      return res.status(400).json({
        success: false,
        error: "recording_key, uuid/start_time, or meeting_id is required",
      });
    }

    const meetingId = String(req.body.meeting_id || "").trim();
    const legacyKey = getLegacyRecordingMeetingKey(req.body);

    db.recordings[key] = {
      ...(db.recordings[key] || {}),
      id: key,
      recording_key: key,
      meeting_id: meetingId || db.recordings[key]?.meeting_id || null,
      published: false,
      unpublished_at: new Date().toISOString(),
    };

    if (
      legacyKey &&
      legacyKey !== key &&
      db.recordings[legacyKey]?.published &&
      ngZoomRecordingOccurrenceMatches(db.recordings[legacyKey], req.body)
    ) {
      db.recordings[legacyKey] = {
        ...(db.recordings[legacyKey] || {}),
        published: false,
        migrated_to_recording_key: key,
        migrated_at: new Date().toISOString(),
      };
    }

    await writeLiveDb(db);
    res.json({ success: true, recording: sanitizePublicRecording(db.recordings[key]) });
  } catch (e) {
    res.status(e.statusCode || 500).json({ success: false, error: e.message });
  }
});

// Detach a wrong admin recording-to-session assignment without deleting the
// Zoom recording or the real roadmap/live-session record. This is intentionally
// limited to unpublished recordings with no attendance on the assigned session.
app.post("/admin/recordings/detach-assignment", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.recordings.manage");
    const requestedKey = buildRecordingStorageKey(req.body);
    const expectedSessionId = String(req.body.expected_session_id || req.body.session_id || "").trim();
    const expectedStartDate = String(req.body.expected_start_date || "").trim().slice(0, 10);
    const confirmation = String(req.body.confirm || "").trim().toUpperCase();

    if (!requestedKey) {
      return res.status(400).json({
        success: false,
        error: "recording_key, uuid/start_time, or meeting_id is required",
      });
    }
    if (!expectedSessionId) {
      return res.status(400).json({ success: false, error: "expected_session_id is required" });
    }
    if (confirmation !== "DETACH_RECORDING_ASSIGNMENT") {
      return res.status(400).json({
        success: false,
        error: "Exact confirmation is required: DETACH_RECORDING_ASSIGNMENT",
      });
    }

    const result = await mutateLiveDb(async (db) => {
      const storedEntry = Object.entries(db.recordings || {}).find(([storageKey, recording]) => {
        return storageKey === requestedKey ||
          String(recording?.recording_key || recording?.id || "") === requestedKey;
      });
      if (!storedEntry) {
        const error = new Error("Recording was not found; nothing was changed");
        error.statusCode = 404;
        throw error;
      }

      const [storageKey, recording] = storedEntry;
      const assignedSessionId = String(recording?.session_id || "").trim();
      if (assignedSessionId !== expectedSessionId) {
        const error = new Error("Recording assignment changed after audit; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      if (expectedStartDate && String(recording?.start_time || "").slice(0, 10) !== expectedStartDate) {
        const error = new Error("Recording start date changed after audit; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      if (recording?.published === true) {
        const error = new Error("Published recordings cannot be detached by this safety operation");
        error.statusCode = 409;
        throw error;
      }

      const assignedSession = db.liveSessions?.[assignedSessionId] || null;
      if (!assignedSession) {
        const error = new Error("Assigned live session was not found; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      const sessionStatus = String(assignedSession.status || "scheduled").trim().toLowerCase();
      if (sessionStatus !== "scheduled") {
        const error = new Error("Only a future scheduled session can be detached by this safety operation");
        error.statusCode = 409;
        throw error;
      }

      const attendanceCount = Object.values(db.attendance || {}).filter((attendance) => {
        return String(attendance?.session_id || attendance?.live_session_id || "") === assignedSessionId;
      }).length;
      if (attendanceCount > 0) {
        const error = new Error("The assigned session has attendance; recording assignment was not detached");
        error.statusCode = 409;
        throw error;
      }

      await ensureDataDir();
      const backupDir = path.join(DATA_DIR, "backups");
      await fs.mkdir(backupDir, { recursive: true });
      const stamp = new Date().toISOString().replace(/[:.]/g, "-");
      const backupPath = path.join(backupDir, `live-session-db-before-recording-detach-${stamp}.json`);
      await ngWriteJsonAtomicStreaming(backupPath, db, "LMS recording-detach backup");

      const now = new Date().toISOString();
      const recordingUrl = String(recording.recording_url || recording.share_url || "").trim();
      const sessionPointsToRecording =
        String(assignedSession.recording_key || assignedSession.recording_id || "") === storageKey ||
        Boolean(recordingUrl && String(assignedSession.recording_url || "").trim() === recordingUrl);

      if (sessionPointsToRecording) {
        db.liveSessions[assignedSessionId] = {
          ...assignedSession,
          recording_key: null,
          recording_id: null,
          recording_url: null,
          recording_published: false,
          recording_published_at: null,
          recording_match_reason: null,
          updated_by: user.id,
          updated_at: now,
        };
      }

      let notesLinksCleared = 0;
      for (const [noteKey, note] of Object.entries(db.notes || {})) {
        if (String(note?.session_id || "") !== assignedSessionId) continue;
        if (String(note?.recording_key || "") !== storageKey) continue;
        db.notes[noteKey] = {
          ...note,
          recording_key: null,
          recording_url: null,
          recording_published: false,
          updated_by: user.id,
          updated_at: now,
        };
        notesLinksCleared += 1;
      }

      const assignmentHistory = Array.isArray(recording.assignment_history)
        ? recording.assignment_history
        : [];
      db.recordings[storageKey] = {
        ...recording,
        id: storageKey,
        recording_key: storageKey,
        session_id: null,
        roadmap_day_id: null,
        day_number: null,
        instructional_day_number: null,
        system_day: null,
        system: null,
        published: false,
        auto_publish_disabled: true,
        assignment_source: "admin_detached_wrong_assignment",
        assignment_locked: true,
        hidden_from_recordings: req.body.hide !== false,
        detached_from_session_id: assignedSessionId,
        detached_from_roadmap_day_id: recording.roadmap_day_id || assignedSession.roadmap_day_id || null,
        detached_at: now,
        detached_by: user.id,
        assignment_history: [
          ...assignmentHistory,
          {
            from_session_id: assignedSessionId,
            to_session_id: null,
            assigned_at: now,
            assigned_by: user.id,
            reason: "wrong_unpublished_future_assignment_detached",
          },
        ],
        unpublished_at: recording.unpublished_at || now,
        updated_at: now,
      };

      return {
        recording_key: storageKey,
        detached_from_session_id: assignedSessionId,
        detached_from_roadmap_day_id: recording.roadmap_day_id || assignedSession.roadmap_day_id || null,
        recording_preserved: true,
        recording_hidden: db.recordings[storageKey].hidden_from_recordings === true,
        live_session_preserved: true,
        session_recording_link_cleared: sessionPointsToRecording,
        notes_recording_links_cleared: notesLinksCleared,
        attendance_count: attendanceCount,
        backup_path: backupPath,
      };
    });

    res.json({
      success: true,
      recording_assignment_build: RECORDING_ASSIGNMENT_BUILD,
      ...result,
      users_deleted: 0,
      enrollments_deleted: 0,
      payments_deleted: 0,
      roadmap_days_deleted: 0,
      live_sessions_deleted: 0,
      recordings_deleted: 0,
      notes_deleted: 0,
      attempts_deleted: 0,
      points_deleted: 0,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to detach recording assignment",
    });
  }
});

// Canonicalize one live session that has several published recording rows.
// This operation is deliberately narrow: the admin supplies every exact raw
// storage key, the one keeper must be playable, every clone must have zero
// duration, and the supplied set must equal all published rows for the exact
// course/session. Rows are preserved, not deleted.
app.post("/admin/recordings/cleanup-session-duplicates", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.recordings.manage");
    const courseId = String(req.body.course_id || "").trim();
    const sessionId = String(req.body.session_id || "").trim();
    const expectedSessionDate = String(req.body.expected_session_date || "").trim().slice(0, 10);
    const keeperRequestedKey = String(req.body.keeper_recording_key || "").trim();
    const cloneRequestedKeys = Array.isArray(req.body.clone_recording_keys)
      ? req.body.clone_recording_keys.map((value) => String(value || "").trim()).filter(Boolean)
      : [];
    const expectedKeeperMeetingId = String(req.body.expected_keeper_meeting_id || "").trim();
    const expectedCloneMeetingId = String(req.body.expected_clone_meeting_id || "").trim();
    const confirmation = String(req.body.confirm || "").trim().toUpperCase();

    if (!courseId || !sessionId || !expectedSessionDate || !keeperRequestedKey) {
      return res.status(400).json({
        success: false,
        error: "course_id, session_id, expected_session_date, and keeper_recording_key are required",
      });
    }
    if (cloneRequestedKeys.length < 1 || cloneRequestedKeys.length > 20) {
      return res.status(400).json({
        success: false,
        error: "clone_recording_keys must contain between 1 and 20 exact keys",
      });
    }
    if (new Set(cloneRequestedKeys).size !== cloneRequestedKeys.length) {
      return res.status(400).json({ success: false, error: "clone_recording_keys contains duplicates" });
    }
    if (cloneRequestedKeys.includes(keeperRequestedKey)) {
      return res.status(400).json({ success: false, error: "The keeper cannot also be a clone" });
    }
    if (confirmation !== "CLEANUP_SESSION_RECORDING_DUPLICATES") {
      return res.status(400).json({
        success: false,
        error: "Exact confirmation is required: CLEANUP_SESSION_RECORDING_DUPLICATES",
      });
    }

    const result = await mutateLiveDb(async (db) => {
      const recordingEntries = Object.entries(db.recordings || {});
      const findExactEntry = (requestedKey) => recordingEntries.find(([storageKey, recording]) => {
        return storageKey === requestedKey ||
          String(recording?.recording_key || "") === requestedKey ||
          String(recording?.id || "") === requestedKey;
      }) || null;
      const durationMinutes = (recording = {}) => {
        const value = Number(recording.duration ?? recording.duration_minutes ?? 0);
        return Number.isFinite(value) && value > 0 ? value : 0;
      };
      const recordingDate = (recording = {}) => String(
        recording.start_time || recording.published_at || recording.created_at || ""
      ).slice(0, 10);
      const titleIsExpectedSession = (value) => {
        const title = String(value || "");
        return /(?:cardio|cardiology)/i.test(title) && /day\s*0?9\b/i.test(title);
      };

      const sessionEntry = Object.entries(db.liveSessions || {}).find(([storageKey, session]) => {
        return storageKey === sessionId || String(session?.id || "") === sessionId;
      }) || null;
      if (!sessionEntry) {
        const error = new Error("Exact live session was not found; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      const [sessionStorageKey, session] = sessionEntry;
      if (String(session.course_id || "") !== courseId) {
        const error = new Error("Live-session course changed after preview; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      if (String(session.scheduled_date || "").slice(0, 10) !== expectedSessionDate) {
        const error = new Error("Live-session date changed after preview; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      if (!titleIsExpectedSession(session.topic || session.title)) {
        const error = new Error("This protected cleanup accepts only the audited Cardiology Day 9 session");
        error.statusCode = 409;
        throw error;
      }

      const keeperEntry = findExactEntry(keeperRequestedKey);
      if (!keeperEntry) {
        const error = new Error("Exact keeper recording key was not found; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      const [keeperStorageKey, keeper] = keeperEntry;
      if (
        keeper.published !== true ||
        String(keeper.course_id || "") !== courseId ||
        String(keeper.session_id || "") !== sessionId ||
        recordingDate(keeper) !== expectedSessionDate ||
        !titleIsExpectedSession(keeper.topic || keeper.title) ||
        durationMinutes(keeper) < 5 ||
        !String(keeper.recording_url || keeper.share_url || "").trim()
      ) {
        const error = new Error("Keeper no longer matches the audited playable Day 9 recording; nothing was changed");
        error.statusCode = 409;
        throw error;
      }
      if (expectedKeeperMeetingId && String(keeper.meeting_id || "") !== expectedKeeperMeetingId) {
        const error = new Error("Keeper meeting ID changed after preview; nothing was changed");
        error.statusCode = 409;
        throw error;
      }

      const cloneEntries = cloneRequestedKeys.map((requestedKey) => {
        const entry = findExactEntry(requestedKey);
        if (!entry) {
          const error = new Error(`Exact clone recording key was not found: ${requestedKey}`);
          error.statusCode = 409;
          throw error;
        }
        return entry;
      });
      const cloneStorageKeys = cloneEntries.map(([storageKey]) => storageKey);
      if (new Set(cloneStorageKeys).size !== cloneStorageKeys.length || cloneStorageKeys.includes(keeperStorageKey)) {
        const error = new Error("Resolved recording storage keys are not unique; nothing was changed");
        error.statusCode = 409;
        throw error;
      }

      for (const [, clone] of cloneEntries) {
        if (
          clone.published !== true ||
          String(clone.course_id || "") !== courseId ||
          String(clone.session_id || "") !== sessionId ||
          !titleIsExpectedSession(clone.topic || clone.title) ||
          durationMinutes(clone) !== 0
        ) {
          const error = new Error("A proposed clone is no longer a published zero-duration Day 9 row; nothing was changed");
          error.statusCode = 409;
          throw error;
        }
        if (expectedCloneMeetingId && String(clone.meeting_id || "") !== expectedCloneMeetingId) {
          const error = new Error("A clone meeting ID changed after preview; nothing was changed");
          error.statusCode = 409;
          throw error;
        }
      }

      const publishedSessionEntries = recordingEntries.filter(([, recording]) => {
        return recording?.published === true &&
          String(recording.course_id || "") === courseId &&
          String(recording.session_id || "") === sessionId;
      });
      const expectedPublishedStorageKeys = new Set([keeperStorageKey, ...cloneStorageKeys]);
      const actualPublishedStorageKeys = new Set(publishedSessionEntries.map(([storageKey]) => storageKey));
      if (
        actualPublishedStorageKeys.size !== expectedPublishedStorageKeys.size ||
        [...actualPublishedStorageKeys].some((storageKey) => !expectedPublishedStorageKeys.has(storageKey))
      ) {
        const error = new Error("Published Day 9 set changed after preview; refresh before cleanup");
        error.statusCode = 409;
        throw error;
      }

      await ensureDataDir();
      const backupDir = path.join(DATA_DIR, "backups");
      await fs.mkdir(backupDir, { recursive: true });
      const stamp = new Date().toISOString().replace(/[:.]/g, "-");
      const backupPath = path.join(backupDir, `live-session-db-before-recording-duplicate-cleanup-${stamp}.json`);
      await ngWriteJsonAtomicStreaming(backupPath, db, "LMS recording-duplicate cleanup backup");

      const now = new Date().toISOString();
      const keeperUrl = keeper.recording_url || keeper.share_url;
      db.recordings[keeperStorageKey] = {
        ...keeper,
        id: keeperStorageKey,
        recording_key: keeperStorageKey,
        course_id: courseId,
        session_id: sessionId,
        published: true,
        hidden_from_recordings: false,
        assignment_source: "admin_explicit_session",
        assignment_locked: true,
        duplicate_cleanup_keeper_at: now,
        duplicate_cleanup_keeper_by: user.id,
        updated_at: now,
      };

      for (const [storageKey, clone] of cloneEntries) {
        const assignmentHistory = Array.isArray(clone.assignment_history)
          ? clone.assignment_history
          : [];
        db.recordings[storageKey] = {
          ...clone,
          id: storageKey,
          recording_key: storageKey,
          session_id: null,
          roadmap_day_id: null,
          day_number: null,
          instructional_day_number: null,
          system_day: null,
          system: null,
          published: false,
          auto_publish_disabled: true,
          assignment_source: "admin_duplicate_cleanup",
          assignment_locked: true,
          hidden_from_recordings: true,
          detached_from_session_id: sessionId,
          detached_from_roadmap_day_id: clone.roadmap_day_id || session.roadmap_day_id || null,
          detached_at: now,
          detached_by: user.id,
          unpublished_at: now,
          assignment_history: [
            ...assignmentHistory,
            {
              from_session_id: sessionId,
              to_session_id: null,
              assigned_at: now,
              assigned_by: user.id,
              reason: "zero_duration_duplicate_hidden",
            },
          ],
          updated_at: now,
        };
      }

      db.liveSessions[sessionStorageKey] = {
        ...session,
        recording_key: keeperStorageKey,
        recording_id: keeperStorageKey,
        recording_url: keeperUrl,
        recording_published: true,
        recording_published_at: keeper.published_at || now,
        recording_match_reason: "admin_duplicate_cleanup_keeper",
        updated_by: user.id,
        updated_at: now,
      };

      let notesRelinked = 0;
      for (const [noteKey, note] of Object.entries(db.notes || {})) {
        if (String(note?.session_id || "") !== sessionId) continue;
        db.notes[noteKey] = {
          ...note,
          recording_key: keeperStorageKey,
          recording_url: keeperUrl,
          meeting_id: keeper.meeting_id || note.meeting_id || null,
          recording_published: true,
          updated_by: user.id,
          updated_at: now,
        };
        notesRelinked += 1;
      }

      return {
        keeper_recording_key: keeperStorageKey,
        keeper_duration_minutes: durationMinutes(keeper),
        clone_recording_keys: cloneStorageKeys,
        clones_hidden: cloneStorageKeys.length,
        notes_relinked: notesRelinked,
        backup_path: backupPath,
      };
    });

    res.json({
      success: true,
      recording_duplicate_cleanup_build: RECORDING_DUPLICATE_CLEANUP_BUILD,
      ...result,
      recordings_deleted: 0,
      live_sessions_deleted: 0,
      roadmap_days_deleted: 0,
      notes_deleted: 0,
      users_deleted: 0,
      enrollments_deleted: 0,
      payments_deleted: 0,
      assessment_attempts_deleted: 0,
      points_deleted: 0,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to clean duplicate recordings",
    });
  }
});

app.get("/live/recordings", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const isStaff = user.role === "admin" || user.role === "instructor";
    const requestedCourseId = String(req.query.course_id || req.query.courseId || "").trim();

    if (requestedCourseId) {
      const enrollment = getBackendEnrollment(db, { userId: user.id, courseId: requestedCourseId });
      if (!enrollment && !isStaff) {
        return res.status(403).json({ success: false, error: "No course access found" });
      }
      if (enrollment?.is_demo && !db.demoSettings.allow_recordings) {
        return res.json({ success: true, count: 0, recordings: [], demo_restricted: true });
      }
    }

    const autoRoadmapSync = requestedCourseId
      ? ngAutoSyncRoadmapLiveSessionsForCourses(db, [requestedCourseId], { actorId: user.id || "recordings_title_sync" })
      : { changed: false, checked: 0, details: [] };
    if (autoRoadmapSync.changed) await writeLiveDb(db);

    let recordings = Object.values(db.recordings || {});
    const includeHidden = isStaff && req.query.include_hidden === "true";
    if (!includeHidden) recordings = recordings.filter((recording) => recording.hidden_from_recordings !== true);
    if (!isStaff) recordings = recordings.filter((recording) => recording.published);
    if (requestedCourseId) recordings = recordings.filter((recording) => String(recording.course_id || "") === requestedCourseId);

    recordings.sort(sortRecordingsNewestFirst);
    res.json({ success: true, count: recordings.length, recordings: recordings.map(sanitizePublicRecording), auto_roadmap_sync: autoRoadmapSync });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message || "Failed to load live recordings" });
  }
});

