app.post("/live/community/:sessionId", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    if (!req.body.message) return res.status(400).json({ success: false, error: "message is required" });

    const db = await readLiveDb();
    const session = db.liveSessions?.[String(req.params.sessionId)] || null;

    if (!session?.id) {
      return res.status(404).json({ success: false, error: "Session not found" });
    }

    const courseId = req.body.course_id || session.course_id || null;
    const access = ngCourseFeatureAccess(db, user, {
      courseId,
      featureKey: "community",
    });

    if (!access.allowed) {
      return ngBlockLockedFeature(res, "community", access.reason);
    }

    const item = {
      id: uuid(),
      session_id: req.params.sessionId,
      course_id: courseId,
      user_id: user.id,
      user_name: user.name || user.email || "Student",
      message: String(req.body.message).slice(0, 2000),
      created_at: new Date().toISOString(),
    };

    const hadStudyActivityTodayBefore = user.role === "student" && courseId
      ? ngStudentHadStudyActivityOnDate(db, { courseId, userId: user.id, dateKey: todayKey() })
      : true;

    db.communityMessages[req.params.sessionId] = [...(db.communityMessages[req.params.sessionId] || []), item];

    let streak_bonus = { awarded: false, reason: "not_applicable" };

    if (courseId && session?.roadmap_day_id) {
      const day = ngFindRoadmapDay(db, { courseId, dayId: session.roadmap_day_id });
      if (day) {
        ngUpsertTaskCompletion(db, {
          courseId,
          userId: user.id,
          userName: user.name || user.email || "Student",
          day,
          taskKey: "community_confusion_post",
          completed: true,
          metadata: { community_message_id: item.id, session_id: req.params.sessionId },
        });
      }
      streak_bonus = user.role === "student"
        ? ngMaybeAwardStreakMilestoneBonus(db, {
            courseId,
            userId: user.id,
            userName: user.name || user.email || "Student",
            hadStudyActivityTodayBefore,
            source: "community_confusion_post",
            metadata: { session_id: req.params.sessionId, community_message_id: item.id },
          })
        : { awarded: false, reason: "staff_or_not_applicable" };

      if (!streak_bonus?.leaderboard) updateLeaderboard(db, { courseId, userId: user.id, userName: user.name || user.email || "Student" });
    }

    await writeLiveDb(db);
    res.json({ success: true, message: item, streak_bonus, leaderboard: courseId ? db.leaderboard?.[courseUserKey(courseId, user.id)] || null : null });
  } catch (e) {
    res.status(e.statusCode || 500).json({ success: false, error: e.message });
  }
});


function ngFindRoadmapDay(db, { courseId, dayId, dayNumber }) {
  const roadmap = db.roadmaps[String(courseId)] || null;
  const days = (roadmap?.days || []).filter((d) => d.is_published !== false);
  if (dayId) return days.find((day) => String(day.id) === String(dayId)) || null;
  if (dayNumber) return days.find((day) => String(day.day_number) === String(dayNumber)) || null;
  const today = todayKey();
  return days.find((day) => day.date === today) || days[0] || null;
}

function ngSanitizeDailyTaskPacket(db, { courseId, userId, day }) {
  if (!day) return null;
  const noClassDay = ngIsNoClassRoadmapDay(day) || ngRoadmapDayIsNoClass(day);
  const progress = ngGetDailyTaskProgress(db, { courseId, userId, dayId: day.id, day }) || ngEnsureDailyTaskProgress(db, { courseId, userId, userName: "Student", day });
  const streak = ngComputeStudentStudyStreakWithFreeze(db, { courseId, userId });
  const progressWithStreak = { ...(progress || {}), streak_days: streak.study_streak, best_streak: streak.best_streak, total_study_days: streak.total_study_days, last_activity_date: streak.last_activity_date, streak_milestone: streak.streak_milestone };
  const cleanDay = sanitizeRoadmapDay(day);

  if (noClassDay) {
    return {
      ...cleanDay,
      no_class_day: true,
      is_no_class_day: true,
      holiday: true,
      task_items: [],
      tasks: [],
      progress: { ...progressWithStreak, tasks: {}, completed_task_count: 0, total_task_count: 0, required_completed_count: 0, required_task_count: 0, completed: false },
      earned_points: 0,
      available_points: 0,
      holiday_message: "No academic task today. The planned content has been pushed to the next teaching day.",
    };
  }

  const taskItems = cleanDay.task_items.map((task) => ({
    ...task,
    completed: Boolean(progress.tasks?.[task.key]?.completed),
    completed_at: progress.tasks?.[task.key]?.completed_at || null,
    metadata: progress.tasks?.[task.key]?.metadata || {},
  }));
  const earnedPoints = Object.values(db.pointEvents || {})
    .filter((event) => String(event.course_id) === String(courseId) && String(event.user_id) === String(userId) && String(event.roadmap_day_id || event.day_id || "") === String(day.id))
    .reduce((sum, event) => sum + Number(event.points || 0), 0);
  return {
    ...cleanDay,
    task_items: taskItems,
    tasks: taskItems,
    progress: progressWithStreak,
    earned_points: earnedPoints,
    available_points: taskItems.reduce((sum, task) => sum + Number(task.points || 0), 0),
  };
}

app.get("/student/daily-task", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const courseId = String(req.query.course_id || req.query.courseId || "").trim();
    if (!courseId) return res.status(400).json({ success: false, error: "course_id is required" });
    const enrollment = getBackendEnrollment(db, { userId: user.id, courseId });
    if (!enrollment && user.role !== "admin" && user.role !== "instructor") return res.status(403).json({ success: false, error: "No course access found" });
    const day = ngFindRoadmapDay(db, { courseId, dayId: req.query.day_id, dayNumber: req.query.day_number });
    if (!day) return res.status(404).json({ success: false, error: "Roadmap day not found" });
    const packet = ngSanitizeDailyTaskPacket(db, { courseId, userId: user.id, day });
    const summary = buildProgressSummary({ db, courseId, userId: user.id });
    const leaderboard = updateLeaderboard(db, { courseId, userId: user.id, userName: user.name || user.email || "Student" });
    await writeLiveDb(db);
    res.json({ success: true, packet, summary, leaderboard });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

app.post("/student/daily-task/:dayId/task", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const courseId = String(req.body.course_id || req.body.courseId || "").trim();
    const taskKey = String(req.body.task_key || req.body.taskKey || req.body.key || "").trim();
    if (!courseId || !taskKey) return res.status(400).json({ success: false, error: "course_id and task_key are required" });
    const enrollment = getBackendEnrollment(db, { userId: user.id, courseId });
    if (!enrollment && user.role !== "admin" && user.role !== "instructor") return res.status(403).json({ success: false, error: "No course access found" });
    const day = ngFindRoadmapDay(db, { courseId, dayId: req.params.dayId });
    if (!day) return res.status(404).json({ success: false, error: "Roadmap day not found" });

    if (ngIsNoClassRoadmapDay(day) || ngRoadmapDayIsNoClass(day)) {
      const leaderboard = updateLeaderboard(db, { courseId, userId: user.id, userName: user.name || user.email || "Student" });
      await writeLiveDb(db);
      return res.json({
        success: true,
        ignored: true,
        no_class_day: true,
        message: "No academic tasks today. The planned content has been pushed to the next teaching day.",
        packet: ngSanitizeDailyTaskPacket(db, { courseId, userId: user.id, day }),
        summary: buildProgressSummary({ db, courseId, userId: user.id }),
        leaderboard,
      });
    }

    // v177n: only true system-verified tasks stay locked.
    // Content-review tasks shown on the dashboard must save when the student presses Mark Reviewed.
    // Otherwise the UI appears to mark them, then a refresh brings them back as incomplete.
    const systemLockedTasks = new Set([
      "live_attendance",
      "assessment_completed",
      "weekly_assessment_completed",
      "grand_system_assessment_completed",
      "assessment_high_score_bonus",
    ]);

    if (user.role === "student" && systemLockedTasks.has(taskKey)) {
      return res.status(403).json({
        success: false,
        error: `${ngTaskLabel(taskKey)} is verified automatically after the real activity is completed.`,
        automated: true,
        task_key: taskKey,
      });
    }

    if (user.role === "student" && taskKey === "daily_task_submitted" && req.body.completed !== false) {
      const currentProgress = ngEnsureDailyTaskProgress(db, { courseId, userId: user.id, userName: user.name || user.email || "Student", day });
      const taskItems = ngGetTaskItems(day).filter((item) => item.required !== false && item.key !== "daily_task_submitted");
      const missing = taskItems.filter((item) => !currentProgress.tasks?.[item.key]?.completed).map((item) => item.key);
      if (missing.length) {
        return res.status(400).json({
          success: false,
          error: "Complete the required verified tasks before submitting the full daily task.",
          missing_tasks: missing,
        });
      }
    }

    const hadStudyActivityTodayBefore = user.role === "student" && req.body.completed !== false
      ? ngStudentHadStudyActivityOnDate(db, { courseId, userId: user.id, dateKey: todayKey() })
      : true;

    const progress = ngUpsertTaskCompletion(db, { courseId, userId: user.id, userName: user.name || user.email || "Student", day, taskKey, completed: req.body.completed !== false, metadata: req.body.metadata || {} });
    const streak_bonus = user.role === "student" && req.body.completed !== false
      ? ngMaybeAwardStreakMilestoneBonus(db, {
          courseId,
          userId: user.id,
          userName: user.name || user.email || "Student",
          hadStudyActivityTodayBefore,
          source: `daily_task:${taskKey}`,
          metadata: { roadmap_day_id: day.id, task_key: taskKey },
        })
      : { awarded: false, reason: "not_completed_or_staff" };
    const leaderboard = streak_bonus?.leaderboard || updateLeaderboard(db, { courseId, userId: user.id, userName: user.name || user.email || "Student" });
    await writeLiveDb(db);
    res.json({ success: true, progress, packet: ngSanitizeDailyTaskPacket(db, { courseId, userId: user.id, day }), summary: buildProgressSummary({ db, courseId, userId: user.id }), streak_bonus, leaderboard });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

