app.get(["/admin/adaptive/baseline-audit", "/admin/baseline/status", "/admin/baseline", "/admin/baseline-diagnostic", "/admin/baseline-diagnostics"], async (req, res) => {
  try {
    await requireAdminOrInstructor(req);
    const db = await readLiveDb();
    const courseId = String(req.query.course_id || req.query.courseId || "").trim();
    if (!courseId) return res.status(400).json({ success: false, error: "course_id is required" });
    const baseline = ngFindBaselineAssessment(db, { courseId });
    const coverage = baseline ? ngAssessmentSystemCoverage(baseline) : null;
    const activeEnrollments = Object.values(db.enrollments || {}).filter((enrollment) => {
      if (String(enrollment.course_id || "") !== courseId) return false;
      if (enrollment.access_granted === false) return false;
      const user = db.users?.[String(enrollment.user_id || "")];
      return Boolean(user?.id);
    });
    const rows = activeEnrollments.map((enrollment) => {
      const user = db.users[String(enrollment.user_id)];
      const assignment = db.adaptiveAssignments?.[ngAdaptiveAssignmentKey(courseId, user.id, "baseline_diagnostic")] || null;
      const attempt = baseline ? ngGetAttemptForAssessmentUser(db, { assessmentId: baseline.id, userId: user.id }) : null;
      return {
        user_id: user.id,
        name: user.name || user.email,
        email: user.email,
        enrollment_type: enrollment.is_demo ? "demo" : "paid",
        assignment_status: assignment?.status || (baseline ? "not_assigned_yet" : "missing_template"),
        reminder_count: Number(assignment?.reminder_count || 0),
        next_reminder_at: assignment?.next_reminder_at || null,
        completed: Boolean(attempt && ngIsAssessmentAttemptSubmitted(attempt)),
        attempt_id: attempt?.id || null,
      };
    });
    res.json({
      success: true,
      course_id: courseId,
      baseline_exists: Boolean(baseline?.id),
      baseline_assessment: baseline ? sanitizeAssessmentForStudent(baseline, null) : null,
      baseline_coverage: coverage,
      coverage_ready: Boolean(coverage?.diagnostic_coverage_ready),
      message: baseline?.id
        ? coverage?.diagnostic_coverage_ready
          ? `Baseline diagnostic covers all ${coverage.expected_system_count} systems.`
          : `Baseline exists but needs coverage correction for: ${(coverage?.underrepresented_systems || []).join(", ") || "unknown systems"}.`
        : "Baseline diagnostic missing — Generate now.",
      enrolled_students: rows.length,
      pending_count: rows.filter((row) => !row.completed).length,
      completed_count: rows.filter((row) => row.completed).length,
      rows,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post(["/admin/adaptive/generate-baseline-diagnostic", "/admin/baseline/generate"], async (req, res) => {
  try {
    const { user } = await requireAdminOrInstructor(req);
    const db = await readLiveDb();
    const courseId = String(req.body.course_id || req.body.courseId || "").trim();
    if (!courseId) return res.status(400).json({ success: false, error: "course_id is required" });
    const settings = ngGetAdaptiveSettings(db, courseId);
    const existing = ngFindBaselineAssessment(db, { courseId });
    if (existing?.id && req.body.force_new !== true) {
      const repair = ngRepairBaselineAssessmentAnswerKeyIfNeeded(db, existing, { force: req.body.repair_answer_key === true });
      if (repair.changed) await writeLiveDb(db);
      const coverage = ngAssessmentSystemCoverage(existing);
      return res.json({
        success: true,
        created: false,
        repaired: repair.changed === true,
        repair,
        coverage,
        assessment: existing,
        message: repair.changed
          ? "Existing baseline diagnostic was repaired: answer choices were shuffled and corrupted attempts were archived for retake."
          : coverage.diagnostic_coverage_ready
            ? `Baseline diagnostic already exists and covers all ${coverage.expected_system_count} systems.`
            : `Baseline diagnostic exists but is underrepresented in: ${coverage.underrepresented_systems.join(", ")}. Existing attempts were preserved; create a corrected version only after reviewing this audit.`
      });
    }
    const cfg = ngNormalizeAssessmentBlockConfig({
      block_mode: true,
      block_count: req.body.block_count ?? settings.baseline_block_count,
      questions_per_block: req.body.questions_per_block ?? settings.baseline_questions_per_block,
      duration_per_block_minutes: req.body.duration_per_block_minutes ?? settings.baseline_duration_per_block_minutes,
    });
    if (cfg.total_questions < NEXTGEN_ADAPTIVE_SYSTEMS.length) {
      return res.status(400).json({
        success: false,
        error: `Baseline diagnostic needs at least ${NEXTGEN_ADAPTIVE_SYSTEMS.length} questions so every configured system can be measured.`,
      });
    }
    const sourceText = String(req.body.source_text || ngBaselineSourceTextForCourse(db, { courseId }) || "").trim();
    let questions = [];
    let warnings = [];
    let aiUsage = null;
    let aiModel = null;
    if (sourceText.length >= 300 && isAIConfigured()) {
      const ai = await generateQuestionsWithAI({
        sourceText,
        questionCount: cfg.total_questions,
        difficulty: req.body.difficulty || "mixed",
        questionType: "mcq",
        metadata: { course_id: courseId, assessment_type: "baseline_diagnostic", block_count: cfg.block_count, questions_per_block: cfg.questions_per_block },
      });
      questions = ai.questions || [];
      warnings = ai.warnings || [];
      aiUsage = ai.usage || null;
      aiModel = ai.model || null;
    } else if (!isAIConfigured()) {
      questions = ngCreateDefaultBaselineQuestions({ courseName: db.courses?.[String(courseId)]?.name || "NextGen USMLE", totalQuestions: cfg.total_questions });
      warnings.push("AI is not configured, so v176 created a published default baseline question set. Admin can edit these questions anytime.");
    } else {
      questions = ngCreateDefaultBaselineQuestions({ courseName: db.courses?.[String(courseId)]?.name || "NextGen USMLE", totalQuestions: cfg.total_questions });
      warnings.push("Not enough source text for AI generation, so v176 created a published default baseline question set. Admin can edit these questions anytime.");
    }
    // v177c safety: AI generation can occasionally return too few questions or an unsafe answer-key pattern.
    // Baseline must always be a complete, usable diagnostic because it gates the mastery profile.
    const expectedBaselineQuestions = Math.max(1, Number(cfg.total_questions || 40) || 40);
    const baselineCourseName = db.courses?.[String(courseId)]?.name || db.courses?.[String(courseId)]?.title || "NextGen USMLE";
    if (!Array.isArray(questions)) questions = [];
    const originalGeneratedCount = questions.length;
    if (questions.length < expectedBaselineQuestions) {
      const fallbackQuestions = ngCreateDefaultBaselineQuestions({
        courseName: baselineCourseName,
        totalQuestions: expectedBaselineQuestions,
      });
      questions = [...questions, ...fallbackQuestions].slice(0, expectedBaselineQuestions);
      warnings.push(`v177d baseline USMLE-style quality guard: generator returned ${originalGeneratedCount}/${expectedBaselineQuestions} questions, so safe default questions were used to complete the diagnostic.`);
    }

    questions = ngNormalizeAssessmentQuestionsForStorage(questions, {
      assessmentId: `baseline:${courseId}:${Date.now()}`,
      assessmentType: "baseline",
      forceRandomize: true,
      distributeCorrectIndex: true,
    });

    const answerDistribution = questions.reduce((acc, q) => {
      const idx = Number.isFinite(Number(q.correct_index)) ? Number(q.correct_index) : -1;
      acc[idx] = Number(acc[idx] || 0) + 1;
      return acc;
    }, {});
    const mostCommonAnswerCount = Math.max(0, ...Object.values(answerDistribution).map((n) => Number(n || 0)));
    const unsafeAnswerPattern = questions.length >= 10 && mostCommonAnswerCount / Math.max(1, questions.length) >= 0.8;
    if (questions.length < expectedBaselineQuestions || unsafeAnswerPattern) {
      questions = ngCreateDefaultBaselineQuestions({
        courseName: baselineCourseName,
        totalQuestions: expectedBaselineQuestions,
      });
      warnings.push("v177d baseline USMLE-style quality guard: unsafe answer-key distribution detected, so the baseline was replaced with the corrected randomized USMLE-style baseline diagnostic.");
    }

    let coverage = ngAssessmentSystemCoverage({ questions });
    if (!coverage.diagnostic_coverage_ready) {
      questions = ngCreateDefaultBaselineQuestions({
        courseName: baselineCourseName,
        totalQuestions: expectedBaselineQuestions,
      });
      coverage = ngAssessmentSystemCoverage({ questions });
      warnings.push(`v191 system-coverage guard replaced an incomplete generated baseline so all ${coverage.expected_system_count} configured systems are diagnosed.`);
    }

    const id = uuid();
    const assessment = ngApplyAssessmentBlockMetadata({
      id,
      course_id: courseId,
      title: req.body.title || "Baseline Weak-Area Diagnostic",
      description: req.body.description || "Original USMLE-style baseline diagnostic to measure system mastery and personalize flashcards.",
      source_type: "baseline_diagnostic",
      assessment_type: "baseline",
      adaptive_baseline: true,
      system: "Mixed Systems",
      topic: "Baseline diagnostic",
      questions,
      is_published: questions.length > 0 && req.body.publish !== false,
      created_by: user.id,
      updated_by: user.id,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      ai_usage: aiUsage,
      ai_model: aiModel,
      system_coverage: coverage,
      warnings,
    }, cfg);
    assessment.published_at = assessment.is_published ? new Date().toISOString() : null;
    db.assessments[id] = assessment;
    await writeLiveDb(db);
    res.json({ success: true, created: true, assessment, coverage, warnings, published: assessment.is_published, message: assessment.is_published ? `Baseline diagnostic generated and published with ${coverage.covered_system_count}/${coverage.expected_system_count} systems covered.` : "Baseline diagnostic draft created. Add questions before publishing." });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});


