app.patch("/admin/assessment-attempts/:attemptId/review", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.assessments.review_attempts");
    const db = await readLiveDb();
    const attempt = db.assessmentAttempts[String(req.params.attemptId)];

    if (!attempt) return res.status(404).json({ success: false, error: "Assessment attempt not found" });

    if (req.body.admin_feedback !== undefined) attempt.admin_feedback = String(req.body.admin_feedback || "");
    if (req.body.review_status !== undefined) {
      const allowed = ["pending_review", "reviewed", "released"];
      const nextStatus = String(req.body.review_status || "pending_review");
      if (allowed.includes(nextStatus)) attempt.review_status = nextStatus;
    }
    if (req.body.released_to_student !== undefined) attempt.released_to_student = Boolean(req.body.released_to_student);

    if (attempt.released_to_student || attempt.review_status === "released") {
      attempt.review_status = "released";
      attempt.released_to_student = true;
      attempt.reviewed_by = user.id;
      attempt.reviewed_at = new Date().toISOString();
      applyReleasedAssessmentAttemptToLeaderboard(db, attempt, db.assessments?.[attempt.assessment_id]);
      const crmDb = await readCrmDb().catch(() => ({}));
      await ngAutoGenerateWeakAreaFlashcardsFromAttempt(db, crmDb, {
        attempt,
        assessment: db.assessments?.[attempt.assessment_id],
        actorId: user.id || "assessment_review_release",
      }).catch((error) => console.warn("Weak-area flashcard sync failed:", error.message));
    } else {
      attempt.reviewed_by = user.id;
      attempt.reviewed_at = new Date().toISOString();
    }

    db.assessmentAttempts[attempt.id] = attempt;
    await writeLiveDb(db);

    res.json({
      success: true,
      attempt: sanitizeAttemptForAdmin(attempt, db),
      leaderboard: db.leaderboard?.[courseUserKey(attempt.course_id, attempt.user_id)] || null,
    });
  } catch (e) {
    res.status(e.statusCode || 500).json({ success: false, error: e.message || "Failed to review assessment attempt" });
  }
});

app.post("/admin/assessment-attempts/:attemptId/release", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.assessments.review_attempts");
    const db = await readLiveDb();
    const attempt = db.assessmentAttempts[String(req.params.attemptId)];

    if (!attempt) return res.status(404).json({ success: false, error: "Assessment attempt not found" });

    if (req.body.admin_feedback !== undefined) attempt.admin_feedback = String(req.body.admin_feedback || "");
    attempt.review_status = "released";
    attempt.released_to_student = true;
    attempt.reviewed_by = user.id;
    attempt.reviewed_at = new Date().toISOString();

    const leaderboard = applyReleasedAssessmentAttemptToLeaderboard(db, attempt, db.assessments?.[attempt.assessment_id]);
    const crmDb = await readCrmDb().catch(() => ({}));
    const weak_flashcard_sync = await ngAutoGenerateWeakAreaFlashcardsFromAttempt(db, crmDb, {
      attempt,
      assessment: db.assessments?.[attempt.assessment_id],
      actorId: user.id || "assessment_release",
    }).catch((error) => ({ created: 0, error: error.message }));

    db.assessmentAttempts[attempt.id] = attempt;
    await writeLiveDb(db);

    res.json({
      success: true,
      attempt: sanitizeAttemptForAdmin(attempt, db),
      leaderboard,
      weak_flashcard_sync,
    });
  } catch (e) {
    res.status(e.statusCode || 500).json({ success: false, error: e.message || "Failed to release assessment result" });
  }
});



// v161: Auto-repair live-session records from the roadmap when student pages read them.
// This covers already-broken courses after a holiday push, without requiring a manual admin sync.
function ngFindRoadmapEntryForCourse(db = {}, courseId = "") {
  const cleanCourseId = String(courseId || "").trim();
  if (!cleanCourseId) return { key: null, roadmap: null };

  const direct = db.roadmaps?.[cleanCourseId] || null;
  if (direct?.days && Array.isArray(direct.days)) {
    return { key: cleanCourseId, roadmap: direct };
  }

  const found = Object.entries(db.roadmaps || {}).find(([, roadmap]) => {
    return String(roadmap?.course_id || roadmap?.courseId || "") === cleanCourseId && Array.isArray(roadmap?.days);
  });

  return found ? { key: found[0], roadmap: found[1] } : { key: null, roadmap: null };
}

function ngPickLiveSessionForRoadmapDay(db = {}, courseId = "", day = {}) {
  const ids = [
    day.live_session_id,
    day.session_id,
    day.pushed_live_session_id,
    day.pushed_from_live_session_id,
    day.original_day_snapshot?.live_session_id,
    day.original_day_snapshot?.session_id,
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean);

  for (const id of ids) {
    const session = db.liveSessions?.[id];
    if (session?.id && String(session.course_id || "") === String(courseId || "")) {
      return session;
    }
  }

  return (
    Object.values(db.liveSessions || {}).find((session) => {
      return (
        session?.id &&
        String(session.course_id || "") === String(courseId || "") &&
        String(session.roadmap_day_id || "") === String(day.id || "")
      );
    }) || null
  );
}

function ngRoadmapNeedsLiveSessionAutoSync(db = {}, roadmap = {}) {
  if (!roadmap || !Array.isArray(roadmap.days) || !roadmap.days.length) return false;

  const courseId = ngRoadmapCourseId(roadmap);
  if (!courseId) return false;

  const today = todayKey();

  const sequenceEntries = ngRoadmapSequenceEntries(roadmap.days || []);

  for (const { day, scheduleSlotNumber, instructionalDayNumber, systemDay, noClass } of sequenceEntries) {
    if (!day?.id) continue;

    const dayDate = String(day.date || day.scheduled_date || "").slice(0, 10);
    const shouldCheckFuture = !dayDate || dayDate >= today;
    const linkedSession = ngPickLiveSessionForRoadmapDay(db, courseId, day);

    if (Number(day.order || day.schedule_slot_number || 0) !== scheduleSlotNumber) return true;
    if (Number(day.schedule_slot_number || day.order || 0) !== scheduleSlotNumber) return true;

    if (noClass) {
      if (day.day_number !== null && day.day_number !== undefined && day.day_number !== "") return true;
      if (day.instructional_day_number !== null && day.instructional_day_number !== undefined && day.instructional_day_number !== "") return true;
      if (day.system_day !== null && day.system_day !== undefined && day.system_day !== "") return true;
      if (day.day_in_system !== null && day.day_in_system !== undefined && day.day_in_system !== "") return true;
    } else {
      if (Number(day.day_number || 0) !== instructionalDayNumber) return true;
      if (Number(day.instructional_day_number || day.day_number || 0) !== instructionalDayNumber) return true;
      if (Number(day.system_day || day.day_in_system || 0) !== systemDay) return true;

      const expectedDay = {
        ...day,
        day_number: instructionalDayNumber,
        instructional_day_number: instructionalDayNumber,
        system_day: systemDay,
        day_in_system: systemDay,
      };
      const expectedTitle = ngBuildLiveSessionTitleFromRoadmap(db, roadmap, expectedDay);
      if (String(day.title || "").trim() !== expectedTitle) return true;
      if (linkedSession?.id) {
        if (Number(linkedSession.day_number || 0) !== instructionalDayNumber) return true;
        if (Number(linkedSession.system_day || linkedSession.day_in_system || 0) !== systemDay) return true;
        if (String(linkedSession.topic || linkedSession.title || "").trim() !== expectedTitle) return true;
      }
    }

    if (noClass) {
      if (!linkedSession?.id) continue;
      const status = String(linkedSession.status || "").toLowerCase();
      if (!["cancelled", "canceled", "completed", "ended", "past"].includes(status)) return true;
      continue;
    }

    if (!shouldCheckFuture) continue;

    if (!linkedSession?.id) return true;

    const status = String(linkedSession.status || "").toLowerCase();
    if (["cancelled", "canceled"].includes(status)) return true;

    const wantedDate = String(day.date || day.scheduled_date || "").slice(0, 10);
    const wantedTime = String(ngRoadmapClassTime(roadmap, day) || "").trim();
    const wantedTimezone = String(ngRoadmapTimezone(roadmap, day) || DEFAULT_TIMEZONE).trim();

    if (wantedDate && String(linkedSession.scheduled_date || "").slice(0, 10) !== wantedDate) return true;
    if (wantedTime && String(linkedSession.scheduled_time || "").trim() !== wantedTime) return true;
    if (wantedTimezone && String(linkedSession.scheduled_timezone || DEFAULT_TIMEZONE).trim() !== wantedTimezone) return true;
    if (String(linkedSession.roadmap_day_id || "") !== String(day.id || "")) return true;
  }

  return false;
}

function ngAutoSyncRoadmapLiveSessionsForCourses(db = {}, courseIds = [], options = {}) {
  const ids = Array.from(new Set((Array.isArray(courseIds) ? courseIds : [courseIds]).map((id) => String(id || "").trim()).filter(Boolean)));
  const result = {
    checked: ids.length,
    changed: false,
    details: [],
  };

  for (const courseId of ids) {
    const entry = ngFindRoadmapEntryForCourse(db, courseId);
    const roadmap = entry.roadmap;

    if (!roadmap || !Array.isArray(roadmap.days) || !roadmap.days.length) {
      result.details.push({ course_id: courseId, skipped: true, reason: "no_roadmap" });
      continue;
    }

    if (!ngRoadmapNeedsLiveSessionAutoSync(db, roadmap)) {
      result.details.push({ course_id: courseId, skipped: true, reason: "already_synced" });
      continue;
    }

    const skipSundays = roadmap.skip_sundays !== false && roadmap.settings?.skip_sundays !== false;
    const startDate = roadmap.start_date || roadmap.settings?.start_date || roadmap.days[0]?.date || todayKey();

    ngRecalculateRoadmapSchedule(db, roadmap, { startDate, skipSundays, actorId: options.actorId || options.userId || "student_auto_live_sync" });

    const dependencySync = {
      days_checked: 0,
      flashcards: 0,
      flashcard_progress: 0,
      assessments: 0,
      assessment_attempts: 0,
      notes: 0,
      roadmap_progress: 0,
      daily_task_progress: 0,
      point_events: 0,
      weak_concepts: 0,
      leaderboards_rebuilt: 0,
    };

    for (const day of roadmap.days || []) {
      const fromDayId = String(day.pushed_from_day_id || day.original_day_id || "").trim();
      if (!fromDayId || ngRoadmapDayIsNoClass(day)) continue;

      const partial = ngRelinkRoadmapDayDependencies(db, {
        courseId,
        fromDayId,
        toDay: day,
        actorId: options.actorId || options.userId || "student_auto_live_sync",
      });

      dependencySync.days_checked += 1;
      for (const key of Object.keys(partial || {})) {
        dependencySync[key] = Number(dependencySync[key] || 0) + Number(partial[key] || 0);
      }
    }

    const sequenceMetadataSync = ngSyncRoadmapSequenceMetadata(db, roadmap, {
      actorId: options.actorId || options.userId || "student_auto_live_sync",
    });

    const liveSessionSync = ngSyncLinkedLiveSessionsForRoadmap(db, roadmap, {
      actorId: options.actorId || options.userId || "student_auto_live_sync",
    });

    if (entry.key) db.roadmaps[entry.key] = roadmap;

    result.changed = true;
    result.details.push({
      course_id: courseId,
      skipped: false,
      roadmap_key: entry.key,
      dependency_sync: dependencySync,
      sequence_metadata_sync: sequenceMetadataSync,
      live_session_sync: liveSessionSync,
    });
  }

  return result;
}


app.get("/student/dashboard/summary", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const courseId = String(req.query.course_id || req.query.courseId || "").trim();
    if (!courseId) return res.status(400).json({ success: false, error: "course_id is required" });

    const db = await readLiveDb();
    const enrollment = getBackendEnrollment(db, { userId: user.id, courseId });
    const roadmap = buildProgressSummary({ db, courseId, userId: user.id });
    const perf = performanceFromAttempts(getStudentAttempts(db, courseId, user.id));
    const streak = ngComputeStudentStudyStreakWithFreeze(db, { courseId, userId: user.id });
    const leaderboard = updateLeaderboard(db, { courseId, userId: user.id, userName: user.name || user.email || "Student" });

    let plan = { name: enrollment?.is_demo ? "Demo" : enrollment ? "Active" : "No active plan", days_left: null, is_demo: Boolean(enrollment?.is_demo) };
    if (enrollment?.is_demo && enrollment.demo_expiry) {
      plan.days_left = Math.max(0, Math.ceil((new Date(`${enrollment.demo_expiry}T23:59:59`).getTime() - Date.now()) / 86400000));
    }

    const assessments = Object.values(db.assessments || {}).filter((a) => String(a.course_id) === String(courseId) && a.is_published);
    const completedAssessments = assessments.filter((a) => {
      const attempt = db.assessmentAttempts[assessmentAttemptKey(a.id, user.id)];
      return attempt && isAttemptReleased(attempt);
    });

    await writeLiveDb(db);

    res.json({
      success: true,
      plan,
      roadmap,
      today: roadmap.today_day,
      streak_days: streak.study_streak,
      streak: streak.study_streak,
      best_streak: streak.best_streak,
      total_study_days: streak.total_study_days,
      last_activity_date: streak.last_activity_date,
      streak_milestone: streak.streak_milestone,
      performance: {
        study_streak: streak.study_streak,
        best_streak: streak.best_streak,
        total_study_days: streak.total_study_days,
        streak_milestone: streak.streak_milestone,
        total_study_time_hours: 0,
        average_mock_score: perf.average_score,
        latest_mock_score: perf.latest_score,
        best_mock_score: perf.best_score,
        attempts_count: perf.attempts_count,
      },
      focus_areas: perf.focus_areas,
      leaderboard: {
        points: leaderboard.total_points || 0,
        attendance_points: leaderboard.attendance_points || 0,
        task_points: leaderboard.task_points || 0,
        quiz_points: leaderboard.quiz_points || 0,
      },
      assessments: {
        available: assessments.length,
        completed: completedAssessments.length,
        pending: Math.max(0, assessments.length - completedAssessments.length),
      },
    });
  } catch (e) {
    res.status(e.statusCode || 500).json({ success: false, error: e.message });
  }
});


// -----------------------------------------------------------------------------
// v158: Student LMS light bootstrap + merged Live/Classroom Center
// -----------------------------------------------------------------------------
// These routes are intentionally lightweight. They prevent the student app from
// loading 120 live-session notes on first open. Notes are only exposed as status
// flags here; full notes still load from /live/notes/:sessionId when a specific
// session is opened.
function ngStudentEnrollmentStatusForCourse(db, user, courseId) {
  return ngResolveCourseAccessRecord(db, user, courseId);
}

function ngStudentHasCourseAccessStatus(status) {
  return ["paid", "demo_active"].includes(String(status || ""));
}

function ngBuildStudentAccessSummary(db = {}, user = {}, courses = []) {
  return safeArray(courses).map((course) => {
    const access = ngStudentEnrollmentStatusForCourse(db, user, course.id);
    return {
      course: sanitizeCourse(course),
      status: access.status,
      enrollment: access.enrollment || null,
      demo_expiry: access.demo_expiry || null,
      access_expires_at: access.access_expires_at || null,
      plan: access.plan ? sanitizePlan(access.plan) : null,
      has_active_access: ngStudentHasCourseAccessStatus(access.status),
      requires_renewal: ["demo_expired", "paid_expired"].includes(String(access.status || "")),
    };
  });
}

function ngSessionDateTimeMs(session) {
  const start = getSessionStartUtc(session?.scheduled_date, session?.scheduled_time, session?.scheduled_timezone || DEFAULT_TIMEZONE);
  return start ? start.getTime() : 0;
}

function ngSessionTimingWindow(session = {}, nowMs = Date.now()) {
  const rawStatus = String(session?.status || "scheduled").trim().toLowerCase();
  const cancelled = ["cancelled", "canceled"].includes(rawStatus);
  const manuallyCompleted = ["completed", "ended", "past"].includes(rawStatus);
  const startMs = ngSessionDateTimeMs(session);
  const scheduledDurationMinutes = Math.max(
    30,
    Number(session?.duration_minutes || session?.duration || DEFAULT_ZOOM_DURATION_MINUTES) || DEFAULT_ZOOM_DURATION_MINUTES
  );
  const lifecycleDurationMinutes = NEXTGEN_LIVE_SESSION_AUTO_COMPLETE_MINUTES;
  const endMs = startMs ? startMs + lifecycleDurationMinutes * 60 * 1000 : 0;
  const joinOpensMs = startMs ? startMs - NEXTGEN_CLASSROOM_OPEN_MINUTES_BEFORE * 60 * 1000 : 0;

  let status = "scheduled";
  if (cancelled) status = "cancelled";
  else if (manuallyCompleted) status = "completed";
  else if (startMs) {
    // The configured IANA timezone and schedule are authoritative. Every live
    // session leaves active LMS views exactly one hour after its scheduled start.
    if (nowMs < startMs) status = "scheduled";
    else if (nowMs <= endMs) status = "live";
    else status = "completed";
  } else if (["live", "live_now", "in_progress", "ongoing"].includes(rawStatus)) status = "live";
  else if (["completed", "ended", "past"].includes(rawStatus)) status = "completed";
  else if (["cancelled", "canceled"].includes(rawStatus)) status = "cancelled";

  return {
    status,
    raw_status: rawStatus || "scheduled",
    timezone: session?.scheduled_timezone || DEFAULT_TIMEZONE,
    duration_minutes: lifecycleDurationMinutes,
    scheduled_duration_minutes: scheduledDurationMinutes,
    auto_complete_after_minutes: NEXTGEN_LIVE_SESSION_AUTO_COMPLETE_MINUTES,
    start_ms: startMs || 0,
    end_ms: endMs || 0,
    join_opens_ms: joinOpensMs || 0,
    start_at: startMs ? new Date(startMs).toISOString() : null,
    end_at: endMs ? new Date(endMs).toISOString() : null,
    join_opens_at: joinOpensMs ? new Date(joinOpensMs).toISOString() : null,
  };
}

function ngAutoCompleteExpiredLiveSessions(db = {}, {
  actorId = "live_session_one_hour_auto_complete",
  nowMs = Date.now(),
} = {}) {
  const completedIds = [];
  const completedAt = new Date(nowMs).toISOString();

  for (const session of Object.values(db.liveSessions || {})) {
    if (!session?.id) continue;

    const storedStatus = String(session.status || "scheduled").trim().toLowerCase();
    if (["completed", "ended", "past", "cancelled", "canceled", "archived", "hidden", "deleted"].includes(storedStatus)) {
      continue;
    }

    const timing = ngSessionTimingWindow(session, nowMs);
    if (!timing.start_ms || nowMs <= timing.end_ms || timing.status !== "completed") continue;

    session.status = "completed";
    session.auto_completed_at = session.auto_completed_at || completedAt;
    session.auto_completed_by = session.auto_completed_by || actorId;
    session.updated_at = completedAt;
    db.liveSessions[session.id] = session;
    completedIds.push(session.id);
  }

  return {
    changed: completedIds.length > 0,
    completed_count: completedIds.length,
    completed_session_ids: completedIds,
    auto_complete_after_minutes: NEXTGEN_LIVE_SESSION_AUTO_COMPLETE_MINUTES,
  };
}

function ngSessionComputedStatus(session, nowMs = Date.now()) {
  return ngSessionTimingWindow(session, nowMs).status;
}

function ngSafetyText(...parts) {
  return parts.map((value) => String(value || "").toLowerCase()).join(" ");
}

function ngCourseIsHiddenFromStudents(course = {}) {
  const status = String(course.status || "active").toLowerCase();
  const text = ngSafetyText(course.name, course.description, course.category, course.course_type);
  return Boolean(
    ["archived", "inactive", "draft"].includes(status) ||
    course.student_visible === false ||
    course.is_internal_test === true ||
    course.internal_only === true ||
    text.includes("private live flow test") ||
    text.includes("internal live-class test") ||
    text.includes("internal test")
  );
}

function ngSessionIsInternalTestOrHidden(session = {}) {
  const status = String(session.status || "scheduled").toLowerCase();
  const text = ngSafetyText(session.topic, session.title, session.description, session.cancelled_reason, session.source, session.type);
  return Boolean(
    session.archived_from_active === true ||
    session.no_class_placeholder === true ||
    session.student_visible === false ||
    ["archived", "cancelled", "canceled"].includes(status) ||
    text.includes("ng live flow test") ||
    text.includes("admin classroom check") ||
    text.includes("host app + student join") ||
    text.includes("private test") ||
    text.includes("internal live-class test") ||
    text.includes("holiday / no live class") ||
    text.includes("holiday/no live class") ||
    text.includes("no live class") ||
    text.includes("no class today") ||
    text.includes("tutor unavailable")
  );
}

function ngLiveSessionsCompeteForSameStudentJoin(left = {}, right = {}) {
  if (!left?.id || !right?.id) return false;
  if (String(left.course_id || "") !== String(right.course_id || "")) return false;
  if (String(left.scheduled_date || "") !== String(right.scheduled_date || "")) return false;

  const leftStart = ngSessionDateTimeMs(left);
  const rightStart = ngSessionDateTimeMs(right);
  if (leftStart && rightStart) return Math.abs(leftStart - rightStart) <= 10 * 60 * 1000;

  return String(left.scheduled_time || "").trim() === String(right.scheduled_time || "").trim();
}

function ngStudentJoinAuthorityRank(session = {}) {
  const timestamp = (value) => {
    const parsed = new Date(value || "").getTime();
    return Number.isFinite(parsed) ? parsed : 0;
  };
  const hasVerifiedJoin = Boolean(
    hasRealZoomMeetingId(session.zoom_meeting_id) &&
    ngManualLiveJoinUrl(session)
  );

  return [
    session.student_join_authoritative_at ? 1 : 0,
    timestamp(session.student_join_authoritative_at),
    session.host_launch_requested_at ? 1 : 0,
    timestamp(session.host_launch_requested_at),
    session.zoom_host_gate_verified_at || session.auto_zoom_host_gated_at || session.zoom_waiting_room_disabled_at || session.auto_zoom_opened_at ? 1 : 0,
    hasVerifiedJoin ? 1 : 0,
    hasRealZoomMeetingId(session.zoom_meeting_id) ? 1 : 0,
    session.roadmap_day_id ? 1 : 0,
    timestamp(session.updated_at || session.created_at),
  ];
}

function ngCompareStudentJoinAuthority(left = {}, right = {}) {
  const leftRank = ngStudentJoinAuthorityRank(left);
  const rightRank = ngStudentJoinAuthorityRank(right);
  for (let index = 0; index < Math.max(leftRank.length, rightRank.length); index += 1) {
    const difference = Number(rightRank[index] || 0) - Number(leftRank[index] || 0);
    if (difference) return difference;
  }
  return String(left.id || "").localeCompare(String(right.id || ""));
}

function ngPickAuthoritativeStudentJoinSession(db = {}, requestedSession = {}) {
  const candidates = Object.values(db.liveSessions || {})
    .filter((session) => !ngSessionIsInternalTestOrHidden(session))
    .filter((session) => ngLiveSessionsCompeteForSameStudentJoin(requestedSession, session))
    .sort(ngCompareStudentJoinAuthority);
  return candidates[0] || requestedSession || null;
}

function ngDeduplicateStudentJoinSessions(db = {}, sessions = []) {
  const selected = [];
  for (const session of sessions) {
    const collisionIndex = selected.findIndex((existing) => {
      return ngLiveSessionsCompeteForSameStudentJoin(existing, session);
    });
    if (collisionIndex < 0) {
      selected.push(session);
      continue;
    }
    if (ngCompareStudentJoinAuthority(session, selected[collisionIndex]) < 0) {
      selected[collisionIndex] = session;
    }
  }
  return selected.sort((a, b) => (ngSessionDateTimeMs(a) || 0) - (ngSessionDateTimeMs(b) || 0));
}

function ngMarkAuthoritativeStudentJoinSession(db = {}, session = {}, actorId = "admin") {
  const now = new Date().toISOString();
  const competing = Object.values(db.liveSessions || {})
    .filter((candidate) => !ngSessionIsInternalTestOrHidden(candidate))
    .filter((candidate) => ngLiveSessionsCompeteForSameStudentJoin(session, candidate));

  for (const candidate of competing) {
    if (String(candidate.id) === String(session.id)) {
      candidate.student_join_authoritative_at = now;
      candidate.student_join_authoritative_by = actorId;
      candidate.host_launch_requested_at = now;
      candidate.student_join_superseded_by = null;
      candidate.student_join_superseded_at = null;
    } else {
      candidate.student_join_superseded_by = session.id;
      candidate.student_join_superseded_at = now;
    }
    candidate.updated_at = now;
    db.liveSessions[candidate.id] = candidate;
  }

  return {
    changed: competing.length > 0,
    authoritative_session_id: session.id,
    competing_session_ids: competing.map((candidate) => candidate.id),
    superseded_session_ids: competing
      .filter((candidate) => String(candidate.id) !== String(session.id))
      .map((candidate) => candidate.id),
    marked_at: now,
  };
}

function ngStudentSessionCanShowInLiveList(session = {}) {
  return !ngSessionIsInternalTestOrHidden(session);
}

function ngStudentSessionCanShowAsNext(session = {}, today = todayKey()) {
  if (ngSessionIsInternalTestOrHidden(session)) return false;
  const computed = ngSessionComputedStatus(session);
  if (!["live", "scheduled"].includes(computed)) return false;
  return computed === "live" || String(session.scheduled_date || "") >= today;
}

function ngCompactNotesMeta(note = null) {
  if (!note) {
    return {
      available: false,
      published: false,
      notes_available: false,
      transcript_available: false,
      recording_available: false,
      recording_url: null,
      transcript_url: null,
      updated_at: null,
    };
  }
  const notesText = String(note.notes || note.cleaned_notes || note.summary || "").trim();
  const transcriptText = String(note.transcript_text || note.transcript || "").trim();
  const recordingUrl = note.recording_url || note.zoom_recording_url || note.recording_link || null;
  const transcriptUrl = note.transcript_url || null;
  const published = note.is_published !== false && String(note.status || "published").toLowerCase() !== "draft";
  return {
    available: published && Boolean(notesText || transcriptText || recordingUrl || transcriptUrl),
    published,
    notes_available: published && Boolean(notesText),
    transcript_available: published && Boolean(transcriptText || transcriptUrl),
    recording_available: published && Boolean(recordingUrl),
    recording_url: recordingUrl,
    transcript_url: transcriptUrl,
    updated_at: note.updated_at || note.created_at || null,
  };
}

function ngCompactSessionForLiveCenter(db, session, course = null) {
  const safe = sanitizeLiveSession(session);
  const note = db.notes?.[String(session.id)] || null;
  const notesMeta = ngCompactNotesMeta(note);
  const manualJoinUrl = ngManualLiveJoinUrl(session);
  const recordingUrl = notesMeta.recording_url || safe.recording_url || null;
  const computed_status = ngSessionComputedStatus(session);
  return {
    ...safe,
    computed_status,
    join_url: manualJoinUrl,
    zoom_join_url: manualJoinUrl,
    zoom_url: manualJoinUrl,
    has_join_url: Boolean(manualJoinUrl),
    has_zoom_url: Boolean(manualJoinUrl),
    recording_url: recordingUrl,
    has_recording: Boolean(recordingUrl),
    notes_meta: notesMeta,
    notes_available: notesMeta.notes_available,
    transcript_available: notesMeta.transcript_available,
    recording_available: notesMeta.recording_available || Boolean(recordingUrl),
    course_id: safe.course_id || course?.id || null,
    course_name: course?.name || safe.course_name || "Course",
  };
}

function ngBuildStudentCourseBundle(db, user, course, { sessionLimit = null } = {}) {
  const access = ngStudentEnrollmentStatusForCourse(db, user, course.id);
  if (!ngStudentHasCourseAccessStatus(access.status)) return null;

  const roadmap = buildProgressSummary({ db, courseId: course.id, userId: user.id });
  const todayRoadmapDay = roadmap.today_day?.id
    ? ngFindRoadmapDay(db, { courseId: course.id, dayId: roadmap.today_day.id })
    : ngFindRoadmapDay(db, { courseId: course.id });
  const dailyTaskPacket = todayRoadmapDay
    ? ngSanitizeDailyTaskPacket(db, { courseId: course.id, userId: user.id, day: todayRoadmapDay })
    : null;
  const attempts = getStudentAttempts(db, course.id, user.id);
  const perf = performanceFromAttempts(attempts);
  const streak = ngComputeStudentStudyStreakWithFreeze(db, { courseId: course.id, userId: user.id });
  const assessments = Object.values(db.assessments || {}).filter((a) => String(a.course_id) === String(course.id) && a.is_published);
  const assessmentsForStudent = assessments.map((assessment) => {
    const attempt = db.assessmentAttempts?.[assessmentAttemptKey(assessment.id, user.id)] || null;
    return sanitizeAssessmentForStudent(assessment, attempt);
  });
  const completedAssessments = assessmentsForStudent.filter((assessment) => assessment.result_visible === true || assessment.attempt_status === "completed");
  const rawStudentSessions = Object.values(db.liveSessions || {})
    .filter((session) => String(session.course_id || "") === String(course.id))
    .filter((session) => ngStudentSessionCanShowInLiveList(session))
    .sort((a, b) => (ngSessionDateTimeMs(a) || 0) - (ngSessionDateTimeMs(b) || 0));
  const sessionsAll = ngDeduplicateStudentJoinSessions(db, rawStudentSessions);

  const today = todayKey();
  const todaySession = sessionsAll.find((session) => String(session.scheduled_date || "") === today && ngStudentSessionCanShowAsNext(session, today)) || null;
  const nextSession = sessionsAll.find((session) => ngStudentSessionCanShowAsNext(session, today)) || null;
  const upcomingSessions = sessionsAll
    .filter((session) => ngStudentSessionCanShowAsNext(session, today))
    .slice(0, 5)
    .map((session) => ngCompactSessionForLiveCenter(db, session, course));

  const sessionsForList = sessionLimit
    ? sessionsAll.slice(0, Number(sessionLimit)).map((session) => ngCompactSessionForLiveCenter(db, session, course))
    : sessionsAll.map((session) => ngCompactSessionForLiveCenter(db, session, course));

  let plan = { name: access.status === "paid" ? (access.plan?.name || "Active") : access.status === "demo_active" ? "Demo" : access.status, days_left: null, is_demo: access.status.startsWith("demo") };
  if (access.status.startsWith("demo") && access.demo_expiry) {
    plan.days_left = Math.max(0, Math.ceil((new Date(`${access.demo_expiry}T23:59:59`).getTime() - Date.now()) / 86400000));
  }
  if (access.status === "paid" && access.access_expires_at) {
    plan.days_left = ngPaidAccessDaysRemaining(access.enrollment);
  }

  return {
    course: sanitizeCourse(course),
    status: access.status,
    enrollment: access.enrollment,
    demo_expiry: access.demo_expiry,
    access_expires_at: access.access_expires_at,
    plan,
    summary: {
      plan,
      roadmap,
      today: roadmap.today_day,
      streak_days: streak.study_streak,
      streak: streak.study_streak,
      best_streak: streak.best_streak,
      total_study_days: streak.total_study_days,
      last_activity_date: streak.last_activity_date,
      streak_milestone: streak.streak_milestone,
      performance: {
        study_streak: streak.study_streak,
        best_streak: streak.best_streak,
        total_study_days: streak.total_study_days,
        streak_milestone: streak.streak_milestone,
        total_study_time_hours: 0,
        average_mock_score: perf.average_score,
        latest_mock_score: perf.latest_score,
        best_mock_score: perf.best_score,
        attempts_count: perf.attempts_count,
      },
      focus_areas: perf.focus_areas,
      leaderboard: (() => {
        const entry = db.leaderboard?.[courseUserKey(course.id, user.id)] || {};
        return {
          points: entry.total_points || 0,
          attendance_points: entry.attendance_points || 0,
          task_points: entry.task_points || 0,
          quiz_points: entry.quiz_points || entry.assessment_points || 0,
        };
      })(),
      assessments: {
        available: assessments.length,
        completed: completedAssessments.length,
        pending: Math.max(0, assessments.length - completedAssessments.length),
      },
    },
    today: dailyTaskPacket || roadmap.today_day,
    dailyTask: {
      packet: dailyTaskPacket,
      summary: roadmap,
      leaderboard: db.leaderboard?.[courseUserKey(course.id, user.id)] || null,
    },
    roadmapItems: [],
    assessments: assessmentsForStudent,
    today_live_session: todaySession ? ngCompactSessionForLiveCenter(db, todaySession, course) : null,
    next_live_session: nextSession ? ngCompactSessionForLiveCenter(db, nextSession, course) : null,
    upcoming_sessions: upcomingSessions,
    sessions: sessionsForList,
    sessions_count: sessionsAll.length,
  };
}

app.get("/student/dashboard/bootstrap", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const requestedCourseId = String(req.query.course_id || "").trim();
    const allCourses = Object.values(db.courses || {})
      .map(sanitizeCourse)
      .filter((course) => !ngCourseIsHiddenFromStudents(course));
    const coursesToCheck = requestedCourseId ? allCourses.filter((course) => String(course.id) === requestedCourseId) : allCourses;
    const autoLiveSync = ngAutoSyncRoadmapLiveSessionsForCourses(db, coursesToCheck.map((course) => course.id), {
      actorId: user.id || "student_dashboard_bootstrap",
    });

    if (autoLiveSync.changed) await writeLiveDb(db);

    const featureAccess = getStudentFeatureAccess(db, user);
    const accessSummary = ngBuildStudentAccessSummary(db, user, coursesToCheck);
    const bundles = coursesToCheck
      .map((course) => ngBuildStudentCourseBundle(db, user, course, { sessionLimit: 5 }))
      .filter(Boolean)
      .sort((a, b) => {
        const ap = a.status === "paid" ? 0 : 1;
        const bp = b.status === "paid" ? 0 : 1;
        return ap - bp || String(a.course?.name || "").localeCompare(String(b.course?.name || ""));
      });
    const primary = bundles[0] || null;
    const announcements = ngFilterDismissedAnnouncements(
      db,
      user.id,
      Object.values(db.announcements || {})
        .map(sanitizeAnnouncement)
        .filter((item) => String(item.status || "active") === "active" && (!item.course_id || !primary?.course?.id || String(item.course_id) === String(primary.course.id)))
    )
      .sort(sortNewestFirst)
      .slice(0, Number(req.query.announcement_limit || 5));
    // Rebuild the current user's leaderboard from pointEvents before returning dashboard data.
    // This prevents refreshes from showing old task points after a Mark Reviewed action.
    for (const bundle of bundles) {
      if (bundle?.course?.id) {
        updateLeaderboard(db, { courseId: bundle.course.id, userId: user.id, userName: user.name || user.email || "Student" });
      }
    }
    await writeLiveDb(db);

    const leaderboard = primary?.course?.id
      ? ngPublicLeaderboardList(db, primary.course.id, { limit: 10 })
      : [];

    res.json({
      success: true,
      source: "student_dashboard_bootstrap_v184",
      user: sanitizeUser(user),
      feature_access: featureAccess,
      features: featureAccess,
      courses: bundles.map((bundle) => bundle.course),
      course_bundles: bundles,
      active_courses: bundles,
      access_summary: accessSummary,
      expired_access: accessSummary.filter((item) => item.requires_renewal),
      has_expired_access: accessSummary.some((item) => item.requires_renewal),
      primary_course: primary?.course || null,
      primary_bundle: primary,
      announcements,
      leaderboard,
      auto_live_sync: autoLiveSync,
      counts: {
        courses: bundles.length,
        access_records: accessSummary.length,
        expired_access: accessSummary.filter((item) => item.requires_renewal).length,
        announcements: announcements.length,
        leaderboard: leaderboard.length,
      },
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message || "Failed to load dashboard bootstrap" });
  }
});

