function ngStudentNotesSessionIsNoClass(session = {}) {
  const status = String(session.status || "").trim().toLowerCase();
  const text = [
    session.topic,
    session.title,
    session.description,
    session.cancelled_reason,
    session.status,
    session.type,
    session.source,
  ].map((value) => String(value || "").toLowerCase()).join(" ");

  return Boolean(
    session.no_class_placeholder === true ||
    session.is_no_class_day === true ||
    session.is_schedule_placeholder === true ||
    session.holiday === true ||
    ["holiday", "no_class", "no-class", "no class", "cancelled", "canceled"].includes(status) ||
    text.includes("holiday / no live class") ||
    text.includes("holiday/no live class") ||
    text.includes("no live class") ||
    text.includes("no class today") ||
    text.includes("tutor unavailable") ||
    text.includes("schedule placeholder")
  );
}

function ngStudentNotesVisibleText(note = {}) {
  return [
    note.cleaned_notes,
    note.student_notes,
    note.notes,
    note.content,
    note.summary,
  ]
    .map((value) => String(value || "").trim())
    .find(Boolean) || "";
}

function ngStudentNotesIsPublished(note = {}) {
  if (!note) return false;
  const status = String(note.status || "").trim().toLowerCase();
  if (["draft", "unpublished", "archived", "hidden"].includes(status)) return false;
  if (note.is_published === false || note.published === false) return false;
  return Boolean(ngStudentNotesVisibleText(note));
}

function ngStudentNotesUpdatedAtMs(note = {}) {
  const parsed = new Date(note.updated_at || note.published_at || note.created_at || 0).getTime();
  return Number.isFinite(parsed) ? parsed : 0;
}

function ngStudentNotesContentIdentity(record = {}, fallback = null) {
  const title = [
    record.title,
    record.topic,
    record.notes_title,
    record.session_title,
    record.lecture_title,
  ].map((value) => String(value || "").trim()).find(Boolean) || "";
  const titleMatch = title.match(/^(.+?)(?:\s*[—–-]\s*|\s+)day\s*0*(\d{1,3})\b/i);
  const explicitSystem = String(
    record.system ||
    record.chapter ||
    record.medical_system ||
    record.organ_system ||
    record.system_name ||
    ""
  ).trim();
  const fallbackSystem = String(
    fallback?.system ||
    fallback?.chapter ||
    fallback?.medical_system ||
    fallback?.organ_system ||
    fallback?.system_name ||
    ""
  ).trim();
  const rawSystem = explicitSystem || String(titleMatch?.[1] || "").trim() || fallbackSystem;
  const normalizedSystem = rawSystem
    ? String(ngNormalizeMasterMapSystemName(rawSystem) || rawSystem).trim().toLowerCase()
    : "";

  const explicitDay = Number(
    record.system_day ??
    record.day_in_system ??
    record.systemDay ??
    0
  );
  const titleDay = Number(titleMatch?.[2] || 0);
  const systemDay = Number.isInteger(explicitDay) && explicitDay > 0
    ? explicitDay
    : Number.isInteger(titleDay) && titleDay > 0
      ? titleDay
      : 0;

  return { system: normalizedSystem, system_day: systemDay };
}

function ngResolveStudentNotesForSession(db = {}, session = null, { publishedOnly = false } = {}) {
  const targetSessionId = String(session?.id || "").trim();
  if (!targetSessionId) return null;

  const targetCourseId = String(session?.course_id || "").trim();
  const targetRoadmapDayId = String(session?.roadmap_day_id || "").trim();
  const targetRoadmapDay = ngFindRoadmapDayForLiveSession(db, session);
  const targetIdentity = ngStudentNotesContentIdentity(targetRoadmapDay || session, session);
  const candidates = [];

  for (const [noteKey, note] of Object.entries(db.notes || {})) {
    if (!note || typeof note !== "object") continue;

    const declaredSessionId = String(note.session_id || note.live_session_id || "").trim();
    const sourceSession = db.liveSessions?.[declaredSessionId] || db.liveSessions?.[String(noteKey)] || null;
    const candidateCourseId = String(note.course_id || sourceSession?.course_id || "").trim();
    if (targetCourseId && candidateCourseId && candidateCourseId !== targetCourseId) continue;

    const storageKeyMatch = String(noteKey) === targetSessionId;
    const declaredSessionMatch = declaredSessionId === targetSessionId;
    const noteRoadmapMatch = Boolean(
      targetRoadmapDayId &&
      String(note.roadmap_day_id || note.day_id || "").trim() === targetRoadmapDayId
    );
    const sourceSessionRoadmapMatch = Boolean(
      targetRoadmapDayId &&
      String(sourceSession?.roadmap_day_id || "").trim() === targetRoadmapDayId
    );
    const noteIdentity = ngStudentNotesContentIdentity(note, sourceSession);
    const identitiesComparable = Boolean(
      targetIdentity.system &&
      targetIdentity.system_day &&
      noteIdentity.system &&
      noteIdentity.system_day
    );
    const courseSystemDayMatch = Boolean(
      targetCourseId &&
      candidateCourseId === targetCourseId &&
      identitiesComparable &&
      noteIdentity.system === targetIdentity.system &&
      noteIdentity.system_day === targetIdentity.system_day
    );
    const contentIdentityConflict = Boolean(
      identitiesComparable &&
      !courseSystemDayMatch
    );

    if (!storageKeyMatch && !declaredSessionMatch && !noteRoadmapMatch && !sourceSessionRoadmapMatch && !courseSystemDayMatch) continue;
    // A roadmap recovery can reuse a live-session id for a later class. When a
    // note retains an explicit system/day identity that conflicts with that
    // reused session, the stale session link must not override its content
    // identity. An explicit matching roadmap-day id remains authoritative.
    if (contentIdentityConflict && !noteRoadmapMatch) continue;
    if (publishedOnly && !ngStudentNotesIsPublished(note)) continue;

    let matchScore = 0;
    let matchedBy = "source_session_roadmap_day_id";
    if (noteRoadmapMatch) {
      matchScore = 700;
      matchedBy = "roadmap_day_id";
    } else if (storageKeyMatch) {
      matchScore = 600;
      matchedBy = "storage_key";
    } else if (declaredSessionMatch) {
      matchScore = 500;
      matchedBy = "session_id";
    } else if (courseSystemDayMatch) {
      matchScore = 450;
      matchedBy = "course_system_day";
    } else if (sourceSessionRoadmapMatch) {
      matchScore = 300;
    }

    if (courseSystemDayMatch) matchScore += 250;
    if (note.published === true || note.is_published === true) matchScore += 25;
    candidates.push({
      note,
      note_key: String(noteKey),
      matched_by: matchedBy,
      match_score: matchScore,
      updated_at_ms: ngStudentNotesUpdatedAtMs(note),
    });
  }

  candidates.sort((left, right) =>
    Number(right.match_score || 0) - Number(left.match_score || 0) ||
    Number(right.updated_at_ms || 0) - Number(left.updated_at_ms || 0) ||
    String(left.note_key || "").localeCompare(String(right.note_key || ""))
  );
  return candidates[0] || null;
}

function ngStudentNotesRoadmapSessionAuthority(db = {}, session = {}) {
  const day = ngFindRoadmapDayForLiveSession(db, session);
  const authoritativeSessionId = String(day?.live_session_id || day?.session_id || "").trim();
  if (authoritativeSessionId && authoritativeSessionId === String(session.id || "")) return 1000;
  if (session.roadmap_day_id) return 100;
  return 0;
}

function ngStudentNotesResolvedSessionRows(db = {}, sessions = []) {
  const selectedByNoteKey = new Map();

  for (const session of sessions) {
    const resolved = ngResolveStudentNotesForSession(db, session, { publishedOnly: true });
    if (!resolved?.note) continue;

    const selectionRank =
      ngStudentNotesRoadmapSessionAuthority(db, session) +
      Number(resolved.match_score || 0);
    const existing = selectedByNoteKey.get(resolved.note_key);
    if (!existing || selectionRank > existing.selection_rank) {
      selectedByNoteKey.set(resolved.note_key, {
        session,
        note: resolved.note,
        selection_rank: selectionRank,
      });
    }
  }

  return Array.from(selectedByNoteKey.values());
}

function ngStudentNotesSessionForList(db = {}, session = {}, course = null, resolvedNote = null) {
  const safe = sanitizeLiveSession(session);
  const note = resolvedNote || ngResolveStudentNotesForSession(db, session, { publishedOnly: true })?.note || null;
  const notesText = ngStudentNotesVisibleText(note);
  return {
    ...safe,
    course_id: safe.course_id || course?.id || null,
    course_name: course?.name || safe.course_name || "Course",
    notes_available: true,
    has_notes: true,
    has_clean_notes: true,
    notes_meta: {
      available: true,
      published: true,
      notes_available: true,
      transcript_available: Boolean(note?.transcript_text || note?.transcript || note?.transcript_url),
      recording_available: Boolean(note?.recording_url || safe.recording_url),
      recording_url: note?.recording_url || safe.recording_url || null,
      transcript_url: note?.transcript_url || null,
      updated_at: note?.updated_at || note?.created_at || null,
      preview: notesText.slice(0, 220),
    },
  };
}

app.get("/student/notes/sessions", async (req, res) => {
  try {
    const { user } = await getAuthenticatedUser(req);
    const db = await readLiveDb();
    const requestedCourseId = String(req.query.course_id || req.query.courseId || "").trim();

    const selfHeal = requestedCourseId
      ? ngMaybeSelfHealDemoEnrollment(db, user, { courseId: requestedCourseId, source: "student_notes_sessions" })
      : ngMaybeSelfHealDemoEnrollment(db, user, { source: "student_notes_sessions" });

    if (selfHeal.changed) await writeLiveDb(db);

    const allCourses = Object.values(db.courses || {})
      .map(sanitizeCourse)
      .filter((course) => !ngCourseIsHiddenFromStudents(course));

    const coursesToCheck = requestedCourseId
      ? allCourses.filter((course) => String(course.id) === requestedCourseId)
      : allCourses;

    // Student Notes is a read path. Schedule reconciliation here could rewrite
    // the full database on every page visit and block unrelated requests.
    const autoRoadmapSync = {
      checked: 0,
      changed: false,
      skipped: true,
      reason: "student_notes_read_only",
    };

    const bundles = coursesToCheck.map((course) => {
      const access = ngStudentEnrollmentStatusForCourse(db, user, course.id);
      if (!ngStudentHasCourseAccessStatus(access.status)) return null;

      const eligibleSessions = Object.values(db.liveSessions || {})
        .filter((session) => String(session.course_id || "") === String(course.id))
        .filter((session) => !ngStudentNotesSessionIsNoClass(session));

      const sessions = ngStudentNotesResolvedSessionRows(db, eligibleSessions)
        .sort((a, b) => {
          return String(b.session?.scheduled_date || "").localeCompare(String(a.session?.scheduled_date || "")) ||
            String(b.session?.scheduled_time || "").localeCompare(String(a.session?.scheduled_time || ""));
        })
        .map((row) => ngStudentNotesSessionForList(db, row.session, course, row.note));

      return {
        course: sanitizeCourse(course),
        status: access.status,
        enrollment: access.enrollment,
        demo_expiry: access.demo_expiry,
        access_expires_at: access.access_expires_at,
        count: sessions.length,
        sessions,
      };
    }).filter(Boolean);

    res.json({
      success: true,
      source: "student_notes_sessions_v225_course_system_day_resolver",
      strategy: "published_notes_resolved_by_storage_session_roadmap_or_exact_course_system_day_identity",
      student_notes_resolver_build: STUDENT_NOTES_RESOLVER_BUILD,
      count: bundles.reduce((sum, bundle) => sum + Number(bundle.count || 0), 0),
      course_bundles: bundles,
      bundles,
      sessions: requestedCourseId ? (bundles[0]?.sessions || []) : [],
      demo_access_self_heal: selfHeal,
      auto_roadmap_sync: autoRoadmapSync,
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: error.message || "Failed to load student notes sessions",
    });
  }
});


