      user_name: user.name || user.email || "Student",
      user_role: user.role || "student",
      is_ai_generated: false,
      is_pinned: false,
      is_locked: false,
      status: "active",
      comments_count: 0,
      reactions_count: 0,
      created_at: now,
      updated_at: now,
