let crmWriteQueue = Promise.resolve();

function nowIso() {
  return new Date().toISOString();
}

function normalizeCrmString(value, fallback = "") {
  return String(value ?? fallback).trim();
}

function normalizeCrmLower(value, fallback = "") {
  return normalizeCrmString(value, fallback).toLowerCase();
}

function ensureCrmArray(db, key) {
  if (!Array.isArray(db[key])) db[key] = [];
  return db[key];
}

function withTimestamps(record = {}, existing = null) {
  const now = nowIso();
  return {
    ...record,
    id: record.id || existing?.id || uuid(),
    created_at: existing?.created_at || record.created_at || now,
    updated_at: now,
  };
}

function safeCrmJson(value, fallback) {
  try {
    if (typeof value === "string") return JSON.parse(value);
    return value ?? fallback;
  } catch {
    return fallback;
  }
}


// v190h: process-lifetime CRM cache.
// The former 2.5-second TTL reparsed the full CRM JSON continually while the
// one-second automation heartbeat was active. A single Render instance is the
// only writer, so the cache is refreshed after every atomic save and released
// naturally on restart.
let crmReadCache = null;
let crmReadCacheAt = 0;
let crmReadInFlight = null;
let crmReadOnlySnapshotCache = null;
let crmReadOnlySnapshotCacheAt = 0;
let crmReadOnlySnapshotInFlight = null;
// Personal Tutor consumes only administrator-approved, read-only success-story
// strategies from this snapshot. CRM writes replace the cache immediately, so
// a longer read TTL removes repeated multi-megabyte disk reads without hiding
// an in-app edit or weakening the approval boundary.
const CRM_READ_ONLY_SNAPSHOT_TTL_MS = Math.max(1000, Math.min(300000, Number(process.env.CRM_READ_ONLY_SNAPSHOT_TTL_MS || 300000)));

function cloneCrmDbForRequest(db) {
  if (!db) return null;

  // Shallow clone keeps requests from replacing the root object while avoiding
  // huge deep-clone memory spikes. Arrays are intentionally shared during the
  // short cache window; writeCrmDb refreshes the cache after every save.
  return {
    ...db,
    settings: { ...(db.settings || {}) },
  };
}


