// -----------------------------------------------------------------------------
// Multi-channel CRM Automation Engine + Provider Layer
// -----------------------------------------------------------------------------
// WhatsApp Cloud API is active when WHATSAPP_ACCESS_TOKEN and
// WHATSAPP_PHONE_NUMBER_ID exist. Email/SMS/social channels share the same
// message/automation storage and can be attached later without changing the
// frontend contract.

const CRM_AUTOMATION_CRON_SECRET = process.env.CRM_AUTOMATION_CRON_SECRET || process.env.ADMIN_API_SECRET || AUTH_JWT_SECRET;
const WHATSAPP_GRAPH_VERSION = process.env.WHATSAPP_GRAPH_VERSION || "v20.0";

function normalizeAutomationChannel(value = "whatsapp") {
  const clean = String(value || "whatsapp").trim().toLowerCase().replace(/[^a-z0-9_]+/g, "_");
  if (["wa", "meta_whatsapp", "whatsapp_cloud"].includes(clean)) return "whatsapp";
  if (["e_mail", "gmail", "smtp", "sendgrid"].includes(clean)) return "email";
  if (["text", "twilio_sms"].includes(clean)) return "sms";
  if (["fb", "facebook_messenger", "messenger"].includes(clean)) return "messenger";
  if (["ig", "instagram_dm"].includes(clean)) return "instagram";
  return clean || "whatsapp";
}

// -----------------------------------------------------------------------------
// NEXTGEN GLOBAL CHANNEL RESOLVER
// -----------------------------------------------------------------------------
// Supports frontend values:
// - auto / global: backend chooses the best available channel.
// - lead_current_channel: use the channel where the lead is already talking.
// Explicit channels like whatsapp/email/sms still work exactly as before.
// -----------------------------------------------------------------------------

const CRM_CHANNEL_AUTO_VALUES = new Set(["", "auto", "global", "lead_current_channel", "lead_current", "current", "current_channel"]);
const CRM_VALID_SEND_CHANNELS = new Set([
  "whatsapp",
  "email",
  "sms",
  "telegram",
  "facebook",
  "messenger",
  "instagram",
  "reddit",
  "linkedin",
  "youtube",
  "tiktok",
  "twitter",
  "x",
  "discord",
  "other",
]);

function normalizeCrmSendChannel(value = "") {
  const clean = normalizeAutomationChannel(value || "");
  if (["facebook_messenger", "fb_messenger", "messenger", "meta_messenger"].includes(clean)) return "facebook";
  if (clean === "fb") return "facebook";
  if (clean === "ig") return "instagram";
  if (clean === "x") return "twitter";
  if (typeof normalizeSocialPlatform === "function") {
    const social = normalizeSocialPlatform(clean);
    if (social && social !== "other") return social;
  }
  return clean || "other";
}

function getLeadCurrentChannel(lead = {}) {
  return (
    lead.current_channel ||
    lead.currentChannel ||
    lead.last_channel ||
    lead.lastChannel ||
    lead.preferred_channel ||
    lead.preferredChannel ||
    lead.source_platform ||
    lead.platform ||
    lead.channel ||
    lead.source ||
    ""
  );
}

function leadHasRecipientForChannel(lead = {}, channel = "") {
  const clean = normalizeCrmSendChannel(channel);
  if (clean === "email") return Boolean(lead.email || lead.student_email || lead.customer_email);
  if (clean === "telegram") return Boolean(lead.telegram_chat_id || lead.chat_id || lead.telegram_id || lead.platform_contact_id || lead.telegram_id || lead.telegram_username);
  if (clean === "whatsapp") return Boolean(lead.whatsapp || lead.whatsapp_phone || lead.wa_id || lead.phone || lead.mobile);
  if (clean === "facebook") return Boolean(lead.facebook_sender_id || lead.facebook_id || lead.facebook_chat_id || lead.platform_contact_id);
  if (clean === "instagram") return Boolean(lead.instagram_sender_id || lead.instagram_id || lead.instagram_chat_id || lead.platform_contact_id);
  if (clean === "discord") return Boolean(lead.discord_chat_id || lead.discord_channel_id || lead.discord_id || lead.platform_contact_id);
  if (["reddit", "linkedin", "youtube", "tiktok", "twitter"].includes(clean)) {
    return Boolean(
      lead.platform_contact_id ||
      lead[`${clean}_id`] ||
      lead[`${clean}_chat_id`] ||
      lead[`${clean}_username`] ||
      lead.username ||
      lead.platform_username
    );
  }
  if (clean === "sms") return Boolean(lead.phone || lead.mobile || lead.whatsapp || lead.whatsapp_phone);
  return Boolean(lead.platform_contact_id || lead.phone || lead.email || lead.username || lead.platform_username);
}

function resolveCrmChannel({ requestedChannel = "", lead = null, template = null, fallback = "whatsapp" } = {}) {
  const rawRequested = String(requestedChannel || template?.channel || template?.send_channel || "").trim();
  const normalizedRequested = normalizeCrmSendChannel(rawRequested);

  if (normalizedRequested && !CRM_CHANNEL_AUTO_VALUES.has(normalizedRequested)) {
    return CRM_VALID_SEND_CHANNELS.has(normalizedRequested) ? normalizedRequested : normalizeCrmSendChannel(fallback || "whatsapp");
  }

  const leadCurrent = normalizeCrmSendChannel(getLeadCurrentChannel(lead || {}));
  if (leadCurrent && !CRM_CHANNEL_AUTO_VALUES.has(leadCurrent) && leadHasRecipientForChannel(lead || {}, leadCurrent)) {
    return leadCurrent;
  }

  const templateChannel = normalizeCrmSendChannel(template?.channel || template?.send_channel || "");
  if (templateChannel && !CRM_CHANNEL_AUTO_VALUES.has(templateChannel) && CRM_VALID_SEND_CHANNELS.has(templateChannel)) {
    return templateChannel;
  }

  if (leadHasRecipientForChannel(lead || {}, "whatsapp")) return "whatsapp";
  if (leadHasRecipientForChannel(lead || {}, "email")) return "email";
  if (leadHasRecipientForChannel(lead || {}, "telegram")) return "telegram";
  if (leadHasRecipientForChannel(lead || {}, "sms")) return "sms";
  if (leadHasRecipientForChannel(lead || {}, "messenger")) return "messenger";
  if (leadHasRecipientForChannel(lead || {}, "instagram")) return "instagram";

  return normalizeCrmSendChannel(fallback || "whatsapp");
}


function ngMessageChannel(message = {}) {
  return normalizeCrmSendChannel(
    message.channel ||
      message.platform ||
      message.provider ||
      message.source_platform ||
      message.source ||
      message.transport ||
      ""
  );
}

function resolveCrmChannelForConversation({ requestedChannel = "", lead = null, template = null, latestInbound = null, fallback = "whatsapp" } = {}) {
  const requested = normalizeCrmSendChannel(requestedChannel || "");
  if (requested && !CRM_CHANNEL_AUTO_VALUES.has(requested) && CRM_VALID_SEND_CHANNELS.has(requested)) {
    return requested;
  }

  const inboundChannel = ngMessageChannel(latestInbound || {});
  if (inboundChannel && !CRM_CHANNEL_AUTO_VALUES.has(inboundChannel) && CRM_VALID_SEND_CHANNELS.has(inboundChannel)) {
    return inboundChannel;
  }

  return resolveCrmChannel({ requestedChannel, lead, template, fallback });
}


function getProviderStatus() {
  const hasWhatsapp = Boolean(process.env.WHATSAPP_ACCESS_TOKEN && process.env.WHATSAPP_PHONE_NUMBER_ID);
  const hasTelegram = Boolean(process.env.TELEGRAM_BOT_TOKEN);
  const hasEmail = Boolean(process.env.SMTP_HOST || process.env.SENDGRID_API_KEY || process.env.RESEND_API_KEY);
  const hasFacebook = Boolean(process.env.META_PAGE_ACCESS_TOKEN || process.env.FACEBOOK_PAGE_ACCESS_TOKEN);
  const hasInstagram = Boolean(process.env.INSTAGRAM_ACCESS_TOKEN || process.env.INSTAGRAM_PAGE_ACCESS_TOKEN || process.env.META_PAGE_ACCESS_TOKEN);

  return {
    whatsapp: {
      key: "whatsapp",
      channel: "whatsapp",
      name: "Meta WhatsApp Cloud API",
      configured: hasWhatsapp,
      ready: hasWhatsapp,
      enabled: hasWhatsapp,
      status: hasWhatsapp ? "active" : "not_configured",
      business_account_id: process.env.WHATSAPP_BUSINESS_ACCOUNT_ID || null,
      phone_number_id: process.env.WHATSAPP_PHONE_NUMBER_ID || null,
      supports: ["text", "template", "webhook", "automation", "bulk"],
      notes: hasWhatsapp
        ? "WhatsApp credentials found. Cold/outside-24h messages may require approved templates."
        : "Add WHATSAPP_ACCESS_TOKEN and WHATSAPP_PHONE_NUMBER_ID.",
    },
    telegram: {
      key: "telegram",
      channel: "telegram",
      name: "Telegram Bot",
      configured: hasTelegram,
      ready: hasTelegram,
      enabled: hasTelegram,
      status: hasTelegram ? "active" : "not_configured",
      bot_configured: hasTelegram,
      webhook_secret_configured: Boolean(process.env.TELEGRAM_WEBHOOK_SECRET),
      supports: ["text", "webhook", "automation", "community_watch"],
      notes: hasTelegram
        ? "Telegram bot token found. Send to numeric chat_id only, not t.me links."
        : "Add TELEGRAM_BOT_TOKEN.",
    },
    email: {
      key: "email",
      channel: "email",
      name: "Email provider",
      configured: hasEmail,
      ready: hasEmail,
      enabled: hasEmail,
      status: hasEmail ? "active" : "not_configured",
      provider: ngEmailTransportStatus().provider,
      supports: ["text", "template", "automation", "bulk"],
      notes: hasEmail
        ? "Email credentials found. Resend, SendGrid, or SMTP can be used."
        : "Add RESEND_API_KEY, SENDGRID_API_KEY, or SMTP_HOST/SMTP_USER/SMTP_PASS.",
    },
    sms: {
      key: "sms",
      channel: "sms",
      name: "SMS provider",
      configured: Boolean(process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN),
      ready: Boolean(process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN),
      enabled: Boolean(process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN),
      supports: ["text", "template", "automation"],
      status: process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN ? "active" : "not_configured",
    },
    facebook: {
      key: "facebook",
      channel: "facebook",
      name: "Facebook Messenger / Page",
      configured: hasFacebook,
      ready: hasFacebook,
      enabled: hasFacebook,
      supports: ["text", "webhook", "automation"],
      status: hasFacebook ? "active" : "manual_first",
      notes: "Facebook/Meta sending may require app permissions and app review.",
    },
    messenger: {
      key: "messenger",
      channel: "messenger",
      name: "Facebook Messenger",
      configured: hasFacebook,
      ready: hasFacebook,
      enabled: hasFacebook,
      supports: ["text", "automation"],
      status: hasFacebook ? "active" : "manual_first",
    },
    instagram: {
      key: "instagram",
      channel: "instagram",
      name: "Instagram DM",
      configured: hasInstagram,
      ready: hasInstagram,
      enabled: hasInstagram,
      supports: ["text", "webhook", "automation"],
      status: hasInstagram ? "active" : "manual_first",
      notes: "Instagram/Meta sending may require app permissions and app review.",
    },
    discord: {
      key: "discord",
      channel: "discord",
      name: "Discord",
      configured: Boolean((process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL) || process.env.DISCORD_BOT_TOKEN),
      ready: Boolean((process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL) || process.env.DISCORD_BOT_TOKEN),
      enabled: Boolean((process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL) || process.env.DISCORD_BOT_TOKEN),
      supports: ["text", "webhook"],
      status: (process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL) || process.env.DISCORD_BOT_TOKEN ? "active" : "not_configured",
    },
  };
}

function normalizePhoneForWhatsapp(value = "") {
  const raw = String(value || "").trim();
  const digits = raw.replace(/[^0-9]/g, "");
  if (!digits) return "";
  return digits;
}

function findLeadByPhoneOrEmail(db, { phone = "", email = "", waId = "" } = {}) {
  const cleanPhone = normalizePhoneForWhatsapp(phone || waId);
  const cleanEmail = normalizeEmail(email || "");
  return ensureCrmArray(db, "leads").find((lead) => {
    const phones = [lead.phone, lead.whatsapp, lead.whatsapp_number, lead.mobile, lead.contact_number, lead.wa_id].map(normalizePhoneForWhatsapp).filter(Boolean);
    const emails = [lead.email, lead.student_email, lead.customer_email].map(normalizeEmail).filter(Boolean);
    return (cleanPhone && phones.includes(cleanPhone)) || (cleanEmail && emails.includes(cleanEmail));
  }) || null;
}

function renderTemplateString(template = "", variables = {}) {
  return String(template || "").replace(/{{\s*([a-zA-Z0-9_.-]+)\s*}}/g, (_, key) => {
    const value = key.split(".").reduce((acc, part) => (acc && acc[part] !== undefined ? acc[part] : undefined), variables);
    return value === undefined || value === null ? "" : String(value);
  });
}

function normalizeTemplateLookupKey(value = "") {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function getMessageTemplateByKey(db, keyOrId = "") {
  const clean = String(keyOrId || "").trim();
  if (!clean) return null;
  const cleanNorm = normalizeTemplateLookupKey(clean);
  return ensureCrmArray(db, "message_templates").find((item) => {
    const candidates = [
      item.id,
      item._id,
      item.uuid,
      item.template_id,
      item.key,
      item.template_key,
      item.slug,
      item.name,
      item.template_name,
      item.meta_template_name,
      item.whatsapp_template_name,
      item.provider_template_name,
    ];
    return candidates.some((x) => {
      const raw = String(x || "").trim();
      return raw === clean || normalizeTemplateLookupKey(raw) === cleanNorm;
    });
  }) || null;
}

function normalizeMessageTemplate(body = {}, existing = null, brandId = null) {
  const channel = normalizeAutomationChannel(body.channel || existing?.channel || "whatsapp");
  return withTimestamps({
    ...(existing || {}),
    ...(body || {}),
    id: body.id || existing?.id || uuid(),
    brand_id: body.brand_id || existing?.brand_id || brandId || null,
    key: normalizeCrmString(body.key || existing?.key || body.name || existing?.name || "template").toLowerCase().replace(/[^a-z0-9]+/g, "_"),
    name: normalizeCrmString(body.name || existing?.name || "Message Template"),
    channel,
    subject: normalizeCrmString(body.subject || existing?.subject || ""),
    body: String(body.body ?? existing?.body ?? body.message ?? ""),
    provider_template_name: normalizeCrmString(
      body.provider_template_name ||
      body.meta_template_name ||
      body.whatsapp_template_name ||
      body.template_name ||
      existing?.provider_template_name ||
      existing?.meta_template_name ||
      existing?.whatsapp_template_name ||
      existing?.template_name ||
      ""
    ),
    meta_template_name: normalizeCrmString(body.meta_template_name || existing?.meta_template_name || body.provider_template_name || body.whatsapp_template_name || body.template_name || ""),
    whatsapp_template_name: normalizeCrmString(body.whatsapp_template_name || existing?.whatsapp_template_name || body.meta_template_name || body.provider_template_name || body.template_name || ""),
    template_name: normalizeCrmString(body.template_name || existing?.template_name || body.meta_template_name || body.whatsapp_template_name || body.provider_template_name || ""),
    meta_language: normalizeWhatsAppLanguageCode(body.meta_language || existing?.meta_language || body.whatsapp_language || existing?.whatsapp_language || body.language_code || body.language || "en"),
    whatsapp_language: normalizeWhatsAppLanguageCode(body.whatsapp_language || existing?.whatsapp_language || body.meta_language || existing?.meta_language || body.language_code || body.language || "en"),
    provider_language_code: normalizeWhatsAppLanguageCode(body.provider_language_code || existing?.provider_language_code || body.meta_language || existing?.meta_language || body.whatsapp_language || existing?.whatsapp_language || body.language_code || body.language || "en"),
    language_code: normalizeWhatsAppLanguageCode(body.language_code || existing?.language_code || body.meta_language || existing?.meta_language || body.whatsapp_language || existing?.whatsapp_language || body.provider_language_code || body.language || "en"),
    language: normalizeCrmString(body.language || existing?.language || body.meta_language || existing?.meta_language || body.language_code || existing?.language_code || "English"),
    category: normalizeCrmString(body.category || existing?.category || "followup"),
    status: normalizeCrmLower(body.status || existing?.status || "active", "active"),
    variables: Array.isArray(body.variables) ? body.variables : existing?.variables || [],
  }, existing);
}

function createMessageLog(db, payload = {}) {
  const channel = normalizeAutomationChannel(payload.channel || "whatsapp");
  const log = withTimestamps({
    id: payload.id || uuid(),
    brand_id: payload.brand_id || null,
    channel,
    provider: payload.provider || channel,
    direction: payload.direction || "outbound",
    lead_id: payload.lead_id || null,
    enrollment_id: payload.enrollment_id || null,
    flow_id: payload.flow_id || null,
    run_id: payload.run_id || null,
    queue_id: payload.queue_id || null,
    template_id: payload.template_id || null,
    to: payload.to || payload.recipient || "",
    from: payload.from || payload.sender || "",
    subject: payload.subject || "",
    text: payload.text || payload.body || "",
    status: payload.status || "queued",
    provider_message_id: payload.provider_message_id || null,
    provider_response: payload.provider_response || null,
    error: payload.error || null,
    sent_at: payload.sent_at || null,
    delivered_at: payload.delivered_at || null,
    read_at: payload.read_at || null,
    metadata: payload.metadata || {},
  });
  ensureCrmArray(db, "message_logs").push(log);
  ensureCrmArray(db, "outbound_messages").push(log);
  return log;
}

const WHATSAPP_TEMPLATE_NAME_ALIASES = {
  meta_ad_first_message: "meta_ad_first_message",
  meta_first_message: "meta_ad_first_message",
  first_message_intro: "meta_ad_first_message",
  greeting_exam_type_question: "greeting_exam_type_question",
  exam_type_question: "greeting_exam_type_question",
  sunday_first_message: "greeting_exam_type_question",
  five_min_live_session_reminder: "five_minute_reminder",
  five_minute_reminder: "five_minute_reminder",
  live_session_1pm_reminder: "live_session_link_now",
  live_session_link_now: "live_session_link_now",
  next_day_missed_session: "next_day_missed_session",
  sorry_you_missed_session: "sorry_you_missed_session",
  recording_followup_after_session: "recording_followup_after_session",
  post_live_notes_recording_followup: "recording_followup_after_session",
  community_fallback_invite: "community_fallback_invite",
  mentor_booking: "mentor_call_offer",
  mentor_call_offer: "mentor_call_offer",
  enrollment_help_after_interest: "enrollment_help_after_interest",
  uworld_video_library_soft_pitch: "uworld_video_library_soft_pitch",
  post_demo_interest_check: "post_demo_interest_check",
  stop_opt_out: "stop_opt_out",
};

function isPlaceholderTemplateName(value = "") {
  const clean = normalizeTemplateLookupKey(value);
  return !clean || [
    "approved_template_name_in_meta",
    "optional_provider_template_id",
    "template_name",
    "meta_template_name",
    "whatsapp_template_name",
  ].includes(clean);
}

function normalizeWhatsAppLanguageCode(value = "") {
  const raw = String(value || "").trim();
  const clean = raw.toLowerCase().replace(/[()]/g, " ").replace(/[\s-]+/g, "_");
  if (!clean) return "en";
  if (["english", "eng", "en"].includes(clean)) return "en";
  if (["english_us", "english_united_states", "en_us", "en_us_"] .includes(clean)) return "en_US";
  if (["english_uk", "english_gb", "english_united_kingdom", "en_gb"].includes(clean)) return "en_GB";
  return raw;
}

function getWhatsAppTemplateName({ template = null, metadata = {} } = {}) {
  const candidates = [
    template?.provider_template_name,
    template?.meta_template_name,
    template?.whatsapp_template_name,
    template?.template_name,
    metadata.provider_template_name,
    metadata.meta_template_name,
    metadata.whatsapp_template_name,
    metadata.template_name,
    metadata.name,
  ];

  for (const candidate of candidates) {
    const clean = String(candidate || "").trim();
    if (clean && !isPlaceholderTemplateName(clean)) return clean;
  }

  const fallbackKey = normalizeTemplateLookupKey(template?.key || template?.template_key || template?.slug || metadata.template_key || metadata.key || "");
  return WHATSAPP_TEMPLATE_NAME_ALIASES[fallbackKey] || fallbackKey;
}

function getWhatsAppLanguageCode({ template = null, metadata = {} } = {}) {
  return normalizeWhatsAppLanguageCode(
    template?.meta_language ||
      template?.whatsapp_language ||
      template?.provider_language_code ||
      metadata.meta_language ||
      metadata.whatsapp_language ||
      metadata.provider_language_code ||
      metadata.language_code ||
      metadata.language ||
      template?.language_code ||
      template?.language ||
      "en"
  );
}

function looksLikePhoneOnly(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return false;
  const digits = raw.replace(/\D/g, "");
  if (digits.length < 7) return false;
  const letters = raw.replace(/[^a-zA-Z]/g, "");
  return letters.length === 0;
}

function safeTemplateValue(value = "") {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function getLeadVariableValue(name = "", lead = {}, variables = {}, metadata = {}) {
  const key = String(name || "").trim();
  const lowerKey = key.toLowerCase();
  const direct = key.split(".").reduce((acc, part) => (acc && acc[part] !== undefined ? acc[part] : undefined), variables);
  if (direct !== undefined && direct !== null && safeTemplateValue(direct) !== "") return safeTemplateValue(direct);

  const source = { ...(metadata || {}), ...(lead || {}) };
  const aliases = {
    lead_name: ["lead_name", "student_name", "doctor_name", "name", "full_name", "first_name", "display_name", "profile_name", "whatsapp_name"],
    student_name: ["student_name", "lead_name", "doctor_name", "name", "full_name", "first_name", "display_name", "profile_name", "whatsapp_name"],
    doctor_name: ["doctor_name", "student_name", "lead_name", "name", "full_name", "first_name", "display_name", "profile_name", "whatsapp_name"],
    name: ["name", "full_name", "student_name", "lead_name", "doctor_name", "first_name", "display_name", "profile_name", "whatsapp_name"],
    exam_type: ["exam_type", "exam_track", "exam", "which_exam", "track", "program_track", "course_name"],
    exam_track: ["exam_track", "exam_type", "exam", "which_exam", "track", "program_track", "course_name"],
    exam_date: ["exam_date", "exam_timeline", "planned_exam_date", "target_exam_date"],
    graduation_year: ["graduation_year", "year_of_graduation", "yog", "years_since_graduation"],
    main_difficulty: ["main_difficulty", "difficulty", "pain_points", "study_problem", "main_problem"],
    course_name: ["course_name", "program_name", "interested_program"],
    program_name: ["program_name", "course_name", "interested_program"],
    session_time: ["session_time", "live_session_time", "appointment_time", "fixed_run_time", "live_time"],
    live_session_link: ["live_session_link", "session_link", "zoom_link", "live_link", "link_url", "url", "default_link"],
    session_link: ["session_link", "live_session_link", "zoom_link", "live_link", "link_url", "url", "default_link"],
    recording_link: ["recording_link", "recording_url", "recording", "link_url", "url", "default_link"],
    mentor_booking_link: ["mentor_booking_link", "booking_link", "appointment_link", "mentor_link", "calendar_link", "link_url", "url", "default_link"],
    community_link: ["community_link", "telegram_link", "whatsapp_group_link", "group_link", "community_url", "link_url", "url", "default_link"],
    proof_link: ["proof_link", "testimonial_link", "review_link", "trustpilot_link", "proof_url", "link_url", "url", "default_link"],
    youtube_link: ["youtube_link", "youtube_url", "proof_link"],
    demo_link: ["demo_link", "lms_link", "dashboard_link", "live_session_link", "link_url", "url", "default_link"],
    payment_link: ["payment_link", "checkout_link", "plan_link", "link_url", "url", "default_link"],
  };

  const keys = aliases[lowerKey] || [key];
  for (const k of keys) {
    const value = source[k];
    if (value !== undefined && value !== null && safeTemplateValue(value) !== "") {
      const clean = safeTemplateValue(value);
      if (["lead_name", "student_name", "doctor_name", "name"].includes(lowerKey) && looksLikePhoneOnly(clean)) continue;
      return clean;
    }
  }

  if (["lead_name", "student_name", "doctor_name", "name"].includes(lowerKey)) return "Doctor";
  if (["exam_type", "exam_track"].includes(lowerKey)) return "USMLE Step 1";
  if (lowerKey === "session_time") return "1 PM EST";
  if (["live_session_link", "session_link"].includes(lowerKey)) return getNextGenConfiguredLiveSessionLink() || "https://live.nextgenusmlelms.com";
  if (["demo_link", "recording_link"].includes(lowerKey)) return "https://live.nextgenusmlelms.com";
  if (lowerKey === "course_name" || lowerKey === "program_name") return "NextGen USMLE";
  if (lowerKey === "exam_date" || lowerKey === "graduation_year" || lowerKey === "main_difficulty") return "not confirmed";
  return "";
}

function extractTemplateVariableNames(templateText = "") {
  const matches = [];
  const seen = new Set();
  String(templateText || "").replace(/{{\s*([a-zA-Z0-9_.-]+)\s*}}/g, (_, key) => {
    const cleanKey = String(key || "").trim();
    if (!cleanKey || /^\d+$/.test(cleanKey)) return "";
    if (!seen.has(cleanKey)) {
      seen.add(cleanKey);
      matches.push(cleanKey);
    }
    return "";
  });
  return matches;
}

function extractNumberedTemplateVariableCount(templateText = "") {
  const nums = [];
  String(templateText || "").replace(/{{\s*(\d+)\s*}}/g, (_, key) => {
    const n = Number(key);
    if (Number.isFinite(n) && n > 0) nums.push(n);
    return "";
  });
  return nums.length ? Math.max(...nums) : 0;
}

const WHATSAPP_TEMPLATE_VARIABLE_ORDERS = {
  meta_ad_first_message: ["student_name", "exam_type", "session_time"],
  meta_first_message: ["student_name", "exam_type", "session_time"],
  first_message_intro: ["student_name", "exam_type", "session_time"],

  // v43 Sunday-safe first template: no variables in approved Meta template.
  greeting_exam_type_question: [],
  exam_type_question: [],
  sunday_first_message: [],

  five_minute_reminder: ["student_name"],
  five_min_live_session_reminder: ["student_name"],

  live_session_link_now: ["student_name", "live_session_link"],
  live_session_1pm_reminder: ["student_name", "live_session_link"],

  next_day_missed_session: ["student_name", "session_time", "exam_type"],
  sorry_you_missed_session: ["student_name", "session_time", "exam_type"],

  recording_followup_after_session: ["student_name", "recording_link", "exam_type"],
  post_live_notes_recording_followup: ["student_name", "recording_link", "exam_type"],

  community_fallback_invite: ["student_name", "exam_type", "community_link"],

  mentor_call_offer: ["student_name", "exam_type", "mentor_booking_link"],
  mentor_booking: ["student_name", "exam_type", "mentor_booking_link"],

  proof_testimonial_message: ["student_name", "proof_link", "youtube_link"],
  proof_testimonial: ["student_name", "proof_link", "youtube_link"],

  stop_opt_out: ["student_name"],

  two_day_lms_demo_access: ["student_name", "demo_link"],
  demo_lms_activation_invite: ["student_name", "demo_link"],
  enrollment_help_after_interest: [],
  uworld_video_library_soft_pitch: [],
  post_demo_interest_check: [],

  // v41 broadcast / future-follow-up templates.
  live_session_invite_broadcast: ["student_name", "exam_type", "session_time", "live_session_link"],
  community_invite_broadcast: ["student_name", "exam_type", "community_link"],
  future_followup_reminder: ["student_name", "follow_up_month", "exam_type", "session_time"],
  september_start_followup: ["student_name", "follow_up_month", "exam_type", "session_time"],
  exam_prep_restart_invite: ["student_name", "follow_up_month", "exam_type", "session_time"],
  mentor_call_followup: ["student_name", "exam_type", "mentor_booking_link"],
  new_launch_broadcast: ["student_name", "announcement_text", "link_url"],
};

const REQUIRED_WHATSAPP_LINK_VARIABLES = new Set([
  "live_session_link",
  "session_link",
  "recording_link",
  "mentor_booking_link",
  "community_link",
  "proof_link",
  "demo_link",
  "payment_link",
]);

function getWhatsAppTemplateLookupKeys({ template = null, metadata = {} } = {}) {
  return [
    template?.key,
    template?.template_key,
    template?.slug,
    template?.name,
    template?.template_name,
    template?.meta_template_name,
    template?.whatsapp_template_name,
    template?.provider_template_name,
    metadata.template_key,
    metadata.key,
    metadata.name,
    metadata.template_name,
    metadata.meta_template_name,
    metadata.whatsapp_template_name,
    metadata.provider_template_name,
  ].map(normalizeTemplateLookupKey).filter(Boolean);
}

function resolveWhatsAppTemplateVariableOrder({ template = null, metadata = {} } = {}) {
  const lookupKeys = getWhatsAppTemplateLookupKeys({ template, metadata });
  const templateName = normalizeTemplateLookupKey(getWhatsAppTemplateName({ template, metadata }));
  if (templateName) lookupKeys.unshift(templateName);

  for (const rawKey of lookupKeys) {
    const alias = WHATSAPP_TEMPLATE_NAME_ALIASES[rawKey] || rawKey;
    if (Object.prototype.hasOwnProperty.call(WHATSAPP_TEMPLATE_VARIABLE_ORDERS, alias)) {
      return WHATSAPP_TEMPLATE_VARIABLE_ORDERS[alias];
    }
    if (Object.prototype.hasOwnProperty.call(WHATSAPP_TEMPLATE_VARIABLE_ORDERS, rawKey)) {
      return WHATSAPP_TEMPLATE_VARIABLE_ORDERS[rawKey];
    }
  }

  const templateBody = template?.body || template?.message || template?.content || template?.text || "";
  const namedFromBody = extractTemplateVariableNames(templateBody);
  if (namedFromBody.length && namedFromBody.length <= 8) return namedFromBody;

  const templateVars = Array.isArray(template?.variables)
    ? template.variables.map((x) => String(x || "").replace(/[{}]/g, "").trim()).filter((x) => x && !/^\d+$/.test(x))
    : [];

  // The Templates UI can store a generic "all variables" list. Do not send that whole list to Meta.
  if (templateVars.length && templateVars.length <= 8) return templateVars;

  return [];
}

function buildWhatsAppTemplateComponents({ template = null, lead = null, variables = {}, metadata = {} } = {}) {
  const names = resolveWhatsAppTemplateVariableOrder({ template, metadata });
  if (!names.length) return [];

  const params = names.map((name) => {
    const value = getLeadVariableValue(name, lead || {}, variables || {}, metadata || {});
    const cleanValue = safeTemplateValue(value);

    if (!cleanValue && REQUIRED_WHATSAPP_LINK_VARIABLES.has(String(name || "").toLowerCase())) {
      const templateName = getWhatsAppTemplateName({ template, metadata }) || metadata.template_key || template?.key || "selected template";
      const error = new Error(`Missing WhatsApp template variable: ${name} for ${templateName}`);
      error.statusCode = 400;
      error.hint = `Add ${name} in Campaigns / Live Session Conversion / Communities / Reviews before sending this template.`;
      throw error;
    }

    return {
      type: "text",
      text: cleanValue || "not confirmed",
    };
  });

  return [{
    type: "body",
    parameters: params,
  }];
}

function sanitizeWhatsAppTemplateComponents(components = []) {
  if (!Array.isArray(components)) return [];
  return components
    .map((component) => {
      if (!component || String(component.type || "").toLowerCase() !== "body") return component;
      const parameters = Array.isArray(component.parameters)
        ? component.parameters
            .filter((param) => param && String(param.type || "").toLowerCase() === "text")
            .map((param) => ({ ...param, text: safeTemplateValue(param.text) || "not confirmed" }))
        : [];
      return { ...component, parameters };
    })
    .filter((component) => {
      if (!component) return false;
      if (String(component.type || "").toLowerCase() !== "body") return true;
      return Array.isArray(component.parameters) && component.parameters.length > 0;
    });
}

async function sendWhatsAppCloudMessage({ to, text = "", templateName = "", languageCode = "en", components = [], mediaUrl = "", mediaId = "", mediaType = "image", caption = "" }) {
  const token = process.env.WHATSAPP_ACCESS_TOKEN;
  const phoneNumberId = process.env.WHATSAPP_PHONE_NUMBER_ID;

  if (!token || !phoneNumberId) {
    const error = new Error("WhatsApp Cloud API is not configured. Add WHATSAPP_ACCESS_TOKEN and WHATSAPP_PHONE_NUMBER_ID.");
    error.statusCode = 500;
    error.hint = "Check Render environment variables and redeploy the backend.";
    throw error;
  }

  const recipient = normalizePhoneForWhatsapp(to);
  if (!recipient) {
    const error = new Error("A valid WhatsApp recipient number is required. Use international format, for example +923001234567.");
    error.statusCode = 400;
    error.hint = "Do not use names or Telegram links for WhatsApp recipient.";
    throw error;
  }

  const payload = {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: recipient,
  };

  if (templateName) {
    const safeComponents = sanitizeWhatsAppTemplateComponents(components);
    payload.type = "template";
    payload.template = {
      name: templateName,
      language: { code: normalizeWhatsAppLanguageCode(languageCode || "en") },
      ...(safeComponents.length ? { components: safeComponents } : {}),
    };
  } else if (mediaUrl || mediaId) {
    const cleanType = ["image", "video", "document", "audio"].includes(String(mediaType || "image").toLowerCase()) ? String(mediaType || "image").toLowerCase() : "image";
    payload.type = cleanType;
    const mediaPayload = mediaId ? { id: String(mediaId).trim() } : { link: String(mediaUrl).trim() };
    const cleanCaption = String(caption || text || "").trim();
    if (cleanCaption && ["image", "video", "document"].includes(cleanType)) mediaPayload.caption = cleanCaption;
    payload[cleanType] = mediaPayload;
  } else {
    const cleanText = String(text || "").trim();
    if (!cleanText) {
      const error = new Error("WhatsApp text message is empty and no template or media was selected.");
      error.statusCode = 400;
      throw error;
    }
    payload.type = "text";
    payload.text = { preview_url: false, body: cleanText };
  }

  const response = await axios.post(
    `https://graph.facebook.com/${WHATSAPP_GRAPH_VERSION}/${phoneNumberId}/messages`,
    payload,
    {
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      timeout: 30000,
    }
  );

  return response.data;
}

async function sendTelegramMessage({ to, text = "", integration = {} }) {
  const chatId = ngNormalizeTelegramChatId(to, { assumeGroup: false });
  if (!chatId) {
    const error = new Error("Telegram chat_id is required. Use numeric chat_id, not a t.me link.");
    error.statusCode = 400;
    error.hint = "Example valid values: 123456789, -5240157430, or -1001577486157.";
    throw error;
  }

  if (/^https?:\/\//i.test(chatId) || chatId.includes("t.me/")) {
    const error = new Error("Telegram recipient must be a numeric chat_id, not a t.me URL.");
    error.statusCode = 400;
    error.hint = "Open Telegram webhook/inbound logs and copy telegram_chat_id. For groups it usually starts with -100 or another negative number.";
    throw error;
  }

  const cleanText = String(text || "").trim();
  if (!cleanText) {
    const error = new Error("Telegram message text is required.");
    error.statusCode = 400;
    throw error;
  }

  return telegramApi("sendMessage", {
    chat_id: chatId,
    text: cleanText,
    disable_web_page_preview: false,
  }, integration || {});
}

function getEmailFromAddress() {
  return (
    process.env.EMAIL_FROM ||
    process.env.RESEND_FROM_EMAIL ||
    process.env.SENDGRID_FROM_EMAIL ||
    process.env.SMTP_FROM ||
    "NextGen USMLE <support@nextgenusmlelms.com>"
  );
}

function ngAylaEmailFromAddress() {
  return (
    process.env.AYLA_EMAIL_FROM ||
    process.env.AYLA_RESEND_FROM_EMAIL ||
    process.env.AYLA_SENDGRID_FROM_EMAIL ||
    process.env.AYLA_SMTP_FROM ||
    "AylaMed <support@aylamedapp.com>"
  );
}

function extractEmailAddress(value = "") {
  const clean = String(value || "").trim();
  return clean.match(/<([^>]+)>/)?.[1] || clean;
}

function extractEmailDisplayName(value = "") {
  const clean = String(value || "").trim();
  const match = clean.match(/^\s*([^<]+?)\s*<[^>]+>\s*$/);
  return match?.[1]?.trim() || "NextGen USMLE";
}

function ngNormalizeEmailProvider(value = "") {
  const clean = String(value || "").trim().toLowerCase();
  if (["smtp", "hostinger", "hostinger_smtp"].includes(clean)) return "smtp";
  if (["resend", "resend_api"].includes(clean)) return "resend";
  if (["sendgrid", "send_grid"].includes(clean)) return "sendgrid";
  return "";
}

function ngEmailProviderAvailability() {
  return {
    smtp: Boolean(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS),
    resend: Boolean(process.env.RESEND_API_KEY),
    sendgrid: Boolean(process.env.SENDGRID_API_KEY),
  };
}

function ngResolveEmailProvider() {
  const available = ngEmailProviderAvailability();
  const requested = ngNormalizeEmailProvider(process.env.EMAIL_PROVIDER || process.env.MAIL_PROVIDER || "");

  if (requested) {
    return {
      requested,
      provider: available[requested] ? requested : null,
      available,
      error: available[requested] ? null : `${requested.toUpperCase()} was selected but its required environment variables are incomplete.`,
    };
  }

  // Preserve the established provider order unless EMAIL_PROVIDER is explicitly set.
  const provider = available.resend ? "resend" : available.sendgrid ? "sendgrid" : available.smtp ? "smtp" : null;
  return { requested: null, provider, available, error: null };
}

function ngAylaEmailProviderAvailability() {
  return {
    smtp: Boolean(process.env.AYLA_SMTP_HOST && process.env.AYLA_SMTP_USER && process.env.AYLA_SMTP_PASS),
    resend: Boolean(process.env.AYLA_RESEND_API_KEY),
    sendgrid: Boolean(process.env.AYLA_SENDGRID_API_KEY),
  };
}

function ngResolveAylaEmailProvider() {
  const available = ngAylaEmailProviderAvailability();
  const requested = ngNormalizeEmailProvider(process.env.AYLA_EMAIL_PROVIDER || process.env.AYLA_MAIL_PROVIDER || "");

  if (requested) {
    return {
      requested,
      provider: available[requested] ? requested : null,
      available,
      error: available[requested]
        ? null
        : `${requested.toUpperCase()} was selected for AylaMed but its AYLA_* environment variables are incomplete.`,
    };
  }

  const provider = available.resend ? "resend" : available.sendgrid ? "sendgrid" : available.smtp ? "smtp" : null;
  return { requested: null, provider, available, error: null };
}

function ngMaskEmailLogin(value = "") {
  const clean = String(value || "").trim();
  const at = clean.indexOf("@");
  if (at <= 1) return clean ? `${clean.slice(0, 1)}***` : null;
  return `${clean.slice(0, 2)}***${clean.slice(at)}`;
}

function ngEmailTransportStatus() {
  const resolved = ngResolveEmailProvider();
  const smtpPort = Number(process.env.SMTP_PORT || 465);
  const smtpSecure = process.env.SMTP_SECURE === undefined
    ? smtpPort === 465
    : String(process.env.SMTP_SECURE).toLowerCase() === "true";

  return {
    configured: Boolean(resolved.provider),
    provider: resolved.provider,
    requested_provider: resolved.requested,
    provider_error: resolved.error,
    available_providers: resolved.available,
    from: getEmailFromAddress(),
    reply_to: process.env.EMAIL_REPLY_TO || process.env.REPLY_TO_EMAIL || null,
    reset_url: process.env.STUDENT_RESET_PASSWORD_URL || "https://live.nextgenusmlelms.com/reset-password",
    login_url: ngStudentLoginUrl(),
    smtp: {
      configured: resolved.available.smtp,
      host: process.env.SMTP_HOST || null,
      port: smtpPort,
      secure: smtpSecure,
      user: ngMaskEmailLogin(process.env.SMTP_USER || ""),
    },
  };
}

function ngAylaEmailTransportStatus() {
  const resolved = ngResolveAylaEmailProvider();
  const smtpPort = Number(process.env.AYLA_SMTP_PORT || 465);
  const smtpSecure = process.env.AYLA_SMTP_SECURE === undefined
    ? smtpPort === 465
    : String(process.env.AYLA_SMTP_SECURE).toLowerCase() === "true";

  return {
    configured: Boolean(resolved.provider),
    provider: resolved.provider,
    requested_provider: resolved.requested,
    provider_error: resolved.error,
    available_providers: resolved.available,
    from: ngAylaEmailFromAddress(),
    reply_to: process.env.AYLA_EMAIL_REPLY_TO || process.env.AYLA_REPLY_TO_EMAIL || null,
    login_url: "https://aylamedapp.com/login",
    smtp: {
      configured: resolved.available.smtp,
      host: process.env.AYLA_SMTP_HOST || null,
      port: smtpPort,
      secure: smtpSecure,
      user: ngMaskEmailLogin(process.env.AYLA_SMTP_USER || ""),
    },
  };
}

function ngGetEmailSettings(db = {}) {
  return { ...DEFAULT_EMAIL_SETTINGS, ...(db.emailSettings || {}) };
}

function ngGetEmailTemplates(db = {}) {
  return ngMergeEmailTemplates(db.emailTemplates || {});
}

function ngGetEmailTemplate(db = {}, key = "") {
  return ngGetEmailTemplates(db)[String(key || "").trim()] || null;
}

function ngRenderEmailString(value = "", variables = {}) {
  return String(value || "").replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (_match, key) => {
    const resolved = variables?.[key];
    return resolved === null || resolved === undefined ? "" : String(resolved);
  });
}

function ngEmailBaseVariables(db = {}, user = {}, extra = {}) {
  const settings = ngGetEmailSettings(db);
  return {
    student_name: String(user?.name || user?.full_name || user?.display_name || "Doctor").trim() || "Doctor",
    student_email: normalizeEmail(user?.email || extra.student_email || ""),
    login_url: ngStudentLoginUrl(),
    dashboard_url: "https://live.nextgenusmlelms.com/student/dashboard",
    plans_url: "https://live.nextgenusmlelms.com/plans",
    support_email: settings.reply_to || process.env.EMAIL_REPLY_TO || extractEmailAddress(getEmailFromAddress()),
    days_suffix: "s",
    ...extra,
  };
}

function ngEmailCoursePhrase(courseName = "") {
  const clean = String(courseName || "").trim();
  return clean ? ` for ${clean}` : "";
}

function ngConfiguredEmailFrom(db = {}) {
  const settings = ngGetEmailSettings(db);
  const existing = getEmailFromAddress();
  return `${String(settings.sender_name || extractEmailDisplayName(existing) || "NextGen USMLE").trim()} <${extractEmailAddress(existing)}>`;
}

function ngConfiguredEmailReplyTo(db = {}) {
  const settings = ngGetEmailSettings(db);
  return String(settings.reply_to || process.env.EMAIL_REPLY_TO || process.env.REPLY_TO_EMAIL || "").trim() || undefined;
}

function ngBuildEmailFromTemplate(db = {}, templateKey = "", variables = {}, overrides = {}) {
  const template = ngGetEmailTemplate(db, templateKey);
  if (!template) {
    const error = new Error(`Email template not found: ${templateKey}`);
    error.statusCode = 404;
    throw error;
  }
  const mergedVariables = ngEmailBaseVariables(db, overrides.user || {}, variables || {});
  const subjectSource = overrides.subject !== undefined ? overrides.subject : template.subject;
  const bodySource = overrides.body !== undefined ? overrides.body : template.body;
  return {
    template,
    variables: mergedVariables,
    subject: ngRenderEmailString(subjectSource, mergedVariables).trim(),
    text: ngRenderEmailString(bodySource, mergedVariables).trim(),
  };
}

async function ngSendConfiguredEmailSafe({ db, templateKey, to, variables = {}, reason = "configured_email", userId = null, enrollmentId = null, subject = undefined, body = undefined, force = false } = {}) {
  const settings = ngGetEmailSettings(db);
  const template = ngGetEmailTemplate(db, templateKey);
  const result = { attempted: false, sent: false, skipped: false, provider: null, error: null, reason, template_key: templateKey };

  if (!template) {
    result.error = `Email template not found: ${templateKey}`;
    return result;
  }
  if (!force && settings.email_notifications_enabled !== true) {
    result.skipped = true;
    result.reason = "master_email_notifications_disabled";
    return result;
  }
  if (!force && template.enabled === false) {
    result.skipped = true;
    result.reason = "email_template_disabled";
    return result;
  }

  result.attempted = true;
  let rendered = null;
  try {
    rendered = ngBuildEmailFromTemplate(db, templateKey, variables, { subject, body });
    const provider = await sendEmailMessage({
      to,
      subject: rendered.subject,
      text: rendered.text,
      from: ngConfiguredEmailFrom(db),
      replyTo: ngConfiguredEmailReplyTo(db),
    });
    result.sent = true;
    result.provider = provider?.provider || provider?.messageId || provider?.id || "email";
    result.subject = rendered.subject;
    ngLogStudentEmail(db, { to, subject: rendered.subject, status: "sent", provider_response: provider, reason, template_key: templateKey, user_id: userId, enrollment_id: enrollmentId });
  } catch (error) {
    result.error = error.message;
    ngLogStudentEmail(db, { to: to || "", subject: rendered?.subject || template?.subject || "NextGen USMLE", status: "failed", error: error.message, reason, template_key: templateKey, user_id: userId, enrollment_id: enrollmentId });
  }
  return result;
}

function ngResolveEmailAudience(db = {}, options = {}) {
  const audience = String(options.audience || "single").trim().toLowerCase();
  const courseId = String(options.course_id || options.courseId || "").trim();
  const requestedUserIds = uniqueList([...(safeArray(options.user_ids)), ...(safeArray(options.userIds))].map(String));
  const requestedEmails = uniqueList([
    ...safeArray(options.emails),
    ...String(options.email || options.to || "").split(/[\s,;]+/),
  ].map(normalizeEmail).filter((email) => email && email.includes("@")));
  const demoSettings = { ...DEFAULT_DEMO_SETTINGS, ...(db.demoSettings || {}) };
  const now = Date.now();
  const rows = [];

  const pushUser = (user, enrollment = null) => {
    const email = normalizeEmail(user?.email || "");
    if (!email || !email.includes("@")) return;
    rows.push({
      user_id: user?.id || null,
      email,
      name: user?.name || user?.full_name || "Doctor",
      enrollment_id: enrollment?.id || null,
      course_id: enrollment?.course_id || courseId || null,
      variables: ngEmailBaseVariables(db, user, {}),
    });
  };

  if (["single", "selected", "custom"].includes(audience)) {
    for (const userId of requestedUserIds) {
      const user = db.users?.[String(userId)] || null;
      if (user) pushUser(user, null);
    }
    for (const email of requestedEmails) {
      const user = findUserByEmail(db, email);
      if (user) pushUser(user, null);
      else rows.push({ user_id: null, email, name: "Doctor", enrollment_id: null, course_id: courseId || null, variables: ngEmailBaseVariables(db, {}, { student_email: email }) });
    }
  } else {
    for (const user of Object.values(db.users || {})) {
      if (!user?.id || String(user.role || "student").toLowerCase() !== "student") continue;
      const enrollments = Object.values(db.enrollments || {}).filter((enrollment) => String(enrollment.user_id || "") === String(user.id));
      const activePaid = enrollments.find((enrollment) => enrollment.is_demo !== true && isPaidEnrollmentActive(
        enrollment,
        enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null,
        db,
      ));
      const activeDemo = enrollments.find((enrollment) => enrollment.is_demo === true && enrollment.access_granted !== false && isDemoEnrollmentActive(enrollment, demoSettings));
      const expiredDemo = enrollments.find((enrollment) => enrollment.is_demo === true && !isDemoEnrollmentActive(enrollment, demoSettings));
      const courseEnrollment = courseId ? enrollments.find((enrollment) => (
        String(enrollment.course_id || "") === courseId
        && (
          enrollment.is_demo === true
            ? enrollment.access_granted !== false && isDemoEnrollmentActive(enrollment, demoSettings)
            : isPaidEnrollmentActive(
                enrollment,
                enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null,
                db,
              )
        )
      )) : null;
      const expiringPaid = enrollments.find((enrollment) => {
        if (enrollment.is_demo === true) return false;
        const plan = enrollment.plan_id ? db.plans?.[String(enrollment.plan_id)] || null : null;
        if (!isPaidEnrollmentActive(enrollment, plan, db)) return false;
        const expires = ngPaidAccessExpiresAt(enrollment, plan, db);
        if (!expires) return false;
        const remaining = expires.getTime() - now;
        return remaining > 0 && remaining <= 7 * 24 * 60 * 60 * 1000;
      });

      if (audience === "course_students" && courseEnrollment) pushUser(user, courseEnrollment);
      else if (audience === "active_paid" && activePaid) pushUser(user, activePaid);
      else if (audience === "active_demo" && activeDemo) pushUser(user, activeDemo);
      else if (audience === "expired_demo" && expiredDemo) pushUser(user, expiredDemo);
      else if (audience === "expiring_soon" && expiringPaid) pushUser(user, expiringPaid);
      else if (audience === "all_active" && (activePaid || activeDemo)) pushUser(user, activePaid || activeDemo);
      else if (audience === "all_students") pushUser(user, activePaid || activeDemo || enrollments[0] || null);
    }
  }

  const unique = [];
  const seen = new Set();
  for (const row of rows) {
    const email = normalizeEmail(row.email);
    if (!email || seen.has(email)) continue;
    seen.add(email);
    unique.push({ ...row, email });
  }
  return unique;
}

function ngQueueEmailBroadcast(db = {}, payload = {}) {
  db.emailBroadcasts = safeArray(db.emailBroadcasts);
  const dedupeKey = String(payload.dedupe_key || "").trim();
  if (dedupeKey) {
    const existing = db.emailBroadcasts.find((job) => String(job.dedupe_key || "") === dedupeKey && ["queued", "running", "completed"].includes(String(job.status || "")));
    if (existing) return { job: existing, created: false, duplicate: true };
  }
  const recipients = safeArray(payload.recipients).map((item) => ({
    email: normalizeEmail(item.email || ""),
    user_id: item.user_id || null,
    name: item.name || "Doctor",
    enrollment_id: item.enrollment_id || null,
    course_id: item.course_id || null,
    variables: item.variables || {},
    status: "pending",
    error: null,
  })).filter((item) => item.email && item.email.includes("@"));
  const job = {
    id: uuid(),
    template_key: payload.template_key || null,
    subject_override: payload.subject_override ?? null,
    body_override: payload.body_override ?? null,
    reason: payload.reason || "admin_email_broadcast",
    audience: payload.audience || "selected",
    course_id: payload.course_id || null,
    dedupe_key: dedupeKey || null,
    force: payload.force === true,
    common_variables: payload.common_variables || {},
    recipients,
    total_count: recipients.length,
    sent_count: 0,
    failed_count: 0,
    skipped_count: 0,
    cursor: 0,
    status: recipients.length ? "queued" : "completed",
    created_by: payload.created_by || null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    completed_at: recipients.length ? null : new Date().toISOString(),
  };
  db.emailBroadcasts.unshift(job);
  db.emailBroadcasts = db.emailBroadcasts.slice(0, 200);
  return { job, created: true, duplicate: false };
}

async function ngProcessEmailBroadcastQueueOnce({ batchSize = 10 } = {}) {
  const db = await readLiveDb();
  db.emailBroadcasts = safeArray(db.emailBroadcasts);
  const job = db.emailBroadcasts.find((item) => ["queued", "running"].includes(String(item.status || "")) && Number(item.cursor || 0) < safeArray(item.recipients).length);
  if (!job) return { processed: false };

  job.status = "running";
  job.started_at = job.started_at || new Date().toISOString();
  const start = Number(job.cursor || 0);
  const end = Math.min(safeArray(job.recipients).length, start + Math.max(1, Math.min(25, Number(batchSize || 10))));

  for (let index = start; index < end; index += 1) {
    const recipient = job.recipients[index];
    if (!recipient || recipient.status !== "pending") {
      job.cursor = index + 1;
      continue;
    }
    const result = await ngSendConfiguredEmailSafe({
      db,
      templateKey: job.template_key,
      to: recipient.email,
      variables: { ...job.common_variables, ...recipient.variables, student_name: recipient.name || "Doctor", student_email: recipient.email },
      reason: job.reason,
      userId: recipient.user_id,
      enrollmentId: recipient.enrollment_id,
      subject: job.subject_override === null ? undefined : job.subject_override,
      body: job.body_override === null ? undefined : job.body_override,
      force: job.force === true,
    });
    recipient.status = result.sent ? "sent" : result.skipped ? "skipped" : "failed";
    recipient.error = result.error || null;
    recipient.sent_at = result.sent ? new Date().toISOString() : null;
    if (result.sent) job.sent_count = Number(job.sent_count || 0) + 1;
    else if (result.skipped) job.skipped_count = Number(job.skipped_count || 0) + 1;
    else job.failed_count = Number(job.failed_count || 0) + 1;
    job.cursor = index + 1;
  }

  if (job.cursor >= safeArray(job.recipients).length) {
    job.status = job.failed_count > 0 && job.sent_count === 0 ? "failed" : "completed";
    job.completed_at = new Date().toISOString();
  }
  job.updated_at = new Date().toISOString();
  await writeLiveDb(db);
  return { processed: true, job_id: job.id, status: job.status, sent_count: job.sent_count, failed_count: job.failed_count, cursor: job.cursor, total_count: job.total_count };
}

function ngQueueCourseTemplateEmail(db = {}, { templateKey, courseId, reason, commonVariables = {}, dedupeKey = "", createdBy = null } = {}) {
  const recipients = ngResolveEmailAudience(db, { audience: "course_students", course_id: courseId });
  return ngQueueEmailBroadcast(db, {
    template_key: templateKey,
    recipients,
    reason,
    audience: "course_students",
    course_id: courseId,
    common_variables: commonVariables,
    dedupe_key: dedupeKey,
    created_by: createdBy,
  });
}

function ngFormatCurrencyAmount(amountCents = 0, currency = "usd") {
  const cents = Number(amountCents || 0);
  if (cents <= 0) return "Free / fully discounted";
  try {
    return new Intl.NumberFormat("en-US", { style: "currency", currency: String(currency || "usd").toUpperCase() }).format(cents / 100);
  } catch {
    return `${(cents / 100).toFixed(2)} ${String(currency || "usd").toUpperCase()}`;
  }
}

