async function ngSendTransactionalEmailSafe({ db, to, subject, text, reason = "transactional_email", userId = null, enrollmentId = null } = {}) {
  const result = { attempted: true, sent: false, provider: null, error: null, reason };
  try {
    const provider = await sendEmailMessage({ to, subject, text });
    result.sent = true;
    result.provider = provider?.provider || provider?.messageId || provider?.id || "email";
    ngLogStudentEmail(db, {
      to,
      subject,
      status: "sent",
      provider_response: provider,
      reason,
      user_id: userId,
      enrollment_id: enrollmentId,
    });
  } catch (error) {
    result.error = error.message;
    ngLogStudentEmail(db, {
      to: to || "",
      subject: subject || "NextGen USMLE",
      status: "failed",
      error: error.message,
      reason,
      user_id: userId,
      enrollment_id: enrollmentId,
    });
  }
  return result;
}

let ngSmtpTransporterCache = null;
let ngSmtpTransporterSignature = "";
let ngAylaSmtpTransporterCache = null;
let ngAylaSmtpTransporterSignature = "";

async function ngGetSmtpTransporter() {
  const host = String(process.env.SMTP_HOST || "").trim();
  const user = String(process.env.SMTP_USER || "").trim();
  const pass = String(process.env.SMTP_PASS || "");
  const port = Number(process.env.SMTP_PORT || 465);
  const secure = process.env.SMTP_SECURE === undefined
    ? port === 465
    : String(process.env.SMTP_SECURE).toLowerCase() === "true";
  const requireTLS = process.env.SMTP_REQUIRE_TLS === undefined
    ? port === 587
    : String(process.env.SMTP_REQUIRE_TLS).toLowerCase() === "true";

  if (!host || !user || !pass) {
    const error = new Error("SMTP_HOST, SMTP_USER, and SMTP_PASS are required for SMTP email delivery.");
    error.statusCode = 500;
    throw error;
  }

  const signature = [host, port, secure, requireTLS, user, pass].join("|");
  if (ngSmtpTransporterCache && ngSmtpTransporterSignature === signature) return ngSmtpTransporterCache;

  let nodemailer;
  try {
    const imported = await import("nodemailer");
    nodemailer = imported.default || imported;
  } catch (error) {
    const wrapped = new Error(`Hostinger SMTP is selected, but the backend dependency "nodemailer" is missing. Run npm install nodemailer and redeploy. Original error: ${error.message}`);
    wrapped.statusCode = 500;
    throw wrapped;
  }

  ngSmtpTransporterCache = nodemailer.createTransport({
    host,
    port,
    secure,
    requireTLS,
    auth: { user, pass },
    connectionTimeout: Number(process.env.SMTP_CONNECTION_TIMEOUT_MS || 20000),
    greetingTimeout: Number(process.env.SMTP_GREETING_TIMEOUT_MS || 20000),
    socketTimeout: Number(process.env.SMTP_SOCKET_TIMEOUT_MS || 30000),
    tls: {
      minVersion: "TLSv1.2",
      servername: host,
    },
  });
  ngSmtpTransporterSignature = signature;
  return ngSmtpTransporterCache;
}

async function ngGetAylaSmtpTransporter() {
  const host = String(process.env.AYLA_SMTP_HOST || "").trim();
  const user = String(process.env.AYLA_SMTP_USER || "").trim();
  const pass = String(process.env.AYLA_SMTP_PASS || "");
  const port = Number(process.env.AYLA_SMTP_PORT || 465);
  const secure = process.env.AYLA_SMTP_SECURE === undefined
    ? port === 465
    : String(process.env.AYLA_SMTP_SECURE).toLowerCase() === "true";
  const requireTLS = process.env.AYLA_SMTP_REQUIRE_TLS === undefined
    ? port === 587
    : String(process.env.AYLA_SMTP_REQUIRE_TLS).toLowerCase() === "true";

  if (!host || !user || !pass) {
    const error = new Error("AYLA_SMTP_HOST, AYLA_SMTP_USER, and AYLA_SMTP_PASS are required for AylaMed SMTP delivery.");
    error.statusCode = 500;
    throw error;
  }

  const signature = [host, port, secure, requireTLS, user, pass].join("|");
  if (ngAylaSmtpTransporterCache && ngAylaSmtpTransporterSignature === signature) return ngAylaSmtpTransporterCache;

  let nodemailer;
  try {
    const imported = await import("nodemailer");
    nodemailer = imported.default || imported;
  } catch (error) {
    const wrapped = new Error(`AylaMed SMTP is selected, but the backend dependency "nodemailer" is missing. Run npm install nodemailer and redeploy. Original error: ${error.message}`);
    wrapped.statusCode = 500;
    throw wrapped;
  }

  ngAylaSmtpTransporterCache = nodemailer.createTransport({
    host,
    port,
    secure,
    requireTLS,
    auth: { user, pass },
    connectionTimeout: Number(process.env.AYLA_SMTP_CONNECTION_TIMEOUT_MS || process.env.SMTP_CONNECTION_TIMEOUT_MS || 20000),
    greetingTimeout: Number(process.env.AYLA_SMTP_GREETING_TIMEOUT_MS || process.env.SMTP_GREETING_TIMEOUT_MS || 20000),
    socketTimeout: Number(process.env.AYLA_SMTP_SOCKET_TIMEOUT_MS || process.env.SMTP_SOCKET_TIMEOUT_MS || 30000),
    tls: {
      minVersion: "TLSv1.2",
      servername: host,
    },
  });
  ngAylaSmtpTransporterSignature = signature;
  return ngAylaSmtpTransporterCache;
}

function ngEmailTextToHtml(text = "", { brand = "nextgen" } = {}) {
  const escaped = String(text || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;")
    .replace(/\n/g, "<br />");
  const linked = escaped.replace(/(https?:\/\/[^<\s]+)/g, '<a href="$1" style="color:#1A4FBF;font-weight:700;text-decoration:none;word-break:break-word">$1</a>');
  const isAyla = String(brand || "").toLowerCase() === "aylamed";
  const badge = isAyla ? "AylaMed" : "NextGen USMLE";
  const footer = isAyla
    ? "Adaptive medical exam preparation · Personal study · Smart revision"
    : "Structured USMLE preparation · Live learning · Smart revision";
  const accent = isAyla ? "#0B7A75" : "#D4A017";
  return `<div style="margin:0;padding:24px;background:#F6F9FE;font-family:Arial,Helvetica,sans-serif;color:#071426"><div style="max-width:640px;margin:0 auto;background:#FFFFFF;border:1px solid #DAEAFF;border-radius:18px;overflow:hidden;box-shadow:0 14px 40px rgba(26,79,191,.08)"><div style="height:5px;background:linear-gradient(90deg,#06101F,${accent},#06101F)"></div><div style="padding:28px"><div style="display:inline-block;padding:7px 12px;border-radius:999px;background:#06101F;color:${accent};font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;margin-bottom:18px">${badge}</div><div style="font-size:15px;line-height:1.75">${linked}</div><div style="margin-top:26px;padding-top:18px;border-top:1px solid #E4EEFC;color:#5A718A;font-size:12px">${footer}</div></div></div></div>`;
}

async function sendEmailMessage({ to, subject = "NextGen USMLE", text = "", from: fromOverride = "", replyTo: replyToOverride = "", transport = "default", brand = "nextgen" }) {
  const recipient = String(Array.isArray(to) ? to[0] : to || "").trim();
  if (!recipient || !recipient.includes("@")) {
    const error = new Error("A valid email recipient is required.");
    error.statusCode = 400;
    throw error;
  }

  const cleanText = String(text || "").trim();
  if (!cleanText) {
    const error = new Error("Email message body is required.");
    error.statusCode = 400;
    throw error;
  }

  const isAylaTransport = String(transport || "").toLowerCase() === "aylamed";
  const defaultFrom = isAylaTransport ? ngAylaEmailFromAddress() : getEmailFromAddress();
  const from = String(fromOverride || defaultFrom).trim() || defaultFrom;
  const cleanSubject = String(subject || "NextGen USMLE").trim() || "NextGen USMLE";
  const replyTo = String(
    replyToOverride ||
    (isAylaTransport
      ? process.env.AYLA_EMAIL_REPLY_TO || process.env.AYLA_REPLY_TO_EMAIL
      : process.env.EMAIL_REPLY_TO || process.env.REPLY_TO_EMAIL) ||
    ""
  ).trim() || undefined;
  const resolved = isAylaTransport ? ngResolveAylaEmailProvider() : ngResolveEmailProvider();
  const html = ngEmailTextToHtml(cleanText, { brand: isAylaTransport ? "aylamed" : brand });

  if (!resolved.provider) {
    const error = new Error(resolved.error || (isAylaTransport
      ? "AylaMed email sending requires AYLA_SMTP_*, AYLA_RESEND_API_KEY, or AYLA_SENDGRID_API_KEY configuration."
      : "Email sending requires a configured SMTP, Resend, or SendGrid provider."));
    error.statusCode = 500;
    throw error;
  }

  if (resolved.provider === "smtp") {
    try {
      const transporter = isAylaTransport ? await ngGetAylaSmtpTransporter() : await ngGetSmtpTransporter();
      const info = await transporter.sendMail({
        from,
        to: recipient,
        subject: cleanSubject,
        text: cleanText,
        html,
        replyTo,
      });
      return {
        provider: "smtp",
        messageId: info.messageId || null,
        accepted: info.accepted || [],
        rejected: info.rejected || [],
        response: info.response || null,
      };
    } catch (error) {
      const wrapped = new Error(`SMTP delivery failed: ${error.message}`);
      wrapped.statusCode = error.statusCode || 502;
      throw wrapped;
    }
  }

  if (resolved.provider === "resend") {
    const response = await axios.post(
      "https://api.resend.com/emails",
      {
        from,
        to: [recipient],
        subject: cleanSubject,
        text: cleanText,
        html,
        ...(replyTo ? { reply_to: replyTo } : {}),
      },
      {
        headers: {
          Authorization: `Bearer ${isAylaTransport ? process.env.AYLA_RESEND_API_KEY : process.env.RESEND_API_KEY}`,
          "Content-Type": "application/json",
        },
        timeout: 30000,
      }
    );
    return { provider: "resend", ...response.data };
  }

  const response = await axios.post(
    "https://api.sendgrid.com/v3/mail/send",
    {
      personalizations: [{ to: [{ email: recipient }] }],
      from: { email: extractEmailAddress(from), name: extractEmailDisplayName(from) },
      ...(replyTo ? { reply_to: { email: replyTo } } : {}),
      subject: cleanSubject,
      content: [
        { type: "text/plain", value: cleanText },
        { type: "text/html", value: html },
      ],
    },
    {
      headers: {
        Authorization: `Bearer ${isAylaTransport ? process.env.AYLA_SENDGRID_API_KEY : process.env.SENDGRID_API_KEY}`,
        "Content-Type": "application/json",
      },
      timeout: 30000,
    }
  );
  return { provider: "sendgrid", status: response.status };
}

function getBestRecipientForChannel({ channel, to = "", lead = null, message = null }) {
  if (to) return to;

  const cleanChannel = normalizeCrmSendChannel(channel || lead?.platform || lead?.source_platform || message?.platform || "");
  const msg = message || {};

  if (cleanChannel === "email") {
    return lead?.email || lead?.student_email || lead?.customer_email || msg.email || msg.from || msg.sender || msg.contact || msg.recipient || "";
  }

  if (cleanChannel === "telegram") {
    return (
      lead?.telegram_chat_id || lead?.chat_id || lead?.telegram_id || lead?.platform_contact_id ||
      msg.telegram_chat_id || msg.chat_id || msg.platform_contact_id || msg.telegram_id ||
      msg.from || msg.sender || msg.contact || msg.recipient || msg.lead_id || ""
    );
  }

  if (cleanChannel === "whatsapp") {
    return lead?.whatsapp || lead?.whatsapp_phone || lead?.wa_id || lead?.phone || lead?.mobile || msg.wa_id || msg.phone || msg.from || msg.contact || msg.recipient || "";
  }

  if (cleanChannel === "facebook") {
    return lead?.facebook_sender_id || lead?.facebook_chat_id || lead?.facebook_id || lead?.platform_contact_id || msg.platform_contact_id || msg.from || msg.sender || msg.contact || msg.recipient || "";
  }

  if (cleanChannel === "instagram") {
    return lead?.instagram_sender_id || lead?.instagram_chat_id || lead?.instagram_id || lead?.platform_contact_id || msg.platform_contact_id || msg.from || msg.sender || msg.contact || msg.recipient || "";
  }

  if (cleanChannel === "discord") {
    return lead?.discord_channel_id || lead?.discord_chat_id || lead?.discord_id || lead?.platform_contact_id || msg.channel_id || msg.platform_contact_id || msg.from || msg.sender || msg.contact || msg.recipient || "";
  }

  if (["reddit", "linkedin", "youtube", "tiktok", "twitter"].includes(cleanChannel)) {
    return (
      lead?.platform_contact_id || lead?.[`${cleanChannel}_chat_id`] || lead?.[`${cleanChannel}_id`] || lead?.[`${cleanChannel}_username`] ||
      msg.platform_contact_id || msg[`${cleanChannel}_chat_id`] || msg[`${cleanChannel}_id`] || msg[`${cleanChannel}_username`] ||
      msg.from || msg.sender || msg.contact || msg.recipient || lead?.platform_username || lead?.username || ""
    );
  }

  return lead?.platform_contact_id || lead?.phone || lead?.email || msg.platform_contact_id || msg.from || msg.sender || msg.contact || msg.recipient || lead?.platform_username || lead?.username || "";
}

function extractProviderError(error) {
  const data = error?.response?.data;
  if (!data) return error?.message || "Provider request failed";
  if (typeof data === "string") return data;
  return data?.error?.message || data?.description || data?.message || JSON.stringify(data);
}

function classifyWhatsAppProviderFailure(error, providerError = "") {
  const raw = JSON.stringify(error?.response?.data || {}) + " " + String(providerError || error?.message || "");
  const text = raw.toLowerCase();
  const status = Number(error?.response?.status || error?.statusCode || 0);

  if (text.includes("rate") || text.includes("too many") || status === 429) {
    return { category: "provider_rate_limited", whatsapp_status: "retry_later", retryable: true, suppress_until_fixed: false };
  }
  if (text.includes("template") || text.includes("parameter") || text.includes("translation") || text.includes("language")) {
    return { category: "template_failed", whatsapp_status: "template_failed", retryable: false, suppress_until_fixed: false };
  }
  if (text.includes("recipient") && (text.includes("not") || text.includes("unable") || text.includes("undeliverable"))) {
    return { category: "possible_no_whatsapp", whatsapp_status: "possible_no_whatsapp", retryable: false, suppress_until_fixed: true };
  }
  if (text.includes("not a whatsapp") || text.includes("does not have whatsapp") || text.includes("not on whatsapp")) {
    return { category: "possible_no_whatsapp", whatsapp_status: "possible_no_whatsapp", retryable: false, suppress_until_fixed: true };
  }
  if (text.includes("invalid") && (text.includes("phone") || text.includes("recipient") || text.includes("number") || text.includes("to"))) {
    return { category: "invalid_whatsapp_number", whatsapp_status: "invalid_whatsapp_number", retryable: false, suppress_until_fixed: true };
  }
  if (text.includes("permission") || text.includes("access token") || text.includes("oauth") || status === 401 || status === 403) {
    return { category: "provider_auth_or_permission", whatsapp_status: "provider_failed", retryable: true, suppress_until_fixed: false };
  }
  return { category: "provider_failed", whatsapp_status: "provider_failed", retryable: true, suppress_until_fixed: false };
}

function ngUpdateLeadWhatsAppSendStatus(lead, result = {}) {
  if (!lead) return;
  const now = nowIso();
  if (result.success) {
    lead.whatsapp_status = "message_sent";
    lead.whatsapp_validation_status = "message_sent";
    lead.whatsapp_last_sent_at = now;
    if (result.quick_action === "first_message") {
      lead.first_message_queue_status = "sent";
      lead.first_message_sent_at = lead.first_message_sent_at || now;
    }
  } else {
    lead.whatsapp_status = result.whatsapp_status || "provider_failed";
    lead.whatsapp_validation_status = result.category || result.whatsapp_status || "provider_failed";
    lead.whatsapp_last_error = result.error || "Provider failed";
    lead.whatsapp_last_error_at = now;
    lead.whatsapp_failure_category = result.category || "provider_failed";
    if (result.suppress_until_fixed) {
      lead.whatsapp_send_suppressed = true;
      lead.whatsapp_suppressed_reason = result.category || "provider_failed";
      lead.first_message_queue_status = "failed_needs_fix";
    } else if (result.retryable) {
      lead.first_message_queue_status = lead.first_message_queue_status === "sent" ? "sent" : "retry_later";
    } else {
      lead.first_message_queue_status = lead.first_message_queue_status === "sent" ? "sent" : "failed";
    }
  }
  lead.updated_at = now;
}


function ngDedupeHashText(value = "") {
  const clean = String(value || "").toLowerCase().replace(/\s+/g, " ").trim().slice(0, 1200);
  return crypto.createHash("sha1").update(clean || "empty").digest("hex").slice(0, 16);
}

function ngMessageLogTimeMs(item = {}) {
  const raw = item.sent_at || item.created_at || item.created || item.updated_at || item.timestamp || "";
  const ms = new Date(raw).getTime();
  return Number.isFinite(ms) ? ms : 0;
}

function ngDeliveryIdentity({ lead = null, leadId = null, to = "" } = {}) {
  return String(lead?.id || leadId || to || "").trim();
}

function ngBuildDeliveryPurpose({ templateId = null, metadata = {} } = {}) {
  const candidates = [
    metadata.delivery_purpose,
    metadata.daily_live_session_action,
    metadata.google_meet_action,
    metadata.quick_action,
    metadata.automation_step_id,
    metadata.template_key,
    metadata.template_name,
    metadata.whatsapp_template_name,
    templateId,
    metadata.source,
  ];
  for (const value of candidates) {
    const clean = normalizeTemplateLookupKey(value || "");
    if (clean) return clean;
  }
  return "manual_message";
}

function ngBuildDeliveryDedupeKey({ lead = null, leadId = null, channel = "whatsapp", to = "", templateId = null, text = "", metadata = {} } = {}) {
  const identity = ngDeliveryIdentity({ lead, leadId, to });
  const purpose = ngBuildDeliveryPurpose({ templateId, metadata });
  const dateScope = String(
    metadata.delivery_date_key ||
    metadata.daily_live_session_date ||
    (metadata.google_meet_appointment_id ? `${metadata.google_meet_appointment_id}:${metadata.google_meet_action || "google_meet"}` : "") ||
    ngDailySessionDateKey(new Date())
  );
  const templateKey = normalizeTemplateLookupKey(metadata.template_key || metadata.template_name || metadata.whatsapp_template_name || templateId || "");
  const textHash = ngDedupeHashText(text || "");
  return ["v67", normalizeAutomationChannel(channel || "whatsapp"), identity, purpose, templateKey, dateScope, textHash].join("|");
}

function ngDeliveryStatusCountsAsSent(status = "") {
  const clean = normalizeCrmLower(status || "", "");
  return ["sent", "delivered", "read", "queued", "queued_for_approval"].includes(clean);
}

function ngFindRecentDuplicateDelivery(db = {}, payload = {}) {
  const metadata = payload.metadata || {};
  if (metadata.allow_duplicate_send === true || metadata.skip_dedupe === true) return null;

  const key = ngBuildDeliveryDedupeKey(payload);
  const identity = ngDeliveryIdentity(payload);
  const channel = normalizeAutomationChannel(payload.channel || "whatsapp");
  const nowMs = Date.now();
  const shortWindowMs = Math.max(30, Number(metadata.dedupe_window_seconds || 180)) * 1000;

  const locks = ensureCrmArray(db, "message_delivery_locks");
  const activeLock = locks.find((lock) => {
    if (String(lock.delivery_dedupe_key || "") !== key) return false;
    if (!["sending", "queued"].includes(String(lock.status || ""))) return false;
    const age = nowMs - ngMessageLogTimeMs(lock);
    return age >= 0 && age <= shortWindowMs;
  });
  if (activeLock) return { type: "active_lock", key, existing: activeLock };

  const logs = [
    ...ensureCrmArray(db, "message_logs"),
    ...ensureCrmArray(db, "outbound_messages"),
  ];
  const textHash = ngDedupeHashText(payload.text || "");
  const purpose = ngBuildDeliveryPurpose(payload);
  const dateScope = String(metadata.delivery_date_key || metadata.daily_live_session_date || ngDailySessionDateKey(new Date()));

  const duplicateLog = logs.find((log) => {
    if (!ngDeliveryStatusCountsAsSent(log.status)) return false;
    const logMeta = log.metadata || {};
    const logChannel = normalizeAutomationChannel(log.channel || log.provider || "whatsapp");
    if (logChannel !== channel) return false;
    const sameIdentity = String(log.lead_id || "") === identity || String(log.to || log.recipient || "") === String(payload.to || "");
    if (!sameIdentity) return false;
    if (String(logMeta.delivery_dedupe_key || "") === key) return true;

    const logPurpose = ngBuildDeliveryPurpose({ templateId: log.template_id, metadata: logMeta });
    const logDateScope = String(logMeta.delivery_date_key || logMeta.daily_live_session_date || String(log.sent_at || log.created_at || "").slice(0, 10));
    const sameScopedAction = logPurpose === purpose && logDateScope === dateScope && purpose !== "manual_message";
    if (sameScopedAction) return true;

    const age = nowMs - ngMessageLogTimeMs(log);
    if (age >= 0 && age <= shortWindowMs && ngDedupeHashText(log.text || log.body || "") === textHash) return true;
    return false;
  });

  return duplicateLog ? { type: "message_log", key, existing: duplicateLog } : null;
}

function ngStartDeliveryLock(db = {}, payload = {}) {
  const key = ngBuildDeliveryDedupeKey(payload);
  const lock = withTimestamps({
    id: uuid(),
    delivery_dedupe_key: key,
    lead_id: payload.lead?.id || payload.leadId || null,
    channel: normalizeAutomationChannel(payload.channel || "whatsapp"),
    to: payload.to || "",
    template_id: payload.templateId || null,
    status: "sending",
    metadata: payload.metadata || {},
  });
  ensureCrmArray(db, "message_delivery_locks").push(lock);
  return lock;
}

function ngFinishDeliveryLock(lock = null, status = "sent", extra = {}) {
  if (!lock) return;
  lock.status = status;
  lock.finished_at = nowIso();
  lock.updated_at = nowIso();
  Object.assign(lock, extra || {});
}

function ngRecentlyContactedMinutesAgo(lead = {}, minutes = 10) {
  const raw = lead.last_contacted_at || lead.last_outbound_sent_at || lead.whatsapp_last_sent_at || lead.first_message_sent_at || "";
  if (!raw) return false;
  const ms = new Date(raw).getTime();
  if (!Number.isFinite(ms)) return false;
  return Date.now() - ms >= 0 && Date.now() - ms <= Math.max(1, Number(minutes || 10)) * 60000;
}

function ngLiveSessionTimingStateNow(db = {}, date = new Date()) {
  const settings = db?.ai_orchestration_settings || db?.assistant_settings || {};
  const tz = "America/New_York";
  const { weekday, hour, minute } = ngDailySessionTimeParts(date, tz);
  const day = String(weekday || "").toLowerCase();
  const reminderMinutes = Number(settings.session_reminder_minutes || settings.default_session_reminder_minutes || 5);
  const postDelay = Number(settings.post_session_followup_delay_minutes || 120);
  const total = hour * 60 + minute;
  const sessionTotal = 13 * 60;

  if (day.startsWith("sat") || day.startsWith("sun")) return { phase: "no_session_day", weekday, total, sessionTotal };
  if (total < sessionTotal - reminderMinutes) return { phase: "before_session_invite", weekday, total, sessionTotal };
  if (total >= sessionTotal - reminderMinutes && total < sessionTotal) return { phase: "reminder_window", weekday, total, sessionTotal };
  if (total >= sessionTotal && total <= sessionTotal + 15) return { phase: "live_window", weekday, total, sessionTotal };
  if (total > sessionTotal + 15 && total < sessionTotal + postDelay) return { phase: "session_finished_waiting_recording_followup", weekday, total, sessionTotal };
  return { phase: "after_session", weekday, total, sessionTotal };
}

function ngShouldUseTodayLiveSessionFirstInvite(db = {}, date = new Date()) {
  return ngLiveSessionTimingStateNow(db, date).phase === "before_session_invite";
}

async function sendCrmMessage({
  db,
  brandId = null,
  channel = "whatsapp",
  to = "",
  subject = "",
  text = "",
  templateId = null,
  templateVariables = {},
  leadId = null,
  enrollmentId = null,
  flowId = null,
  runId = null,
  queueId = null,
  metadata = {},
  mediaUrl = "",
  mediaId = "",
  mediaType = "",
  caption = "",
}) {
  const forceFreeformAiAuto = Boolean(
    metadata?.ai_auto === true ||
    metadata?.full_ai_auto === true ||
    [
      "full_ai_auto",
      "process_ai_auto",
      "ayla_auto_wakeup",
      "webhook_ai_auto_wakeup",
      "universal_social_webhook_wakeup",
      "social_webhook_full_ai_auto",
    ].includes(String(metadata?.source || "").trim())
  );

  // v96: WhatsApp templates are only for cold first-message/reopen/scheduled approved messages.
  // Once a student replies and Ayla is in Full AI Auto, force a natural free-form AI reply.
  const template = (!forceFreeformAiAuto && templateId) ? getMessageTemplateByKey(db, templateId) : null;
  const lead = leadId ? getLeadByAnyId(db, leadId) : null;
  const commandMetadata = ngAylaOutboundCommandMetadata(db, lead || templateVariables?.lead || {});
  const cleanChannel = resolveCrmChannel({
    requestedChannel: channel || template?.channel || template?.send_channel || "auto",
    lead,
    template,
    fallback: "whatsapp",
  });
  const variables = { ...(templateVariables || {}), lead: lead || templateVariables?.lead || {} };
  const finalSubject = renderTemplateString(subject || template?.subject || "", variables) || "NextGen USMLE";
  const finalText = renderTemplateString(text || template?.body || template?.message || "", variables);
  const finalTo = getBestRecipientForChannel({ channel: cleanChannel, to, lead });
  const integration = getIntegrationByPlatform(db, cleanChannel) || { id: null, platform: cleanChannel, brand_id: brandId };
  const resolvedWhatsAppTemplateName = cleanChannel === "whatsapp" && !forceFreeformAiAuto ? getWhatsAppTemplateName({ template, metadata }) : "";
  const resolvedWhatsAppLanguageCode = cleanChannel === "whatsapp" && !forceFreeformAiAuto ? getWhatsAppLanguageCode({ template, metadata }) : "";
  const resolvedWhatsAppComponents = cleanChannel === "whatsapp" && !forceFreeformAiAuto
    ? buildWhatsAppTemplateComponents({ template, lead, variables, metadata })
    : [];
  const resolvedMediaUrl = normalizeCrmString(mediaUrl || metadata.media_url || metadata.mediaUrl || metadata.image_url || metadata.imageUrl || metadata.public_url || "");
  const resolvedMediaId = normalizeCrmString(mediaId || metadata.media_id || metadata.mediaId || metadata.whatsapp_media_id || "");
  const resolvedMediaType = normalizeCrmLower(mediaType || metadata.media_type || metadata.mediaType || (resolvedMediaUrl || resolvedMediaId ? "image" : ""), "");
  const resolvedCaption = normalizeCrmString(caption || metadata.caption || finalText || "");

  const baseLog = {
    brand_id: brandId,
    channel: cleanChannel,
    provider: cleanChannel,
    lead_id: lead?.id || leadId || null,
    enrollment_id: enrollmentId,
    flow_id: flowId,
    run_id: runId,
    queue_id: queueId,
    template_id: template?.id || templateId || null,
    to: finalTo,
    subject: finalSubject,
    text: finalText,
    metadata: {
      ...(metadata || {}),
      ai_control: commandMetadata,
      source: metadata?.source || "crm_messages_send",
      template_key: template?.key || templateId || null,
      ...(cleanChannel === "whatsapp" ? {
        template_name: resolvedWhatsAppTemplateName,
        whatsapp_template_name: resolvedWhatsAppTemplateName,
        language_code: resolvedWhatsAppLanguageCode,
        components: resolvedWhatsAppComponents,
        media_url: resolvedMediaUrl,
        media_id: resolvedMediaId,
        media_type: resolvedMediaType,
        caption: resolvedCaption,
      } : {}),
    },
  };

  let deliveryLock = null;

  try {
    if (!finalTo) {
      const error = new Error(`Recipient is required for ${cleanChannel}.`);
      error.statusCode = 400;
      throw error;
    }

    const deliveryPayload = {
      lead,
      leadId: lead?.id || leadId || null,
      channel: cleanChannel,
      to: finalTo,
      templateId: template?.id || templateId || null,
      text: finalText,
      metadata: baseLog.metadata || {},
    };
    const duplicate = ngFindRecentDuplicateDelivery(db, deliveryPayload);
    if (duplicate) {
      return {
        success: true,
        sent: false,
        skipped: true,
        duplicate_blocked: true,
        channel: cleanChannel,
        provider: cleanChannel,
        to: finalTo,
        status: "duplicate_blocked",
        reason: "duplicate_message_blocked",
        delivery_dedupe_key: duplicate.key,
        duplicate_type: duplicate.type,
      };
    }

    deliveryLock = ngStartDeliveryLock(db, deliveryPayload);
    baseLog.metadata.delivery_dedupe_key = deliveryLock.delivery_dedupe_key;

    let providerResponse = null;
    let providerMessageId = null;

    if (cleanChannel === "whatsapp") {
      providerResponse = await sendWhatsAppCloudMessage({
        to: finalTo,
        text: finalText,
        templateName: resolvedWhatsAppTemplateName,
        languageCode: resolvedWhatsAppLanguageCode,
        components: resolvedWhatsAppComponents,
        mediaUrl: resolvedMediaUrl,
        mediaId: resolvedMediaId,
        mediaType: resolvedMediaType || "image",
        caption: resolvedCaption,
      });
      providerMessageId = providerResponse?.messages?.[0]?.id || null;
    } else if (cleanChannel === "telegram") {
      providerResponse = await sendTelegramMessage({ to: finalTo, text: finalText, integration });
      providerMessageId = providerResponse?.result?.message_id || null;
    } else if (cleanChannel === "email") {
      providerResponse = await sendEmailMessage({ to: finalTo, subject: finalSubject, text: finalText });
      providerMessageId = providerResponse?.id || providerResponse?.messageId || null;
    } else if (["facebook", "instagram", "discord", "reddit", "linkedin", "youtube", "tiktok", "twitter", "other"].includes(cleanChannel)) {
      providerResponse = await sendSocialMessage({
        db,
        integration,
        body: {
          to: finalTo,
          recipient: finalTo,
          subject: finalSubject,
          text: finalText,
          message: finalText,
          body: finalText,
          messaging_type: metadata.messaging_type || "RESPONSE",
          media_url: resolvedMediaUrl,
          media_id: resolvedMediaId,
          media_type: resolvedMediaType,
        },
      });
      providerMessageId = providerResponse?.raw?.message_id || providerResponse?.raw?.recipient_id || providerResponse?.approval_item?.id || null;
    } else {
      const draft = withTimestamps({
        id: uuid(),
        brand_id: brandId,
        channel: cleanChannel,
        action_type: `${cleanChannel}_manual_send_draft`,
        input_text: finalText,
        output_text: finalText,
        status: "draft",
        approval_status: "needs_approval",
        metadata: { to: finalTo, subject: finalSubject },
      });
      ensureCrmArray(db, "approval_queue").push(draft);
      providerResponse = { manual_first: true, approval_item: draft };
      providerMessageId = draft.id;
    }

    const log = createMessageLog(db, {
      ...baseLog,
      status: providerResponse?.manual_first ? "queued" : "sent",
      provider_message_id: providerMessageId,
      provider_response: providerResponse,
      sent_at: providerResponse?.manual_first ? null : nowIso(),
    });
    ngFinishDeliveryLock(deliveryLock, providerResponse?.manual_first ? "queued" : "sent", { message_log_id: log.id, provider_message_id: providerMessageId });

    if (lead) {
      appendSocialConversation(db, {
        lead,
        platform: cleanChannel,
        direction: "outbound",
        text: finalText,
        payload: { provider_response: providerResponse, message_log_id: log.id },
        integration,
      });
      if (!providerResponse?.manual_first) {
        const sentNow = nowIso();
        lead.last_contacted_at = sentNow;
        lead.last_outbound_sent_at = sentNow;
      }
      if (cleanChannel === "whatsapp" && !providerResponse?.manual_first) {
        ngUpdateLeadWhatsAppSendStatus(lead, { success: true, quick_action: metadata?.quick_action || metadata?.source || "message" });
      }
    }

    return {
      success: !providerResponse?.manual_first,
      queued: Boolean(providerResponse?.manual_first),
      channel: cleanChannel,
      provider: cleanChannel,
      to: finalTo,
      status: providerResponse?.manual_first ? "queued_for_approval" : "sent",
      message: providerResponse?.manual_first ? "Provider is manual-first; message queued for approval." : `${cleanChannel} message sent`,
      log,
      provider_response: providerResponse,
    };
  } catch (error) {
    const providerError = extractProviderError(error);
    const failure = cleanChannel === "whatsapp" ? classifyWhatsAppProviderFailure(error, providerError) : { category: "provider_failed", whatsapp_status: "provider_failed", retryable: true, suppress_until_fixed: false };
    const log = createMessageLog(db, {
      ...baseLog,
      status: "failed",
      error: providerError,
      provider_response: error.response?.data || null,
      metadata: {
        ...(baseLog.metadata || {}),
        hint: error.hint || null,
        status_code: error.statusCode || error.response?.status || null,
        failure_category: failure.category,
        whatsapp_status: failure.whatsapp_status,
      },
    });
    ngFinishDeliveryLock(deliveryLock, "failed", { message_log_id: log.id, error: providerError });

    if (lead && cleanChannel === "whatsapp") {
      ngUpdateLeadWhatsAppSendStatus(lead, {
        success: false,
        error: providerError,
        category: failure.category,
        whatsapp_status: failure.whatsapp_status,
        retryable: failure.retryable,
        suppress_until_fixed: failure.suppress_until_fixed,
      });
    }

    return {
      success: false,
      channel: cleanChannel,
      provider: cleanChannel,
      to: finalTo,
      status: "failed",
      error: providerError,
      hint: error.hint || null,
      category: failure.category,
      whatsapp_status: failure.whatsapp_status,
      retryable: failure.retryable,
      suppress_until_fixed: failure.suppress_until_fixed,
      log,
      provider_response: error.response?.data || null,
    };
  }
}

function normalizeAutomationEnrollment(body = {}, existing = null, brandId = null) {
  const now = nowIso();
  return {
    ...(existing || {}),
    ...(body || {}),
    id: body.id || existing?.id || uuid(),
    brand_id: body.brand_id || existing?.brand_id || brandId || null,
    flow_id: body.flow_id || existing?.flow_id || null,
    lead_id: body.lead_id || existing?.lead_id || null,
    channel: normalizeAutomationChannel(body.channel || existing?.channel || "whatsapp"),
    recipient: body.recipient || existing?.recipient || body.to || "",
    status: body.status || existing?.status || "active",
    current_step_index: Number(body.current_step_index ?? existing?.current_step_index ?? 0),
    next_run_at: body.next_run_at || existing?.next_run_at || now,
    started_at: existing?.started_at || body.started_at || now,
    completed_at: body.completed_at || existing?.completed_at || null,
    paused_at: body.paused_at || existing?.paused_at || null,
    metadata: body.metadata || existing?.metadata || {},
    created_at: existing?.created_at || body.created_at || now,
    updated_at: now,
  };
}

function getFlowStepDelayMs(step = {}) {
  const minutes = Number(step.delay_minutes ?? step.wait_minutes ?? step.after_minutes ?? 0) || 0;
  const hours = Number(step.delay_hours ?? step.wait_hours ?? 0) || 0;
  const days = Number(step.delay_days ?? step.wait_days ?? 0) || 0;
  return Math.max(0, Math.round((minutes * 60 + hours * 3600 + days * 86400) * 1000));
}

function getFlowStepMessage(step = {}, flow = {}, lead = null) {
  const fallback = "Hi Doctor, this is NextGen USMLE. Are you preparing for Step 1 or Step 2 CK, and when is your exam planned?";
  const raw = step.message || step.message_text || step.body || step.text || step.content || flow.default_message || fallback;
  return renderTemplateString(raw, { lead: lead || {}, flow, step });
}

function isSendStep(step = {}) {
  const type = String(step.type || step.action || "").toLowerCase();
  return type.includes("send") || type.includes("message") || type.includes("whatsapp") || type.includes("email") || type.includes("sms") || type === "draft_or_send";
}

async function processAutomationEnrollment({ db, enrollment, flow, autoSend = true, maxSteps = 1 }) {
  const events = [];
  const lead = enrollment.lead_id ? getLeadByAnyId(db, enrollment.lead_id) : null;
  const steps = Array.isArray(flow.steps) ? flow.steps : [];
  let processed = 0;

  while (enrollment.status === "active" && enrollment.current_step_index < steps.length && processed < maxSteps) {
    const step = steps[enrollment.current_step_index] || {};
    const delayMs = getFlowStepDelayMs(step);

    if (delayMs > 0 && !step._delay_already_applied) {
      enrollment.next_run_at = new Date(Date.now() + delayMs).toISOString();
      step._delay_already_applied = true;
      events.push(withTimestamps({ id: uuid(), brand_id: enrollment.brand_id, flow_id: flow.id, enrollment_id: enrollment.id, lead_id: enrollment.lead_id, event_type: "step_delayed", message: `Step delayed until ${enrollment.next_run_at}`, step }));
      break;
    }

    if (isSendStep(step)) {
      const channel = normalizeAutomationChannel(step.channel || enrollment.channel || flow.platforms?.[0] || "whatsapp");
      const to = step.to || enrollment.recipient || lead?.whatsapp || lead?.phone || lead?.email || "";
      const messageText = getFlowStepMessage(step, flow, lead);
      const approvalRequired = step.approval_required === true || flow.approval_mode === "draft_first" || flow.approval_mode === "needs_approval";

      if (approvalRequired && !autoSend) {
        const approval = withTimestamps({
          id: uuid(),
          brand_id: enrollment.brand_id,
          flow_id: flow.id,
          enrollment_id: enrollment.id,
          lead_id: enrollment.lead_id,
          channel,
          to,
          message: messageText,
          status: "needs_approval",
          type: "automation_message",
          step,
        });
        ensureCrmArray(db, "approval_queue").push(approval);
        events.push(withTimestamps({ id: uuid(), brand_id: enrollment.brand_id, flow_id: flow.id, enrollment_id: enrollment.id, lead_id: enrollment.lead_id, event_type: "approval_created", message: "Message queued for approval", approval_id: approval.id }));
      } else {
        const result = await sendCrmMessage({
          db,
          brandId: enrollment.brand_id,
          channel,
          to,
          text: messageText,
          templateId: step.template_id || step.template_key || null,
          templateVariables: { lead: lead || {}, flow, step },
          leadId: enrollment.lead_id,
          enrollmentId: enrollment.id,
          flowId: flow.id,
          metadata: { automation_step_id: step.id || null, template_name: step.provider_template_name || step.whatsapp_template_name || "" },
        });
        events.push(withTimestamps({ id: uuid(), brand_id: enrollment.brand_id, flow_id: flow.id, enrollment_id: enrollment.id, lead_id: enrollment.lead_id, event_type: result.success ? "message_sent" : "message_failed", message: result.success ? "Automation message sent" : result.error, message_log_id: result.log?.id || null, step }));
      }
    } else {
      events.push(withTimestamps({ id: uuid(), brand_id: enrollment.brand_id, flow_id: flow.id, enrollment_id: enrollment.id, lead_id: enrollment.lead_id, event_type: "step_recorded", message: `Automation step recorded: ${step.label || step.type || "step"}`, step }));
    }

    enrollment.current_step_index += 1;
    processed += 1;
    enrollment.next_run_at = nowIso();
  }

  if (enrollment.current_step_index >= steps.length) {
    enrollment.status = "completed";
    enrollment.completed_at = nowIso();
  }

  enrollment.updated_at = nowIso();
  ensureCrmArray(db, "crm_flow_events").push(...events);
  return { enrollment, events, processed_steps: processed };
}


function ngLeadHasOutboundTemplate(db, lead = {}, templateKeys = []) {
  const leadId = getStableLeadId(lead) || lead.id || lead.lead_id || "";
  if (!leadId) return false;
  const wanted = new Set(templateKeys.map(normalizeTemplateLookupKey).filter(Boolean));
  const logs = [
    ...ensureCrmArray(db, "message_logs"),
    ...ensureCrmArray(db, "outbound_messages"),
    ...ensureCrmArray(db, "conversations"),
  ];
  return logs.some((item) => {
    if (String(item.lead_id || "") !== String(leadId)) return false;
    if (!ngIsOutboundMessage(item) && String(item.direction || "").toLowerCase() !== "outbound") return false;
    const meta = item.metadata || item.meta || {};
    const candidates = [
      item.template_id,
      item.template_key,
      item.template_name,
      item.whatsapp_template_name,
      meta.template_id,
      meta.template_key,
      meta.template_name,
      meta.whatsapp_template_name,
    ].map(normalizeTemplateLookupKey).filter(Boolean);
    return candidates.some((key) => wanted.has(key) || wanted.has(WHATSAPP_TEMPLATE_NAME_ALIASES[key] || key));
  });
}

function ngLeadLooksLikeMetaCampaignLead(lead = {}) {
  const text = [
    lead.origin,
    lead.lead_origin,
    lead.lead_source,
    lead.source,
    lead.source_type,
    lead.created_from,
    lead.import_source,
    lead.opt_in_status,
    lead.campaign_name,
    lead.campaign_key,
    lead.campaign_id,
  ].map((x) => String(x || "").toLowerCase()).join(" ");

  return Boolean(
    text.includes("meta") ||
    text.includes("lead form") ||
    text.includes("lead_form") ||
    text.includes("facebook lead") ||
    text.includes("usmle step1 live session") ||
    text.includes("meta_usmle") ||
    lead.campaign_id ||
    lead.campaign_name ||
    lead.campaign_key
  );
}

function ngLeadExplicitlyQueuedForFirstMessage(lead = {}) {
  const queueStatus = normalizeCrmLower(lead.first_message_queue_status || lead.first_message_status || lead.first_template_status || "", "");
  const sourceText = [
    lead.origin,
    lead.lead_origin,
    lead.lead_source,
    lead.source,
    lead.source_type,
    lead.source_platform,
    lead.created_from,
    lead.import_source,
    lead.first_message_queue_source,
    lead.opt_in_status,
  ].map((x) => String(x || "").toLowerCase()).join(" ");

  return Boolean(
    lead.queue_first_message === true ||
    lead.send_first_message_after_import === true ||
    lead.first_message_after_import === true ||
    ["queued", "pending", "retry_later", "failed", "failed_needs_fix"].includes(queueStatus) ||
    sourceText.includes("import_confirm") ||
    sourceText.includes("console_import_test") ||
    sourceText.includes("meta") ||
    sourceText.includes("lead form") ||
    sourceText.includes("requested_contact")
  );
}

function ngCanSendAutoFirstMessage(db, lead = {}) {
  const stage = normalizeCrmLeadStageValue(lead.stage || lead.lead_stage || lead.sales_stage || lead.pipeline_stage || lead.status || "new_lead", "new_lead");
  const status = normalizeCrmLower(lead.status || lead.lead_status || "new", "new");
  const unsub = normalizeCrmLower(lead.unsubscribe_status || lead.opt_out_status || "active", "active");
  const aiMode = normalizeCrmLeadAiMode(lead.ai_mode || lead.automation_mode || "draft");
  const queuedByImportOrAdmin = ngLeadExplicitlyQueuedForFirstMessage(lead);

  if (["paid_enrolled", "not_interested", "lost", "unsubscribed", "deleted"].includes(stage)) return { ok: false, reason: "lead_stage_blocks_first_message" };
  if (["paid", "enrolled", "lost", "unsubscribed", "not_interested", "deleted"].includes(status)) return { ok: false, reason: "lead_status_blocks_first_message" };
  if (["stop", "stopped", "opted_out", "unsubscribed", "inactive"].includes(unsub)) return { ok: false, reason: "lead_unsubscribed_or_inactive" };
  if (aiMode === "manual" && lead.ai_enabled === false) return { ok: false, reason: "ai_manual_disabled" };

  // v95: do not permanently block an explicitly queued first message because of an old template failure flag.
  // True opt-out/invalid number still blocks; stale template/provider suppressions can be retried after templates are fixed.
  const suppressedReason = normalizeCrmLower(lead.whatsapp_suppressed_reason || lead.first_message_error || "", "");
  if (lead.whatsapp_send_suppressed === true && !queuedByImportOrAdmin) return { ok: false, reason: lead.whatsapp_suppressed_reason || "whatsapp_send_suppressed" };
  if (lead.whatsapp_send_suppressed === true && queuedByImportOrAdmin && (suppressedReason.includes("opt") || suppressedReason.includes("stop") || suppressedReason.includes("invalid"))) return { ok: false, reason: lead.whatsapp_suppressed_reason || "whatsapp_send_suppressed" };

  if (["invalid_whatsapp_number", "possible_no_whatsapp", "needs_country_code", "not_sendable"].includes(normalizeCrmLower(lead.whatsapp_status || lead.whatsapp_validation_status || "", ""))) return { ok: false, reason: lead.whatsapp_status || "whatsapp_not_sendable" };
  if (["needs_country_code", "invalid_phone"].includes(normalizeCrmLower(lead.phone_import_status || lead.phone_import_category || "", ""))) return { ok: false, reason: lead.phone_import_status || "phone_import_not_ready" };
  if (!leadHasRecipientForChannel(lead, "whatsapp")) return { ok: false, reason: "no_whatsapp_recipient" };

  // v95: every imported/new lead may receive the first approved template unless admin turned it off.
  // We no longer require the lead source to literally contain Meta/campaign.
  if (!ngLeadLooksLikeMetaCampaignLead(lead) && !queuedByImportOrAdmin) return { ok: false, reason: "not_queued_for_first_message" };

  if (lead.first_message_sent_at || lead.first_template_sent_at || stage === "first_message_sent") return { ok: false, reason: "first_message_already_marked_sent" };
  if (ngLeadHasOutboundTemplate(db, lead, ["meta_ad_first_message", "first_message_intro", "meta_first_message", "greeting_exam_type_question", "exam_type_question", "sunday_first_message", "welcome_demo_invite"])) return { ok: false, reason: "first_message_already_logged" };
  return { ok: true, reason: "eligible" };
}

function ngFirstMessageVariablesForLead(lead = {}) {
  const rawName = safeTemplateValue(lead.student_name || lead.lead_name || lead.name || lead.full_name || lead.first_name || lead.whatsapp_name || lead.profile_name || "");
  const studentName = rawName && !looksLikePhoneOnly(rawName) ? rawName : "Doctor";
  return {
    student_name: studentName,
    lead_name: studentName,
    doctor_name: studentName,
    exam_type: safeTemplateValue(lead.exam_type || lead.exam_track || lead.exam || lead.program_track || "USMLE Step 1"),
    exam_track: safeTemplateValue(lead.exam_track || lead.exam_type || lead.exam || "USMLE Step 1"),
    session_time: safeTemplateValue(lead.session_time || lead.live_session_time || lead.fixed_run_time || "1:00 PM EST"),
  };
}


function ngGetAssistantTimeZone(db = {}) {
  const settings = db?.ai_orchestration_settings || db?.assistant_settings || {};
  return normalizeCrmString(
    settings.live_session_timezone ||
      settings.default_timezone ||
      settings.timezone ||
      process.env.NEXTGEN_LIVE_SESSION_TIMEZONE ||
      process.env.TZ ||
      "America/New_York"
  ) || "America/New_York";
}

function ngWeekdayInTimeZone(date = new Date(), timeZone = "America/New_York") {
  try {
    return new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone }).format(date);
  } catch (_) {
    return new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "America/New_York" }).format(date);
  }
}

function ngIsSundayNoLiveSessionDay(db = {}, date = new Date()) {
  const settings = db?.ai_orchestration_settings || {};
  const ownerText = normalizeCrmString([
    settings.owner_live_command,
    settings.owner_do_rule,
    settings.owner_dont_rule,
    settings.live_session_rule,
    settings.meta_lead_first_flow,
  ].filter(Boolean).join("\n")).toLowerCase();

  const tz = ngGetAssistantTimeZone(db);
  const weekday = ngWeekdayInTimeZone(date, tz).toLowerCase();
  const isSunday = weekday === "sunday";

  // Sunday is the business default no-live-session day for NextGen. Admin command can reinforce it.
  if (!isSunday) return false;
  if (!ownerText) return true;
  if (ownerText.includes("sunday") && (ownerText.includes("do not invite") || ownerText.includes("no live") || ownerText.includes("no session") || ownerText.includes("greeting_exam_type_question"))) return true;
  return true;
}

function ngResolveAutoFirstMessageTemplateKey(db = {}, lead = {}) {
  const settings = db?.ai_orchestration_settings || db?.assistant_settings || {};
  const leadPreferred = normalizeTemplateLookupKey(lead.first_message_template_key || lead.template_key || lead.whatsapp_template_key || "");
  if (leadPreferred) return WHATSAPP_TEMPLATE_NAME_ALIASES[leadPreferred] || leadPreferred;

  const settingsPreferred = normalizeTemplateLookupKey(settings.first_message_template_key || settings.meta_first_message_template_key || settings.default_first_message_template_key || "");
  if (settingsPreferred) return WHATSAPP_TEMPLATE_NAME_ALIASES[settingsPreferred] || settingsPreferred;

  // v95: use the already-approved Meta first-message template by default for all first outreach.
  // This is safest for cold WhatsApp messages because it opens a conversation with an approved Marketing template.
  if (ngIsSundayNoLiveSessionDay(db)) return "greeting_exam_type_question";
  return "meta_ad_first_message";
}

function ngGetOfficialWhatsAppTemplateNameForKey(templateKey = "") {
  const clean = normalizeTemplateLookupKey(templateKey);
  return WHATSAPP_TEMPLATE_NAME_ALIASES[clean] || clean || "meta_ad_first_message";
}

function ngAutoFirstVirtualTemplate(templateKey = "meta_ad_first_message", existingTemplate = null) {
  const key = ngGetOfficialWhatsAppTemplateNameForKey(templateKey);
  if (existingTemplate) {
    return {
      ...existingTemplate,
      key: existingTemplate.key || key,
      template_key: existingTemplate.template_key || existingTemplate.key || key,
      provider_template_name: existingTemplate.provider_template_name || existingTemplate.meta_template_name || existingTemplate.whatsapp_template_name || key,
      meta_template_name: existingTemplate.meta_template_name || existingTemplate.provider_template_name || existingTemplate.whatsapp_template_name || key,
      whatsapp_template_name: existingTemplate.whatsapp_template_name || existingTemplate.meta_template_name || existingTemplate.provider_template_name || key,
      language_code: existingTemplate.language_code || existingTemplate.meta_language || existingTemplate.whatsapp_language || "en",
      meta_language: existingTemplate.meta_language || existingTemplate.language_code || existingTemplate.whatsapp_language || "en",
      whatsapp_language: existingTemplate.whatsapp_language || existingTemplate.meta_language || existingTemplate.language_code || "en",
    };
  }

  if (key === "greeting_exam_type_question") {
    return {
      id: key,
      key,
      template_key: key,
      name: "Greeting Exam Type Question",
      channel: "whatsapp",
      body: "Hi Doctor, welcome to NextGen USMLE. Are you preparing for Step 1 or Step 2 CK?",
      provider_template_name: key,
      meta_template_name: key,
      whatsapp_template_name: key,
      language_code: "en",
      meta_language: "en",
      whatsapp_language: "en",
      variables: [],
    };
  }

  return {
    id: key,
    key,
    template_key: key,
    name: "Meta Ad First Message",
    channel: "whatsapp",
    body: "Hi Doctor {{student_name}}, this is NextGen USMLE. You reached out about {{exam_type}} preparation. We have a live guidance session today at {{session_time}} to explain the program and mentor teaching style. Can you join?",
    provider_template_name: "meta_ad_first_message",
    meta_template_name: "meta_ad_first_message",
    whatsapp_template_name: "meta_ad_first_message",
    language_code: "en",
    meta_language: "en",
    whatsapp_language: "en",
    variables: ["student_name", "exam_type", "session_time"],
  };
}

function ngAutoFirstFallbackTextForTemplate(templateKey = "meta_ad_first_message") {
  const clean = normalizeTemplateLookupKey(templateKey);
  if (clean === "greeting_exam_type_question" || clean === "exam_type_question" || clean === "sunday_first_message") {
    return "Hi Doctor, welcome to NextGen USMLE. Are you preparing for Step 1 or Step 2 CK?";
  }
  return "Hi Doctor {{student_name}}, this is NextGen USMLE. You reached out about {{exam_type}} preparation. We have a live guidance session today at {{session_time}} to explain the program and mentor teaching style. Can you join?";
}

async function ngSendAutoFirstMessageForLead({ db, lead, brandId = null, actorId = "system", source = "auto_first_message", dryRun = false } = {}) {
  const ownerBlock = ngAylaOwnerCommandBlocksBulkSend(db);
  if (ownerBlock.blocked) {
    return { success: true, sent: false, skipped: true, reason: ownerBlock.reason, lead_id: lead?.id || null };
  }

  const allowed = ngCanSendAutoFirstMessage(db, lead || {});
  if (!allowed.ok) {
    return { success: true, sent: false, skipped: true, reason: allowed.reason, lead_id: lead?.id || null };
  }

  const templateKey = ngResolveAutoFirstMessageTemplateKey(db, lead);
  const storedTemplate =
    getMessageTemplateByKey(db, templateKey) ||
    getMessageTemplateByKey(db, templateKey.toUpperCase()) ||
    getMessageTemplateByKey(db, ngGetOfficialWhatsAppTemplateNameForKey(templateKey)) ||
    (templateKey === "meta_ad_first_message" ? getMessageTemplateByKey(db, "META_AD_FIRST_MESSAGE") : null);
  const template = ngAutoFirstVirtualTemplate(templateKey, storedTemplate);
  const vars = { ...ngFirstMessageVariablesForLead(lead), ai_control_command_context: ngBuildAylaCommandContext(db, lead).slice(0, 3000) };
  const fallbackText = ngAutoFirstFallbackTextForTemplate(templateKey);
  const to = getBestRecipientForChannel({ channel: "whatsapp", lead });

  if (dryRun) {
    return { success: true, sent: false, dry_run: true, lead_id: lead.id, to, template_key: templateKey, live_session_timing: ngLiveSessionTimingStateNow(db), variables: vars };
  }

  const result = await sendCrmMessage({
    db,
    brandId: brandId || lead.brand_id || null,
    channel: "whatsapp",
    to,
    subject: "NextGen USMLE",
    text: template?.body || template?.message || fallbackText,
    templateId: template?.id || template?.key || templateKey,
    templateVariables: { ...vars, lead },
    leadId: lead.id || lead.lead_id,
    metadata: {
      source,
      quick_action: "first_message",
      template_key: templateKey,
      sunday_template_router: ngIsSundayNoLiveSessionDay(db),
      live_session_timing_phase: ngLiveSessionTimingStateNow(db).phase,
      template_name: ngGetOfficialWhatsAppTemplateNameForKey(templateKey),
      meta_template_name: ngGetOfficialWhatsAppTemplateNameForKey(templateKey),
      whatsapp_template_name: ngGetOfficialWhatsAppTemplateNameForKey(templateKey),
      language_code: normalizeWhatsAppLanguageCode(template?.meta_language || template?.whatsapp_language || template?.language_code || "en"),
      triggered_by: actorId || "system",
    },
  });

  if (result.success) {
    const now = nowIso();
    lead.stage = "first_message_sent";
    lead.lead_stage = "first_message_sent";
    lead.sales_stage = "first_message_sent";
    lead.pipeline_stage = "first_message_sent";
    lead.first_message_sent_at = now;
    lead.first_template_sent_at = now;
    lead.last_contacted_at = now;
    lead.next_action = "wait_for_reply";
    lead.updated_at = now;
  }

  return { ...result, sent: Boolean(result.success && !result.skipped), lead_id: lead.id || lead.lead_id, template_key: templateKey, sunday_template_router: ngIsSundayNoLiveSessionDay(db), live_session_timing: ngLiveSessionTimingStateNow(db) };
}

function ngGetBulkFirstMessageSettings(db = {}, overrides = {}) {
  const settings = {
    ...(db.ai_orchestration_settings || {}),
    ...(db.bulk_first_message_settings || {}),
    ...(overrides || {}),
  };
  const dailyMax = Math.max(1, Math.min(500, Number(settings.first_message_daily_max || settings.daily_max_first_messages || settings.bulk_first_message_daily_max || process.env.NEXTGEN_FIRST_MESSAGE_DAILY_MAX || 200)));
  const batchSize = Math.max(1, Math.min(25, Number(settings.first_message_batch_size || settings.bulk_first_message_batch_size || process.env.NEXTGEN_FIRST_MESSAGE_BATCH_SIZE || 10)));
  const delayMinutes = Math.max(1, Math.min(60, Number(settings.first_message_batch_delay_minutes || settings.bulk_first_message_batch_delay_minutes || process.env.NEXTGEN_FIRST_MESSAGE_BATCH_DELAY_MINUTES || 5)));
  const pauseFailureRate = Math.max(0.1, Math.min(1, Number(settings.first_message_pause_failure_rate || settings.bulk_first_message_pause_failure_rate || 0.35)));
  const pauseMinutes = Math.max(5, Math.min(180, Number(settings.first_message_pause_minutes_on_high_failure || settings.bulk_first_message_pause_minutes || 30)));
  return { daily_max: dailyMax, batch_size: batchSize, batch_delay_minutes: delayMinutes, pause_failure_rate: pauseFailureRate, pause_minutes_on_high_failure: pauseMinutes };
}

function ngFirstMessageSentTodayCount(db = {}, dateKey = todayKey()) {
  return ensureCrmArray(db, "message_logs").filter((log) => {
    const meta = log.metadata || {};
    const isFirst = normalizeTemplateLookupKey(meta.quick_action || meta.source || log.template_id || meta.template_key || "").includes("first_message") || normalizeTemplateLookupKey(meta.template_key || log.template_id || "") === "meta_ad_first_message";
    const isSent = ["sent", "delivered", "queued"].includes(normalizeCrmLower(log.status || "", ""));
    const logDate = String(log.sent_at || log.created_at || log.created || "").slice(0, 10);
    return isFirst && isSent && logDate === dateKey;
  }).length;
}

function ngGetBulkFirstMessageState(db = {}) {
  if (!db.bulk_first_message_sending_state || typeof db.bulk_first_message_sending_state !== "object") db.bulk_first_message_sending_state = {};
  if (!db.bulk_first_message_sending_state.first_message || typeof db.bulk_first_message_sending_state.first_message !== "object") {
    db.bulk_first_message_sending_state.first_message = { date_key: todayKey(), sent_today: 0, last_batch_sent_at: null, paused_until: null, updated_at: nowIso() };
  }
  return db.bulk_first_message_sending_state.first_message;
}

async function ngRunDueAutoFirstMessages({ db, brandId = null, limit = 25, actorId = "system", dryRun = false, bulkSettings = {} } = {}) {
  const settings = ngGetBulkFirstMessageSettings(db, bulkSettings);
  const state = ngGetBulkFirstMessageState(db);
  const today = todayKey();
  const nowMs = Date.now();

  if (state.date_key !== today) {
    state.date_key = today;
    state.sent_today = 0;
    state.failed_today = 0;
    state.last_batch_sent_at = null;
    state.paused_until = null;
  }

  if (!dryRun && state.paused_until && new Date(state.paused_until).getTime() > nowMs) {
    return [{ success: true, sent: false, skipped: true, reason: "bulk_first_message_paused_until", paused_until: state.paused_until, settings }];
  }

  if (!dryRun && state.last_batch_sent_at) {
    const nextAllowedAt = new Date(new Date(state.last_batch_sent_at).getTime() + settings.batch_delay_minutes * 60000);
    if (nextAllowedAt.getTime() > nowMs) {
      return [{ success: true, sent: false, skipped: true, reason: "bulk_first_message_batch_cooldown", next_allowed_at: nextAllowedAt.toISOString(), settings }];
    }
  }

  const sentTodayFromLogs = ngFirstMessageSentTodayCount(db, today);
  state.sent_today = Math.max(Number(state.sent_today || 0), sentTodayFromLogs);
  const remainingDaily = Math.max(0, settings.daily_max - state.sent_today);
  if (remainingDaily <= 0 && !dryRun) {
    return [{ success: true, sent: false, skipped: true, reason: "bulk_first_message_daily_limit_reached", sent_today: state.sent_today, settings }];
  }

  const runLimit = Math.max(0, Number(limit || 0));
  const effectiveLimit = dryRun ? Math.min(runLimit || settings.batch_size, settings.batch_size) : Math.min(runLimit || settings.batch_size, settings.batch_size, remainingDaily);
  if (effectiveLimit <= 0) return [];

  const leads = ensureCrmArray(db, "leads")
    .filter((lead) => !brandId || String(lead.brand_id || "") === String(brandId || ""))
    .filter((lead) => ngCanSendAutoFirstMessage(db, lead).ok)
    .sort((a, b) => String(a.first_message_queued_at || a.created_at || "").localeCompare(String(b.first_message_queued_at || b.created_at || "")))
    .slice(0, effectiveLimit);

  const results = [];
  let sentCount = 0;
  let failedCount = 0;

  for (const lead of leads) {
    const result = await ngSendAutoFirstMessageForLead({ db, lead, brandId: brandId || lead.brand_id || null, actorId, source: "run_due_auto_first_message", dryRun });
    if (result.sent) sentCount += 1;
    if (result.success === false) failedCount += 1;
    results.push({
      lead_id: lead.id || lead.lead_id,
      name: lead.name || lead.student_name || "Lead",
      to: getBestRecipientForChannel({ channel: "whatsapp", lead }),
      success: Boolean(result.success),
      sent: Boolean(result.sent),
      skipped: Boolean(result.skipped),
      reason: result.reason || result.error || null,
      category: result.category || null,
      whatsapp_status: result.whatsapp_status || lead.whatsapp_status || null,
      log_id: result.log?.id || null,
    });
  }

  if (!dryRun && leads.length) {
    state.last_batch_sent_at = nowIso();
    state.sent_today = Number(state.sent_today || 0) + sentCount;
    state.failed_today = Number(state.failed_today || 0) + failedCount;
    state.last_batch_size = leads.length;
    state.last_batch_sent = sentCount;
    state.last_batch_failed = failedCount;
    state.settings_snapshot = settings;
    state.updated_at = nowIso();

    const failureRate = leads.length ? failedCount / leads.length : 0;
    if (leads.length >= Math.min(5, settings.batch_size) && failureRate >= settings.pause_failure_rate) {
      state.paused_until = new Date(Date.now() + settings.pause_minutes_on_high_failure * 60000).toISOString();
      results.push({ success: true, sent: false, skipped: true, reason: "bulk_first_message_paused_high_failure_rate", failure_rate: failureRate, paused_until: state.paused_until });
    }
  }


  return results;
}

const ngPostImportFirstMessageJobKeys = new Set();

function ngCountEligibleAutoFirstMessageLeads(db = {}, brandId = null) {
  return ensureCrmArray(db, "leads")
    .filter((lead) => !brandId || String(lead.brand_id || "") === String(brandId || ""))
    .filter((lead) => ngCanSendAutoFirstMessage(db, lead).ok)
    .length;
}

function ngNextSafeBulkFirstMessageDelayMs(db = {}, settings = {}) {
  const state = ngGetBulkFirstMessageState(db);
  const nowMs = Date.now();

  if (state.paused_until && new Date(state.paused_until).getTime() > nowMs) {
    return { ok: false, reason: "bulk_first_message_paused_until", next_at: state.paused_until };
  }

  if (state.last_batch_sent_at) {
    const nextAllowedAt = new Date(new Date(state.last_batch_sent_at).getTime() + Number(settings.batch_delay_minutes || 5) * 60000);
    if (nextAllowedAt.getTime() > nowMs) {
      return {
        ok: true,
        reason: "bulk_first_message_batch_cooldown",
        next_at: nextAllowedAt.toISOString(),
        delay_ms: Math.max(1500, nextAllowedAt.getTime() - nowMs + 1500),
      };
    }
  }

  return { ok: true, delay_ms: Math.max(1500, Number(process.env.NEXTGEN_SAFE_BULK_FIRST_MESSAGE_START_DELAY_MS || 1500)) };
}

function ngSchedulePostImportFirstMessageSend({ leadIds = [], brandId = null, batchId = "", actorId = "import_confirm", delayMs = null } = {}) {
  const cleanIds = Array.from(new Set((Array.isArray(leadIds) ? leadIds : [])
    .map((id) => String(id || "").trim())
    .filter(Boolean)));

  if (!cleanIds.length) return { scheduled: false, reason: "no_lead_ids" };

  const jobKey = String(batchId || cleanIds.join(",")).slice(0, 220);
  if (ngPostImportFirstMessageJobKeys.has(jobKey)) return { scheduled: false, reason: "already_scheduled", job_key: jobKey };

  ngPostImportFirstMessageJobKeys.add(jobKey);

  const firstDelayMs = Math.max(
    1000,
    Math.min(60000, Number(delayMs || process.env.NEXTGEN_SAFE_BULK_FIRST_MESSAGE_START_DELAY_MS || 1200))
  );

  const maxRuns = Math.max(
    1,
    Math.min(120, Number(process.env.NEXTGEN_SAFE_BULK_FIRST_MESSAGE_MAX_RUNS || 60))
  );

  const runSafeBulkBatch = async (runNumber = 1) => {
    const runStartedAt = nowIso();
    let shouldKeepJobKey = false;

    try {
      const db = await readCrmDb();
      const settings = ngGetBulkFirstMessageSettings(db);
      const state = ngGetBulkFirstMessageState(db);
      const queuedBefore = ngCountEligibleAutoFirstMessageLeads(db, brandId);

      if (queuedBefore <= 0) {
        ensureCrmArray(db, "post_import_auto_first_message_runs").unshift({
          id: uuid(),
          batch_id: batchId || null,
          lead_count: cleanIds.length,
          queued_before: queuedBefore,
          queued_after: 0,
          sent: 0,
          failed: 0,
          skipped: true,
          reason: "no_eligible_queued_first_messages",
          actor_id: actorId || "import_confirm",
          source: "safe_bulk_post_import_auto_first_message",
          run_number: runNumber,
          settings,
          started_at: runStartedAt,
          created_at: nowIso(),
        });
        await writeCrmDb(db);
        return;
      }

      const timing = ngNextSafeBulkFirstMessageDelayMs(db, settings);
      if (!timing.ok) {
        ensureCrmArray(db, "post_import_auto_first_message_runs").unshift({
          id: uuid(),
          batch_id: batchId || null,
          lead_count: cleanIds.length,
          queued_before: queuedBefore,
          sent: 0,
          failed: 0,
          skipped: true,
          reason: timing.reason,
          next_at: timing.next_at || null,
          actor_id: actorId || "import_confirm",
          source: "safe_bulk_post_import_auto_first_message",
          run_number: runNumber,
          settings,
          started_at: runStartedAt,
          created_at: nowIso(),
        });
        await writeCrmDb(db);
        return;
      }

      if (timing.reason === "bulk_first_message_batch_cooldown" && runNumber <= maxRuns) {
        shouldKeepJobKey = true;
        setTimeout(() => runSafeBulkBatch(runNumber + 1), timing.delay_ms);
        ensureCrmArray(db, "post_import_auto_first_message_runs").unshift({
          id: uuid(),
          batch_id: batchId || null,
          lead_count: cleanIds.length,
          queued_before: queuedBefore,
          sent: 0,
          failed: 0,
          skipped: true,
          reason: timing.reason,
          next_at: timing.next_at || null,
          next_run_in_ms: timing.delay_ms,
          actor_id: actorId || "import_confirm",
          source: "safe_bulk_post_import_auto_first_message",
          run_number: runNumber,
          settings,
          started_at: runStartedAt,
          created_at: nowIso(),
        });
        await writeCrmDb(db);
        return;
      }

      const results = await ngRunDueAutoFirstMessages({
        db,
        brandId,
        limit: settings.batch_size,
        actorId,
        dryRun: false,
        bulkSettings: settings,
      });

      const sentCount = results.filter((item) => item.sent).length;
      const failedCount = results.filter((item) => item.success === false).length;
      const queuedAfter = ngCountEligibleAutoFirstMessageLeads(db, brandId);
      const stopReason = results.find((item) => item.reason)?.reason || null;

      ensureCrmArray(db, "post_import_auto_first_message_runs").unshift({
        id: uuid(),
        batch_id: batchId || null,
        lead_count: cleanIds.length,
        queued_before: queuedBefore,
        queued_after: queuedAfter,
        result_count: results.length,
        sent: sentCount,
        failed: failedCount,
        skipped: sentCount <= 0,
        reason: stopReason,
        results: results.slice(0, 25),
        actor_id: actorId || "import_confirm",
        source: "safe_bulk_post_import_auto_first_message",
        run_number: runNumber,
        settings,
        started_at: runStartedAt,
        created_at: nowIso(),
      });

      await writeCrmDb(db);

      const nextState = ngGetBulkFirstMessageState(db);
      const dailyRemaining = Math.max(0, Number(settings.daily_max || 0) - Number(nextState.sent_today || 0));
      const pauseActive = nextState.paused_until && new Date(nextState.paused_until).getTime() > Date.now();

      if (queuedAfter > 0 && dailyRemaining > 0 && !pauseActive && runNumber < maxRuns) {
        shouldKeepJobKey = true;
        const nextDelayMs = Math.max(60000, Number(settings.batch_delay_minutes || 5) * 60000 + 1500);
        setTimeout(() => runSafeBulkBatch(runNumber + 1), nextDelayMs);
      }

      console.log("Safe bulk post-import first-message runner", {
        batch_id: batchId || null,
        run_number: runNumber,
        queued_before: queuedBefore,
        sent: sentCount,
        failed: failedCount,
        queued_after: queuedAfter,
        next_run_scheduled: shouldKeepJobKey,
      });
    } catch (error) {
      console.error("Safe bulk post-import first-message runner failed:", error.message);
    } finally {
      if (!shouldKeepJobKey) ngPostImportFirstMessageJobKeys.delete(jobKey);
    }
  };

  setTimeout(() => runSafeBulkBatch(1), firstDelayMs);

  return {
    scheduled: true,
    job_key: jobKey,
    lead_count: cleanIds.length,
    mode: "safe_bulk_auto",
    batch_size: "uses_safe_bulk_settings",
    delay_minutes: "uses_safe_bulk_settings",
    first_run_delay_ms: firstDelayMs,
  };
}


app.get("/admin/crm/debug/first-message-template", async (req, res) => {
  try {
    const db = await readCrmDb();
    const leadId = req.query.lead_id || req.query.id || "";
    const phone = req.query.phone || req.query.to || "";
    const lead = leadId ? getLeadByAnyId(db, leadId) : findLeadByPhoneOrEmail(db, { phone });
    const templateKey = ngResolveAutoFirstMessageTemplateKey(db, lead || {});
    const storedTemplate = getMessageTemplateByKey(db, templateKey) || getMessageTemplateByKey(db, ngGetOfficialWhatsAppTemplateNameForKey(templateKey));
    const template = ngAutoFirstVirtualTemplate(templateKey, storedTemplate);
    const vars = ngFirstMessageVariablesForLead(lead || {});
    const components = buildWhatsAppTemplateComponents({ template, lead: lead || {}, variables: vars, metadata: { template_key: templateKey, whatsapp_template_name: ngGetOfficialWhatsAppTemplateNameForKey(templateKey) } });
    return res.json({
      success: true,
      lead_id: lead?.id || null,
      can_send: lead ? ngCanSendAutoFirstMessage(db, lead) : null,
      template_key: templateKey,
      official_whatsapp_template_name: ngGetOfficialWhatsAppTemplateNameForKey(templateKey),
      stored_template_found: Boolean(storedTemplate),
      language_code: getWhatsAppLanguageCode({ template, metadata: { template_key: templateKey } }),
      variables: vars,
      components,
      body: template.body || template.message || "",
    });
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message, hint: error.hint || null });
  }
});

async function requireAutomationRunPermission(req) {
  const authHeader = String(req.headers.authorization || "").replace("Bearer ", "").trim();
  const cronSecret = String(req.headers["x-crm-cron-secret"] || req.query.secret || req.body?.secret || "").trim();
  if (cronSecret && CRM_AUTOMATION_CRON_SECRET && cronSecret === CRM_AUTOMATION_CRON_SECRET) {
    return { user: { id: "cron", role: "system", email: "cron" }, cron: true };
  }
  if (authHeader) return requireCrmAdmin(req);
  const e = new Error("Admin auth token or valid x-crm-cron-secret is required");
  e.statusCode = 401;
  throw e;
}

app.get("/admin/crm/providers", async (req, res) => {
  try {
    const ctx = await getAuthenticatedUser(req);
    if (ctx.user.role !== "admin") {
      const crmDb = await readCrmDb();
      const member = getTeamMemberForUser(crmDb, ctx.user);
      if (!member || member.portal_enabled === false || member.crm_access_enabled === false) {
        const e = new Error("Missing CRM portal access");
        e.statusCode = 403;
        throw e;
      }
    }
    res.json({ success: true, providers: getProviderStatus(), scoped: ctx.user.role !== "admin" });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

