app.post("/admin/crm/automation/run-due", async (req, res) => {
  try {
    await requireAutomationRunPermission(req);
    const db = await readCrmDb();
    const now = Date.now();
    const brandId = getCrmBrandId(req, db);
    const limit = Math.max(1, Math.min(100, Number(req.body.limit || req.query.limit || 25)));
    const autoSend = req.body.auto_send !== false && req.query.auto_send !== "false";
    const due = ensureCrmArray(db, "automation_enrollments")
      .filter((item) => item.status === "active")
      .filter((item) => !brandId || String(item.brand_id || "") === String(brandId || ""))
      .filter((item) => !item.next_run_at || new Date(item.next_run_at).getTime() <= now)
      .slice(0, limit);

    const results = [];
    for (const enrollment of due) {
      const flow = ensureCrmArray(db, "crm_flows").find((item) => String(item.id) === String(enrollment.flow_id));
      if (!flow || flow.enabled === false || flow.status === "paused") {
        enrollment.status = "paused";
        enrollment.paused_at = nowIso();
        enrollment.updated_at = nowIso();
        results.push({ enrollment_id: enrollment.id, skipped: true, reason: "flow_missing_or_inactive" });
        continue;
      }
      const result = await processAutomationEnrollment({ db, enrollment, flow, autoSend, maxSteps: Number(req.body.max_steps || 1) });
      results.push({ enrollment_id: enrollment.id, flow_id: flow.id, status: enrollment.status, processed_steps: result.processed_steps, events: result.events.length });
    }

    const remainingLimit = Math.max(0, limit - results.length);
    const firstMessageResults = await ngRunDueAutoFirstMessages({
      db,
      brandId,
      limit: Number(req.body.first_message_limit || req.query.first_message_limit || remainingLimit || limit),
      actorId: "run_due",
      dryRun: req.body.dry_run === true || req.query.dry_run === "true",
      bulkSettings: {
        first_message_daily_max: req.body.first_message_daily_max || req.query.first_message_daily_max,
        first_message_batch_size: req.body.first_message_batch_size || req.query.first_message_batch_size,
        first_message_batch_delay_minutes: req.body.first_message_batch_delay_minutes || req.query.first_message_batch_delay_minutes,
      },
    });

    const dailySessionResults = await ngRunDailyLiveSessionScheduler({
      db,
      brandId,
      limit: Number(req.body.daily_session_limit || req.query.daily_session_limit || remainingLimit || limit),
      dryRun: req.body.dry_run === true || req.query.dry_run === "true",
      source: req.body.source || req.query.source || "run_due",
    });

    const googleMeetAppointmentResults = await ngRunGoogleMeetAppointmentScheduler({
      db,
      brandId,
      limit: Number(req.body.google_meet_limit || req.query.google_meet_limit || remainingLimit || limit),
      dryRun: req.body.dry_run === true || req.query.dry_run === "true",
      source: req.body.source || req.query.source || "run_due",
    });

    // v94: Run Due now also drains pending Full AI Auto replies for fresh inbound student messages.
    const aiAutoResults = req.body.dry_run === true || req.query.dry_run === "true"
      ? []
      : await ngAylaRunPendingFullAiAuto({
          db,
          brandId,
          limit: Number(req.body.ai_auto_limit || req.query.ai_auto_limit || remainingLimit || limit || 10),
          source: req.body.source || req.query.source || "run_due_ai_auto",
          actorId: "run_due",
          force: req.body.force_ai_auto === true || req.query.force_ai_auto === "true",
        });

    await writeCrmDb(db);
    res.json({
      success: true,
      processed: results.length + firstMessageResults.length + Number(dailySessionResults.processed || 0) + Number(googleMeetAppointmentResults.processed || 0) + aiAutoResults.length,
      automation_processed: results.length,
      first_message_processed: firstMessageResults.length,
      daily_session_processed: dailySessionResults.processed || 0,
      google_meet_processed: googleMeetAppointmentResults.processed || 0,
      ai_auto_processed: aiAutoResults.length,
      results,
      first_message_results: firstMessageResults,
      daily_session_results: dailySessionResults,
      google_meet_results: googleMeetAppointmentResults,
      ai_auto_results: aiAutoResults,
    });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

