app.post("/admin/crm/ai-training/content-imports/:jobId/import-draft", async (req, res) => {
  let upload;
  let claimed = null;
  let priorStatus = "";
  try {
    const existing = await getContentImportJob(req.params.jobId);
    priorStatus = String(existing?.status || "");
    if (!existing) return res.status(404).json({ success: false, error: "Content import job not found" });
    await requireAylaMedContentJobAdmin(req, existing);
    if (existing.counts?.import_blocked === true || Number(existing.counts?.blocking_issues || 0) > 0) {
      return res.status(409).json({
        success: false,
        error: "This preview contains a blocking specialized-format or exam-mapping issue and cannot be imported through the ordinary MCQ adapter.",
        blocking_collections: Array.isArray(existing.counts?.blocking_collections)
          ? existing.counts.blocking_collections
          : [],
        blocking_reasons: existing.counts?.blocking_reasons || {},
      });
    }
    if (!["preview_ready", "preview_with_warnings"].includes(String(existing.status))) {
      return res.status(409).json({ success: false, error: `Import job cannot be committed from status ${existing.status}` });
    }
    upload = await ngReceiveOrResolveContentZip(req, ["question_zip", "mixed_qbank_zip"]);
    if (String(upload.sha256) !== String(existing.zip_sha256)) {
      await ngCleanupRejectedContentUpload(upload); upload = null;
      return res.status(409).json({ success: false, error: "ZIP checksum does not match the approved preview. Upload the exact same ZIP." });
    }
    claimed = await claimContentImportDraft(existing.id);
    if (!claimed) {
      await ngCleanupRejectedContentUpload(upload); upload = null;
      return res.status(409).json({ success: false, error: "Import job was already claimed or its status changed" });
    }
    const backgroundJob = await ngQueueContentOperation({
      type: "content_question_draft", lane: "question_zip", upload, domainJobId: claimed.id,
    });
    upload = null;
    return res.status(202).json({
      success: true, job_id: claimed.id, background_job_id: backgroundJob.id, status: "importing_draft",
      poll_url: `/admin/crm/ai-training/content-imports/${claimed.id}`,
      message: "Checksum verified. Questions are importing as disabled drafts; nothing is published.",
    });
  } catch (error) {
    if (claimed?.id) await setContentImportJobStatus(claimed.id, priorStatus || "preview_ready").catch(() => {});
    await ngCleanupRejectedContentUpload(upload);
    return res.status(error.statusCode || 500).json({ success: false, error: error.message || "Draft import failed" });
  }
});

async function ngRunContentMediaDraftImport({ mediaJob, parentJob, upload, queueContext }) {
  const trackProgress = ngContentProgressTracker("indexing_media_zip");
  try {
    const references = await getContentMediaReferences(parentJob.id, "r2");
    const existingAssets = await listContentMediaImportAssets(mediaJob.id);
    const existingBytes = existingAssets.reduce(
      (total, asset) => total + Math.max(0, Number(asset.sizeBytes || 0)),
      0,
    );
    const inventoryCacheKey = mediaInventoryCacheKey({
      zipSha256: mediaJob.zip_sha256,
      references,
    });
    const previousCheckpoint = queueContext.job.checkpoint || {};
    const cachedInventory = resolveMediaInventoryCheckpoint(previousCheckpoint, inventoryCacheKey);
    let inventory = cachedInventory.inventory;
    let inventorySource = cachedInventory.source;
    let durableCheckpoint = previousCheckpoint;
    await finishContentMediaImportJob(mediaJob.id, "uploading", {
      resumable: true,
      accelerated: true,
      staged_assets: existingAssets.length,
      question_media_references: references.length,
      inventory_cache: inventorySource,
    }, []);

    if (!inventory) {
      await queueContext.heartbeat(trackProgress({
        stage: "indexing_media_zip",
        files_processed: 0,
        files_total: 0,
        bytes_processed: 0,
        bytes_total: 0,
        resumed_files: existingAssets.length,
        newly_uploaded: 0,
        inventory_cache: "miss",
        percent: 0,
      }));
      inventory = await inspectMediaZip({
        zipSource: upload.source || upload.file,
        references,
        directoryCacheKey: inventoryCacheKey,
        onProgress: (progress) => queueContext.heartbeat(trackProgress(progress)),
      });
      if (!Number(inventory.candidateEntries || 0)
        || !Number(inventory.candidateUncompressedBytes || 0)) {
        const entriesScanned = Math.max(0, Number(inventory.entries || 0));
        const referenceCount = references.length;
        throw Object.assign(new Error(referenceCount > 0
          ? `Media ZIP scan completed (${entriesScanned} entries), but no image/audio filename matched the ${referenceCount} private question media references. Review the stored reference paths before retrying; the uploaded ZIP remains reusable.`
          : `Media ZIP scan completed (${entriesScanned} entries), but this private collection exposes no attachable image/audio references. Restore the import-scoped references before retrying; the uploaded ZIP remains reusable.`), {
          statusCode: 409,
          code: "CONTENT_MEDIA_REFERENCE_INVENTORY_EMPTY",
          details: {
            entries_scanned: entriesScanned,
            question_media_references: referenceCount,
            uploaded_zip_reusable: true,
          },
        });
      }
      inventorySource = "fresh_index";
    }

    const initialProgress = {
      stage: "uploading_private_images",
      files_processed: existingAssets.length,
      files_total: inventory.candidateEntries,
      bytes_processed: existingBytes,
      durable_bytes_processed: existingBytes,
      bytes_total: inventory.candidateUncompressedBytes,
      resumed_files: existingAssets.length,
      newly_uploaded: 0,
      inventory_cache: inventorySource,
      accelerated: true,
      percent: inventory.candidateEntries > 0
        ? Math.min(99, Math.round((existingAssets.length / inventory.candidateEntries) * 100))
        : 0,
    };
    durableCheckpoint = buildMediaCheckpoint({
      previous: durableCheckpoint,
      cacheKey: inventoryCacheKey,
      inventory,
      progress: initialProgress,
    });
    await queueContext.updateCheckpoint(durableCheckpoint, trackProgress(initialProgress));

    const uploaded = await uploadMediaZipToR2({
      zipSource: upload.source || upload.file,
      references,
      examTrack: parentJob.exam_track,
      sourceNamespace: parentJob.source_namespace,
      importJobId: parentJob.id,
      mediaImportJobId: mediaJob.id,
      inventory,
      existingAssets,
      directoryCacheKey: inventoryCacheKey,
      concurrency: ngMultiQbankConfig.media_workers_per_job,
      transferGate: ngMediaTransferGate,
      onProgress: (progress) => queueContext.heartbeat(trackProgress(progress)),
      onAssets: async (assets, { lastEntryIndex, progress }) => {
        await stageContentMediaImportAssets({
          mediaImportJobId: mediaJob.id,
          assets,
        });
        durableCheckpoint = buildMediaCheckpoint({
          previous: durableCheckpoint,
          cacheKey: inventoryCacheKey,
          inventory,
          progress: {
            ...progress,
            media_entry_index: lastEntryIndex,
          },
        });
        await queueContext.updateCheckpoint(durableCheckpoint, trackProgress(progress));
      },
    });
    await queueContext.heartbeat(trackProgress({
      stage: "matching_private_media",
      files_processed: uploaded.assets.length,
      files_total: uploaded.candidateEntries,
      bytes_processed: uploaded.candidateUncompressedBytes,
      bytes_total: uploaded.candidateUncompressedBytes,
      resumed_files: uploaded.resumedFiles,
      newly_uploaded: uploaded.newlyUploaded,
      percent: 99,
    }));
    const report = matchMediaReferences(references, uploaded.assets);
    const finalizationConfig = mediaFinalizationConfig();
    const finalizationKey = mediaFinalizationCacheKey({
      mediaJobId: mediaJob.id,
      inventoryCacheKey,
    });
    const resumedFinalization = resolveMediaFinalizationCheckpoint(
      durableCheckpoint,
      finalizationKey,
      uploaded.assets.length,
    );
    let finalizationLinks = resumedFinalization.linksVerified;
    let finalizationLinksCreated = resumedFinalization.linksCreated;
    let finalizationLinkConflicts = resumedFinalization.linkConflicts;
    let finalizationDuplicateObjects = resumedFinalization.duplicateObjects;
    const remainingFinalizationBatches = Math.ceil(
      Math.max(0, uploaded.assets.length - resumedFinalization.assetsCommitted)
        / finalizationConfig.batch_size,
    );
    const finalizationBatchesTotal = resumedFinalization.batchesCommitted
      + remainingFinalizationBatches;
    let releaseFinalizer = null;
    let finalizerError = null;
    let finalizationBatchesCommitted = resumedFinalization.batchesCommitted;
    try {
      releaseFinalizer = await ngMediaFinalizerGate.acquire({
        metadata: {
          media_import_job_id: mediaJob.id,
          content_import_job_id: parentJob.id,
        },
        onWait: (gate) => queueContext.heartbeat(trackProgress({
          stage: "waiting_for_postgres_finalizer",
          files_processed: uploaded.assets.length,
          files_total: uploaded.candidateEntries,
          bytes_processed: uploaded.candidateUncompressedBytes,
          bytes_total: uploaded.candidateUncompressedBytes,
          resumed_files: uploaded.resumedFiles,
          newly_uploaded: uploaded.newlyUploaded,
          finalization_assets_committed: resumedFinalization.assetsCommitted,
          finalization_assets_total: uploaded.assets.length,
          finalization_links_verified: finalizationLinks,
          finalization_batches_committed: resumedFinalization.batchesCommitted,
          finalization_batches_total: finalizationBatchesTotal,
          finalization_batch_size: finalizationConfig.batch_size,
          finalization_cache: resumedFinalization.source,
          finalizer_gate: gate,
          percent: 99,
        })),
      });
      await queueContext.heartbeat(trackProgress({
        stage: "saving_private_media",
        files_processed: uploaded.assets.length,
        files_total: uploaded.candidateEntries,
        bytes_processed: uploaded.candidateUncompressedBytes,
        bytes_total: uploaded.candidateUncompressedBytes,
        resumed_files: uploaded.resumedFiles,
        newly_uploaded: uploaded.newlyUploaded,
        finalization_assets_committed: resumedFinalization.assetsCommitted,
        finalization_assets_total: uploaded.assets.length,
        finalization_links_verified: finalizationLinks,
        finalization_batches_committed: resumedFinalization.batchesCommitted,
        finalization_batches_total: finalizationBatchesTotal,
        finalization_batch_size: finalizationConfig.batch_size,
        finalization_cache: resumedFinalization.source,
        finalizer_gate: ngMediaFinalizerGate.snapshot(),
        percent: 99,
      }));
      const finalizationRun = await finalizeMediaInBatches({
        assets: uploaded.assets,
        matches: report.matches,
        batchSize: finalizationConfig.batch_size,
        startOffset: resumedFinalization.assetsCommitted,
        onBatch: async ({
          assets,
          matches,
          nextOffset,
          batchNumber,
        }) => {
          const savedBatch = await saveContentMediaMatchBatch({
            mediaJobId: mediaJob.id,
            parentJob,
            assets,
            matches,
          });
          for (const duplicateObjectKey of savedBatch.duplicateObjects) {
            await deleteR2Object(duplicateObjectKey).catch((error) => {
              console.warn("R2 duplicate cleanup failed:", error.message);
            });
          }
          finalizationLinks += savedBatch.links;
          finalizationLinksCreated += savedBatch.linksCreated;
          finalizationLinkConflicts += savedBatch.linkConflicts;
          finalizationDuplicateObjects += savedBatch.duplicateObjects.length;
          const batchesCommitted = resumedFinalization.batchesCommitted + batchNumber;
          durableCheckpoint = buildMediaFinalizationCheckpoint({
            previous: durableCheckpoint,
            cacheKey: finalizationKey,
            assetsTotal: uploaded.assets.length,
            assetsCommitted: nextOffset,
            linksVerified: finalizationLinks,
            linksCreated: finalizationLinksCreated,
            linkConflicts: finalizationLinkConflicts,
            duplicateObjects: finalizationDuplicateObjects,
            batchesCommitted,
            batchSize: finalizationConfig.batch_size,
          });
          await queueContext.updateCheckpoint(durableCheckpoint, trackProgress({
            stage: "saving_private_media",
            files_processed: uploaded.assets.length,
            files_total: uploaded.candidateEntries,
            bytes_processed: uploaded.candidateUncompressedBytes,
            bytes_total: uploaded.candidateUncompressedBytes,
            resumed_files: uploaded.resumedFiles,
            newly_uploaded: uploaded.newlyUploaded,
            finalization_assets_committed: nextOffset,
            finalization_assets_total: uploaded.assets.length,
            finalization_links_verified: finalizationLinks,
            finalization_links_created: finalizationLinksCreated,
            finalization_link_conflicts: finalizationLinkConflicts,
            finalization_batches_committed: batchesCommitted,
            finalization_batches_total: finalizationBatchesTotal,
            finalization_batch_size: finalizationConfig.batch_size,
            finalization_cache: resumedFinalization.source,
            finalizer_gate: ngMediaFinalizerGate.snapshot(),
            movement: true,
            percent: 99,
          }));
        },
      });
      finalizationBatchesCommitted = resumedFinalization.batchesCommitted
        + finalizationRun.batchesCommitted;
      durableCheckpoint = buildMediaFinalizationCheckpoint({
        previous: durableCheckpoint,
        cacheKey: finalizationKey,
        assetsTotal: uploaded.assets.length,
        assetsCommitted: uploaded.assets.length,
        linksVerified: finalizationLinks,
        linksCreated: finalizationLinksCreated,
        linkConflicts: finalizationLinkConflicts,
        duplicateObjects: finalizationDuplicateObjects,
        batchesCommitted: finalizationBatchesCommitted,
        batchSize: finalizationConfig.batch_size,
        completed: true,
      });
      await queueContext.updateCheckpoint(durableCheckpoint, trackProgress({
        stage: "saving_private_media",
        files_processed: uploaded.assets.length,
        files_total: uploaded.candidateEntries,
        bytes_processed: uploaded.candidateUncompressedBytes,
        bytes_total: uploaded.candidateUncompressedBytes,
        resumed_files: uploaded.resumedFiles,
        newly_uploaded: uploaded.newlyUploaded,
        finalization_assets_committed: uploaded.assets.length,
        finalization_assets_total: uploaded.assets.length,
        finalization_links_verified: finalizationLinks,
        finalization_links_created: finalizationLinksCreated,
        finalization_link_conflicts: finalizationLinkConflicts,
        finalization_batches_committed: finalizationBatchesCommitted,
        finalization_batches_total: finalizationBatchesTotal,
        finalization_batch_size: finalizationConfig.batch_size,
        finalization_cache: resumedFinalization.source,
        finalization_complete: true,
        finalizer_gate: ngMediaFinalizerGate.snapshot(),
        movement: true,
        percent: 99,
      }));
    } catch (error) {
      finalizerError = error;
      throw error;
    } finally {
      releaseFinalizer?.({ error: finalizerError });
    }
    const saved = {
      links: finalizationLinks,
      linksCreated: finalizationLinksCreated,
      linkConflicts: finalizationLinkConflicts,
      duplicateObjects: finalizationDuplicateObjects,
      batchesCommitted: finalizationBatchesCommitted,
    };
    await queueContext.heartbeat(trackProgress({
      stage: "image_import_complete",
      files_processed: uploaded.assets.length,
      files_total: uploaded.candidateEntries,
      bytes_processed: uploaded.candidateUncompressedBytes,
      bytes_total: uploaded.candidateUncompressedBytes,
      resumed_files: uploaded.resumedFiles,
      newly_uploaded: uploaded.newlyUploaded,
      workers_configured: uploaded.workersConfigured,
      maximum_workers_active: uploaded.maximumWorkersActive,
      inventory_cache: inventorySource,
      matched: report.matches.length,
      linked: saved.links,
      finalization_links_created: saved.linksCreated,
      finalization_link_conflicts: saved.linkConflicts,
      finalization_batches_committed: saved.batchesCommitted,
      percent: 100,
      completed: true,
    }));
    await finishContentMediaImportJob(mediaJob.id, report.ambiguous.length || saved.linkConflicts
      ? "draft_imported_with_warnings"
      : "draft_imported", {
      zip_entries: uploaded.entries,
      uncompressed_bytes: uploaded.uncompressedBytes,
      images_uploaded: uploaded.assets.filter((asset) => asset.mediaKind === "image").length,
      audio_uploaded: uploaded.assets.filter((asset) => asset.mediaKind === "audio").length,
      resumed_files: uploaded.resumedFiles,
      newly_uploaded: uploaded.newlyUploaded,
      workers_configured: uploaded.workersConfigured,
      maximum_workers_active: uploaded.maximumWorkersActive,
      inventory_cache: inventorySource,
      question_media_references: references.length,
      matched: report.matches.length,
      linked: saved.links,
      links_created: saved.linksCreated,
      link_conflicts: saved.linkConflicts,
      finalization_batches: saved.batchesCommitted,
      finalization_batch_size: finalizationConfig.batch_size,
      missing: report.missing.length,
      ambiguous: report.ambiguous.length,
      unreferenced: report.unreferenced.length,
      duplicate_assets: saved.duplicateObjects,
      missing_samples: report.missing.slice(0, 100).map((item) => ({ student_qid: item.studentQid, media_ref: item.mediaRef })),
      ambiguous_samples: report.ambiguous.slice(0, 100),
      unreferenced_samples: report.unreferenced.slice(0, 100).map((item) => item.originalName),
    }, []);
    return { report, saved };
  } catch (error) {
    console.error("Content Registry media import failed:", mediaJob.id, error);
    const stagedAssets = await listContentMediaImportAssets(mediaJob.id).catch(() => []);
    await finishContentMediaImportJob(mediaJob.id, "draft_import_retrying", {
      failed: true,
      resumable: true,
      staged_assets: stagedAssets.length,
    }, [{ error: error.message || "Media import failed" }]).catch(() => {});
    throw error;
  }
}

app.post("/admin/crm/ai-training/content-imports/:jobId/media/import-draft", async (req, res) => {
  let upload;
  let mediaJob = null;
  try {
    if (!contentMediaStatus().configured) return res.status(503).json({ success: false, error: "Cloudflare R2 is not configured" });
    const parentJob = await getContentImportJob(req.params.jobId);
    if (!parentJob) return res.status(404).json({ success: false, error: "Content import job not found" });
    const { user } = await requireAylaMedContentJobAdmin(req, parentJob);
    if (!["draft_imported", "draft_imported_with_warnings"].includes(String(parentJob.status))) {
      return res.status(409).json({ success: false, error: "Questions must be imported as drafts before media can be attached" });
    }
    upload = await ngReceiveOrResolveContentZip(req, ["image_zip", "media_zip"]);
    mediaJob = await createContentMediaImportJob({
      id: crypto.randomUUID(), contentImportJobId: parentJob.id, zipSha256: upload.sha256,
      originalFilename: upload.originalFilename, createdBy: String(user.id),
    });
    const backgroundJob = await ngQueueContentOperation({
      type: "content_image_draft", lane: "image_zip", upload, domainJobId: mediaJob.id,
    });
    upload = null;
    return res.status(202).json({
      success: true, media_job_id: mediaJob.id, background_job_id: backgroundJob.id, content_import_job_id: parentJob.id, status: "queued",
      poll_url: `/admin/crm/ai-training/content-media-imports/${mediaJob.id}`,
      message: "Media package accepted. Referenced images and audio are deduplicated into private disabled drafts.",
    });
  } catch (error) {
    if (mediaJob?.id) await finishContentMediaImportJob(mediaJob.id, "queue_failed", { failed: true }, [{ error: error.message }]).catch(() => {});
    await ngCleanupRejectedContentUpload(upload);
    return res.status(error.statusCode || 500).json({ success: false, error: error.message || "Media ZIP import failed" });
  }
});

