app.get("/admin/crm/ai-training/content-imports/:jobId/media-bundle/latest", async (req, res) => {
  try {
    const auth = await requireOwnedCatalogAdmin(req);
    const parentJob = await getContentImportJob(req.params.jobId);
    if (!parentJob) {
      return res.status(404).json({ success: false, error: "Content import job not found" });
    }
    if (auth.ownedCatalogOnly && !ngOwnedAylaMedImportJob(parentJob)) {
      throw ngOwnedMediaUploadScopeError();
    }
    const privateBundleJob = ngLatestOwnedMediaBundleJob(parentJob.id);
    if (!privateBundleJob) {
      return res.status(404).json({ success: false, error: "No combined media import job exists for this collection" });
    }
    return res.json(await ngOwnedMediaBundlePollSnapshot(req, privateBundleJob, auth));
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/crm/ai-training/content-imports/:jobId/media-bundle/retry", async (req, res) => {
  let reacquiredUpload = false;
  let uploadId = "";
  let backgroundJobId = "";
  try {
    const auth = await requireOwnedCatalogAdmin(req);
    const parentJob = await getContentImportJob(req.params.jobId);
    if (!parentJob) {
      return res.status(404).json({ success: false, error: "Content import job not found" });
    }
    if (auth.ownedCatalogOnly && !ngOwnedAylaMedImportJob(parentJob)) {
      throw ngOwnedMediaUploadScopeError();
    }
    const privateBundleJob = ngLatestOwnedMediaBundleJob(parentJob.id);
    if (!privateBundleJob) {
      return res.status(404).json({ success: false, error: "No combined media import job exists for this collection" });
    }
    ({ uploadId } = await requireOwnedMediaBundleJobAdmin(req, privateBundleJob, auth));
    backgroundJobId = String(privateBundleJob.id || "");

    // This verifies that the finalized R2 object still exists and renews its
    // staging TTL. It never uploads bytes or creates another archive.
    await ngContentUploadStore.resolveFinalized(uploadId, { allowedPurposes: ["media_zip", "mixed_qbank_zip"] });

    const current = ngContentBackgroundQueue.get(backgroundJobId);
    if (!current) {
      return res.status(404).json({ success: false, error: "Combined media import job not found" });
    }
    const active = ["queued", "running", "retry_wait", "pause_requested", "cancel_requested"]
      .includes(String(current.status || ""));
    if (active || current.status === "completed") {
      const snapshot = await ngOwnedMediaBundlePollSnapshot(req, privateBundleJob, auth);
      return res.status(current.status === "completed" ? 200 : 202).json({
        ...snapshot,
        requeued: false,
        deduplicated: true,
        reused_upload_id: uploadId,
        message: current.status === "completed"
          ? "Private media matching is already complete. No upload or duplicate job was created."
          : "Private media matching is already active. The existing job was reused without uploading again.",
      });
    }
    if (current.status !== "failed") {
      return res.status(409).json({
        success: false,
        error: `Media matching cannot be retried from status ${current.status}`,
      });
    }

    await ngContentUploadStore.acquire(uploadId, backgroundJobId);
    reacquiredUpload = true;
    await ngContentBackgroundQueue.retry(backgroundJobId);
    const snapshot = await ngOwnedMediaBundlePollSnapshot(req, privateBundleJob, auth);
    return res.status(202).json({
      ...snapshot,
      requeued: true,
      deduplicated: false,
      reused_upload_id: uploadId,
      message: "Failed private media matching was requeued from the finalized Cloudflare R2 ZIP. No upload or duplicate job was created.",
    });
  } catch (error) {
    if (reacquiredUpload && uploadId && backgroundJobId) {
      await ngContentUploadStore.release(uploadId, backgroundJobId).catch(() => {});
    }
    return res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

async function ngBuildContentVideoReconcileAudit(videoJobId) {
  const videoJob = await getContentVideoImportJob(videoJobId);
  if (!videoJob) throw Object.assign(new Error("Video import job not found"), { statusCode: 404 });
  if (!String(videoJob.status || "").startsWith("draft_imported")) {
    throw Object.assign(
      new Error("Wait for the Vimeo job to finish before preparing contextual reconciliation"),
      { statusCode: 409 },
    );
  }
  const parentJob = await getContentImportJob(videoJob.content_import_job_id);
  if (!parentJob) throw Object.assign(new Error("Parent content import job not found"), { statusCode: 404 });
  const snapshot = ngContentBackgroundSnapshot(videoJob.id);
  const uploadId = String(snapshot.resumeUploadId || "");
  const upload = uploadId
    ? await ngContentUploadStore.get(uploadId).catch(() => null)
    : null;
  const existingRepair = ngContentBackgroundQueue.list({ limit: 500 }).find((job) =>
    String(job.metadata?.repair_of_video_job_id || "") === String(videoJob.id)
    && [
      "queued",
      "running",
      "retry_wait",
      "paused",
      "pause_requested",
      "cancel_requested",
    ].includes(String(job.status || "")));
  const fingerprint = crypto.createHash("sha256")
    .update([
      videoJob.id,
      String(videoJob.updated_at || ""),
      uploadId,
      String(upload?.status || ""),
      String(upload?.expires_at || ""),
    ].join("\u0000"))
    .digest("hex");
  return {
    videoJob,
    parentJob,
    snapshot,
    uploadId,
    upload,
    existingRepair,
    fingerprint,
  };
}

function ngContentVideoEditionAuditFingerprint({
  videoJob,
  upload,
  edition,
  references,
  videos,
  report,
}) {
  const digest = crypto.createHash("sha256");
  digest.update([
    String(videoJob?.id || ""),
    String(videoJob?.updated_at || ""),
    String(upload?.uploadId || upload?.id || ""),
    String(upload?.sha256 || upload?.fingerprint || ""),
    ngContentEdition(edition),
  ].join("\u0000"));
  for (const reference of [...references].sort((left, right) =>
    `${left.questionId}\u0000${left.mediaRef}`
      .localeCompare(`${right.questionId}\u0000${right.mediaRef}`))) {
    digest.update(
      `\nref:${reference.questionId}\u0000${reference.mediaRef}\u0000${reference.sourceSnapshot}`,
    );
  }
  for (const video of [...videos].sort((left, right) =>
    String(left.originalName).localeCompare(String(right.originalName)))) {
    digest.update(
      `\nvideo:${video.originalName}\u0000${video.sizeBytes}\u0000${video.crc32 || 0}`,
    );
  }
  digest.update(`\nmatched:${report.matches.length}`);
  digest.update(`\nmissing:${report.missing.length}`);
  digest.update(`\nambiguous:${report.ambiguous.length}`);
  return digest.digest("hex");
}

async function ngBuildContentVideoEditionAudit(videoJobId, editionInput) {
  const edition = ngContentEdition(editionInput);
  const base = await ngBuildContentVideoReconcileAudit(videoJobId);
  if (!base.uploadId || base.upload?.status !== "finalized") {
    throw Object.assign(
      new Error("The saved private video ZIP is no longer available"),
      { statusCode: 410 },
    );
  }
  const resolvedUpload = await ngContentUploadStore.resolveFinalized(
    base.uploadId,
    { allowedPurposes: ["video_zip", "media_zip"] },
  );
  const allReferences = await getContentMediaReferences(base.parentJob.id, "video");
  const references = filterContentReferencesByEdition(allReferences, edition);
  const inventory = await inspectContentVideoEntries({
    zipSource: resolvedUpload.source || resolvedUpload.file,
    edition,
    directoryCacheKey: `${base.videoJob.zip_sha256}:videos:${edition}`,
  });
  const report = matchVideoReferences(references, inventory.videos);
  const mappings = await auditContentVideoMappings(report.matches);
  const existingRepair = ngContentBackgroundQueue.list({ limit: 500 }).find((job) =>
    String(job.metadata?.edition_repair_of_video_job_id || "")
      === String(base.videoJob.id)
    && String(job.metadata?.edition || "") === edition
    && [
      "queued",
      "running",
      "retry_wait",
      "paused",
      "pause_requested",
      "cancel_requested",
    ].includes(String(job.status || "")));
  return {
    ...base,
    edition,
    resolvedUpload,
    references,
    inventory,
    report,
    mappings,
    existingEditionRepair: existingRepair,
    fingerprint: ngContentVideoEditionAuditFingerprint({
      videoJob: base.videoJob,
      upload: resolvedUpload,
      edition,
      references,
      videos: inventory.videos,
      report,
    }),
  };
}

function ngPublicContentVideoEditionAudit(audit) {
  return {
    edition: audit.edition,
    video_job_id: audit.videoJob.id,
    content_import_job_id: audit.parentJob.id,
    audit_fingerprint: audit.fingerprint,
    package_available: true,
    package_expires_at: audit.upload?.expires_at || null,
    archive_entries: audit.inventory.entries,
    video_files_found: audit.inventory.videos.length,
    video_references: audit.references.length,
    exact_matches: audit.report.matches.length,
    already_linked: audit.mappings.linked.length,
    repairable_links: audit.mappings.missing.length,
    remaining_missing: audit.report.missing.length,
    remaining_ambiguous: audit.report.ambiguous.length,
    unreferenced_video_files: audit.report.unreferenced.length,
    existing_repair_background_job_id:
      audit.existingEditionRepair?.id || null,
    existing_repair_video_job_id:
      audit.existingEditionRepair?.metadata?.domain_job_id || null,
    source_snapshot_scoped: true,
    all_edition_videos_inventoried_before_matching: true,
    filename_treated_as_question_id: false,
    sha256_vimeo_deduplication: true,
    existing_video_links_overwritten: false,
    other_editions_touched: [],
    student_visibility: "disabled_drafts_until_collection_approval",
    missing_samples: audit.report.missing.slice(0, 50).map((item) => ({
      student_qid: item.studentQid,
      media_ref: item.mediaRef,
    })),
    ambiguous_samples: audit.report.ambiguous.slice(0, 50).map((item) => ({
      student_qid: item.studentQid,
      media_ref: item.mediaRef,
      candidates: (item.candidates || []).slice(0, 20),
    })),
  };
}

