function aylaQbankSeenQuestionIds(db, {
  userId = "",
  studentId = "",
  examTrack = "",
} = {}) {
  const ids = [];
  for (const session of aylaValues(db, "aylaQbankSessions")) {
    if (
      String(session.userId || "") !== String(userId || "")
      || String(session.studentId || "") !== String(studentId || "")
      || String(session.examTrack || "") !== String(examTrack || "")
    ) {
      continue;
    }
    for (const mapping of Array.isArray(session.questions) ? session.questions : []) {
      const questionId = String(
        mapping.contentQuestionId || mapping.content_question_id || "",
      );
      if (questionId) ids.push(questionId);
    }
  }
  return [...new Set(ids)];
}

async function aylaSelectQbankSessionQuestions({
  db,
  examTrack,
  requestedCount,
  filters,
  purpose,
  sourceProfile = "",
  selectedBanks = [],
  destinationScope = "",
  preferredQuestionIds = [],
  selectionSeed = "",
  questionExposureCounts = {},
  seenQuestionIds = [],
  allowedCollectionIds = [],
  examVariant = "",
} = {}) {
  const publicationDestination = purpose === "baseline_diagnostic" ? "diagnostic" : "qbank";
  if (purpose !== "baseline_diagnostic" && Array.isArray(selectedBanks) && selectedBanks.length) {
    const banksBySourceExam = new Map();
    for (const bank of selectedBanks) {
      const sourceExamTrack = normalizeAylaRegistryExamTrack(bank.source_exam_track || examTrack);
      if (!sourceExamTrack) continue;
      if (!banksBySourceExam.has(sourceExamTrack)) banksBySourceExam.set(sourceExamTrack, []);
      banksBySourceExam.get(sourceExamTrack).push(bank);
    }
    const pools = await Promise.all([...banksBySourceExam.entries()].map(async ([sourceExamTrack, banks]) => {
      const rows = await listContentQbankQuestions({
        examTrack: sourceExamTrack,
        destination: "aylamed_qbank",
        systemKey: filters.system_key,
        subsystemKey: filters.subsystem_key,
        topicKey: filters.topic_key,
        subtopicKey: filters.subtopic_key,
        difficulty: filters.difficulty,
        sourceProfile,
        destinationScope,
        limit: 200,
        seed: crypto.randomUUID(),
        seenQuestionIds,
        collectionIds: banks.map((row) => row.id),
      });
      const banksById = new Map(banks.map((row) => [String(row.id), row]));
      return rows.map((row) => {
        const bank = banksById.get(String(row.collection_id || ""));
        return {
          ...row,
          source_exam_track: sourceExamTrack,
          supplemental: bank?.supplemental === true,
          scoring_allowed: bank?.scoring_allowed !== false,
        };
      });
    }));
    const selected = [];
    const seenIds = new Set();
    for (let index = 0; selected.length < requestedCount; index += 1) {
      let added = false;
      for (const poolRows of pools) {
        const row = poolRows[index];
        if (!row || seenIds.has(String(row.id))) continue;
        seenIds.add(String(row.id));
        selected.push(row);
        added = true;
        if (selected.length >= requestedCount) break;
      }
      if (!added) break;
    }
    return { selected, availableSystemKeys: [], selectedSystemKeys: [] };
  }
  let collectionIds = Array.isArray(allowedCollectionIds) && allowedCollectionIds.length
    ? [...new Set(allowedCollectionIds.map(String).filter(Boolean))]
    : await aylaPublishedQbankCollectionIds(db, {
      examTrack,
      sourceExamTrack: examTrack,
      destination: publicationDestination,
      destinationScope,
      sourceProfile,
    });
  if (purpose === "baseline_diagnostic" && !collectionIds.length) {
    // Diagnostic publication may intentionally have no separate bank toggle.
    // Reuse only collections already published to this student's QBank; the
    // diagnostic media, taxonomy, system-balance and weighting gates below
    // remain unchanged and still fail closed.
    collectionIds = await aylaPublishedQbankCollectionIds(db, {
      examTrack,
      sourceExamTrack: examTrack,
      destination: "qbank",
      destinationScope,
      sourceProfile,
    });
  }
  if (purpose !== "baseline_diagnostic") {
    const selected = await listContentQbankQuestions({
      examTrack,
      destination: "aylamed_qbank",
      systemKey: filters.system_key,
      subsystemKey: filters.subsystem_key,
      topicKey: filters.topic_key,
      subtopicKey: filters.subtopic_key,
      difficulty: filters.difficulty,
      sourceProfile,
      destinationScope,
      limit: requestedCount,
      seed: crypto.randomUUID(),
      seenQuestionIds,
      collectionIds,
    });
    return { selected, availableSystemKeys: [], selectedSystemKeys: [] };
  }

  const baseDiagnosticSeed = selectionSeed
    || `aylamed-${aylaCanonicalExamTrack(examTrack) || "exam"}-diagnostic-v${AYLA_DIAGNOSTIC_BLUEPRINT_VERSION}:${destinationScope || "default"}`;
  // Large banks can legitimately contain all reviewed systems while a single
  // randomized 200-item window misses a low-frequency category. Four bounded,
  // deterministic discovery windows prevent that false "not ready" result;
  // the selector still admits only media-ready, classified questions.
  const listedCandidates = (await Promise.all(Array.from({ length: 4 }, (_, batch) =>
    listContentQbankQuestions({
      examTrack,
      destination: "aylamed_qbank",
      destinationScope,
      limit: Math.min(200, Math.max(requestedCount, requestedCount * 10)),
      seed: `${baseDiagnosticSeed}:batch-${batch + 1}`,
      seenQuestionIds,
      collectionIds,
    })))).flat();
  const preferredCandidates = preferredQuestionIds.length
    ? await getContentQbankQuestions({
      questionIds: preferredQuestionIds,
      examTrack,
      destination: "aylamed_qbank",
      destinationScope,
      collectionIds,
    })
    : [];
  const candidates = [...new Map(
    [...preferredCandidates, ...listedCandidates]
      .filter((question) => question?.id)
      .map((question) => [String(question.id), question]),
  ).values()];
  const examTrackId = aylaCanonicalExamTrack(examTrack);
  const examDefinition = AYLA_EXAM_REGISTRY[examTrackId] || {};
  const nclexBlueprint = examTrackId === "nclex"
    ? aylaNclexDiagnosticBlueprint(examVariant)
    : null;
  if (examTrackId === "nclex" && !nclexBlueprint) {
    const error = new Error("Choose NCLEX-RN or NCLEX-PN before starting the diagnostic");
    error.statusCode = 409;
    error.code = "NCLEX_VARIANT_REQUIRED";
    throw error;
  }
  const multiExamMinimumSystems = {
    // A seeded 200-question Step 2 discovery window consistently exposes six
    // or more verified clinical lanes. Requiring a rare seventh lane made a
    // student's diagnostic availability depend on the random attempt seed.
    // Untested curriculum lanes remain explicitly unknown in the baseline.
    usmle_step_2_ck: 6,
    usmle_step_3: 8,
    plab: 8,
    amc: 6,
    mccqe: 6,
    nclex: 8,
  };
  const blueprint = examTrackId === "usmle_step_1"
    ? buildStep1DiagnosticSelection(candidates, {
      requestedCount,
      minimumSystems: Math.min(12, requestedCount),
      preferredQuestionIds,
      selectionSeed,
      questionExposureCounts,
    })
    : buildMultiExamDiagnosticSelection(candidates, {
      requestedCount,
      minimumSystems: Math.min(multiExamMinimumSystems[examTrackId] || 6, requestedCount),
      allowedSystems: nclexBlueprint
        ? aylaNclexDiagnosticSystems(examVariant)
        : examDefinition.systems || [],
      resolveSystem: (question) => nclexBlueprint
        ? aylaNclexDiagnosticQuestionClientNeed(question, examVariant)
        : aylaV227CanonicalSystemForStudent(
          { examTrack: examTrackId },
          question.system_label
            || question.taxonomy?.labels?.system
            || question.system_key
            || question.taxonomy?.system_key
            || question.system,
          "",
          question.subsystem_label
            || question.taxonomy?.labels?.subsystem
            || question.subsystem_key
            || question.taxonomy?.subsystem_key
            || question.subsystem,
        ),
      preferredQuestionIds,
      selectionSeed,
      questionExposureCounts,
      targetPercentBySystem: nclexBlueprint
        ? aylaNclexDiagnosticTargetPercentages(examVariant)
        : {},
    });
  if (!blueprint.ready) {
    const error = new Error(
      `The verified ${examDefinition.label || "exam"} diagnostic is not ready yet. Every diagnostic question must have complete media and verified exam-system placement.`,
    );
    error.statusCode = 409;
    error.code = "DIAGNOSTIC_CONTENT_NOT_READY";
    error.details = {
      code: error.code,
      eligible_questions: blueprint.eligibleQuestionCount,
      required_questions: blueprint.requestedCount,
        systems_available: blueprint.availableSystemKeys.length,
        available_systems: blueprint.availableSystemKeys,
        systems_required: blueprint.minimumSystems,
      media_incomplete_questions: blueprint.rejectedMissingMediaCount,
      governed_replacements: blueprint.governedReplacementCount,
      unmatched_replacement_slots: blueprint.unmatchedReplacementCount,
      unavailable_preferred_questions: blueprint.preferredUnavailableCount,
      replacement_gaps: blueprint.rejected.unmatchedReplacements,
      unclassified_questions: blueprint.rejectedUnclassifiedCount,
      official_weighting_ready: blueprint.weightingReady !== false,
      target_question_counts: blueprint.targetQuestionCountBySystem || null,
      selected_question_counts: blueprint.selectedQuestionCountBySystem || null,
      official_blueprint: nclexBlueprint
        ? aylaNclexDiagnosticBlueprintSnapshot(examVariant)
        : null,
      private_drafts_exposed: false,
    };
    throw error;
  }
  return {
    selected: blueprint.selected,
    availableSystemKeys: blueprint.availableSystemKeys,
    selectedSystemKeys: blueprint.selectedSystemKeys,
    diagnosticSystemByQuestionId: Object.fromEntries(
      blueprint.selected.map((question) => [String(question.id), question.diagnostic_system]),
    ),
    diagnosticReplacementLineage: blueprint.replacements,
    diagnosticTaxonomyByQuestionId: blueprint.diagnosticTaxonomyByQuestionId,
    diagnosticBlueprint: nclexBlueprint
      ? aylaNclexDiagnosticBlueprintSnapshot(examVariant)
      : null,
    blueprintVersion: AYLA_DIAGNOSTIC_BLUEPRINT_VERSION,
    quality: {
      blueprintVersion: AYLA_DIAGNOSTIC_BLUEPRINT_VERSION,
      requestedQuestionCount: blueprint.requestedCount,
      eligibleQuestionCount: blueprint.eligibleQuestionCount,
      selectedQuestionCount: blueprint.selected.length,
      minimumSystemCount: blueprint.minimumSystems,
      availableSystemCount: blueprint.availableSystemKeys.length,
      selectedSystemCount: blueprint.selectedSystemKeys.length,
      mediaReferenceCount: blueprint.mediaReferenceCount,
      mediaIncompleteQuestionCount: blueprint.rejectedMissingMediaCount,
      governedReplacementCount: blueprint.governedReplacementCount,
      unmatchedReplacementCount: blueprint.unmatchedReplacementCount,
      preferredUnavailableCount: blueprint.preferredUnavailableCount,
      selectedImageQuestionCount: blueprint.selectedImageQuestionCount,
      unclassifiedQuestionCount: blueprint.rejectedUnclassifiedCount,
      selectionMode: blueprint.selectionMode,
      selectionSeedHash: blueprint.selectionSeedHash,
      studentAttemptSeeded: blueprint.studentAttemptSeeded,
      repeatedQuestionCount: blueprint.repeatedQuestionCount,
      freshQuestionCount: blueprint.freshQuestionCount,
      maximumPriorExposure: blueprint.maximumPriorExposure,
      taxonomyDepthReady: blueprint.taxonomyDepthReady,
      taxonomyCoverage: blueprint.taxonomyCoverage,
      weightingRequired: Boolean(nclexBlueprint),
      weightingReady: blueprint.weightingReady !== false,
      targetPercentBySystem: blueprint.targetPercentBySystem || null,
      targetQuestionCountBySystem: blueprint.targetQuestionCountBySystem || null,
      selectedQuestionCountBySystem: blueprint.selectedQuestionCountBySystem || null,
      officialBlueprintRequired: Boolean(nclexBlueprint),
      officialBlueprintId: nclexBlueprint?.id || null,
      officialBlueprintVersion: nclexBlueprint?.version || null,
      officialBlueprintSource: nclexBlueprint?.sourceUrl || null,
      examVariant: nclexBlueprint?.variant || null,
      mediaReady: true,
      taxonomyReady: true,
      governedReplacementReady: blueprint.unmatchedReplacementCount === 0
        && blueprint.preferredUnavailableCount === 0,
      privateDraftsExposed: false,
    },
  };
}

