app.post("/api/ayla/admin/catalog/uworld-cleanup/apply", async (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  try {
    await aylaRequireAdmin(req);
    const preflight = await ngGuardedUworldCleanupPreview();
    const expected = String(req.body?.expected_fingerprint || req.body?.expectedFingerprint || "");
    if (!preflight.ready || !expected || expected !== preflight.fingerprint) {
      return aylaSendError(res, 409, "UWorld cleanup preflight changed or did not pass; nothing was deleted", { preflight });
    }
    const database = await applyGuardedUworldCleanup({
      expectedFingerprint: preflight.database.fingerprint,
    });
    const failedR2Objects = [];
    for (const objectKey of database.r2_object_keys) {
      try { await deleteContentR2Object(objectKey); }
      catch (error) { failedR2Objects.push({ object_key: objectKey, error: String(error.message || error) }); }
    }
    const archive = {
      object_key: preflight.archive.object_key,
      upload_ids: preflight.archive.upload_ids,
      total_bytes: preflight.archive.total_bytes,
      deleted: false,
      manifest_updates: [],
    };
    try {
      await deleteContentR2Object(preflight.archive.object_key);
      archive.deleted = true;
      for (const uploadId of preflight.archive.upload_ids || []) {
        try { archive.manifest_updates.push(await ngContentUploadStore.cancel(uploadId)); }
        catch (error) {
          if (Number(error.statusCode || 0) !== 404) throw error;
          archive.manifest_updates.push({ id: uploadId, status: "manifest_missing" });
        }
      }
    } catch (error) {
      archive.error = String(error.message || error);
    }
    return aylaSendOk(res, {
      database: { ...database, r2_object_keys: undefined },
      media_objects_requested: database.r2_object_keys.length,
      media_objects_failed: failedR2Objects,
      archive,
      storage_cleanup_complete: failedR2Objects.length === 0 && archive.deleted && !archive.error,
      global_student_access: false,
      preserved: ["AylaMed student history", "Vimeo", "notes", "recordings", "unrelated AylaMed-owned content"],
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details || null);
  }
});

app.post("/api/ayla/admin/catalog/owned-collections/:collectionId/student-access", async (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("Pragma", "no-cache");
  try {
    const admin = await aylaRequireAdmin(req);
    const studentId = String(req.body.student_id || req.body.studentId || "").trim().toLowerCase();
    if (!/^(?:[0-9a-f]{8}-[0-9a-f-]{27}|dx-[0-9]{6}-[0-9a-f]{8})$/i.test(studentId)) {
      return aylaSendError(res, 400, "A valid AylaMed student_id is required");
    }
    const db = await readAylaDb();
    const student = aylaValues(db, "aylaStudents").find((row) => (
      String(row.id || row.student_id || row.studentId || "").trim().toLowerCase() === studentId
    )) || null;
    if (!student) return aylaSendError(res, 404, "AylaMed student not found");
    const examTrack = normalizeAylaRegistryExamTrack(
      student.examTrackId || student.exam_track_id || student.examTrack || student.exam_track || student.exam,
    );
    if (!examTrack) return aylaSendError(res, 409, "Student has no supported exam track");
    const collections = await listContentCollections({ examTrack, limit: 200 });
    const collection = collections.find((row) => String(row.id) === String(req.params.collectionId));
    if (!collection) return aylaSendError(res, 404, "Owned catalogue collection not found for this exam");
    if (String(collection.source_profile || "") !== "aylamed_original") {
      return aylaSendError(res, 409, "Only AylaMed-owned original collections can use exact-student access");
    }
    const destinationScope = `${AYLA_STUDENT_CATALOG_SCOPE_PREFIX}${studentId}`;
    const destinations = [
      "aylamed_qbank",
      "aylamed_roadmap",
      "aylamed_auto_assessment",
      "aylamed_personal_assessment",
      "baseline_diagnostic",
      "revision",
      "flashcards",
    ].flatMap((destination) => ([
      { destination, destination_scope: "", enabled: false, settings: { owned_catalogue_guard: true } },
      { destination, destination_scope: destinationScope, enabled: true, settings: { owned_catalogue_guard: true, student_id: studentId } },
    ]));
    const updated = await updateContentCollectionControls({
      collectionId: collection.id,
      status: "approved",
      destinations,
      sourceProfile: "aylamed_original",
      sourceRightsStatus: "owned",
      displayPolicy: { question_id_mode: "internal", source_label_mode: "hidden" },
      actorId: String(admin.user?.id || admin.method || "aylamed-admin"),
    });
    return aylaSendOk(res, {
      collection: updated,
      student_id: studentId,
      destination_scope: destinationScope,
      global_student_access: false,
      legacy_catalogue_changed: false,
      message: "AylaMed-owned catalogue access enabled for this student only.",
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details || null);
  }
});

app.get("/api/ayla/admin/diagnostic/step1/media-replacements/preview", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const destinationScope = String(
      req.query.destination_scope || req.query.destinationScope || "private_step1_pilot",
    ).trim().slice(0, 120);
    const sessionId = String(req.query.session_id || req.query.sessionId || "").trim();
    let preferredQuestionIds = String(
      req.query.preferred_question_ids || req.query.preferredQuestionIds || "",
    ).split(",").map((value) => value.trim()).filter(Boolean).slice(0, 40);
    if (sessionId) {
      const db = await readAylaDb();
      const session = aylaGetItem(db, "aylaQbankSessions", sessionId);
      if (!session || String(session.purpose || "") !== "baseline_diagnostic") {
        return aylaSendError(res, 404, "Step 1 diagnostic session not found");
      }
      if (normalizeAylaQbankExamTrack(session.examTrack) !== "usmle_step_1") {
        return aylaSendError(res, 409, "This preview only supports a Step 1 diagnostic");
      }
      preferredQuestionIds = (Array.isArray(session.questions) ? session.questions : [])
        .map((mapping) => String(mapping.contentQuestionId || ""))
        .filter(Boolean)
        .slice(0, 40);
    }
    const listed = await listContentQbankQuestions({
      examTrack: "usmle_step_1",
      destination: "aylamed_qbank",
      destinationScope,
      limit: 200,
      seed: `aylamed-step1-diagnostic-v${AYLA_DIAGNOSTIC_BLUEPRINT_VERSION}:${destinationScope || "default"}`,
    });
    const preferred = preferredQuestionIds.length
      ? await getContentQbankQuestions({
        questionIds: preferredQuestionIds,
        examTrack: "usmle_step_1",
        destination: "aylamed_qbank",
        destinationScope,
      })
      : [];
    const candidates = [...new Map(
      [...preferred, ...listed]
        .filter((question) => question?.id)
        .map((question) => [String(question.id), question]),
    ).values()];
    const blueprint = buildStep1DiagnosticSelection(candidates, {
      requestedCount: 40,
      minimumSystems: 12,
      preferredQuestionIds,
    });
    const titleById = new Map(candidates.map((question) => [
      String(question.id),
      String(question.title || ""),
    ]));
    return aylaSendOk(res, {
      read_only: true,
      write_performed: false,
      answer_keys_included: false,
      question_stems_included: false,
      private_drafts_exposed: false,
      session_id: sessionId || null,
      destination_scope: destinationScope,
      blueprint_version: AYLA_DIAGNOSTIC_BLUEPRINT_VERSION,
      ready: blueprint.ready,
      summary: {
        required_questions: blueprint.requestedCount,
        selected_questions: blueprint.selected.length,
        selected_systems: blueprint.selectedSystemKeys.length,
        required_systems: blueprint.minimumSystems,
        broken_media_questions: blueprint.rejectedMissingMediaCount,
        governed_replacements: blueprint.governedReplacementCount,
        unmatched_replacement_slots: blueprint.unmatchedReplacementCount,
        unavailable_preferred_questions: blueprint.preferredUnavailableCount,
      },
      replacements: blueprint.replacements.map((row) => ({
        ...row,
        originalTitle: titleById.get(row.originalQuestionId) || "",
        replacementTitle: titleById.get(row.replacementQuestionId) || "",
      })),
      gaps: blueprint.rejected.unmatchedReplacements,
      unavailable_preferred_questions: blueprint.rejected.preferredUnavailable,
      media_incomplete_questions: blueprint.rejected.missingMedia,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details || null);
  }
});

function aylaRequireCurrentDiagnosticBlueprint(session = {}) {
  if (diagnosticSessionUsesCurrentBlueprint(session)) return;
  const error = new Error(
    "This diagnostic is being upgraded to verified media and system coverage. Start or resume it from the diagnostic builder after the content check passes.",
  );
  error.statusCode = 409;
  error.code = "DIAGNOSTIC_BLUEPRINT_UPGRADE_REQUIRED";
  throw error;
}

function aylaDiagnosticQuestionForSession(session = {}, question = {}) {
  if (String(session.purpose || "") !== "baseline_diagnostic") return question;
  const system = session.diagnosticSystemByQuestionId?.[String(question.id || "")];
  return applyDiagnosticSystemOverride(question, system, {
    allowApprovedLabel: aylaCanonicalExamTrack(session.examTrack || session.exam_track) !== "usmle_step_1",
  });
}

function aylaStudentQbankPresentationPolicy(
  policy = {},
  selectedSourceProfile = "",
  availableBanks = [],
  selectedCollectionIds = [],
) {
  return {
    student_bank_mode: policy.student_bank_mode || "unified_aylamed",
    student_can_choose_source_profile: policy.student_can_choose_source_profile === true,
    student_can_choose_collections: policy.student_can_choose_collections === true,
    student_brand_label: policy.student_brand_label || "AylaMed QBank",
    selected_source_profile: selectedSourceProfile || null,
    available_source_profiles: (Array.isArray(policy.available_source_profiles)
      ? policy.available_source_profiles
      : []).map((row) => ({
      source_profile: row.source_profile,
      question_count: Number(row.question_count || 0),
      collection_count: Number(row.collection_count || 0),
    })),
    available_banks: (Array.isArray(availableBanks) ? availableBanks : []).map((row) => ({
      collection_id: row.id,
      collection_key: row.collection_key,
      name: row.name,
      source_provider: row.source_provider,
      source_year: row.source_year,
      question_count: Number(row.question_count || 0),
      source_exam_track: row.source_exam_track,
      supplemental: row.supplemental === true,
      scoring_allowed: row.scoring_allowed !== false,
      nclex_variant: row.nclex_variant || null,
    })),
    selected_collection_ids: [...new Set((Array.isArray(selectedCollectionIds)
      ? selectedCollectionIds : []).map(String).filter(Boolean))],
    roadmap_source_strategy: "all_approved_profiles",
    personal_tutor_source_strategy: "all_approved_profiles",
    exact_duplicates_count_once: true,
  };
}

function aylaStudentSelectableQbankPolicy(policy = {}, availableBanks = []) {
  const hasBanks = (Array.isArray(availableBanks) ? availableBanks : [])
    .some((row) => Number(row?.question_count || 0) > 0);
  return {
    ...policy,
    student_bank_mode: "collection_switchable",
    student_can_choose_source_profile: false,
    student_can_choose_collections: hasBanks,
    student_brand_label: "Question Bank",
  };
}

// -----------------------------------------------------------------------------
// v256: Exam-scoped NBME Center
// -----------------------------------------------------------------------------
// The source package is imported through the existing private Content Registry
// lane with destination `aylamed_nbme`. AylaMed stores only form metadata and
// resumable student attempts in aylamed-db.json; question bodies and private
// media remain in PostgreSQL/R2. Every student request is checked against both
// the owned profile and its exact paid exam entitlement.

const AYLA_NBME_EXAM_TRACKS = Object.freeze([
  "usmle-step-1",
  "usmle-step-2",
  "usmle-step-3",
]);

function aylaNbmeAccess(db, user, student, requestedExamTrack = "") {
  const profileExam = normalizeAylaNbmeExamTrack(
    student.examTrackId || student.exam_track_id || student.examTrack || student.exam_track || student.exam,
  );
  const requested = normalizeAylaNbmeExamTrack(requestedExamTrack || profileExam);
  if (!profileExam || !requested) {
    throw Object.assign(new Error("The NBME Center is available only for USMLE Step 1, Step 2 CK, and Step 3 dashboards"), {
      statusCode: 409,
      code: "NBME_EXAM_NOT_SUPPORTED",
    });
  }
  if (profileExam !== requested) {
    throw Object.assign(new Error("The requested self-assessment exam does not match this AylaMed dashboard"), {
      statusCode: 403,
      code: "NBME_STUDENT_EXAM_MISMATCH",
    });
  }
  const entitlement = aylaDashboardEntitlement(db, user, student, "nbme_center");
  const entitlementExam = normalizeAylaNbmeExamTrack(entitlement.exam_track || entitlement.exam_track_id);
  if (entitlementExam && entitlementExam !== requested) {
    throw Object.assign(new Error("This self-assessment is outside the active exam entitlement"), {
      statusCode: 403,
      code: "NBME_ENTITLEMENT_EXAM_MISMATCH",
    });
  }
  return { ...entitlement, exam_track: requested };
}

function aylaRevalidateNbmeContext(db, userId, studentId, examTrack) {
  const rawUser = aylaGetItem(db, "aylaUsers", userId);
  const student = aylaGetItem(db, "aylaStudents", studentId);
  if (!rawUser || ["disabled", "deleted"].includes(String(rawUser.status || "").toLowerCase())) {
    throw Object.assign(new Error("AylaMed user is no longer active"), { statusCode: 401 });
  }
  if (!student || String(student.ayla_user_id || student.aylaUserId || student.user_id || student.userId || "") !== String(rawUser.id)) {
    throw Object.assign(new Error("AylaMed student profile not found"), { statusCode: 404 });
  }
  const user = aylaSanitizeUser(rawUser);
  const entitlement = aylaNbmeAccess(db, user, student, examTrack);
  return { rawUser, user, student, entitlement };
}

function aylaOwnedNbmeAttempt(db, user, student, attemptId) {
  const attempt = aylaGetItem(db, "aylaNbmeAttempts", attemptId);
  if (!attempt
    || String(attempt.userId || attempt.user_id || "") !== String(user.id)
    || String(attempt.studentId || attempt.student_id || "") !== String(student.id)) {
    throw Object.assign(new Error("Self-assessment attempt not found"), {
      statusCode: 404,
      code: "NBME_ATTEMPT_NOT_FOUND",
    });
  }
  assertAylaNbmeExamPlacement(attempt, student.examTrackId || student.exam_track_id || student.exam);
  return attempt;
}

function aylaNbmeRegistryRowForForm(rows = [], form = {}) {
  const collectionId = String(form.collectionId || form.collection_id || "");
  const collectionKey = String(form.collectionKey || form.collection_key || "");
  return rows.find((row) => collectionId && String(row.id) === collectionId)
    || rows.find((row) => collectionKey && String(row.collection_key) === collectionKey)
    || null;
}

function aylaNbmeFormWithRegistry(form = {}, registry = null) {
  if (!registry) return form;
  return buildAylaNbmeFormRecord({
    ...form,
    collectionKey: registry.collection_key,
    collectionId: registry.id,
    importedQuestionCount: Number(registry.question_count || 0),
    registryStatus: registry.status || "draft",
    rightsStatus: registry.source_rights_status || "unverified",
    destinationEnabled: registry.destination_enabled === true,
    studentEnabled: form.studentEnabled === true,
  }, form);
}

function aylaPublicNbmeForm(form = {}) {
  const questionCount = Number(form.importedQuestionCount || 0);
  const blockSize = Math.max(1, Number(form.blockSize || 50));
  return {
    id: form.id,
    collection_key: form.collectionKey,
    exam_track: form.examTrack,
    title: form.title,
    short_title: form.shortTitle,
    form_type: form.formType,
    family: form.family,
    form_number: form.formNumber,
    specialty_key: form.specialtyKey || null,
    specialty_label: form.specialtyLabel || null,
    question_count: questionCount,
    expected_question_count: Number(form.expectedQuestionCount || 0),
    block_size: blockSize,
    block_count: Math.ceil(questionCount / blockSize),
    content_complete: questionCount === Number(form.expectedQuestionCount || 0),
    quality_override: form.qualityOverride === true,
    enabled: form.studentEnabled === true,
  };
}

function aylaAdminNbmeForm(form = {}) {
  return {
    ...aylaPublicNbmeForm(form),
    source_question_count: Number(form.sourceQuestionCount || 0),
    answer_choice_count: Number(form.answerChoiceCount || 0),
    media_count: Number(form.mediaCount || 0),
    missing_explanation_count: Number(form.missingExplanationCount || 0),
    orphan_answer_count: Number(form.orphanAnswerCount || 0),
    invalid_answer_key_count: Number(form.invalidAnswerKeyCount || 0),
    collection_id: form.collectionId || null,
    content_import_job_id: form.contentImportJobId || null,
    registry_status: form.registryStatus || "not_imported",
    rights_status: form.rightsStatus || "unverified",
    destination_enabled: form.destinationEnabled === true,
    status: form.status || "private_draft",
    quality_gate: form.qualityGate || null,
    quality_override_reason: form.qualityOverrideReason || null,
    source_sha256: form.sourceSha256 || null,
    archive_sha256: form.archiveSha256 || null,
    created_at: form.createdAt || null,
    updated_at: form.updatedAt || null,
  };
}

async function aylaNbmeRegistryRows(examTrack, includePrivate = false) {
  const normalized = normalizeAylaNbmeExamTrack(examTrack);
  if (!normalized) return [];
  return listContentNbmeCollections({ examTrack: normalized, includePrivate });
}

async function aylaNbmeStudentForms(db, examTrack) {
  const registryRows = await aylaNbmeRegistryRows(examTrack, false);
  return aylaValues(db, "aylaNbmeForms")
    .filter((form) => normalizeAylaNbmeExamTrack(form.examTrack || form.exam_track) === examTrack)
    .map((form) => aylaNbmeFormWithRegistry(form, aylaNbmeRegistryRowForForm(registryRows, form)))
    .filter((form) => form.studentEnabled === true)
    .filter((form) => String(form.registryStatus || "") === "approved" && form.destinationEnabled === true)
    .sort((left, right) =>
      String(left.formType).localeCompare(String(right.formType))
      || String(left.specialtyLabel || "").localeCompare(String(right.specialtyLabel || ""))
      || Number(left.formNumber || 0) - Number(right.formNumber || 0));
}

function aylaNbmeAttemptRows(db, student, examTrack) {
  return aylaValues(db, "aylaNbmeAttempts")
    .filter((row) => String(row.studentId || row.student_id || "") === String(student.id))
    .filter((row) => normalizeAylaNbmeExamTrack(row.examTrack || row.exam_track) === examTrack)
    .sort((left, right) => String(right.updatedAt || right.createdAt || "").localeCompare(String(left.updatedAt || left.createdAt || "")));
}

async function aylaPlayableNbmeAttempt(attempt, { blockIndex = null } = {}) {
  const rawQuestions = await getContentNbmeCollectionQuestions({
    collectionId: attempt.collectionId,
    examTrack: attempt.examTrack,
    approvedOnly: true,
  });
  const rawById = new Map(rawQuestions.map((row) => [String(row.id), row]));
  const blocks = Array.isArray(attempt.blocks) ? attempt.blocks : [];
  const derivedBlock = Math.floor(Math.max(0, Number(attempt.currentQuestionIndex || 0)) / Math.max(1, Number(attempt.blockSize || 50)));
  const selectedBlock = Math.max(0, Math.min(
    Math.max(0, blocks.length - 1),
    blockIndex !== null && blockIndex !== undefined && blockIndex !== "" && Number.isInteger(Number(blockIndex))
      ? Number(blockIndex)
      : derivedBlock,
  ));
  const selectedRefs = new Set(blocks[selectedBlock]?.questionRefs || []);
  const mappings = (Array.isArray(attempt.questions) ? attempt.questions : [])
    .filter((row) => !selectedRefs.size || selectedRefs.has(row.ref));
  const questions = [];
  for (const mapping of mappings) {
    const raw = rawById.get(String(mapping.contentQuestionId)) || null;
    if (!raw) {
      questions.push({
        question_ref: mapping.ref,
        unavailable: true,
        message: "This question is no longer approved for delivery.",
      });
      continue;
    }
    const playable = await ngRegistryQuestionWithPlayableMedia(raw);
    questions.push(sanitizeAylaQbankQuestion(playable, {
      session: { ...attempt, mode: "test" },
      questionRef: mapping.ref,
    }));
  }
  return {
    build: AYLA_NBME_CENTER_BUILD,
    attempt: sanitizeAylaNbmeAttempt(attempt),
    block: {
      index: selectedBlock,
      count: blocks.length,
      question_refs: blocks[selectedBlock]?.questionRefs || [],
    },
    questions,
  };
}

const AYLA_NBME_REVIEWED_RELEASE_NAMESPACES = Object.freeze({
  "usmle-step-1": "aylamed-nbme-step-1-complete",
  "usmle-step-2": "aylamed-nbme-step-2-complete",
  "usmle-step-3": "aylamed-nbme-step-3-complete",
});

function aylaAssertReviewedNbmeImportJob(job = null, {
  requireDraftImported = false,
  expectedExamTrack = "",
} = {}) {
  if (!job) {
    throw Object.assign(new Error("Reviewed NBME import job not found"), {
      statusCode: 404,
      code: "NBME_RELEASE_IMPORT_NOT_FOUND",
    });
  }
  const destinations = Array.isArray(job.destinations) ? job.destinations.map((row) => String(row)) : [];
  const examTrack = normalizeAylaNbmeExamTrack(job.exam_track);
  const expected = expectedExamTrack ? normalizeAylaNbmeExamTrack(expectedExamTrack) : null;
  const reviewedPackage = examTrack
    && String(job.source_namespace || "") === AYLA_NBME_REVIEWED_RELEASE_NAMESPACES[examTrack]
    && String(job.source_profile || "") === "other"
    && String(job.source_rights_status || "") === "authorized"
    && destinations.includes("aylamed_nbme");
  if (!reviewedPackage) {
    throw Object.assign(new Error("This import is not a reviewed NBME package for its exam track"), {
      statusCode: 403,
      code: "NBME_RELEASE_IMPORT_NOT_REVIEWED",
    });
  }
  if (expected && examTrack !== expected) {
    throw Object.assign(new Error("The reviewed package belongs to a different exam track"), {
      statusCode: 409,
      code: "NBME_RELEASE_IMPORT_EXAM_MISMATCH",
    });
  }
  if (requireDraftImported && !["draft_imported", "draft_imported_with_warnings"].includes(String(job.status || ""))) {
    throw Object.assign(new Error("The reviewed questions must finish private draft import before this action"), {
      statusCode: 409,
      code: "NBME_RELEASE_DRAFT_IMPORT_REQUIRED",
    });
  }
  return job;
}

app.post("/api/ayla/admin/nbme-center/content-imports/:jobId/media/import-draft", async (req, res) => {
  let upload;
  let mediaJob = null;
  try {
    const admin = await aylaRequireAdmin(req);
    if (!contentMediaStatus().configured) return aylaSendError(res, 503, "Cloudflare R2 is not configured");
    const parentJob = aylaAssertReviewedNbmeImportJob(
      await getContentImportJob(req.params.jobId),
      { requireDraftImported: true },
    );
    upload = await ngReceiveOrResolveContentZip(req, ["image_zip", "media_zip", "question_zip"]);
    if (String(upload.sha256 || "") !== String(parentJob.zip_sha256 || "")) {
      await ngCleanupRejectedContentUpload(upload);
      upload = null;
      return aylaSendError(res, 409, "Use the exact reviewed NBME ZIP that passed the private preview");
    }
    mediaJob = await createContentMediaImportJob({
      id: crypto.randomUUID(),
      contentImportJobId: parentJob.id,
      zipSha256: upload.sha256,
      originalFilename: upload.originalFilename,
      createdBy: String(admin.user?.id || admin.method || "aylamed-admin"),
    });
    const backgroundJob = await ngQueueContentOperation({
      type: "content_image_draft",
      lane: "image_zip",
      upload,
      domainJobId: mediaJob.id,
    });
    upload = null;
    return aylaSendOk(res, {
      media_job_id: mediaJob.id,
      background_job_id: backgroundJob.id,
      content_import_job_id: parentJob.id,
      status: "queued",
      exam_track: normalizeAylaNbmeExamTrack(parentJob.exam_track),
      reviewed_form_ids: normalizeAylaNbmeExamTrack(parentJob.exam_track) === "usmle-step-1"
        ? AYLA_NBME_STEP1_REVIEWED_RELEASE_FORM_IDS
        : [],
      message: "Reviewed media accepted for private import. Student access remains disabled.",
    }, 202);
  } catch (error) {
    if (mediaJob?.id) {
      await finishContentMediaImportJob(
        mediaJob.id,
        "queue_failed",
        { failed: true },
        [{ error: error.message }],
      ).catch(() => {});
    }
    await ngCleanupRejectedContentUpload(upload);
    return aylaSendError(res, error.statusCode || 500, error.message || "Reviewed NBME media import failed", {
      ...(error.code ? { code: error.code } : {}),
    });
  }
});

app.get("/api/ayla/admin/nbme-center/content-media-imports/:mediaJobId", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const job = await getContentMediaImportJob(req.params.mediaJobId);
    if (!job) return aylaSendError(res, 404, "Reviewed NBME media import job not found");
    aylaAssertReviewedNbmeImportJob(await getContentImportJob(job.content_import_job_id));
    const snapshot = ngContentBackgroundSnapshot(job.id);
    return aylaSendOk(res, {
      job,
      background_jobs: snapshot.backgroundJobs,
      monitoring: snapshot.monitoring,
      resume_upload_id: snapshot.resumeUploadId,
      storage: contentMediaStatus(),
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to load reviewed NBME media import", {
      ...(error.code ? { code: error.code } : {}),
    });
  }
});

app.put("/api/ayla/admin/nbme-center/collections/:collectionId/release", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    const formId = String(req.body?.form_id || req.body?.formId || "").trim();
    const initialDb = await readAylaDb();
    const form = aylaGetItem(initialDb, "aylaNbmeForms", formId);
    if (!form) return aylaSendError(res, 404, "Reviewed NBME form not found");
    const definition = assertAylaNbmeReviewedReleaseForm(
      formId,
      form.collectionKey || form.collection_key,
    );
    if (String(req.body?.confirmation || "") !== formId) {
      return aylaSendError(res, 400, "Type the exact form ID to release this reviewed collection");
    }
    if (form.qualityGate?.ready !== true) {
      return aylaSendError(
        res,
        409,
        `This form no longer passes its complete ${definition.expectedQuestionCount}-question quality gate`,
      );
    }
    const collections = await listContentCollections({ examTrack: definition.examTrack, limit: 200 });
    const collection = collections.find((row) => String(row.id) === String(req.params.collectionId));
    if (!collection || String(collection.collection_key || "") !== definition.collectionKey) {
      return aylaSendError(res, 409, "The Content Registry collection does not match the reviewed form");
    }
    if (Number(collection.question_count || 0) !== definition.expectedQuestionCount) {
      return aylaSendError(
        res,
        409,
        `The reviewed collection must contain exactly ${definition.expectedQuestionCount} questions`,
      );
    }
    const parentJob = aylaAssertReviewedNbmeImportJob(
      await getContentImportJob(collection.draft_import_job_id),
      { requireDraftImported: true, expectedExamTrack: definition.examTrack },
    );
    const registry = aylaNbmeRegistryRowForForm(
      await aylaNbmeRegistryRows(definition.examTrack, true),
      { ...form, collectionId: collection.id, collectionKey: definition.collectionKey },
    );
    if (!registry || Number(registry.media_link_count || 0) < Number(form.mediaCount || 0)) {
      return aylaSendError(res, 409, "All reviewed media must finish private attachment before release");
    }
    const updated = await updateContentCollectionControls({
      collectionId: collection.id,
      status: "approved",
      destinations: [{
        destination: "aylamed_nbme",
        destination_scope: "",
        enabled: true,
        settings: {
          reviewed_release: true,
          reviewed_form_id: formId,
          reviewed_import_job_id: parentJob.id,
        },
      }],
      sourceRightsStatus: "authorized",
      displayPolicy: { question_id_mode: "internal", source_label_mode: "hidden" },
      actorId: String(admin.user?.id || admin.method || "aylamed-admin"),
    });
    return aylaSendOk(res, {
      form_id: formId,
      collection: updated,
      question_count: Number(updated?.question_count || 0),
      destination: "aylamed_nbme",
      destination_enabled: true,
      student_form_enabled: false,
      message: "Reviewed collection approved and routed to the NBME destination. Enablement remains a separate final gate.",
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to release reviewed NBME collection", {
      ...(error.code ? { code: error.code } : {}),
      ...(error.details ? { details: error.details } : {}),
    });
  }
});

app.post("/api/ayla/admin/nbme-center/manifests", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    const manifest = normalizeAylaNbmeManifest(req.body?.manifest || req.body || {});
    const result = await mutateAylaDb(async (db) => {
      const saved = [];
      for (const row of manifest.forms) {
        const previous = aylaGetItem(db, "aylaNbmeForms", row.formId) || {};
        const form = buildAylaNbmeFormRecord({
          ...previous,
          ...row,
          archiveSha256: manifest.archiveSha256,
          studentEnabled: false,
        }, previous);
        aylaSetItem(db, "aylaNbmeForms", form);
        saved.push(form);
      }
      const event = {
        id: aylaId("AYLA-NBME-EVENT"),
        type: "source_manifest_registered",
        archiveSha256: manifest.archiveSha256,
        formCount: saved.length,
        exams: [...new Set(saved.map((row) => row.examTrack))],
        studentVisibility: false,
        actorId: admin.user?.id || admin.method || "aylamed-admin",
        createdAt: aylaNow(),
      };
      aylaSetItem(db, "aylaNbmeAuditEvents", event);
      return { saved, event };
    });
    return aylaSendOk(res, {
      build: AYLA_NBME_CENTER_BUILD,
      count: result.saved.length,
      forms: result.saved.map(aylaAdminNbmeForm),
      event: result.event,
      student_visibility: false,
      message: "Self-assessment manifest registered as private disabled drafts.",
    }, 201);
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to register the self-assessment manifest");
  }
});

app.post("/api/ayla/admin/nbme-center/sync", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    const requested = normalizeAylaNbmeExamTrack(req.body?.exam_track || req.body?.examTrack || "");
    const exams = requested ? [requested] : [...AYLA_NBME_EXAM_TRACKS];
    const registryRows = (await Promise.all(exams.map((examTrack) => aylaNbmeRegistryRows(examTrack, true)))).flat();
    const result = await mutateAylaDb(async (db) => {
      const updated = [];
      for (const registry of registryRows) {
        const definition = parseAylaNbmeCollectionKey(registry.collection_key);
        if (!definition || definition.examTrack !== normalizeAylaNbmeExamTrack(registry.exam_track)) continue;
        const previous = aylaGetItem(db, "aylaNbmeForms", definition.formId) || {};
        const form = aylaNbmeFormWithRegistry(buildAylaNbmeFormRecord({
          ...previous,
          collectionKey: definition.collectionKey,
          sourceQuestionCount: previous.sourceQuestionCount || Number(registry.question_count || 0),
          importedQuestionCount: Number(registry.question_count || 0),
          studentEnabled: previous.studentEnabled === true,
        }, previous), registry);
        aylaSetItem(db, "aylaNbmeForms", form);
        updated.push(form);
      }
      const event = {
        id: aylaId("AYLA-NBME-EVENT"),
        type: "content_registry_sync",
        registryCollectionCount: registryRows.length,
        formCount: updated.length,
        exams,
        actorId: admin.user?.id || admin.method || "aylamed-admin",
        createdAt: aylaNow(),
      };
      aylaSetItem(db, "aylaNbmeAuditEvents", event);
      return { updated, event };
    });
    return aylaSendOk(res, {
      build: AYLA_NBME_CENTER_BUILD,
      count: result.updated.length,
      forms: result.updated.map(aylaAdminNbmeForm),
      event: result.event,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to synchronize self-assessment forms");
  }
});

app.get("/api/ayla/admin/nbme-center", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const db = await readAylaDb();
    const requested = normalizeAylaNbmeExamTrack(req.query.exam_track || req.query.examTrack || "");
    const rows = aylaValues(db, "aylaNbmeForms")
      .filter((row) => !requested || normalizeAylaNbmeExamTrack(row.examTrack || row.exam_track) === requested)
      .sort((left, right) => String(left.examTrack).localeCompare(String(right.examTrack))
        || String(left.formType).localeCompare(String(right.formType))
        || Number(left.formNumber || 0) - Number(right.formNumber || 0));
    const registryByExam = new Map();
    for (const exam of requested ? [requested] : AYLA_NBME_EXAM_TRACKS) {
      registryByExam.set(exam, await aylaNbmeRegistryRows(exam, true));
    }
    const forms = rows.map((form) => aylaNbmeFormWithRegistry(
      form,
      aylaNbmeRegistryRowForForm(registryByExam.get(normalizeAylaNbmeExamTrack(form.examTrack)) || [], form),
    ));
    const attempts = aylaValues(db, "aylaNbmeAttempts")
      .filter((attempt) => !requested
        || normalizeAylaNbmeExamTrack(attempt.examTrack || attempt.exam_track) === requested);
    return aylaSendOk(res, {
      build: AYLA_NBME_CENTER_BUILD,
      count: forms.length,
      forms: forms.map(aylaAdminNbmeForm),
      attempts: attempts.length,
      student_visibility_requires_both_gates: true,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to load NBME Center administration");
  }
});

app.patch("/api/ayla/admin/nbme-center/forms/:formId", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    if (typeof req.body?.student_enabled !== "boolean" && typeof req.body?.studentEnabled !== "boolean") {
      return aylaSendError(res, 400, "student_enabled must be true or false");
    }
    const enabled = req.body.student_enabled === true || req.body.studentEnabled === true;
    if (enabled && String(req.body.confirmation || "") !== String(req.params.formId)) {
      return aylaSendError(res, 400, "Type the exact form ID to enable this self-assessment");
    }
    const initialDb = await readAylaDb();
    const initial = aylaGetItem(initialDb, "aylaNbmeForms", req.params.formId);
    if (!initial) return aylaSendError(res, 404, "Self-assessment form not found");
    const registryRows = await aylaNbmeRegistryRows(initial.examTrack, true);
    const registry = aylaNbmeRegistryRowForForm(registryRows, initial);
    const result = await mutateAylaDb(async (db) => {
      const current = aylaGetItem(db, "aylaNbmeForms", req.params.formId);
      if (!current) throw Object.assign(new Error("Self-assessment form not found"), { statusCode: 404 });
      const refreshed = aylaNbmeFormWithRegistry(current, registry);
      let quality = { allowed: true, override: false, reasons: [] };
      if (enabled) {
        quality = validateAylaNbmeStudentEnable(refreshed, {
          confirmQualityOverride: req.body.confirm_quality_override === true || req.body.confirmQualityOverride === true,
          qualityOverrideReason: req.body.quality_override_reason || req.body.qualityOverrideReason || "",
        });
      }
      const updated = {
        ...refreshed,
        studentEnabled: enabled,
        status: enabled ? "student_enabled" : refreshed.qualityGate?.ready ? "review_ready" : "private_draft",
        qualityOverride: enabled && quality.override === true,
        qualityOverrideReasons: enabled && quality.override ? quality.reasons : [],
        qualityOverrideReason: enabled && quality.override ? quality.reason : null,
        enabledBy: enabled ? admin.user?.id || admin.method || "aylamed-admin" : null,
        enabledAt: enabled ? aylaNow() : null,
        disabledAt: enabled ? null : aylaNow(),
        updatedAt: aylaNow(),
      };
      aylaSetItem(db, "aylaNbmeForms", updated);
      const event = {
        id: aylaId("AYLA-NBME-EVENT"),
        type: enabled ? "student_form_enabled" : "student_form_disabled",
        formId: updated.id,
        examTrack: updated.examTrack,
        qualityOverride: updated.qualityOverride === true,
        qualityOverrideReasons: updated.qualityOverrideReasons || [],
        actorId: admin.user?.id || admin.method || "aylamed-admin",
        createdAt: aylaNow(),
      };
      aylaSetItem(db, "aylaNbmeAuditEvents", event);
      return { updated, event };
    });
    return aylaSendOk(res, {
      build: AYLA_NBME_CENTER_BUILD,
      form: aylaAdminNbmeForm(result.updated),
      event: result.event,
      student_visibility: result.updated.studentEnabled === true,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to update self-assessment visibility");
  }
});

