app.get("/api/ayla/qbank/catalog", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.query.student_id || ""), "qbank");
    const access = aylaRequireQbankAccess(auth.db, auth.user, auth.student, req.query.exam_track || req.query.examTrack || "");
    const examTrack = access.exam_track;
    aylaRequireExamPublished(auth.db, aylaCanonicalExamTrack(examTrack), "qbank");
    const destinationScope = aylaStudentCatalogDestinationScope(auth.student);
    const bankSummaryMode = String(req.query.view || "") === "bank_summary";
    const presentationPolicy = bankSummaryMode
      ? {}
      : await getContentQbankPresentationPolicy({ examTrack });
    const sourceProfile = bankSummaryMode
      ? ""
      : resolveContentQbankStudentSourceProfile(
        presentationPolicy,
        req.query.source_profile || req.query.sourceProfile || "",
      );
    const availableBanks = await aylaAvailableQbankBanks(auth.db, {
      examTrack,
      destination: "qbank",
      destinationScope,
      sourceProfile,
      student: auth.student,
    });
    const studentPresentationPolicy = aylaStudentSelectableQbankPolicy(presentationPolicy, availableBanks);
    const requestedCollectionIds = aylaRequestedQbankCollectionIds(
      req.query.collection_ids ?? req.query.collectionIds ?? [],
    );
    const selectedCollectionIds = resolveContentQbankStudentCollectionIds(
      { ...studentPresentationPolicy, available_banks: availableBanks },
      requestedCollectionIds,
    );
    const selectedBanks = availableBanks.filter((row) => selectedCollectionIds.includes(row.id));
    const banksBySourceExam = new Map();
    for (const bank of selectedBanks) {
      if (!banksBySourceExam.has(bank.source_exam_track)) banksBySourceExam.set(bank.source_exam_track, []);
      banksBySourceExam.get(bank.source_exam_track).push(bank);
    }
    const catalog = bankSummaryMode
      ? selectedBanks.map((bank) => ({
        bank_id: bank.id,
        bank_name: bank.name,
        source_exam_track: bank.source_exam_track,
        supplemental: bank.supplemental === true,
        scoring_allowed: bank.scoring_allowed !== false,
        nclex_variant: bank.nclex_variant || null,
        question_count: Number(bank.question_count || 0),
      }))
      : (await Promise.all([...banksBySourceExam.entries()].map(async ([sourceExamTrack, banks]) => {
        const collectionIds = banks.map((row) => row.id);
        const rows = await getContentQbankCatalog({
          examTrack: sourceExamTrack,
          destination: "aylamed_qbank",
          destinationScope,
          sourceProfile,
          collectionIds,
        });
        return rows.map((row) => ({
          ...row,
          source_exam_track: sourceExamTrack,
          supplemental: sourceExamTrack !== examTrack,
          scoring_allowed: sourceExamTrack === examTrack,
        }));
      }))).flat();
    return aylaSendOk(res, {
      exam_track: examTrack,
      exam_variant: aylaStudentNclexVariant(auth.student) || null,
      entitlement: { type: access.entitlement_type, expires_at: access.expires_at || null },
      presentation: aylaStudentQbankPresentationPolicy(
        studentPresentationPolicy,
        sourceProfile,
        availableBanks,
        selectedCollectionIds,
      ),
      content_delivery_policy: contentDeliveryPolicySnapshot(),
      count: catalog.length,
      question_count: catalog.reduce((sum, row) => sum + Number(row.question_count || 0), 0),
      catalog,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details || (error.code ? { code: error.code } : null));
  }
});

app.post("/api/ayla/qbank/sessions", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body.student_id || req.body.studentId || ""), "qbank");
    const access = aylaRequireQbankAccess(auth.db, auth.user, auth.student, req.body.exam_track || req.body.examTrack || "");
    const nclexVariant = requireAylaNclexVariant(auth.student, access.exam_track);
    const destinationScope = aylaStudentCatalogDestinationScope(auth.student);
    const purpose = normalizeAylaQbankPurpose(req.body.purpose || req.body.session_purpose || "practice");
    aylaRequireExamPublished(auth.db, aylaCanonicalExamTrack(access.exam_track), purpose === "baseline_diagnostic" ? "diagnostic" : "qbank");
    const requestedCount = Number(req.body.question_count ?? req.body.questionCount ?? 40);
    if (!Number.isInteger(requestedCount) || requestedCount < 1 || requestedCount > 200) {
      return aylaSendError(res, 400, "question_count must be an integer between 1 and 200");
    }
    const filters = purpose === "baseline_diagnostic"
      ? normalizeAylaQbankFilters({})
      : normalizeAylaQbankFilters(req.body.filters || req.body);
    const requestedMode = purpose === "baseline_diagnostic" ? "test" : normalizeAylaQbankMode(req.body.mode || "tutor");
    const defaultBlockSize = purpose === "baseline_diagnostic" ? 20 : 40;
    const requestedBlockSize = Math.max(1, Math.min(40, Math.trunc(Number(req.body.block_size ?? req.body.blockSize ?? defaultBlockSize) || defaultBlockSize)));
    const idempotencyKey = String(req.headers["idempotency-key"] || req.body.idempotency_key || req.body.idempotencyKey || "").trim().slice(0, 120);
    if (purpose === "baseline_diagnostic") {
      if (auth.student.serverVerifiedBaseline === true || String(auth.student.onboardingStatus || "") === "complete") {
        return aylaSendError(res, 409, "The verified starting diagnostic is already complete. Use a normal test session for later reassessment.");
      }
      const activeDiagnostics = aylaValues(auth.db, "aylaQbankSessions").filter((row) =>
        String(row.userId || "") === String(auth.user.id)
        && String(row.studentId || "") === String(auth.student.id)
        && String(row.examTrack || "") === String(access.exam_track)
        && String(row.purpose || "") === "baseline_diagnostic"
        && String(row.status || "") === "in_progress");
      const activeDiagnostic = activeDiagnostics.find((row) =>
        diagnosticSessionUsesCurrentBlueprint(row));
      if (activeDiagnostic) {
        assertAylaNclexSessionVariant(auth.student, activeDiagnostic);
        const bundle = await aylaPlayableQbankSession(auth.db, activeDiagnostic);
        return aylaSendOk(res, {
          ...bundle,
          requested_question_count: Number(activeDiagnostic.requestedQuestionCount || activeDiagnostic.questionCount || 0),
          selected_question_count: Number(activeDiagnostic.questionCount || 0),
          partial_selection: Number(activeDiagnostic.questionCount || 0) < Number(activeDiagnostic.requestedQuestionCount || activeDiagnostic.questionCount || 0),
          idempotent_replay: true,
          resumed_existing_diagnostic: true,
        });
      }
      const answeredLegacyDiagnostic = activeDiagnostics.find((row) =>
        Object.keys(row.answers && typeof row.answers === "object" ? row.answers : {}).length > 0);
      if (answeredLegacyDiagnostic) {
        return aylaSendError(
          res,
          409,
          "An earlier diagnostic contains answers and requires review before it can be upgraded. No answer or baseline was changed.",
          {
            code: "ANSWERED_DIAGNOSTIC_REVIEW_REQUIRED",
            session_id: answeredLegacyDiagnostic.id,
            answered_question_count: Object.keys(answeredLegacyDiagnostic.answers || {}).length,
          },
        );
      }
    }

    let origin = "personal";
    let roadmapAssignmentId = null;
    let roadmapQuestionIds = [];
    const requestedRoadmapAssignmentId = String(req.body.roadmap_assignment_id || req.body.roadmapAssignmentId || "").trim();
    if (requestedRoadmapAssignmentId) {
      const assignment = aylaGetItem(auth.db, "aylaResourceAssignments", requestedRoadmapAssignmentId);
      if (!assignment || String(assignment.studentId || "") !== String(auth.student.id)) return aylaSendError(res, 404, "Roadmap assignment not found");
      if (!aylaQbankRoadmapAssignmentEligible(assignment)) return aylaSendError(res, 409, "Roadmap assignment is not a QBank question assignment");
      if (["completed", "cancelled", "canceled", "skipped", "superseded"].includes(String(assignment.status || "").toLowerCase())) {
        return aylaSendError(res, 409, "This roadmap QBank assignment is no longer active");
      }
      const assignmentExam = normalizeAylaQbankExamTrack(assignment.examTrackId || assignment.examTrack || assignment.exam_track || "");
      if (assignmentExam && assignmentExam !== access.exam_track) return aylaSendError(res, 403, "Roadmap assignment belongs to another exam track");
      roadmapQuestionIds = qbankRoadmapAssignmentQuestionIds(assignment);
      if (!roadmapQuestionIds.length) return aylaSendError(res, 409, "This roadmap assignment has no published QBank question identities");
      origin = "roadmap";
      roadmapAssignmentId = assignment.id;

      const activeRoadmapSession = aylaValues(auth.db, "aylaQbankSessions").find((row) =>
        String(row.userId || "") === String(auth.user.id)
        && String(row.studentId || "") === String(auth.student.id)
        && String(row.examTrack || "") === String(access.exam_track)
        && String(row.origin || "") === "roadmap"
        && String(row.roadmapAssignmentId || "") === String(roadmapAssignmentId)
        && String(row.status || "") === "in_progress");
      if (activeRoadmapSession) {
        assertAylaNclexSessionVariant(auth.student, activeRoadmapSession);
        if (!qbankRoadmapSessionMatchesAssignment(activeRoadmapSession, assignment)) {
          return aylaSendError(res, 409, "This roadmap QBank assignment changed after its earlier session began. Refresh the roadmap before continuing.");
        }
        const bundle = await aylaPlayableQbankSession(auth.db, activeRoadmapSession);
        return aylaSendOk(res, {
          ...bundle,
          requested_question_count: Number(activeRoadmapSession.requestedQuestionCount || activeRoadmapSession.questionCount || 0),
          selected_question_count: Number(activeRoadmapSession.questionCount || 0),
          partial_selection: false,
          idempotent_replay: true,
          resumed_existing_roadmap: true,
        });
      }
    }
    const effectiveRequestedCount = roadmapAssignmentId ? roadmapQuestionIds.length : requestedCount;
    const effectiveFilters = roadmapAssignmentId ? normalizeAylaQbankFilters({}) : filters;
    const presentationPolicy = {};
    const sourceProfile = "";
    let availableBanks = [];
    let selectedCollectionIds = [];
    let selectedBanks = [];
    if (isAylaNclexExamTrack(access.exam_track)) {
      availableBanks = await aylaAvailableQbankBanks(auth.db, {
        examTrack: access.exam_track,
        destination: purpose === "baseline_diagnostic" ? "diagnostic" : roadmapAssignmentId ? "roadmap" : "qbank",
        destinationScope,
        sourceProfile,
        student: auth.student,
      });
      // NCLEX diagnostics may reuse the student's already published RN- or
      // PN-isolated QBank collections when no separate diagnostic delivery
      // toggle exists. The subsequent official client-needs classifier,
      // weighted blueprint, media audit, and exact 40-item selection still
      // fail closed; this does not expose a private or cross-variant bank.
      if (purpose === "baseline_diagnostic" && nclexVariant && !availableBanks.length) {
        availableBanks = (await aylaAvailableQbankBanks(auth.db, {
          examTrack: access.exam_track,
          destination: "qbank",
          destinationScope,
          sourceProfile,
          student: auth.student,
        })).map((bank) => ({ ...bank, diagnostic_reuse_policy: "published_variant_qbank" }));
      }
      selectedCollectionIds = availableBanks.map((row) => row.id);
      selectedBanks = [...availableBanks];
    }
    if (!roadmapAssignmentId && purpose !== "baseline_diagnostic") {
      if (!availableBanks.length) {
        availableBanks = await aylaAvailableQbankBanks(auth.db, {
          examTrack: access.exam_track,
          destination: "qbank",
          destinationScope,
          sourceProfile,
          student: auth.student,
        });
      }
      const studentPresentationPolicy = aylaStudentSelectableQbankPolicy(presentationPolicy, availableBanks);
      const requestedCollectionIds = aylaRequestedQbankCollectionIds(
        req.body.collection_ids ?? req.body.collectionIds ?? [],
      );
      selectedCollectionIds = resolveContentQbankStudentCollectionIds(
        { ...studentPresentationPolicy, available_banks: availableBanks },
        requestedCollectionIds,
      );
      selectedBanks = availableBanks.filter((row) => selectedCollectionIds.includes(row.id));
    }

    const idempotencyFingerprint = crypto.createHash("sha256").update(JSON.stringify({
      examTrack: access.exam_track,
      examVariant: nclexVariant || null,
      mode: requestedMode,
      purpose,
      requestedCount: effectiveRequestedCount,
      blockSize: requestedBlockSize,
      filters: effectiveFilters,
      origin,
      roadmapAssignmentId,
      roadmapQuestionIds,
      sourceProfile,
      selectedCollectionIds,
      destinationScope,
      timeLimitMinutes: req.body.time_limit_minutes ?? req.body.timeLimitMinutes ?? null,
    })).digest("hex");
    if (idempotencyKey) {
      const existing = aylaValues(auth.db, "aylaQbankSessions").find((row) =>
        String(row.userId || "") === String(auth.user.id)
        && String(row.studentId || "") === String(auth.student.id)
        && String(row.idempotencyKey || "") === idempotencyKey);
      if (existing) {
        if (String(existing.idempotencyFingerprint || "") !== idempotencyFingerprint) return aylaSendError(res, 409, "Idempotency key was already used for a different QBank session request");
        const legacyDiagnostic = purpose === "baseline_diagnostic"
          && !diagnosticSessionUsesCurrentBlueprint(existing);
        if (!legacyDiagnostic) {
          aylaRequireQbankAccess(auth.db, auth.user, auth.student, existing.examTrack);
          assertAylaNclexSessionVariant(auth.student, existing);
          const bundle = await aylaPlayableQbankSession(auth.db, existing);
          return aylaSendOk(res, {
            ...bundle,
            requested_question_count: Number(existing.requestedQuestionCount || existing.questionCount || 0),
            selected_question_count: Number(existing.questionCount || 0),
            partial_selection: Number(existing.questionCount || 0) < Number(existing.requestedQuestionCount || existing.questionCount || 0),
            idempotent_replay: true,
          });
        }
        if (Object.keys(existing.answers && typeof existing.answers === "object" ? existing.answers : {}).length > 0) {
          return aylaSendError(
            res,
            409,
            "An earlier diagnostic contains answers and requires review before it can be upgraded. No answer or baseline was changed.",
            {
              code: "ANSWERED_DIAGNOSTIC_REVIEW_REQUIRED",
              session_id: existing.id,
              answered_question_count: Object.keys(existing.answers || {}).length,
            },
          );
        }
      }
    }

    const sessionId = aylaId("AYLA-QBS");
    const diagnosticSelectionSeed = purpose === "baseline_diagnostic"
      ? `${auth.student.id}:${access.exam_track}:${sessionId}:${crypto.randomUUID()}`
      : "";
    const diagnosticQuestionExposureCounts = {};
    if (purpose === "baseline_diagnostic") {
      for (const priorSession of aylaValues(auth.db, "aylaQbankSessions")) {
        if (
          String(priorSession.userId || "") !== String(auth.user.id)
          || String(priorSession.studentId || "") !== String(auth.student.id)
          || String(priorSession.examTrack || "") !== String(access.exam_track)
          || String(priorSession.purpose || "") !== "baseline_diagnostic"
        ) {
          continue;
        }
        for (const mapping of Array.isArray(priorSession.questions) ? priorSession.questions : []) {
          const questionId = String(
            mapping.contentQuestionId || mapping.content_question_id || "",
          );
          if (!questionId) continue;
          diagnosticQuestionExposureCounts[questionId] = Number(
            diagnosticQuestionExposureCounts[questionId] || 0,
          ) + 1;
        }
      }
    }
    const seenQuestionIds = aylaQbankSeenQuestionIds(auth.db, {
      userId: auth.user.id,
      studentId: auth.student.id,
      examTrack: access.exam_track,
    });

    let selection;
    if (roadmapAssignmentId) {
      const collectionIds = nclexVariant
        ? selectedCollectionIds
        : await aylaPublishedQbankCollectionIds(auth.db, {
          examTrack: access.exam_track,
          sourceExamTrack: access.exam_track,
          destination: "roadmap",
          destinationScope,
          sourceProfile,
        });
      const rows = await getContentQbankQuestions({
        questionIds: roadmapQuestionIds,
        examTrack: access.exam_track,
        destination: "aylamed_qbank",
        destinationScope,
        collectionIds,
      });
      const byId = new Map(rows.map((row) => [String(row.id || ""), row]));
      const selected = roadmapQuestionIds.map((id) => byId.get(String(id))).filter(Boolean);
      if (selected.length !== roadmapQuestionIds.length) {
        return aylaSendError(
          res,
          409,
          "One or more assigned QBank questions are not currently approved for student delivery",
          {
            assigned: roadmapQuestionIds.length,
            approved: selected.length,
            private_drafts_exposed: false,
          },
        );
      }
      const staleOrMediaIncomplete = selected.filter((question) =>
        ![2026, 2025, 2024].includes(Number(question.source_year))
        || question.media_integrity_verified !== true);
      if (staleOrMediaIncomplete.length) {
        return aylaSendError(
          res,
          409,
          "This assignment contains an older or media-incomplete question. Refresh the roadmap so it can select from the current verified pool.",
          {
            code: "QBANK_ASSIGNMENT_REFRESH_REQUIRED",
            affected_questions: staleOrMediaIncomplete.length,
            content_delivery_policy: contentDeliveryPolicySnapshot(),
          },
        );
      }
      selection = { selected, availableSystemKeys: [], selectedSystemKeys: [] };
    } else {
      selection = await aylaSelectQbankSessionQuestions({
        db: auth.db,
        examTrack: access.exam_track,
        requestedCount: effectiveRequestedCount,
        filters: effectiveFilters,
        purpose,
        sourceProfile,
        selectedBanks,
        destinationScope,
        selectionSeed: diagnosticSelectionSeed,
        questionExposureCounts: diagnosticQuestionExposureCounts,
        seenQuestionIds,
        allowedCollectionIds: nclexVariant ? selectedCollectionIds : [],
        examVariant: nclexVariant || "",
      });
    }
    const selected = selection.selected;
    if (!selected.length) return aylaSendError(res, 409, "No approved QBank questions match this exam track and filter selection");

    const questionMappings = selected.map((question) => {
      const bank = selectedBanks.find((row) => String(row.id) === String(question.collection_id));
      return {
        ref: crypto.randomUUID(),
        contentQuestionId: question.id,
        collectionId: bank?.id || question.collection_id || null,
        collectionKey: bank?.collection_key || null,
        bankName: bank?.name || null,
        sourceExamTrack: bank?.source_exam_track || question.source_exam_track || access.exam_track,
        supplemental: bank?.supplemental === true || question.supplemental === true,
        scoringAllowed: bank?.scoring_allowed !== false && question.scoring_allowed !== false,
        nclexVariant: nclexVariant || null,
      };
    });
    const mutation = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, access.exam_track);
      const freshNclexVariant = requireAylaNclexVariant(fresh.student, fresh.entitlement.exam_track);
      if (freshNclexVariant !== nclexVariant) {
        const error = new Error("The NCLEX program changed while this session was being prepared. Refresh before continuing.");
        error.statusCode = 409;
        error.code = "NCLEX_VARIANT_CHANGED";
        error.details = { code: error.code };
        throw error;
      }
      let legacyDiagnostics = [];
      if (purpose === "baseline_diagnostic") {
        const activeDiagnostics = aylaValues(db, "aylaQbankSessions").filter((row) =>
          String(row.userId || "") === String(fresh.user.id)
          && String(row.studentId || "") === String(fresh.student.id)
          && String(row.examTrack || "") === String(fresh.entitlement.exam_track)
          && String(row.purpose || "") === "baseline_diagnostic"
          && String(row.status || "") === "in_progress");
        const currentDiagnostic = activeDiagnostics.find((row) =>
          diagnosticSessionUsesCurrentBlueprint(row));
        if (currentDiagnostic) {
          return {
            session: currentDiagnostic,
            replayed: true,
            resumedExistingDiagnostic: true,
          };
        }
        const answeredLegacyDiagnostic = activeDiagnostics.find((row) =>
          Object.keys(row.answers && typeof row.answers === "object" ? row.answers : {}).length > 0);
        if (answeredLegacyDiagnostic) {
          const error = new Error(
            "An earlier diagnostic contains answers and requires review before it can be upgraded. No answer or baseline was changed.",
          );
          error.statusCode = 409;
          error.code = "ANSWERED_DIAGNOSTIC_REVIEW_REQUIRED";
          throw error;
        }
        legacyDiagnostics = activeDiagnostics;
      }
      if (idempotencyKey) {
        const existing = aylaValues(db, "aylaQbankSessions").find((row) =>
          String(row.userId || "") === String(auth.user.id)
          && String(row.studentId || "") === String(auth.student.id)
          && String(row.idempotencyKey || "") === idempotencyKey);
        if (existing) {
          if (String(existing.idempotencyFingerprint || "") !== idempotencyFingerprint) {
            const error = new Error("Idempotency key was already used for a different QBank session request");
            error.statusCode = 409;
            throw error;
          }
          if (purpose !== "baseline_diagnostic" || diagnosticSessionUsesCurrentBlueprint(existing)) {
            return { session: existing, replayed: true };
          }
          const answeredCount = Object.keys(
            existing.answers && typeof existing.answers === "object" ? existing.answers : {},
          ).length;
          if (answeredCount > 0) {
            const error = new Error(
              "An earlier diagnostic contains answers and requires review before it can be upgraded. No answer or baseline was changed.",
            );
            error.statusCode = 409;
            error.code = "ANSWERED_DIAGNOSTIC_REVIEW_REQUIRED";
            throw error;
          }
          const existingStatus = String(existing.status || "");
          if (!["in_progress", "abandoned"].includes(existingStatus)) {
            const error = new Error(
              "This idempotency key belongs to an earlier diagnostic version. Start the verified diagnostic with a new request.",
            );
            error.statusCode = 409;
            error.code = "LEGACY_DIAGNOSTIC_IDEMPOTENCY_KEY";
            throw error;
          }
          legacyDiagnostics = [...legacyDiagnostics, existing];
        }
      }
      if (roadmapAssignmentId) {
        const assignment = aylaGetItem(db, "aylaResourceAssignments", roadmapAssignmentId);
        if (!assignment || String(assignment.studentId || "") !== String(fresh.student.id)) {
          const error = new Error("Roadmap assignment not found");
          error.statusCode = 404;
          throw error;
        }
        if (!aylaQbankRoadmapAssignmentEligible(assignment)) {
          const error = new Error("Roadmap assignment is not a QBank question assignment");
          error.statusCode = 409;
          throw error;
        }
        const currentQuestionIds = qbankRoadmapAssignmentQuestionIds(assignment);
        if (JSON.stringify(currentQuestionIds) !== JSON.stringify(roadmapQuestionIds)) {
          const error = new Error("The roadmap QBank assignment changed before the session was created. Refresh the roadmap and try again.");
          error.statusCode = 409;
          throw error;
        }
      }
      const session = createAylaQbankSession({
        id: sessionId,
        userId: fresh.user.id,
        studentId: fresh.student.id,
        examTrack: fresh.entitlement.exam_track,
        mode: requestedMode,
        purpose,
        questions: questionMappings,
        filters: effectiveFilters,
        blockSize: requestedBlockSize,
        origin,
        roadmapAssignmentId,
        sourceProfile,
        selectedBanks,
        destinationScope,
        timeLimitMinutes: req.body.time_limit_minutes ?? req.body.timeLimitMinutes ?? null,
        entitlement: fresh.entitlement,
      });
      session.idempotencyKey = idempotencyKey || null;
      session.idempotencyFingerprint = idempotencyKey ? idempotencyFingerprint : null;
      session.nclexVariant = nclexVariant || null;
      session.nclex_variant = nclexVariant || null;
      session.requestedQuestionCount = effectiveRequestedCount;
      session.contentDeliveryPolicy = contentDeliveryPolicySnapshot();
      session.contentDeliverySelection = {
        sourceYearCounts: selected.reduce((counts, question) => {
          const year = String(Number(question.source_year || 0) || "unknown");
          counts[year] = Number(counts[year] || 0) + 1;
          return counts;
        }, {}),
        verifiedMediaQuestionCount: selected.filter((question) =>
          Number(question.required_media_count || 0) > 0).length,
        brokenMediaQuestionCount: selected.filter((question) =>
          question.media_integrity_verified === false).length,
        priorSeenPoolSize: seenQuestionIds.length,
      };
      if (purpose === "baseline_diagnostic") {
        session.diagnosticBlueprintVersion = selection.blueprintVersion;
        session.diagnosticSystemByQuestionId = selection.diagnosticSystemByQuestionId;
        session.diagnosticReplacementLineage = selection.diagnosticReplacementLineage;
        session.diagnosticTaxonomyByQuestionId = selection.diagnosticTaxonomyByQuestionId;
        session.diagnosticBlueprint = selection.diagnosticBlueprint || null;
        session.diagnosticQuality = selection.quality;
        session.diagnosticCoverage = {
          availableSystemCount: selection.availableSystemKeys.length,
          selectedSystemCount: selection.selectedSystemKeys.length,
          selectedSystemKeys: selection.selectedSystemKeys,
          taxonomy: selection.quality.taxonomyCoverage,
          sampledTaxonomyOnly: true,
          untestedTaxonomyIsUnknown: true,
        };
      }
      aylaSetItem(db, "aylaQbankSessions", session);
      if (purpose === "baseline_diagnostic") {
        const supersededAt = aylaNow();
        const uniqueLegacyDiagnostics = new Map(
          legacyDiagnostics
            .filter((row) => row?.id && String(row.id) !== String(session.id))
            .map((row) => [String(row.id), row]),
        );
        for (const legacy of uniqueLegacyDiagnostics.values()) {
          legacy.status = "abandoned";
          legacy.abandonedAt = legacy.abandonedAt || supersededAt;
          legacy.abandonReason = "diagnostic_blueprint_upgrade";
          legacy.supersededBySessionId = session.id;
          legacy.supersededIdempotencyKey = legacy.idempotencyKey || null;
          legacy.idempotencyKey = null;
          legacy.idempotencyFingerprint = null;
          legacy.updatedAt = supersededAt;
          aylaSetItem(db, "aylaQbankSessions", legacy);
          aylaQbankEvent(db, legacy, "diagnostic_session_superseded", {
            supersededBySessionId: session.id,
            reason: legacy.abandonReason,
            answeredQuestionCount: 0,
          });
        }
      }
      aylaQbankEvent(db, session, "session_created", {
        mode: session.mode,
        purpose: session.purpose,
        questionCount: session.questionCount,
        origin: session.origin,
        sourceProfile: session.sourceProfile || null,
        selectedCollectionIds: session.selectedBanks.map((row) => row.collectionId),
        diagnosticSelectionMode: session.diagnosticQuality?.selectionMode || null,
        diagnosticFreshQuestionCount: session.diagnosticQuality?.freshQuestionCount ?? null,
        diagnosticRepeatedQuestionCount: session.diagnosticQuality?.repeatedQuestionCount ?? null,
        contentDeliveryPolicyVersion: session.contentDeliveryPolicy.version,
        sourceYearCounts: session.contentDeliverySelection.sourceYearCounts,
        verifiedMediaQuestionCount: session.contentDeliverySelection.verifiedMediaQuestionCount,
        brokenMediaQuestionCount: session.contentDeliverySelection.brokenMediaQuestionCount,
      });
      aylaV189RecordActivity(db, session.studentId, "qbank_session_created", { sessionId: session.id, examTrack: session.examTrack, questionCount: session.questionCount, mode: session.mode, purpose: session.purpose });
      return { session, replayed: false };
    });
    const latestDb = await readAylaDb();
    assertAylaNclexSessionVariant(auth.student, mutation.session);
    const bundle = await aylaPlayableQbankSession(latestDb, mutation.session);
    return aylaSendOk(res, {
      ...bundle,
      requested_question_count: effectiveRequestedCount,
      selected_question_count: mutation.session.questionCount,
      partial_selection: mutation.session.questionCount < effectiveRequestedCount,
      idempotent_replay: mutation.replayed,
      resumed_existing_diagnostic: mutation.resumedExistingDiagnostic === true,
    }, mutation.replayed ? 200 : 201);
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details || null);
  }
});

app.get("/api/ayla/qbank/sessions/:sessionId", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.query.student_id || ""), "qbank");
    const session = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, session.examTrack);
    aylaRequireCurrentDiagnosticBlueprint(session);
    return aylaSendOk(res, await aylaPlayableQbankSession(auth.db, session));
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

app.post("/api/ayla/qbank/sessions/:sessionId/answers", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body.student_id || req.body.studentId || ""), "qbank");
    const session = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, session.examTrack);
    aylaRequireCurrentDiagnosticBlueprint(session);
    const questionRef = String(req.body.question_ref || req.body.questionRef || "").trim();
    const mapping = qbankSessionQuestion(session, questionRef);
    if (!mapping) return aylaSendError(res, 404, "Question does not belong to this QBank session");
    const [question] = await aylaSessionQbankQuestions(session, [mapping]);
    if (!question) return aylaSendError(res, 409, "This question is no longer approved for QBank delivery");
    const selectedAnswerId = Number(req.body.selected_answer_id ?? req.body.selectedAnswerId);
    if (!question.answers.some((row) => Number(row.answer_id) === selectedAnswerId)) return aylaSendError(res, 400, "selected_answer_id is not a valid answer choice");

    const mutateAnswer = session.purpose === "baseline_diagnostic" && session.mode === "test"
      ? mutateAylaDiagnosticAnswer
      : mutateAylaDb;
    const mutation = await mutateAnswer(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, session.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, session.id);
      aylaRequireCurrentDiagnosticBlueprint(current);
      const currentMapping = qbankSessionQuestion(current, questionRef);
      if (!currentMapping || String(currentMapping.contentQuestionId) !== String(mapping.contentQuestionId)) {
        const error = new Error("Question does not belong to this QBank session");
        error.statusCode = 404;
        throw error;
      }
      const recorded = recordAylaQbankAnswer(current, {
        questionRef,
        selectedAnswerId,
        correctAnswerId: question.correct_answer_id,
        elapsedMs: req.body.elapsed_ms ?? req.body.elapsedMs ?? null,
      });
      let adaptiveUpdate = null;
      if (!recorded.replayed) {
        aylaSetItem(db, "aylaQbankSessions", recorded.session);
        const immediate = recorded.session.mode === "tutor";
        const attemptResult = immediate ? aylaRecordQbankAttempt(db, recorded.session, currentMapping, recorded.answer, question) : null;
        const attempt = attemptResult?.attempt || null;
        const event = aylaQbankEvent(db, recorded.session, "answer_recorded", immediate
          ? { questionRef, correct: recorded.answer.correct, attemptId: attempt?.id || null }
          : { questionRef, resultWithheldUntilSubmit: true });
        if (immediate) {
          aylaV189RecordActivity(db, recorded.session.studentId, "qbank_question_answered", { sessionId: recorded.session.id, questionRef, correct: recorded.answer.correct, examTrack: recorded.session.examTrack });
          const weakAreas = currentMapping.scoringAllowed === false
            ? { count: 0 }
            : aylaV227RefreshWeakAreaProjection(db, fresh.student);
          adaptiveUpdate = {
            verified_attempts_created: attemptResult?.created ? 1 : 0,
            weak_area_flashcards_created: attemptResult?.flashcardCreated ? 1 : 0,
            weak_area_flashcards_linked: attemptResult?.flashcardResourceId ? 1 : 0,
            weak_areas_refreshed: weakAreas.count,
            future_roadmap_refresh: "on_session_submit",
            answer_keys_included: false,
          };
        }
        return {
          ...recorded,
          adaptiveUpdate,
          __diagnosticJournal: immediate ? null : {
            session: recorded.session,
            event,
          },
        };
      }
      return { ...recorded, adaptiveUpdate };
    });
    const latestDb = await readAylaDb();
    const current = aylaOwnedQbankSession(latestDb, auth.user, auth.student, session.id);
    const renderedQuestion = await aylaPlayableQbankQuestion(latestDb, current, mapping, question);
    return aylaSendOk(res, {
      session: sanitizeAylaQbankSession(current),
      question: renderedQuestion,
      idempotent_replay: mutation.replayed,
      adaptive_update: mutation.adaptiveUpdate || null,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

app.post("/api/ayla/qbank/sessions/:sessionId/submit", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body.student_id || req.body.studentId || ""), "qbank");
    const initial = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, initial.examTrack);
    aylaRequireCurrentDiagnosticBlueprint(initial);
    const rawReviewQuestions = await aylaSessionQbankQuestions(initial, initial.questions || []);
    const reviewQuestions = rawReviewQuestions.map((question) =>
      aylaDiagnosticQuestionForSession(initial, question));
    const reviewById = new Map(reviewQuestions.map((row) => [String(row.id), row]));
    const mutation = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, initial.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, initial.id);
      aylaRequireCurrentDiagnosticBlueprint(current);
      if (!canSubmitAylaQbankRoadmapSession(current)) {
        const error = new Error("Answer every assigned question before completing this roadmap QBank block");
        error.statusCode = 409;
        error.code = "ROADMAP_QBANK_INCOMPLETE";
        throw error;
      }
      const finalized = finalizeAylaQbankSession(current);
      let adaptiveUpdate = null;
      if (!finalized.replayed) {
        aylaSetItem(db, "aylaQbankSessions", finalized.session);
        const attemptResults = [];
        if (finalized.session.mode === "test") {
          for (const [questionRef, answer] of Object.entries(finalized.session.answers || {})) {
            const mapping = qbankSessionQuestion(finalized.session, questionRef);
            if (!mapping) continue;
            attemptResults.push(aylaRecordQbankAttempt(db, finalized.session, mapping, answer, reviewById.get(String(mapping.contentQuestionId)) || {}));
          }
        }
        if (finalized.session.origin === "roadmap" && finalized.session.roadmapAssignmentId) {
          const assignment = aylaGetItem(db, "aylaResourceAssignments", finalized.session.roadmapAssignmentId);
          const assignmentIsActive = assignment
            && !["completed", "cancelled", "canceled", "skipped", "superseded"].includes(String(assignment.status || "").toLowerCase());
          if (
            assignmentIsActive
            && String(assignment.studentId || "") === String(finalized.session.studentId)
            && aylaQbankRoadmapAssignmentEligible(assignment)
            && qbankRoadmapSessionMatchesAssignment(finalized.session, assignment)
          ) {
            assignment.status = "completed";
            assignment.progressPercent = 100;
            assignment.qbankSessionIds = [...new Set([...(Array.isArray(assignment.qbankSessionIds) ? assignment.qbankSessionIds : []), finalized.session.id])];
            assignment.completedAt = assignment.completedAt || finalized.session.submittedAt;
            assignment.updatedAt = finalized.session.submittedAt;
            aylaSetItem(db, "aylaResourceAssignments", assignment);
            if (assignment.dailyPlanId) aylaV189UpdatePlanCompletion(db, assignment.dailyPlanId);
          }
        }
        let verifiedBaseline = null;
        let baselineRecommendation = null;
        let referralMilestone = null;
        if (finalized.session.purpose === "baseline_diagnostic") {
          if (fresh.student.serverVerifiedBaseline === true && String(fresh.student.diagnosticSessionId || "") !== String(finalized.session.id)) {
            const error = new Error("A different verified starting diagnostic is already final");
            error.statusCode = 409;
            throw error;
          }
          const examTrackId = aylaCanonicalExamTrack(fresh.student.examTrackId || fresh.student.exam_track_id || fresh.student.exam);
          const examDefinition = examTrackId ? AYLA_EXAM_REGISTRY[examTrackId] : null;
          const baseline = buildAylaVerifiedDiagnosticBaseline({
            session: finalized.session,
            questions: reviewQuestions,
            examDefinition,
          });
          Object.assign(fresh.student, baseline);
          baselineRecommendation = aylaRecommendation(fresh.student);
          fresh.student.riskLevel = baselineRecommendation.riskLevel;
          fresh.student.roadmapMode = baselineRecommendation.roadmapMode;
          fresh.student.phase = baselineRecommendation.phase;
          fresh.student.phasePlan = aylaPhasePlan(fresh.student, baselineRecommendation);
          fresh.student.updatedAt = aylaNow();
          aylaSetItem(db, "aylaStudents", fresh.student);
          const completedDiagnosticAssignments = aylaV258CompleteDiagnosticAssignments(
            db,
            finalized.session,
          );
          verifiedBaseline = {
            score_percent: baseline.currentScore,
            weak_areas: baseline.weakAreas,
            systems_covered: baseline.diagnosticCoverage.systemsCovered,
            systems_expected: baseline.diagnosticCoverage.systemsExpected,
            mapped_question_count: baseline.diagnosticCoverage.mappedQuestionCount,
            diagnostic_assignments_completed: completedDiagnosticAssignments,
            server_verified: true,
          };
          aylaV189RecordActivity(db, finalized.session.studentId, "baseline_diagnostic_completed", {
            sessionId: finalized.session.id,
            examTrack: finalized.session.examTrack,
            scorePercent: baseline.currentScore,
            systemsCovered: baseline.diagnosticCoverage.systemsCovered,
            mappedQuestionCount: baseline.diagnosticCoverage.mappedQuestionCount,
          });
          referralMilestone = aylaRecordReferralMilestone(db, {
            referredUserId: fresh.user.id,
            referredStudentId: fresh.student.id,
            type: "verified_diagnostic_completed",
            serverVerified: true,
            source: "baseline_diagnostic_submit",
            occurredAt: finalized.session.submittedAt || aylaNow(),
          });
        }
        aylaQbankEvent(db, finalized.session, "session_submitted", {
          purpose: finalized.session.purpose || "practice",
          scorePercent: finalized.session.scorePercent,
          correctCount: finalized.session.correctCount,
          questionCount: finalized.session.questionCount,
        });
        aylaV189RecordActivity(db, finalized.session.studentId, "qbank_session_submitted", {
          sessionId: finalized.session.id,
          examTrack: finalized.session.examTrack,
          scorePercent: finalized.session.scorePercent,
          questionCount: finalized.session.questionCount,
          purpose: finalized.session.purpose || "practice",
        });
        const weakAreas = finalized.session.scoredQuestionCount > 0
          ? aylaV227RefreshWeakAreaProjection(db, fresh.student)
          : { count: 0 };
        let startingReadinessReport = null;
        let roadmapOutlineRefresh = null;
        if (baselineRecommendation) {
          roadmapOutlineRefresh = aylaV229StoreFutureRoadmapOutline(
            db,
            fresh.student,
            aylaBuildRoadmapTasks(fresh.student, baselineRecommendation),
            {
              fromDate: aylaDateOnly(),
              reason: "verified_baseline_diagnostic",
            },
          );
          const examTrackId = aylaCanonicalExamTrack(
            fresh.student.examTrackId || fresh.student.exam_track_id || fresh.student.exam,
          );
          startingReadinessReport = buildAylaStartingReadinessReport({
            student: fresh.student,
            recommendation: baselineRecommendation,
            roadmapTasks: roadmapOutlineRefresh.activeTasks,
            weakAreaLogs: aylaValues(db, "aylaWeakAreaLogs")
              .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, fresh.student)),
            examDefinition: examTrackId ? AYLA_EXAM_REGISTRY[examTrackId] : {},
          });
        }
        const tomorrow = aylaDateOnly(aylaAddDays(new Date(), 1));
        let futureRoadmap = { status: "deferred_safe_retry", date: tomorrow };
        try {
          const rebuilt = await aylaV189BuildDailyPlan(db, fresh.student, tomorrow, {
            force: true,
            includeAssessment: false,
            skipAi: true,
          });
          futureRoadmap = {
            status: rebuilt.completedHistoryProtected ? "completed_history_protected" : rebuilt.reused ? "reused" : "refreshed",
            date: tomorrow,
            plan_id: rebuilt.plan?.id || null,
            version: rebuilt.plan?.version || null,
          };
        } catch (error) {
          aylaV189RecordActivity(db, finalized.session.studentId, "qbank_future_roadmap_refresh_deferred", {
            sessionId: finalized.session.id,
            date: tomorrow,
            reason: "safe_retry_required",
          });
        }
        adaptiveUpdate = {
          verified_attempts_created: attemptResults.filter((row) => row.created).length,
          weak_area_flashcards_created: attemptResults.filter((row) => row.flashcardCreated).length,
          weak_area_flashcards_linked: Object.values(finalized.session.answers || {}).filter((answer) => answer?.correct === false).length,
          weak_areas_refreshed: weakAreas.count,
          shared_weak_topics: weakAreas.sharedUnderlyingTopics,
          future_roadmap: futureRoadmap,
          roadmap_outline: roadmapOutlineRefresh ? {
            generation_id: roadmapOutlineRefresh.generationId,
            generated_tasks: roadmapOutlineRefresh.generatedTasks.length,
            preserved_completed: roadmapOutlineRefresh.preservedCompleted,
            preserved_past: roadmapOutlineRefresh.preservedPast,
            superseded_future: roadmapOutlineRefresh.supersededFuture,
            completed_history_protected: true,
          } : null,
          verified_baseline: verifiedBaseline,
          starting_readiness_report: startingReadinessReport,
          referral_milestone: referralMilestone ? {
            recorded: referralMilestone.recorded,
            reason: referralMilestone.reason,
            rewards_created: referralMilestone.rewards_created,
          } : null,
          answer_keys_included: false,
        };
      }
      return { ...finalized, adaptiveUpdate };
    });
    const latestDb = await readAylaDb();
    const session = aylaOwnedQbankSession(latestDb, auth.user, auth.student, initial.id);
    return aylaSendOk(res, {
      ...(await aylaPlayableQbankSession(latestDb, session)),
      idempotent_replay: mutation.replayed,
      adaptive_update: mutation.adaptiveUpdate || null,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

app.get("/api/ayla/qbank/history", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.query.student_id || ""), "qbank");
    const access = aylaRequireQbankAccess(auth.db, auth.user, auth.student, req.query.exam_track || req.query.examTrack || "");
    const nclexVariant = requireAylaNclexVariant(auth.student, access.exam_track);
    const limit = Math.max(1, Math.min(200, Number(req.query.limit) || 50));
    const offset = Math.max(0, Number(req.query.offset) || 0);
    const rows = aylaValues(auth.db, "aylaQbankSessions")
      .filter((row) => String(row.userId || "") === String(auth.user.id) && String(row.studentId || "") === String(auth.student.id))
      .filter((row) => String(row.examTrack || "") === String(access.exam_track))
      .filter((row) => !nclexVariant || normalizeAylaNclexVariant(row.nclexVariant || row.nclex_variant) === nclexVariant)
      .sort((a, b) => String(b.submittedAt || b.updatedAt || b.createdAt || "").localeCompare(String(a.submittedAt || a.updatedAt || a.createdAt || "")));
    return aylaSendOk(res, {
      exam_track: access.exam_track,
      exam_variant: nclexVariant || null,
      total: rows.length,
      limit,
      offset,
      history: rows.slice(offset, offset + limit).map(qbankSessionHistoryRow),
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

async function aylaHandleQbankMark(req, res, marked) {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body?.student_id || req.body?.studentId || req.query.student_id || ""), "qbank");
    const initial = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, initial.examTrack);
    const questionRef = String(req.params.questionRef || "").trim();
    if (!qbankSessionQuestion(initial, questionRef)) return aylaSendError(res, 404, "Question does not belong to this QBank session");
    const session = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, initial.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, initial.id);
      const currentMapping = qbankSessionQuestion(current, questionRef);
      if (!currentMapping) throw Object.assign(new Error("Question does not belong to this QBank session"), { statusCode: 404 });
      const updated = setAylaQbankQuestionMark(current, questionRef, marked);
      aylaSetItem(db, "aylaQbankSessions", updated);
      if (marked) aylaUpsertQbankRevision(db, updated, currentMapping, {}, "marked_for_review");
      else aylaRemoveQbankRevisionReason(db, updated, currentMapping, "marked_for_review");
      aylaQbankEvent(db, updated, marked ? "question_marked" : "question_unmarked", { questionRef });
      return updated;
    });
    return aylaSendOk(res, { session: sanitizeAylaQbankSession(session), question_ref: questionRef, marked });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
}

app.put("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/mark", (req, res) => aylaHandleQbankMark(req, res, req.body?.marked !== false));
app.delete("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/mark", (req, res) => aylaHandleQbankMark(req, res, false));

async function aylaHandleQbankBookmark(req, res, bookmarked) {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body?.student_id || req.body?.studentId || req.query.student_id || ""), "qbank");
    const initial = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, initial.examTrack);
    const mapping = qbankSessionQuestion(initial, req.params.questionRef);
    if (!mapping) return aylaSendError(res, 404, "Question does not belong to this QBank session");
    const result = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, initial.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, initial.id);
      const currentMapping = qbankSessionQuestion(current, req.params.questionRef);
      if (!currentMapping || String(currentMapping.contentQuestionId) !== String(mapping.contentQuestionId)) {
        const error = new Error("Question does not belong to this QBank session");
        error.statusCode = 404;
        throw error;
      }
      const existing = aylaValues(db, "aylaQbankBookmarks")
        .filter((row) => String(row.studentId || "") === String(current.studentId))
        .filter((row) => String(row.examTrack || "") === String(current.examTrack))
        .find((row) => String(row.contentQuestionId || "") === String(currentMapping.contentQuestionId));
      const bookmark = {
        ...(existing || {}),
        id: existing?.id || aylaId("AYLA-QBB"),
        studentId: current.studentId,
        userId: current.userId,
        examTrack: current.examTrack,
        sessionId: current.id,
        questionRef: currentMapping.ref,
        contentQuestionId: currentMapping.contentQuestionId,
        deletedAt: bookmarked ? null : aylaNow(),
        createdAt: existing?.createdAt || aylaNow(),
        updatedAt: aylaNow(),
      };
      aylaSetItem(db, "aylaQbankBookmarks", bookmark);
      if (bookmarked) aylaUpsertQbankRevision(db, current, currentMapping, {}, "bookmarked");
      else aylaRemoveQbankRevisionReason(db, current, currentMapping, "bookmarked");
      aylaQbankEvent(db, current, bookmarked ? "question_bookmarked" : "question_unbookmarked", { questionRef: currentMapping.ref, bookmarkId: bookmark.id });
      return bookmark;
    });
    return aylaSendOk(res, { bookmark: { id: result.id, question_ref: result.questionRef, bookmarked: !result.deletedAt, updated_at: result.updatedAt } });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
}

app.put("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/bookmark", (req, res) => aylaHandleQbankBookmark(req, res, true));
app.delete("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/bookmark", (req, res) => aylaHandleQbankBookmark(req, res, false));

async function aylaHandleQbankNoteDelete(req, res) {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body?.student_id || req.body?.studentId || req.query.student_id || ""), "qbank");
    const initial = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, initial.examTrack);
    const mapping = qbankSessionQuestion(initial, req.params.questionRef);
    if (!mapping) return aylaSendError(res, 404, "Question does not belong to this QBank session");
    const note = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, initial.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, initial.id);
      const existing = aylaValues(db, "aylaQbankNotes")
        .filter((row) => String(row.studentId || "") === String(current.studentId) && String(row.examTrack || "") === String(current.examTrack))
        .find((row) => String(row.contentQuestionId || "") === String(mapping.contentQuestionId));
      if (!existing || existing.deletedAt) return null;
      existing.deletedAt = aylaNow();
      existing.updatedAt = existing.deletedAt;
      aylaSetItem(db, "aylaQbankNotes", existing);
      aylaQbankEvent(db, current, "question_note_deleted", { questionRef: mapping.ref, noteId: existing.id });
      return existing;
    });
    return aylaSendOk(res, { deleted: Boolean(note), note_id: note?.id || null });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
}

app.put("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/note", async (req, res) => {
  try {
    const text = String(req.body.note ?? req.body.text ?? "").replace(/\u0000/g, "").trim();
    if (!text) return aylaSendError(res, 400, "note text is required");
    if (text.length > 20000) return aylaSendError(res, 400, "note text cannot exceed 20,000 characters");
    const auth = await aylaV189RequireStudent(req, String(req.body.student_id || req.body.studentId || ""), "qbank");
    const initial = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, initial.examTrack);
    const mapping = qbankSessionQuestion(initial, req.params.questionRef);
    if (!mapping) return aylaSendError(res, 404, "Question does not belong to this QBank session");
    const note = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, initial.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, initial.id);
      const existing = aylaValues(db, "aylaQbankNotes")
        .filter((row) => String(row.studentId || "") === String(current.studentId) && String(row.examTrack || "") === String(current.examTrack))
        .find((row) => String(row.contentQuestionId || "") === String(mapping.contentQuestionId));
      const versions = Array.isArray(existing?.versions) ? [...existing.versions] : [];
      if (existing?.text && existing.text !== text) versions.push({ text: existing.text, savedAt: existing.updatedAt || existing.createdAt });
      const next = {
        ...(existing || {}),
        id: existing?.id || aylaId("AYLA-QBN"),
        studentId: current.studentId,
        userId: current.userId,
        examTrack: current.examTrack,
        sessionId: current.id,
        questionRef: mapping.ref,
        contentQuestionId: mapping.contentQuestionId,
        text,
        versions: versions.slice(-50),
        deletedAt: null,
        createdAt: existing?.createdAt || aylaNow(),
        updatedAt: aylaNow(),
      };
      aylaSetItem(db, "aylaQbankNotes", next);
      aylaQbankEvent(db, current, existing ? "question_note_updated" : "question_note_created", { questionRef: mapping.ref, noteId: next.id });
      return next;
    });
    return aylaSendOk(res, { note: { id: note.id, question_ref: note.questionRef, text: note.text, updated_at: note.updatedAt } });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

app.delete("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/note", aylaHandleQbankNoteDelete);

async function aylaHandleQbankRevision(req, res, enabled) {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body?.student_id || req.body?.studentId || req.query.student_id || ""), "qbank");
    const initial = aylaOwnedQbankSession(auth.db, auth.user, auth.student, req.params.sessionId);
    aylaRequireQbankAccess(auth.db, auth.user, auth.student, initial.examTrack);
    const mapping = qbankSessionQuestion(initial, req.params.questionRef);
    if (!mapping) return aylaSendError(res, 404, "Question does not belong to this QBank session");
    let question = null;
    if (enabled) [question] = await getContentQbankQuestions({
      questionIds: [mapping.contentQuestionId],
      examTrack: initial.examTrack,
      destination: "aylamed_qbank",
      destinationScope: initial.destinationScope || "",
      sourceProfile: initial.sourceProfile || "",
    });
    const revision = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, initial.examTrack);
      const current = aylaOwnedQbankSession(db, fresh.user, fresh.student, initial.id);
      const currentMapping = qbankSessionQuestion(current, req.params.questionRef);
      if (!currentMapping) {
        const error = new Error("Question does not belong to this QBank session");
        error.statusCode = 404;
        throw error;
      }
      if (enabled) {
        const item = aylaUpsertQbankRevision(db, current, currentMapping, question || {}, "student_added");
        aylaQbankEvent(db, current, "question_added_to_revision", { questionRef: currentMapping.ref, revisionId: item.id });
        return item;
      }
      const item = aylaValues(db, "aylaRevisionQueue")
        .filter((row) => String(row.studentId || "") === String(current.studentId) && String(row.examTrack || "") === String(current.examTrack))
        .filter((row) => String(row.sourceType || "") === "qbank_question")
        .find((row) => String(row.sourceId || row.contentQuestionId || "") === String(currentMapping.contentQuestionId));
      if (!item) return null;
      item.status = "removed";
      item.removedAt = aylaNow();
      item.updatedAt = item.removedAt;
      aylaSetItem(db, "aylaRevisionQueue", item);
      aylaQbankEvent(db, current, "question_removed_from_revision", { questionRef: currentMapping.ref, revisionId: item.id });
      return item;
    });
    return aylaSendOk(res, { revision: revision ? { id: revision.id, question_ref: revision.questionRef, in_revision: enabled, status: revision.status, updated_at: revision.updatedAt } : null });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
}

app.post("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/revision", (req, res) => aylaHandleQbankRevision(req, res, true));
app.delete("/api/ayla/qbank/sessions/:sessionId/questions/:questionRef/revision", (req, res) => aylaHandleQbankRevision(req, res, false));

async function aylaQbankSavedList(req, res, collection, responseKey) {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.query.student_id || ""), "qbank");
    const access = aylaRequireQbankAccess(auth.db, auth.user, auth.student, req.query.exam_track || req.query.examTrack || "");
    const nclexVariant = requireAylaNclexVariant(auth.student, access.exam_track);
    const limit = Math.max(1, Math.min(100, Number(req.query.limit) || 50));
    const rows = aylaValues(auth.db, collection)
      .filter((row) => String(row.userId || "") === String(auth.user.id) && String(row.studentId || "") === String(auth.student.id))
      .filter((row) => String(row.examTrack || "") === String(access.exam_track) && !row.deletedAt)
      .filter((row) => collection !== "aylaRevisionQueue" || (String(row.sourceType || "") === "qbank_question" && !["removed", "completed"].includes(String(row.status || "due").toLowerCase())))
      .filter((row) => {
        if (!nclexVariant) return true;
        const saved = aylaQbankSavedItemSession(auth.db, row);
        return normalizeAylaNclexVariant(saved.session.nclexVariant || saved.session.nclex_variant) === nclexVariant;
      })
      .sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
      .slice(0, limit);
    const content = await getContentQbankQuestions({
      questionIds: rows.map((row) => row.contentQuestionId || row.sourceId),
      examTrack: access.exam_track,
      destination: "aylamed_qbank",
      destinationScope: aylaStep1PilotDestinationScope(auth.student),
    });
    const byId = new Map(content.map((row) => [String(row.id), row]));
    const items = [];
    for (const row of rows) {
      const saved = aylaQbankSavedItemSession(auth.db, row);
      const reveal = canRevealAylaQbankAnswer(saved.session, saved.mapping.ref);
      const reasons = Array.isArray(row.reasons) ? row.reasons : [];
      const publicReasons = reveal ? reasons : reasons.filter((reason) => reason !== "incorrect_answer");
      if (collection === "aylaRevisionQueue" && !reveal && !publicReasons.length) continue;
      items.push({
        id: row.id,
        status: row.status || null,
        reasons: publicReasons,
        note: collection === "aylaQbankNotes" ? { text: row.text || "", updated_at: row.updatedAt || null } : null,
        created_at: row.createdAt || null,
        updated_at: row.updatedAt || null,
        question: await aylaPlayableQbankQuestion(auth.db, saved.session, saved.mapping, byId.get(String(row.contentQuestionId || row.sourceId)) || null),
      });
    }
    return aylaSendOk(res, { exam_track: access.exam_track, exam_variant: nclexVariant || null, count: items.length, [responseKey]: items });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
}

app.get("/api/ayla/qbank/bookmarks", (req, res) => aylaQbankSavedList(req, res, "aylaQbankBookmarks", "bookmarks"));
app.get("/api/ayla/qbank/notes", (req, res) => aylaQbankSavedList(req, res, "aylaQbankNotes", "notes"));
app.get("/api/ayla/qbank/revision", (req, res) => aylaQbankSavedList(req, res, "aylaRevisionQueue", "revision"));

function aylaOwnedCdmSession(db, user, student, sessionId) {
  const session = aylaGetItem(db, "aylaCdmSessions", String(sessionId || ""));
  if (!session
    || String(session.userId || "") !== String(user.id)
    || String(session.studentId || "") !== String(student.id)) {
    const error = new Error("CDM session not found");
    error.statusCode = 404;
    error.code = "CDM_SESSION_NOT_FOUND";
    throw error;
  }
  return session;
}

function aylaCdmEvent(db, session, action, metadata = {}) {
  const event = {
    id: aylaId("AYLA-CDME"),
    userId: session.userId,
    studentId: session.studentId,
    examTrack: session.examTrack,
    sessionId: session.id,
    caseId: session.caseId,
    action,
    metadata: metadata && typeof metadata === "object" ? metadata : {},
    createdAt: aylaNow(),
    updatedAt: aylaNow(),
  };
  aylaSetItem(db, "aylaCdmEvents", event);
  return event;
}

function aylaCdmLegacyNotice() {
  return {
    title: "Legacy clinical-decision practice",
    message: "Legacy clinical-decision practice — non-scoring and not part of the current MCCQE format.",
    current_mccqe_format: "230 multiple-choice questions",
    cdm_removed_from_current_exam: true,
    scoring: "student_self_review_only",
  };
}

const AYLA_CURRENT_MCCQE_CDM_ENABLED = false;

app.use("/api/ayla/cdm", (req, res) => aylaSendError(
  res,
  410,
  "Clinical Decision Making cases were removed from the current MCCQE format. Use the current MCCQE MCQ banks instead.",
  { current_mccqe_format: "230 multiple-choice questions", cdm_removed_from_current_exam: true },
));

async function aylaPlayableCdmSession(db, session) {
  const sourceCase = await getContentCdmCase({
    caseId: session.caseId,
    examTrack: session.examTrack,
    destination: "aylamed_cdm",
  });
  if (!sourceCase) {
    return {
      session: sanitizeAylaCdmSession(session),
      case: {
        case_id: session.caseId,
        title: session.caseTitle,
        unavailable: true,
        message: "This case is no longer approved for student delivery.",
        steps: [],
      },
      notice: aylaCdmLegacyNotice(),
    };
  }
  const mappingByQuestionId = new Map((session.steps || [])
    .map((row) => [String(row.contentQuestionId || ""), row]));
  const currentIndex = Math.max(0, Number(session.currentStepIndex || 0));
  const steps = [];
  for (const [index, rawStep] of sourceCase.steps.entries()) {
    const mapping = mappingByQuestionId.get(String(rawStep.id || ""));
    if (!mapping) continue;
    const response = session.responses?.[mapping.ref] || null;
    const review = session.reviews?.[mapping.ref] || null;
    const locked = index > currentIndex && !review;
    if (locked) {
      steps.push({
        step_ref: mapping.ref,
        position: index + 1,
        title: `Step ${index + 1}`,
        locked: true,
        response_locked: false,
        reviewed: false,
      });
      continue;
    }
    const playable = await ngRegistryQuestionWithPlayableMedia(rawStep);
    const revealKey = Boolean(response);
    const visibleMedia = (playable.media || []).filter((item) => {
      const placement = String(item.placement || "explanation");
      return placement === "question" || revealKey;
    });
    const visibleVideos = (playable.videos || []).filter((item) => {
      const placement = String(item.placement || "explanation");
      return placement === "question" || revealKey;
    });
    steps.push({
      step_ref: mapping.ref,
      content_question_id: mapping.contentQuestionId,
      position: index + 1,
      title: rawStep.title || `Step ${index + 1}`,
      question_html: rawStep.question_html,
      explanation_html: revealKey ? rawStep.explanation_html : null,
      max_responses: Number(rawStep.max_responses || mapping.maxResponses || 1),
      has_dangerous_acts_in_key: revealKey ? rawStep.has_dangerous_acts === true : null,
      response_locked: Boolean(response),
      reviewed: Boolean(review),
      response: response ? {
        responses: response.responses,
        response_count: response.responseCount,
        max_responses: response.maxResponses,
        over_limit: response.overLimit,
        confidence: response.confidence,
        locked_at: response.lockedAt,
      } : null,
      self_review: review ? {
        marks: review.marks,
        correct_count: review.correctCount,
        not_acceptable_count: review.notAcceptableCount,
        dangerous_act_count: review.dangerousActCount,
        needs_revision: review.needsRevision,
        note: review.note,
        reviewed_at: review.reviewedAt,
      } : null,
      taxonomy: rawStep.taxonomy || {},
      media: visibleMedia,
      videos: visibleVideos,
      locked: false,
    });
  }
  return {
    session: sanitizeAylaCdmSession(session),
    case: {
      case_id: sourceCase.case_id,
      title: sourceCase.title,
      case_number: sourceCase.case_number,
      step_count: sourceCase.step_count,
      source_label: sourceCase.source_label,
      interaction_format: sourceCase.interaction_format,
      scoring_mode: sourceCase.scoring_mode,
      legacy_exam_format: true,
      steps,
    },
    notice: aylaCdmLegacyNotice(),
  };
}

function aylaUpsertCdmRevision(db, session, sourceCase, mapping, response, review) {
  if (!review?.needsRevision) return null;
  const existing = aylaValues(db, "aylaRevisionQueue").find((row) =>
    String(row.studentId || "") === String(session.studentId)
    && String(row.sourceType || "") === "legacy_cdm_case"
    && String(row.sourceId || "") === String(session.caseId));
  const step = (sourceCase?.steps || []).find((row) => String(row.id) === String(mapping.contentQuestionId)) || {};
  const reasons = [
    ...(review.dangerousActCount > 0 ? ["dangerous_act_self_marked"] : []),
    ...(review.notAcceptableCount > 0 ? ["not_acceptable_response"] : []),
    ...(response.overLimit ? ["maximum_response_count_exceeded"] : []),
    ...(response.confidence === "not_sure" ? ["low_confidence"] : []),
  ];
  const item = {
    ...(existing || {}),
    id: existing?.id || aylaId("AYLA-REV"),
    userId: session.userId,
    studentId: session.studentId,
    examTrack: session.examTrack,
    sourceType: "legacy_cdm_case",
    sourceId: session.caseId,
    resourceId: session.caseId,
    sourceSessionId: session.id,
    sourceQuestionRef: mapping.ref,
    contentQuestionId: mapping.contentQuestionId,
    title: session.caseTitle,
    system: step.taxonomy?.system_key || "Clinical decision practice",
    subsystem: step.taxonomy?.subsystem_key || "",
    topic: step.taxonomy?.topic_key || "Clinical decision practice",
    reasons: [...new Set([...(existing?.reasons || []), ...reasons])],
    priority: review.dangerousActCount > 0 ? "Critical" : "High",
    status: "due",
    evidenceType: "student_self_reviewed_legacy_cdm_practice",
    serverVerifiedScore: false,
    dueDate: aylaDateOnly(aylaAddDays(new Date(), review.dangerousActCount > 0 ? 1 : 3)),
    createdAt: existing?.createdAt || aylaNow(),
    updatedAt: aylaNow(),
  };
  aylaSetItem(db, "aylaRevisionQueue", item);
  return item;
}

app.get("/api/ayla/cdm/catalog", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.query.student_id || ""), "qbank");
    const access = aylaRequireQbankAccess(
      auth.db,
      auth.user,
      auth.student,
      req.query.exam_track || req.query.examTrack || "",
    );
    if (access.exam_track !== "mccqe") {
      return aylaSendError(res, 409, "Legacy CDM practice is available only inside the MCCQE roadmap");
    }
    const cases = await listContentCdmCases({
      examTrack: access.exam_track,
      destination: "aylamed_cdm",
      systemKey: req.query.system_key || "",
      subsystemKey: req.query.subsystem_key || "",
      topicKey: req.query.topic_key || "",
      limit: req.query.limit,
      seed: `${auth.student.id}:${String(req.query.seed || aylaDateOnly())}`,
    });
    return aylaSendOk(res, {
      exam_track: access.exam_track,
      count: cases.length,
      step_count: cases.reduce((sum, row) => sum + Number(row.step_count || 0), 0),
      cases,
      notice: aylaCdmLegacyNotice(),
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details);
  }
});

app.post("/api/ayla/cdm/sessions", async (req, res) => {
  try {
    const auth = await aylaV189RequireStudent(req, String(req.body.student_id || req.body.studentId || ""), "qbank");
    const access = aylaRequireQbankAccess(
      auth.db,
      auth.user,
      auth.student,
      req.body.exam_track || req.body.examTrack || "",
    );
    if (access.exam_track !== "mccqe") {
      return aylaSendError(res, 409, "Legacy CDM practice is available only inside the MCCQE roadmap");
    }
    const roadmapAssignmentId = String(
      req.body.roadmap_assignment_id || req.body.roadmapAssignmentId || "",
    ).trim();
    let caseId = String(req.body.case_id || req.body.caseId || "").trim();
    let origin = "personal";
    if (roadmapAssignmentId) {
      const assignment = aylaGetItem(auth.db, "aylaResourceAssignments", roadmapAssignmentId);
      if (!assignment || String(assignment.studentId || "") !== String(auth.student.id)) {
        return aylaSendError(res, 404, "Roadmap CDM assignment not found");
      }
      if (!cdmRoadmapAssignmentEligible(assignment)) {
        return aylaSendError(res, 409, "Roadmap assignment is not a CDM case");
      }
      if (["completed", "cancelled", "canceled", "skipped", "superseded"].includes(
        String(assignment.status || "").toLowerCase(),
      )) {
        return aylaSendError(res, 409, "This roadmap CDM assignment is no longer active");
      }
      caseId = cdmRoadmapAssignmentCaseId(assignment);
      origin = "roadmap";
    }
    if (!caseId) return aylaSendError(res, 400, "case_id or roadmap_assignment_id is required");

    const active = aylaValues(auth.db, "aylaCdmSessions").find((row) =>
      String(row.userId || "") === String(auth.user.id)
      && String(row.studentId || "") === String(auth.student.id)
      && String(row.examTrack || "") === String(access.exam_track)
      && String(row.caseId || "") === caseId
      && String(row.roadmapAssignmentId || "") === roadmapAssignmentId
      && String(row.status || "") === "in_progress");
    if (active) {
      return aylaSendOk(res, {
        ...(await aylaPlayableCdmSession(auth.db, active)),
        idempotent_replay: true,
      });
    }

    const sourceCase = await getContentCdmCase({
      caseId,
      examTrack: access.exam_track,
      destination: "aylamed_cdm",
    });
    if (!sourceCase?.steps?.length) {
      return aylaSendError(res, 409, "This CDM case is not currently approved for student delivery");
    }
    const sessionId = aylaId("AYLA-CDM");
    const created = await mutateAylaDb(async (db) => {
      const fresh = aylaRevalidateQbankContext(db, auth.user.id, auth.student.id, access.exam_track);
      if (roadmapAssignmentId) {
        const assignment = aylaGetItem(db, "aylaResourceAssignments", roadmapAssignmentId);
        if (!assignment
          || String(assignment.studentId || "") !== String(fresh.student.id)
          || !cdmRoadmapAssignmentEligible(assignment)
          || cdmRoadmapAssignmentCaseId(assignment) !== caseId) {
          const error = new Error("The roadmap CDM assignment changed before the session was created");
          error.statusCode = 409;
          throw error;
        }
      }
      const session = createAylaCdmSession({
        id: sessionId,
        userId: fresh.user.id,
        studentId: fresh.student.id,
        examTrack: access.exam_track,
        caseId,
        caseTitle: sourceCase.title,
        origin,
        roadmapAssignmentId: roadmapAssignmentId || null,
        entitlement: fresh.entitlement,
        steps: sourceCase.steps.map((step) => ({
          ref: crypto.randomUUID(),
          contentQuestionId: step.id,
          maxResponses: step.max_responses,
        })),
      });
      aylaSetItem(db, "aylaCdmSessions", session);
      aylaCdmEvent(db, session, "session_created", {
        stepCount: session.stepCount,
        origin: session.origin,
      });
      aylaV189RecordActivity(db, session.studentId, "legacy_cdm_session_created", {
        sessionId: session.id,
        caseId: session.caseId,
        examTrack: session.examTrack,
        scoreGenerated: false,
      });
      return session;
    });
    const latestDb = await readAylaDb();
    return aylaSendOk(res, {
      ...(await aylaPlayableCdmSession(latestDb, created)),
      idempotent_replay: false,
    }, 201);
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message, error.details);
  }
});

