function ngAylaLooksLikeTimePreference(text = "") {
  const t = String(text || "").toLowerCase();
  return /(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday|\b\d{1,2}(:\d{2})?\s*(am|pm)\b|morning|evening|night|afternoon)/i.test(t);
}

function ngAylaNextDateForWeekday(weekdayIndex, base = new Date()) {
  const d = new Date(base);
  const current = d.getDay();
  let diff = (weekdayIndex + 7 - current) % 7;
  if (diff === 0) diff = 7;
  d.setDate(d.getDate() + diff);
  return d;
}

function ngAylaParsePreferredGoogleMeetTime(text = "") {
  const t = String(text || "").toLowerCase();
  const now = new Date();
  let date = new Date(now);
  if (/tomorrow/i.test(t)) date.setDate(date.getDate() + 1);
  const weekdays = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
  for (const [name, idx] of Object.entries(weekdays)) {
    if (t.includes(name)) { date = ngAylaNextDateForWeekday(idx, now); break; }
  }
  let hour = null;
  let minute = 0;
  const timeMatch = t.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/);
  if (timeMatch) {
    hour = Number(timeMatch[1]);
    minute = Number(timeMatch[2] || 0);
    const ap = timeMatch[3];
    if (ap === "pm" && hour < 12) hour += 12;
    if (ap === "am" && hour === 12) hour = 0;
    if (!ap && hour >= 1 && hour <= 7) hour += 12;
  } else if (/morning/i.test(t)) hour = 10;
  else if (/afternoon/i.test(t)) hour = 15;
  else if (/evening|night/i.test(t)) hour = 18;
  if (hour === null || hour < 0 || hour > 23) return null;
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  const hh = String(hour).padStart(2, "0");
  const mm = String(minute).padStart(2, "0");
  return { date: `${y}-${m}-${d}`, time: `${hh}:${mm}`, start_time: `${y}-${m}-${d}T${hh}:${mm}:00`, timezone: "America/New_York" };
}

function ngAylaCreateGoogleMeetAppointmentFromPreference(db = {}, lead = {}, preference = null, sourceText = "") {
  if (!db || !lead?.id || !preference) return null;
  const existing = ensureCrmArray(db, "appointments").find((item) => String(item.lead_id || "") === String(lead.id || "") && ["scheduled", "missing_link", "needs_link", "rescheduled"].includes(String(item.status || "").toLowerCase()));
  const payload = withTimestamps({
    ...(existing || {}),
    id: existing?.id || uuid(),
    brand_id: lead.brand_id || db.settings?.default_brand_id || null,
    title: "Google Meet Mentor Consultation",
    name: "Google Meet Mentor Consultation",
    lead_id: lead.id,
    student_name: ng41LeadName(lead),
    student_email: ng41LeadEmail(lead),
    student_phone: ng41LeadPhone(lead),
    phone: ng41LeadPhone(lead),
    email: ng41LeadEmail(lead),
    appointment_type: "google_meet_mentor_consultation",
    type: "google_meet_mentor_consultation",
    status: existing?.status || "missing_link",
    link_status: existing?.link_status || "missing_link",
    date: preference.date,
    time: preference.time,
    scheduled_date: preference.date,
    scheduled_time: preference.time,
    start_time: preference.start_time,
    timezone: preference.timezone || "America/New_York",
    timezone_str: preference.timezone || "America/New_York",
    reminder_minutes_before: 5,
    google_meet_requested: true,
    link_send_scheduled: false,
    google_meet_link_send_scheduled: false,
    conversation_summary: sourceText || "Student shared preferred time for Google Meet mentor consultation.",
    notes: sourceText || existing?.notes || "Preferred Google Meet time collected by Ayla.",
    next_action: "admin_paste_google_meet_link",
    source: "ayla_google_meet_booking_bridge",
  }, existing || {});
  if (existing) Object.assign(existing, payload); else ensureCrmArray(db, "appointments").push(payload);
  lead.next_action = "admin_paste_google_meet_link";
  lead.stage = "google_meet_time_collected";
  lead.lead_stage = "google_meet_time_collected";
  lead.google_meet_appointment_id = payload.id;
  lead.google_meet_time_collected_at = lead.google_meet_time_collected_at || nowIso();
  lead.google_meet_booking_state = "waiting_for_admin_link";
  lead.waiting_for_google_meet_link = true;
  lead.live_session_automation_paused_until_google_meet = true;
  lead.updated_at = nowIso();
  return payload;
}

function ngAylaHardSalesRouter({ db = {}, lead = {}, messages = [], channel = "whatsapp" } = {}) {
  const cleanMessages = safeArray(messages).filter((m) => ngMessageText(m));
  const latestInbound = ngLatestInbound(cleanMessages);
  const latestText = ngMessageText(latestInbound || "").trim();
  if (!latestText) return null;

  const historyText = ngAylaSalesHistoryText(cleanMessages);
  const sentText = ngAylaSalesOutboundHistoryText(cleanMessages);
  const lastOutboundText = ngAylaLastOutboundText(cleanMessages);
  const assets = ngAylaGetSalesAssets(db);
  const examInText = ngAylaMentionedStep(latestText);
  const examKnown = examInText || ngAylaMentionedStep(historyText) || lead.exam_type || lead.exam || lead.exam_track || "";
  const isSunday = ngAylaIsSundayInEST();

  // STOP must be handled before sales logic.
  if (/\b(stop|unsubscribe|do not message|don't message|dont message|remove me|wrong number|not interested)\b/i.test(latestText)) {
    lead.ai_suppressed = true;
    lead.suppressed = true;
    lead.stop_requested = true;
    lead.status = lead.status === "converted" ? lead.status : "suppressed";
    lead.updated_at = typeof ngNowIso === "function" ? ngNowIso() : new Date().toISOString();
    return {
      intent: "stop_suppression",
      reply: "Understood Doctor. I’ll stop messaging you now."
    };
  }

  const asksRecording = /(recording|recordings|recorded|replay|session video|class video|recording lecture|lecture recording|watch.*recording|recording.*link)/i.test(latestText);
  const asksUworld = /(uworld|u world|qbank|question bank|mcq|library|video library|lms|demo)/i.test(latestText);
  const asksSessionTime = /(what\s*time|when|schedule|live session|class time|session time|today|zoom|join link|session link|class link|live link)/i.test(latestText);
  const asksProgram = /(program|course|how it works|details|offer|features|what do you provide|what is included)/i.test(latestText);
  const asksRoadmap = ngAylaIsRoadmapQuestion(latestText);
  const asksResources = ngAylaIsResourcesQuestion(latestText);
  const asksInvite = /(invite me|add me|send.*session|send.*live|share.*session|share.*zoom|i want.*join|want to join|yes.*join|yes.*invite|join session|attend session)/i.test(latestText);
  const watchedRecording = /(watched|seen|checked|viewed).*recording|recording.*(good|fine|okay|ok|enough|watched|seen|checked)|i\s+am\s+fine\s+with\s+that/i.test(latestText);
  const cannotAttendLive = /(can't join|cannot join|cant join|no time|busy|missed|miss it|not available|recording only)/i.test(latestText);
  const worriedOrFailed = /(failed|fail|attempt|low score|nbme|weak|weakness|struggling|confused|lost|worried|scared|old graduate|gap|long gap|delayed|no confidence|don't know what to do|dont know what to do)/i.test(latestText);
  const directQuestion = ngAylaHasQuestionMarkOrQuestionWord(latestText);
  const genericClarification = ngAylaIsGenericClarification(latestText);
  const basicConversationRequest = ngAylaIsBasicConversationRequest(latestText);
  const shortNonInformational = ngAylaIsShortNonInformational(latestText);
  const shortInterest = /^(yes|yeah|yep|ok|okay|interested|sure|send|share|hmm+|great|great i will check out|i will check|i will check out|sounds good|fine|step\s*1|step\s*2|step1|step2|ck)$/i.test(latestText);
  const acknowledgementOnly = ngAylaIsAcknowledgementOnly(latestText) || /^(that's great|thats great)$/i.test(latestText);
  const asksPrice = ngAylaIsPriceQuestion(latestText);
  const directGoogleMeetRequest = ngAylaIsDirectGoogleMeetRequest(latestText);
  const previousOfferedGoogleMeet = ngAylaLastOutboundOfferedGoogleMeet(lastOutboundText);
  const activeGoogleMeetAppointment = ngAylaFindActiveGoogleMeetAppointment(db, lead);
  const leadWaitingForGoogleMeetTime = /google_meet_requested|google_meet_time_collected|admin_paste_google_meet_link|waiting_for_google_meet_link|missing_link|needs_link|google_meet_scheduled|schedule_google_meet|collect_new_google_meet_time/i.test(String([lead.stage, lead.lead_stage, lead.next_action, lead.google_meet_booking_state].join(" ")));
  const leadHasGoogleMeetStateLock = ngAylaLeadGoogleMeetState(lead, activeGoogleMeetAppointment);
  const positiveGoogleMeetContext = previousOfferedGoogleMeet && ngAylaIsPositiveShortReply(latestText);
  const timePreference = (leadWaitingForGoogleMeetTime || previousOfferedGoogleMeet || leadHasGoogleMeetStateLock) && ngAylaLooksLikeTimePreference(latestText)
    ? ngAylaParsePreferredGoogleMeetTime(latestText)
    : null;

  if (timePreference) {
    const appointment = ngAylaCreateGoogleMeetAppointmentFromPreference(db, lead, timePreference, latestText);
    ngAylaMarkGoogleMeetLockedLead(lead, appointment);
    return {
      intent: "google_meet_time_collected_missing_link",
      reply: `Great Doctor, I have noted your preferred Google Meet time for ${timePreference.date} at ${timePreference.time} EST.

Our team will confirm the Google Meet link shortly. You will receive the link at the meeting time.`
    };
  }

  if (leadHasGoogleMeetStateLock) {
    ngAylaMarkGoogleMeetLockedLead(lead, activeGoogleMeetAppointment);
    const lockedReply = ngAylaGoogleMeetLockedReply({ latestText, lead, appointment: activeGoogleMeetAppointment, assets });
    if (lockedReply?.reply) return lockedReply;
    // v106: Google Meet state must not make Ayla dumb/silent. If the student asks a real question
    // about recordings, UWorld, roadmap, program, resources, live classes, etc., let OpenAI answer it.
    if (basicConversationRequest || asksRecording || asksUworld || asksRoadmap || asksResources || asksProgram || asksSessionTime || directQuestion) return null;
    return {
      intent: "google_meet_state_hold_no_sales_restart",
      reply: `Yes Doctor, I’m here. Your Google Meet is already noted, and you can ask me anything before the session. How can I help you?`
    };
  }

  // v106: Acknowledgements like "that's great" should not restart the same canned sales message.
  // Move naturally to one next question unless the student asked for Google Meet/price/etc.
  if (acknowledgementOnly && !directGoogleMeetRequest && !positiveGoogleMeetContext && !leadHasGoogleMeetStateLock) {
    const alreadySharedUworld = ngAylaHasSentAsset(sentText, ["uworld video library", "150 hours", "3000+", "try demo", "lms.nextgen"]);
    const alreadySharedRecording = ngAylaHasSentAsset(sentText, ["recording", "recordings", assets.recordingLink]);
    const alreadySharedLive = ngAylaHasSentAsset(sentText, ["live session", "1 pm est", "1:00 pm est"]);
    if (alreadySharedUworld || alreadySharedRecording || alreadySharedLive) {
      return {
        intent: "acknowledgement_continue_conversation",
        reply: `Great Doctor. To guide you properly, what is your exam timeline and your biggest difficulty right now — UWorld, First Aid retention, NBME score, or scheduling?`
      };
    }
  }

  if (asksPrice) {
    ngAylaCreateGoogleMeetRequest(db, lead, "pricing_interest", latestText);
    return {
      intent: "pricing_question_google_meet_handoff",
      reply: ngAylaPricingReply(assets.timezone || "EST")
    };
  }

  if (directGoogleMeetRequest || positiveGoogleMeetContext) {
    ngAylaCreateGoogleMeetRequest(db, lead, "google_meet_requested", latestText);
    return {
      intent: "google_meet_requested",
      reply: ngAylaGoogleMeetBookingReply(assets.timezone || "EST")
    };
  }

  if (asksRoadmap) {
    return {
      intent: "roadmap_requested",
      reply: ngAylaRoadmapReply(assets)
    };
  }

  if (asksResources) {
    return {
      intent: "resources_requested",
      reply: ngAylaResourcesReply(assets)
    };
  }

  // v57: Basic conversation must be answered by real AI before any sales checklist.
  // This prevents canned Google Meet/live-session text from overriding questions like tutors, roadmap, curriculum, recordings, etc.
  if (basicConversationRequest && !shortNonInformational && !asksPrice && !directGoogleMeetRequest && !positiveGoogleMeetContext && !timePreference) {
    return null;
  }

  // Direct student questions and confusion override the sales sequence.
  if (genericClarification && !asksUworld && !asksRecording && !asksSessionTime && !asksProgram) {
    return ngAylaClarifyPreviousMessageReply({ latestText, lastOutboundText, assets });
  }

  if (/prompt/i.test(latestText)) {
    return {
      intent: "confusion_repair",
      reply: `Sorry Doctor, let me clarify properly.

I’m not talking about a prompt. I’m here to guide you about our live sessions, recent recordings, and UWorld Video Library demo.

Are you preparing for Step 1 or Step 2?`
    };
  }

  if (worriedOrFailed) {
    return {
      intent: "failed_or_worried_reassurance",
      reply: ngAylaFailedOrWorriedReply(assets)
    };
  }

  if (watchedRecording) {
    return {
      intent: "mentor_after_recording_watched",
      reply: `Great Doctor. Since you have checked the recording, the next best step is a one-on-one Google Meet mentor consultation.

The mentor can review your exam timeline, weak areas, and preparation plan properly.`
    };
  }

  if (asksInvite) {
    const linkLine = assets.liveSessionLink ? `\n\nLive session link:\n${assets.liveSessionLink}` : "";
    const recLine = assets.recordingLink && !ngAylaHasSentAsset(sentText, [assets.recordingLink])
      ? `\n\nAlso, check ${ngAylaRecordingTitle(assets)} before the live session:\n${assets.recordingLink}`
      : "";
    return {
      intent: "explicit_live_session_invite",
      reply: `Perfect Doctor. I’ll make sure you receive the ${assets.sessionTime} live-session reminder 5 minutes before, and the link at session time.${linkLine}${recLine}`
    };
  }

  if (cannotAttendLive) {
    const rec = assets.recordingLink ? `\n\nRecording:\n${assets.recordingLink}` : "";
    return {
      intent: "cannot_attend_send_recording",
      reply: `No problem Doctor. If live timing is difficult, you can still catch up through our recordings.${rec}

${ngAylaPostRecordingInterestQuestion(assets)}`
    };
  }

  if (!examKnown && /^(hi|hello|hey|salam|assalam|details)$/i.test(latestText)) {
    return {
      intent: "welcome_ask_exam",
      reply: `Hi Doctor, how are you doing? Welcome to Next Generation USMLE.

Are you preparing for Step 1 or Step 2?`
    };
  }

  if (examInText && !ngAylaHasSentAsset(sentText, ["live session", "1 pm est", "1:00 pm est"])) {
    return {
      intent: "exam_known_invite_live",
      reply: `Great Doctor. For ${examInText}, we have live USMLE guidance sessions ${assets.sessionDays} at ${assets.sessionTime}.

You can join even for 5-10 minutes to see the teaching style. I’ll remind you 5 minutes before and share the link at session time.`
    };
  }

  if (asksSessionTime) {
    const linkLine = assets.liveSessionLink ? `\n\nLive session link:\n${assets.liveSessionLink}` : "";
    return {
      intent: "session_time_or_link",
      reply: `Doctor, our live session runs ${assets.sessionDays} at ${assets.sessionTime}.

You can join even for 5-10 minutes to see how the teaching works.${linkLine}`
    };
  }

  if (asksRecording) {
    const linkLine = assets.recordingLink ? `\n\nRecording:\n${assets.recordingLink}` : "\n\nI’ll share the latest available recording link with you.";
    return {
      intent: "recording_requested",
      reply: `Yes Doctor, we have recordings so you can check the teaching quality before joining.${linkLine}

${ngAylaPostRecordingInterestQuestion(assets)}`
    };
  }

  if (asksUworld) {
    return {
      intent: "uworld_requested",
      reply: ngAylaUworldDemoExplanation(assets, "Yes Doctor, our UWorld Video Library is one of our strongest features.")
    };
  }

  if (asksProgram) {
    return {
      intent: "program_requested_roadmap_resources_soft",
      reply: ngAylaProgramWithRoadmapResourcesReply(assets)
    };
  }

  // If the student is asking a real question that is not covered above, let OpenAI answer intelligently.
  // Do NOT force the sales checklist over an unknown question.
  if (directQuestion && !shortInterest) {
    return null;
  }

  // Proactive persuasion: only when the student is not asking a clarification/question.
  if (shortInterest || examKnown) {
    if (isSunday && !ngAylaHasSentAsset(sentText, ["recording", "recordings"])) {
      const rec = assets.recordingLink ? `\n\nRecording:\n${assets.recordingLink}` : "";
      return {
        intent: "sunday_recording_first",
        reply: `Doctor, since we do not push a Sunday live-session invite, I’m sharing ${ngAylaRecordingTitle(assets)} so you can check the teaching quality first.${rec}

After that, you can join the next ${assets.sessionDays} ${assets.sessionTime} live session.`
      };
    }

    if (!ngAylaHasSentAsset(sentText, ["live session", "1 pm est", "1:00 pm est"])) {
      return {
        intent: "proactive_live_invite",
        reply: `Doctor, we have live USMLE guidance sessions ${assets.sessionDays} at ${assets.sessionTime}.

Join even for 5-10 minutes to see the teaching style. I’ll remind you 5 minutes before and share the link at session time.`
      };
    }

    if (!ngAylaHasSentAsset(sentText, ["recording", "recordings"])) {
      const rec = assets.recordingLink ? `\n\nRecording:\n${assets.recordingLink}` : "";
      return {
        intent: "proactive_recording",
        reply: `Doctor, I’m also sharing ${ngAylaRecordingTitle(assets)} so you can check the teaching quality yourself.${rec}

${ngAylaPostRecordingInterestQuestion(assets)}`
      };
    }

    if (!ngAylaHasSentAsset(sentText, ["uworld video library", "150 hours", "3000+", "try demo", "lms.nextgen"])) {
      return {
        intent: "proactive_uworld_demo",
        reply: ngAylaUworldDemoExplanation(assets, "Doctor, we also have a UWorld Video Library demo.")
      };
    }

    if (assets.youtubeLink && !ngAylaHasSentAsset(sentText, ["youtube", assets.youtubeLink])) {
      return {
        intent: "proactive_youtube_lectures",
        reply: `${assets.companyProofLine}

You can also check our YouTube lectures/channel here:\n${assets.youtubeLink}`
      };
    }

    return {
      intent: "google_meet_after_assets_interest_check",
      reply: `Doctor, after you check the session, recording, or UWorld demo, I can arrange a Google Meet mentor consultation for one-on-one guidance.

Are you interested in live sessions or Google Meet mentor guidance?`
    };
  }

  return null;
}



function ngAylaNormalizeReplyForRepeat(text = "") {
  return String(text || "").toLowerCase().replace(/https?:\/\/\S+/g, "[link]").replace(/\s+/g, " ").trim();
}

function ngAylaIsRepeatOfRecentOutbound(reply = "", messages = []) {
  const cleanReply = ngAylaNormalizeReplyForRepeat(reply);
  if (!cleanReply) return false;
  const outbound = safeArray(messages).filter((m) => ngIsOutboundMessage(m)).slice(-4);
  return outbound.some((m) => ngAylaNormalizeReplyForRepeat(ngMessageText(m)) === cleanReply);
}

function ngAylaAutoReplyDelayMs(db = {}) {
  const s = db ? ngAylaPickSettings(db) : {};
  const fixed = Number(s.ai_auto_reply_delay_seconds ?? 4);
  const min = Number(s.ai_auto_reply_delay_min_seconds ?? 3);
  const max = Number(s.ai_auto_reply_delay_max_seconds ?? 5);
  const lo = Number.isFinite(min) ? Math.max(0, min) : 3;
  const hi = Number.isFinite(max) ? Math.max(lo, max) : 5;
  const seconds = Number.isFinite(fixed) ? Math.max(lo, Math.min(hi, fixed)) : (lo + Math.random() * Math.max(0, hi - lo));
  return Math.round(seconds * 1000);
}

function ngAylaSleep(ms = 0) {
  return new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}

async function ngAylaWaitBeforeAutoSend(db = {}) {
  const ms = ngAylaAutoReplyDelayMs(db);
  if (ms > 0) await ngAylaSleep(ms);
  return ms;
}

function ngAylaShouldBypassHardSalesRouterForNaturalConversation({ latestInboundText = "", messages = [] } = {}) {
  const text = String(latestInboundText || "").trim();
  const lower = text.toLowerCase();
  if (!lower) return false;

  // Keep deterministic safety/booking guards for these.
  if (/(stop|unsubscribe|do not message|don't message|dont message|remove me|wrong number|not interested)/i.test(text)) return false;
  if (/(price|cost|fee|fees|package|payment|discount|charges|how much)/i.test(text)) return false;
  if (/(google\s*meet|meet|call|book|schedule|connect me|talk to mentor|speak to mentor)/i.test(text)) return false;

  // v96: real student questions must go to OpenAI, not canned router lines.
  // This includes program explanation, roadmap, UWorld, resources, tutors, demo, LMS, recordings, live class, etc.
  if (/[?؟]/.test(text)) return true;
  if (/(program|course|details|detail|included|include|how it works|roadmap|study plan|curriculum|schedule|resources|resource|uworld|u world|qbank|mcq|library|demo|lms|recording|recordings|video|lecture|live session|class|teacher|tutor|mentor|dr\.?\s*ahmad|first aid|pathoma|assessment|nbme|marathon|120)/i.test(text)) return true;

  // v107: acknowledgements like "that's great" were being treated as a sales trigger and Ayla repeated the same offer.
  // Let OpenAI read the previous message and continue naturally instead of using the hard router.
  if (/^(that'?s great|thats great|great|ok|okay|sounds good|perfect|nice|yes|yep|sure|alright|fine)$/i.test(text) && safeArray(messages).length > 1) return true;

  // If the student writes more than a very short acknowledgement, let Ayla reason naturally.
  const words = lower.split(/\s+/).filter(Boolean);
  if (words.length >= 4) return true;

  return false;
}

async function ngGenerateStudentAutoReply({ db = null, lead, messages, channel }) {
  const cleanMessages = safeArray(messages)
    .filter((m) => ngMessageText(m))
    .slice(-12);

  const history = cleanMessages
    .map((m) => `${ngIsOutboundMessage(m) ? "NextGen/Ayla" : "Student"}: ${ngMessageText(m)}`)
    .join("\n");

  const latestInboundForRouting = ngLatestInbound(cleanMessages);
  const latestInboundTextForRouting = ngMessageText(latestInboundForRouting || {});
  const bypassHardRouter = ngAylaShouldBypassHardSalesRouterForNaturalConversation({
    latestInboundText: latestInboundTextForRouting,
    messages: cleanMessages,
  });

  const hardSalesReply = (!bypassHardRouter && db)
    ? ngAylaHardSalesRouter({ db, lead, messages: cleanMessages, channel })
    : null;

  if (hardSalesReply?.reply) {
    const hardReplyText = ngAylaApplyGreetingOnce(ngCleanAylaStudentReply(hardSalesReply.reply), cleanMessages);
    if (!ngAylaIsRepeatOfRecentOutbound(hardReplyText, cleanMessages)) {
      return {
        reply: hardReplyText,
        usage: {},
        model: "nextgen-v58-safe-session-override-cors-fix",
        hard_router: true,
        intent: hardSalesReply.intent || "sales_asset_push",
      };
    }
  }

  if (!isAIConfigured()) {
    // v103: Ayla should not go completely silent if OpenAI is temporarily missing/misconfigured.
    // Use the safe local counselor fallback so inbound students still receive a useful reply.
    const fallback = ngGenerateFallbackReply({ db, lead, messages: cleanMessages, mode: "reply" });
    return {
      reply: ngAylaApplyGreetingOnce(ngCleanAylaStudentReply(fallback.reply || "Doctor, thanks for your message. Are you preparing for Step 1, and when is your exam planned?"), cleanMessages),
      usage: {},
      model: "nextgen-ayla-local-fallback-no-openai",
      fallback: true,
      code: "AI_NOT_CONFIGURED",
      intent: fallback.intent || "fallback_guidance",
    };
  }

  const latestInbound = ngLatestInbound(cleanMessages);
  const latestInboundText = ngMessageText(latestInbound || {});
  const trainingContext = db ? ngTrainingContextForFullAiAuto(db) : "";
  const commandContext = db ? ngBuildAylaCommandContext(db, lead) : "";

  const backendSalesBrain = db ? ngBuildAylaBackendSalesBrain(db, lead, latestInboundText, history) : "";
  const latestSignals = ngAylaLatestMessageSignals(latestInboundText, history);

  const systemPrompt = `You are Ayla, the NextGen USMLE Full AI Auto assistant replying to a medical student lead.

Backend-enforced identity:
- You are a warm, professional NextGen USMLE admissions counselor and sales closer.
- You are not a generic support bot, not a passive FAQ bot, and not a WhatsApp template sender.
- Templates only open/reopen WhatsApp conversations. Once the student replies, you speak freely, naturally, and intelligently.
- Never repeat the approved first-message template after the student has replied. Do not answer normal program questions with canned template text. Use the conversation history and explain like a human counselor.

Non-negotiable reply style:
- Keep replies short and readable by default. For UWorld/library/program explanations, use 3-5 short WhatsApp-style lines if needed.
- Open warmly only once at the start of a new conversation. Do not start every reply with "Hi Doctor". After the first greeting, use "Doctor," / "Yes Doctor," / "Sure Doctor," or answer directly.
- Never say "prompt response", "I appreciate your prompt response", or talk like you are responding to a prompt. Say "Thank you, Doctor" or continue naturally.
- The student’s latest message must be answered first. If they ask “what is this/that,” explain the previous Ayla message before continuing the sales flow. If they ask about tutors, roadmap, live sessions, recordings, UWorld, schedule, curriculum, or any normal program detail, answer that exact question first in plain human language.
- Sound confident, persuasive, doctor-to-doctor, and human.
- Do not write robotic paragraphs. Do not use markdown headings. Explain clearly when the student asks.
- Do not end with weak generic filler like "feel free to ask" unless it is paired with a strong next step.

Sales behavior:
- After answering the student’s latest message, continue the conversation naturally. There is no 2-message or 3-message limit; every new student inbound deserves a fresh contextual reply if no outbound exists after it.
- Use broad reasoning for any weak area or system the student mentions; do not hard-code only MSK or only Cardiology. Adapt to the system named by the student.
- After answering the student’s question, move the lead forward naturally: build trust, share/offer session recording, explain the UWorld Video Library, invite to live session, ask exam date/weak area, or offer Google Meet mentor consultation at the right time.
- Session recordings are still an important proof asset. Do not suppress recording links. If a recording is useful for trust or the student asks about recordings, share it; just keep listening and continue the next turn when the student replies.
- Never ignore the student’s direct question or instruction. Do not repeat a previous offer when the student asked something else. Answer first, then convert naturally.
- If the student asks price/cost/package/payment, do NOT give numbers. Move them to Google Meet mentor guidance for program/pricing guidance.
- If the student is weak, failed, old graduate, delayed, confused, or struggling, reassure first: tell them they are in the right place, explain roadmap/mentor feedback/weak-area correction, then guide to recording/demo/live session.
- If the student says yes/ok/interested, send the next useful asset unless they asked a question. Do not jump to Google Meet time before value is shown.
- Always use EST for scheduling unless the student asks for another timezone.

Conversation intelligence:
- If lead is already in Google Meet requested/time collected/waiting for link/scheduled state, do not offer live sessions, recordings, UWorld demo, or Google Meet again. Acknowledge short replies and keep the lead waiting for the meeting/link.
- If the student says thank you/thanks/ok/noted/great/perfect after Google Meet time is collected, reply only: “You’re welcome Doctor. We’ll share the Google Meet link at the meeting time.”
- Do not ask for exam type again if already known.
- Do not ask for exam date again if already known.
- Do not ask for weak area again if already known.
- If something is missing, ask only one clear question.
- If enough is known, move to recording/live session/UWorld demo first, then Google Meet mentor consultation after value is shown or if directly requested.
- Roadmap knowledge: if the student asks roadmap/study plan/curriculum, summarize: structured 120-day system-wise roadmap starting with Cardiology first and continuing through Psychiatry in this order: Cardiology, MSK, Central Nervous System, Reproductive, Endocrinology, GIT, Renal, Pulmonology, Immunology, Hematology, Psychiatry. Explain that each lecture connects First Aid topic + mapped UWorld QIDs from LMS + live teaching + matching recording + homework/tasks + notes/recordings + assessment/revision. Do not say MSK first. Do not explain each day unless asked.
- Resources knowledge: if the student asks resources, say we use First Aid, UWorld-style QBank/MCQ discussion, Pathoma concepts, and NextGen assessments, connected with MCQ-solving, weak-area review, and exam strategy.
- Softly mention roadmap/resources in general program explanation even when not asked, but keep it short.
- Mention the UWorld Video Library naturally when it helps sell value: around 150 hours, 3000+ MCQs, First Aid integrated with every MCQ, MCQ approach, option elimination, concept connection, and weak-area correction. Explain Try Demo: 2 days free access and first lecture of every chapter.
- Share the UWorld library link only as the UWorld Video Library/resource, not as a random website link.

Hard safety/compliance:
- Stop automation only for clear opt-out/not interested/wrong number/unsubscribe/do not message.
- Do not guarantee scores, passing, residency, licensing, visas, or exam success.
- Do not claim official affiliation with USMLE, NBME, UWorld, First Aid, Pathoma, or Sketchy.

${backendSalesBrain}

Enforced AI Control Center behavior rules and proof policy:
${commandContext || "No AI Control Center command rules found."}

Enforced training context from AI Training Center:
${trainingContext || "No extra training context found."}`;

  const userPrompt = `Lead JSON:
${JSON.stringify(lead || {}).slice(0, 2500)}

Detected latest-message signals:
${JSON.stringify(latestSignals)}

Channel: ${channel}

Conversation:
${history || "No previous conversation available."}

Latest student message:
${latestInboundText || "No latest inbound message text found."}

Write only Ayla's next message. No markdown headings. No bullet list unless the student asks for details.`;

  const result = await callOpenAIResponsesAPI({
    model: process.env.AI_MODEL || "gpt-4o-mini",
    systemPrompt,
    userPrompt,
    maxOutputTokens: 180,
    jsonMode: false,
  });

  const reply = ngAylaApplyGreetingOnce(ngCleanAylaStudentReply(result.text || ""), cleanMessages);

  if (!reply) {
    const error = new Error("AI_EMPTY_REPLY: OpenAI returned an empty reply.");
    error.statusCode = 502;
    error.code = "AI_EMPTY_REPLY";
    throw error;
  }

  return {
    reply,
    usage: result.usage || {},
    model: result.model || process.env.AI_MODEL || "gpt-4o-mini",
  };
}

app.post("/admin/crm/conversations/:leadId/ai-auto-send", async (req, res) => {
  let aiAutoLockKey = null;

  try {
    const { user } = await requireCrmAdmin(req);
    const db = await readCrmDb();
    const lead = getLeadByAnyId(db, req.params.leadId);

    if (!lead) {
      return res.status(404).json({ success: false, error: "Lead not found" });
    }

    ngNormalizeLeadAiMode(lead);

    const messages = ngLeadConversationMessages(db, lead.id);
    const latestInbound = ngLatestInbound(messages);

    if (!latestInbound) {
      const firstMessageResult = await ngSendAutoFirstMessageForLead({
        db,
        lead,
        brandId: lead.brand_id || getCrmBrandId(req, db),
        actorId: user.id,
        source: "full_ai_auto_first_message_no_inbound",
      });

      await writeCrmDb(db);

      if (firstMessageResult.sent || firstMessageResult.skipped) {
        return res.status(firstMessageResult.success ? 200 : 502).json({
          success: Boolean(firstMessageResult.success),
          sent: Boolean(firstMessageResult.sent),
          skipped: Boolean(firstMessageResult.skipped),
          first_message: true,
          reason: firstMessageResult.reason || null,
          message: firstMessageResult.sent
            ? "First approved WhatsApp template sent. AI Auto will continue after the student replies."
            : "First message was not sent because it was skipped by safety checks.",
          result: firstMessageResult,
          log: firstMessageResult.log || null,
          error: firstMessageResult.error || null,
        });
      }

      return res.status(400).json({
        success: false,
        error: firstMessageResult.error || "No inbound student message found for AI Auto",
        first_message: true,
        result: firstMessageResult,
      });
    }

    const channel = resolveCrmChannelForConversation({
      requestedChannel:
        req.body?.channel ||
        req.body?.requested_channel ||
        lead.current_channel ||
        lead.last_channel ||
        lead.source_platform ||
        lead.platform ||
        "auto",
      lead,
      latestInbound,
      fallback: "whatsapp",
    });

    const forceSend = req.body?.force === true || req.body?.bypass_cooldown === true || req.query?.force === "true";

    if (!forceSend && ngHasOutboundAfterInbound(messages, latestInbound)) {
      return res.json({
        success: true,
        sent: false,
        skipped: true,
        reason: "already_replied_after_latest_inbound",
        message: "Ayla skipped because an outbound reply already exists after the latest student message.",
      });
    }

    const duplicateGuard = forceSend
      ? (() => {
          const lock = ngTryLockAiAuto({ lead, inbound: latestInbound, channel, ttlSeconds: 8 });
          return lock.locked ? { skip: false, lock_key: lock.key } : { skip: true, reason: lock.reason, wait_ms: lock.wait_ms || 0 };
        })()
      : ngShouldSkipAiAutoForInbound(lead, latestInbound, { channel });

    if (duplicateGuard.skip) {
      await writeCrmDb(db);
      return res.json({
        success: true,
        sent: false,
        skipped: true,
        reason: duplicateGuard.reason,
        wait_ms: duplicateGuard.wait_ms || 0,
        message: "Full AI Auto already replied recently or already processed this inbound message.",
      });
    }

    aiAutoLockKey = duplicateGuard.lock_key;

    const isWhatsAppOutsideWindow =
      channel === "whatsapp" &&
      !ngWithinHours(
        latestInbound.created_at ||
          latestInbound.received_at ||
          latestInbound.timestamp,
        24
      );

    if (isWhatsAppOutsideWindow && !req.body?.template_id && !req.body?.template_key) {
      ngReleaseAiAutoLock(aiAutoLockKey);
      aiAutoLockKey = null;

      return res.status(400).json({
        success: false,
        error: "WhatsApp AI Auto outside 24-hour window requires an approved WhatsApp template.",
        requires_template: true,
      });
    }

    const ai = await ngGenerateStudentAutoReply({ db, lead, messages, channel });
    const replyDelayMs = await ngAylaWaitBeforeAutoSend(db);
    const to = getBestRecipientForChannel({
      channel,
      lead,
      message: latestInbound,
      to: req.body?.to || req.body?.recipient || "",
    });
    const aylaMediaAsset = channel === "whatsapp"
      ? ngPickAylaMediaAssetForReply(db, { lead, reply: ai.reply, latestInboundText: ngMessageText(latestInbound || {}), messages })
      : null;

    const result = await sendCrmMessage({
      db,
      brandId: lead.brand_id || getCrmBrandId(req, db),
      channel,
      to,
      text: ai.reply,
      // v96: after inbound, Ayla must answer freely. Do not reuse approved templates for normal chat.
      templateId: null,
      templateVariables: { lead },
      leadId: lead.id,
      mediaUrl: aylaMediaAsset?.public_url || aylaMediaAsset?.relative_url || "",
      mediaId: aylaMediaAsset?.whatsapp_media_id || "",
      mediaType: aylaMediaAsset?.asset_type || "image",
      caption: aylaMediaAsset ? ngRenderAylaMediaCaption(aylaMediaAsset, { lead, reply: ai.reply }) : "",
      metadata: {
        source: "full_ai_auto",
        ai_auto: true,
        triggered_by: user.id,
        latest_inbound_id: latestInbound.id || null,
        inbound_message_id: ngAiAutoMessageFingerprint(latestInbound),
        ayla_media_asset_id: aylaMediaAsset?.id || null,
        ayla_media_usage_area: aylaMediaAsset?.usage_area || null,
      },
    });
    if (aylaMediaAsset) ngMarkAylaMediaSent(db, lead, aylaMediaAsset, { source: "full_ai_auto", result });

    const adminAlert = await ngAylaMaybeSendConversationAdminAlert({
      db,
      lead,
      appointment: typeof ngAylaFindActiveGoogleMeetAppointment === "function" ? ngAylaFindActiveGoogleMeetAppointment(db, lead) : null,
      ai,
      latestInbound,
      source: "full_ai_auto",
    });

    const deliveryActuallySent = ngAylaMarkProcessedOnlyIfDelivered({ lead, inbound: latestInbound, channel, reply: ai.reply, sendResult: result });

    if (typeof aylaLogCost === "function") {
      await aylaLogCost({
        db,
        actor: user,
        model: ai.model,
        usage: ai.usage,
        action: "full_ai_auto_send",
        meta: { lead_id: lead.id, channel },
      }).catch(() => null);
    }

    ngAffArray(db, "ai_auto_runs").unshift({
      id: uuid(),
      lead_id: lead.id,
      inbound_message_id: ngAiAutoMessageFingerprint(latestInbound),
      channel,
      reply: ai.reply,
      sent: deliveryActuallySent,
      result,
      model: ai.model,
      usage: ai.usage,
      created_by: user.id,
      reply_delay_ms: replyDelayMs || 0,
      admin_alert: adminAlert,
      created_at: ngAffNow(),
    });

    await writeCrmDb(db);

    ngReleaseAiAutoLock(aiAutoLockKey);
    aiAutoLockKey = null;

    return res.json({
      success: deliveryActuallySent,
      sent: deliveryActuallySent,
      reply: ai.reply,
      result,
      usage: ai.usage,
      model: ai.model,
      channel,
      cooldown_seconds: NG_AI_AUTO_COOLDOWN_SECONDS,
      reply_delay_ms: replyDelayMs || 0,
      admin_alert: adminAlert,
    });
  } catch (error) {
    if (aiAutoLockKey) {
      ngReleaseAiAutoLock(aiAutoLockKey);
    }

    return res.status(error.statusCode || 500).json({
      success: false,
      error: error.message,
      code: error.code || null,
      detail: error.response?.data || null,
    });
  }
});



// v94: Ayla auto-reply wake-up engine.
// This runs after inbound WhatsApp/webhook messages and also from Run Due, so Full AI Auto
// does not depend on you pressing Trigger Auto manually inside the inbox.
async function ngAylaProcessFullAiAutoForLead({ db, leadId = null, lead: providedLead = null, brandId = null, source = "ayla_auto_wakeup", actorId = "system", force = false } = {}) {
  const leads = ngAffArray(db, "leads");
  const lead = providedLead || getLeadByAnyId(db, leadId) || leads.find((item) => String(item.id || item.lead_id || "") === String(leadId || ""));

  if (!lead) return { skipped: true, reason: "lead_not_found", lead_id: leadId || null };

  ngNormalizeLeadAiMode(lead);

  const aiMode = String(lead.ai_mode || lead.automation_mode || "auto").toLowerCase();
  const explicitlyManualOrDraft =
    (lead.ai_mode_set === true || lead.automation_mode_set === true || lead.mode_locked === true || lead.ai_mode_manually_set === true) &&
    (aiMode === "manual" || aiMode === "draft" || aiMode === "ai_draft");

  // Full AI Auto is default. v103: inbound webhook wakeups can revive Ayla automatically,
  // because imported/test leads were often left in Manual/AI Draft and the bot appeared silent.
  const sourceText = String(source || "").toLowerCase();
  const isInboundWebhookWakeup = /webhook|inbound|wakeup/.test(sourceText);
  const forceAutoOnInbound = String(process.env.NEXTGEN_AYLA_FORCE_AUTO_ON_INBOUND || "true").toLowerCase() !== "false";
  if (explicitlyManualOrDraft && isInboundWebhookWakeup && forceAutoOnInbound) {
    lead.ai_mode = "auto";
    lead.automation_mode = "auto";
    lead.ai_mode_set = false;
    lead.automation_mode_set = false;
    lead.mode_locked = false;
    lead.ai_mode_manually_set = false;
    lead.updated_at = ngAffNow();
  } else if (explicitlyManualOrDraft) {
    return { lead_id: lead.id || lead.lead_id || null, skipped: true, reason: "explicit_manual_or_draft_mode", ai_mode: aiMode };
  }

  if (ngLeadIsPaidOrGroupAddedForLiveSession(lead)) {
    return { lead_id: lead.id || lead.lead_id || null, skipped: true, reason: "paid_or_group_added" };
  }

  const messages = ngLeadConversationMessages(db, lead.id);
  const latestInbound = ngLatestInbound(messages);
  const latestOutbound = ngLatestOutbound(messages);

  if (!latestInbound) return { lead_id: lead.id || lead.lead_id || null, skipped: true, reason: "no_inbound" };

  const channel = resolveCrmChannelForConversation({
    requestedChannel: lead.current_channel || lead.last_channel || lead.source_platform || lead.platform || "auto",
    lead,
    latestInbound,
    fallback: "whatsapp",
  });

  const inboundFingerprint = ngAiAutoMessageFingerprint(latestInbound);
  const hasOutboundAfterInbound = ngHasOutboundAfterInbound(messages, latestInbound);

  // Clear stale guard: do not block a student forever if no real outbound exists after their message.
  if (
    lead.last_ai_auto_replied_message_id &&
    String(lead.last_ai_auto_replied_message_id) === String(inboundFingerprint) &&
    !hasOutboundAfterInbound
  ) {
    lead.last_ai_auto_replied_message_id = null;
    lead.last_ai_auto_replied_at = null;
  }

  const inboundTime = new Date(latestInbound.created_at || latestInbound.received_at || latestInbound.timestamp || 0).getTime();
  const outboundTime = new Date(latestOutbound?.created_at || latestOutbound?.sent_at || latestOutbound?.timestamp || 0).getTime();

  if (!force && latestOutbound && Number.isFinite(outboundTime) && Number.isFinite(inboundTime) && outboundTime > inboundTime + 1000) {
    return {
      lead_id: lead.id || lead.lead_id || null,
      skipped: true,
      reason: "already_replied",
      has_outbound_after_inbound: true,
      last_inbound_text: ngMessageText(latestInbound).slice(0, 120),
      last_outbound_text: ngMessageText(latestOutbound).slice(0, 120),
    };
  }

  const duplicateGuard = ngShouldSkipAiAutoForInbound(lead, latestInbound, {
    channel,
    forceReprocess: force === true,
  });

  if (duplicateGuard.skip) {
    return {
      lead_id: lead.id || lead.lead_id || null,
      skipped: true,
      reason: duplicateGuard.reason,
      wait_ms: duplicateGuard.wait_ms || 0,
      last_inbound_text: ngMessageText(latestInbound).slice(0, 120),
      last_outbound_text: ngMessageText(latestOutbound || {}).slice(0, 120),
      has_outbound_after_inbound: hasOutboundAfterInbound,
      inbound_fingerprint: inboundFingerprint || null,
      last_ai_auto_replied_message_id: lead.last_ai_auto_replied_message_id || null,
    };
  }

  if (channel === "whatsapp" && !ngWithinHours(latestInbound.created_at || latestInbound.received_at || latestInbound.timestamp, 24)) {
    ngReleaseAiAutoLock(duplicateGuard.lock_key);
    ngAffArray(db, "ai_actions").unshift({
      id: uuid(),
      title: "WhatsApp template required for Full AI Auto",
      area: "whatsapp",
      type: "template_required",
      status: "pending_approval",
      lead_id: lead.id,
      payload: { lead_id: lead.id, channel, source },
      created_at: ngAffNow(),
      updated_at: ngAffNow(),
    });
    return { lead_id: lead.id || lead.lead_id || null, skipped: true, reason: "whatsapp_template_required", requires_template: true };
  }

  try {
    const ai = await ngGenerateStudentAutoReply({ db, lead, messages, channel });
    const replyDelayMs = await ngAylaWaitBeforeAutoSend(db);
    const to = getBestRecipientForChannel({ channel, lead, message: latestInbound });
    const aylaMediaAsset = channel === "whatsapp"
      ? ngPickAylaMediaAssetForReply(db, { lead, reply: ai.reply, latestInboundText: ngMessageText(latestInbound || {}), messages })
      : null;

    const sendResult = await sendCrmMessage({
      db,
      brandId: lead.brand_id || brandId || null,
      channel,
      to,
      text: ai.reply,
      leadId: lead.id,
      mediaUrl: aylaMediaAsset?.public_url || aylaMediaAsset?.relative_url || "",
      mediaId: aylaMediaAsset?.whatsapp_media_id || "",
      mediaType: aylaMediaAsset?.asset_type || "image",
      caption: aylaMediaAsset ? ngRenderAylaMediaCaption(aylaMediaAsset, { lead, reply: ai.reply }) : "",
      metadata: {
        source,
        ai_auto: true,
        latest_inbound_id: latestInbound.id || null,
        inbound_message_id: inboundFingerprint,
        ayla_media_asset_id: aylaMediaAsset?.id || null,
        ayla_media_usage_area: aylaMediaAsset?.usage_area || null,
      },
    });

    if (aylaMediaAsset) ngMarkAylaMediaSent(db, lead, aylaMediaAsset, { source, result: sendResult });

    const adminAlert = await ngAylaMaybeSendConversationAdminAlert({
      db,
      lead,
      appointment: typeof ngAylaFindActiveGoogleMeetAppointment === "function" ? ngAylaFindActiveGoogleMeetAppointment(db, lead) : null,
      ai,
      latestInbound,
      source,
    });

    const deliveryActuallySent = ngAylaMarkProcessedOnlyIfDelivered({ lead, inbound: latestInbound, channel, reply: ai.reply, sendResult });

    ngAffArray(db, "ai_auto_runs").unshift({
      id: uuid(),
      lead_id: lead.id,
      inbound_message_id: inboundFingerprint,
      channel,
      reply: ai.reply,
      sent: deliveryActuallySent,
      queued: Boolean(sendResult.queued),
      result: sendResult,
      model: ai.model,
      usage: ai.usage,
      admin_alert: adminAlert,
      created_by: actorId,
      source,
      reply_delay_ms: replyDelayMs || 0,
      created_at: ngAffNow(),
    });

    ngReleaseAiAutoLock(duplicateGuard.lock_key);

    return {
      lead_id: lead.id || lead.lead_id || null,
      sent: deliveryActuallySent,
      queued: Boolean(sendResult.queued),
      reply: ai.reply,
      channel,
      to,
      admin_alert: adminAlert,
      source,
      result: sendResult,
    };
  } catch (error) {
    ngReleaseAiAutoLock(duplicateGuard.lock_key);
    return {
      lead_id: lead.id || lead.lead_id || null,
      sent: false,
      error: error.message,
      channel,
      source,
    };
  }
}

async function ngAylaRunPendingFullAiAuto({ db, brandId = null, limit = 10, source = "run_due_ai_auto", actorId = "run_due", force = false } = {}) {
  const candidates = ngAffArray(db, "leads")
    .map(ngNormalizeLeadAiMode)
    .filter((lead) => !brandId || String(lead.brand_id || "") === String(brandId || ""))
    .filter((lead) => String(lead.ai_mode || lead.automation_mode || "auto").toLowerCase() === "auto")
    .slice(0, Math.max(1, Math.min(50, Number(limit || 10))));

  const results = [];
  for (const lead of candidates) {
    const messages = ngLeadConversationMessages(db, lead.id);
    const inbound = ngLatestInbound(messages);
    if (!inbound) continue;
    if (!force && ngHasOutboundAfterInbound(messages, inbound)) continue;
    results.push(await ngAylaProcessFullAiAutoForLead({ db, lead, brandId, source, actorId, force }));
  }
  return results;
}

function ngScheduleAylaAutoReplyAfterInbound({ leadId, source = "webhook_ai_auto_wakeup", delayMs = null } = {}) {
  const cleanLeadId = String(leadId || "").trim();
  if (!cleanLeadId) return;

  // v111: do not trust one single setTimeout. In production the inline webhook AI path can
  // fail after taking a duplicate lock, then the old one-shot wake-up fires too early and
  // silently skips with ai_auto_already_processing. We now retry safely. Before every retry
  // we re-read the DB and stop if a real outbound reply already exists after the latest inbound.
  // v114: make inbound reply feel real-time. The previous attempts (4.5s/22s/52s)
  // were too slow, so the student saw silence until refreshing or until a later run-due pass.
  // We still keep idempotency by re-reading the DB before every attempt and stopping if a
  // real outbound already exists after the latest inbound.
  const firstDelay = Number.isFinite(Number(delayMs)) ? Math.max(1000, Number(delayMs)) : 1500;
  const attempts = [firstDelay, 7000, 18000, 45000];

  attempts.forEach((waitMs, index) => {
    setTimeout(async () => {
      try {
        const db = await readCrmDb();
        const lead = getLeadByAnyId(db, cleanLeadId) || ngAffArray(db, "leads").find((item) => String(item.id || item.lead_id || "") === cleanLeadId);
        if (!lead) {
          console.warn("Ayla webhook wake-up skipped: lead not found", { leadId: cleanLeadId, source, attempt: index + 1 });
          return;
        }

        const messages = ngLeadConversationMessages(db, lead.id || lead.lead_id || cleanLeadId);
        const latestInbound = ngLatestInbound(messages);
        if (!latestInbound) {
          console.log("Ayla webhook wake-up skipped: no latest inbound", { leadId: cleanLeadId, source, attempt: index + 1 });
          return;
        }

        if (ngHasOutboundAfterInbound(messages, latestInbound)) {
          console.log("Ayla webhook wake-up not needed: outbound already exists after latest inbound", { leadId: cleanLeadId, source, attempt: index + 1 });
          return;
        }

        // First try respects normal guards. Retry attempts bypass stale fingerprint/lock state only
        // after the cooldown window, while still avoiding duplicates via the outbound-after-inbound check above.
        const result = await ngAylaProcessFullAiAutoForLead({
          db,
          lead,
          leadId: lead.id || cleanLeadId,
          source: `${source}_attempt_${index + 1}`,
          actorId: "webhook_wakeup",
          force: index > 0,
        });

        ngAffArray(db, "ai_auto_runs").unshift({
          id: uuid(),
          lead_id: lead.id || lead.lead_id || cleanLeadId,
          source: `${source}_attempt_${index + 1}`,
          status: result?.sent ? "sent" : (result?.skipped ? "skipped" : "checked"),
          result,
          latest_inbound_text: ngMessageText(latestInbound).slice(0, 240),
          created_by: "webhook_wakeup",
          created_at: ngAffNow(),
        });

        await writeCrmDb(db);
        console.log("Ayla webhook wake-up result:", result);
      } catch (error) {
        console.error("Ayla webhook wake-up failed:", error.message, error.response?.data || "");
      }
    }, waitMs);
  });
}

app.post("/admin/crm/automation/revive-ayla", async (req, res) => {
  try {
    await requireCrmAdmin(req);
    const db = await readCrmDb();
    const ids = Array.isArray(req.body?.lead_ids) ? req.body.lead_ids.map((x) => String(x || "").trim()).filter(Boolean) : [];
    const limit = Math.max(1, Math.min(200, Number(req.body?.limit || 100)));
    const runNow = req.body?.run_now !== false;

    const leads = ngAffArray(db, "leads");
    const candidates = leads
      .filter((lead) => !ids.length || ids.includes(String(lead.id || lead.lead_id || "")))
      .filter((lead) => req.body?.include_paid === true || !ngLeadIsPaidOrGroupAddedForLiveSession(lead))
      .filter((lead) => req.body?.include_opted_out === true || !lead.opted_out && !lead.opt_out && !lead.unsubscribed && !lead.do_not_contact && !lead.stop_requested)
      .slice(0, limit);

    const results = [];
    for (const lead of candidates) {
      lead.ai_mode = "auto";
      lead.automation_mode = "auto";
      lead.ai_mode_set = false;
      lead.automation_mode_set = false;
      lead.mode_locked = false;
      lead.ai_mode_manually_set = false;
      lead.last_ai_auto_replied_message_id = null;
      lead.last_ai_auto_replied_at = null;
      lead.last_ai_auto_reply_channel = null;
      lead.last_ai_auto_reply_text = "";
      lead.updated_at = ngAffNow();

      if (runNow) {
        results.push(await ngAylaProcessFullAiAutoForLead({
          db,
          lead,
          source: "revive_ayla_admin",
          actorId: "admin_revival",
          force: req.body?.force === true,
        }));
      } else {
        results.push({ lead_id: lead.id || lead.lead_id || null, revived: true, run_now: false });
      }
    }

    await writeCrmDb(db);
    return res.json({
      success: true,
      revived_count: candidates.length,
      run_now: runNow,
      results,
      message: "Ayla set back to Full AI Auto and duplicate guards cleared for selected leads.",
    });
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/crm/automation/reset-ai-auto-guard", async (req, res) => {
  try {
    await requireCrmAdmin(req);
    const db = await readCrmDb();
    const leadId = String(req.body?.lead_id || req.body?.leadId || req.body?.id || "").trim();
    if (!leadId) return res.status(400).json({ success: false, error: "lead_id is required" });
    const leads = ngAffArray(db, "leads");
    const lead = leads.find((item) => String(item.id || item.lead_id || "") === leadId);
    if (!lead) return res.status(404).json({ success: false, error: "Lead not found" });
    lead.last_ai_auto_replied_message_id = null;
    lead.last_ai_auto_replied_at = null;
    lead.last_ai_auto_reply_channel = null;
    lead.last_ai_auto_reply_text = "";
    lead.ai_mode = "auto";
    lead.automation_mode = "auto";
    lead.updated_at = ngAffNow();
    await writeCrmDb(db);
    return res.json({ success: true, lead_id: lead.id || lead.lead_id, message: "AI auto duplicate guard reset for this lead" });
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});


// v106: diagnose why Ayla is not replying to the latest inbound message.
app.post("/admin/crm/automation/diagnose-ayla", async (req, res) => {
  try {
    await requireCrmAdmin(req);
    const db = await readCrmDb();
    const leadId = String(req.body?.lead_id || req.body?.leadId || req.body?.id || "").trim();
    const phoneDigits = String(req.body?.phone || "").replace(/\D/g, "");
    const leads = ngAffArray(db, "leads").map(ngNormalizeLeadAiMode);
    const lead = leadId
      ? leads.find((item) => String(item.id || item.lead_id || "") === leadId)
      : leads.find((item) => {
          const p = String(item.phone || item.whatsapp || item.whatsapp_phone || "").replace(/\D/g, "");
          return phoneDigits && (p === phoneDigits || p.endsWith(phoneDigits) || phoneDigits.endsWith(p));
        });
    if (!lead) return res.status(404).json({ success: false, error: "Lead not found" });
    const messages = ngLeadConversationMessages(db, lead.id);
    const latestInbound = ngLatestInbound(messages);
    const latestOutbound = ngLatestOutbound(messages);
    const channel = resolveCrmChannelForConversation({ requestedChannel: lead.current_channel || lead.last_channel || lead.source_platform || lead.platform || "auto", lead, latestInbound, fallback: "whatsapp" });
    const hasOutboundAfterInbound = latestInbound ? ngHasOutboundAfterInbound(messages, latestInbound) : false;
    const duplicateGuardPreview = latestInbound ? {
      inbound_fingerprint: ngAiAutoMessageFingerprint(latestInbound),
      last_ai_auto_replied_message_id: lead.last_ai_auto_replied_message_id || null,
      same_fingerprint: String(lead.last_ai_auto_replied_message_id || "") === String(ngAiAutoMessageFingerprint(latestInbound) || ""),
    } : null;
    return res.json({
      success: true,
      build: NEXTGEN_BACKEND_BUILD,
      lead: { id: lead.id || lead.lead_id, name: lead.name, phone: lead.phone || lead.whatsapp, ai_mode: lead.ai_mode, automation_mode: lead.automation_mode, status: lead.status, stage: lead.stage || lead.lead_stage, next_action: lead.next_action },
      channel,
      counts: { messages: messages.length, inbound: messages.filter(ngIsInboundMessage).length, outbound: messages.filter(ngIsOutboundMessage).length },
      latest_inbound: latestInbound ? { id: latestInbound.id, text: ngMessageText(latestInbound), created_at: latestInbound.created_at || latestInbound.received_at || latestInbound.timestamp, direction: latestInbound.direction } : null,
      latest_outbound: latestOutbound ? { id: latestOutbound.id, text: ngMessageText(latestOutbound), created_at: latestOutbound.created_at || latestOutbound.sent_at || latestOutbound.timestamp, direction: latestOutbound.direction } : null,
      has_outbound_after_inbound: hasOutboundAfterInbound,
      duplicate_guard_preview: duplicateGuardPreview,
      whatsapp_window_ok: latestInbound ? ngWithinHours(latestInbound.created_at || latestInbound.received_at || latestInbound.timestamp, 24) : null,
    });
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});


app.post("/admin/crm/automation/force-reply-latest", async (req, res) => {
  try {
    const { user } = await requireCrmAdmin(req);
    const db = await readCrmDb();
    const key = req.body?.lead_id || req.body?.phone || req.body?.contact || req.body?.id || "";
    const lead = getLeadByAnyId(db, key);
    if (!lead) return res.status(404).json({ success: false, error: "Lead not found", key });

    lead.ai_mode = "auto";
    lead.automation_mode = "auto";
    lead.ai_mode_set = false;
    lead.automation_mode_set = false;
    lead.mode_locked = false;
    lead.ai_mode_manually_set = false;
    lead.last_ai_auto_replied_message_id = req.body?.reset_guard === false ? lead.last_ai_auto_replied_message_id : null;
    lead.last_ai_auto_replied_at = req.body?.reset_guard === false ? lead.last_ai_auto_replied_at : null;

    const result = await ngAylaProcessFullAiAutoForLead({
      db,
      lead,
      brandId: lead.brand_id || getCrmBrandId(req, db),
      source: "admin_force_reply_latest",
      actorId: user.id || "admin",
      force: req.body?.force !== false,
    });

    await writeCrmDb(db);
    return res.json({ success: true, build: NEXTGEN_BACKEND_BUILD, lead_id: lead.id || lead.lead_id, result });
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message, detail: error.response?.data || null });
  }
});


// v111: one-click/admin diagnostic repair for the exact symptom: inbound messages exist,
// but Ayla did not produce any outbound reply after the latest inbound.
app.post("/admin/crm/automation/wake-silent-inbound", async (req, res) => {
  try {
    const { user } = await requireCrmAdmin(req);
    const db = await readCrmDb();
    const key = req.body?.lead_id || req.body?.phone || req.body?.contact || req.body?.id || "";
    const limit = Math.max(1, Math.min(50, Number(req.body?.limit || 10)));
    const force = req.body?.force !== false;

    let candidates = [];
    if (key) {
      const lead = getLeadByAnyId(db, key);
      if (!lead) return res.status(404).json({ success: false, error: "Lead not found", key });
      candidates = [lead];
    } else {
      candidates = ngAffArray(db, "leads")
        .map(ngNormalizeLeadAiMode)
        .filter((lead) => String(lead.ai_mode || lead.automation_mode || "auto").toLowerCase() === "auto")
        .slice(0, limit * 3);
    }

    const results = [];
    for (const lead of candidates) {
      if (results.length >= limit) break;
      const messages = ngLeadConversationMessages(db, lead.id || lead.lead_id);
      const latestInbound = ngLatestInbound(messages);
      if (!latestInbound) {
        if (key) results.push({ lead_id: lead.id || lead.lead_id, skipped: true, reason: "no_inbound" });
        continue;
      }
      if (ngHasOutboundAfterInbound(messages, latestInbound)) {
        if (key) results.push({ lead_id: lead.id || lead.lead_id, skipped: true, reason: "outbound_already_after_latest_inbound" });
        continue;
      }

      lead.ai_mode = "auto";
      lead.automation_mode = "auto";
      lead.ai_mode_set = false;
      lead.automation_mode_set = false;
      lead.mode_locked = false;
      lead.ai_mode_manually_set = false;
      if (force) {
        lead.last_ai_auto_replied_message_id = null;
        lead.last_ai_auto_replied_at = null;
      }

      const result = await ngAylaProcessFullAiAutoForLead({
        db,
        lead,
        brandId: lead.brand_id || getCrmBrandId(req, db),
        source: "admin_wake_silent_inbound",
        actorId: user.id || "admin",
        force,
      });
      results.push({
        lead_id: lead.id || lead.lead_id,
        name: lead.name || lead.lead_name || "Lead",
        phone: lead.phone || lead.whatsapp || lead.whatsapp_phone || "",
        latest_inbound: ngMessageText(latestInbound).slice(0, 240),
        result,
      });
    }

    await writeCrmDb(db);
    return res.json({ success: true, build: NEXTGEN_BACKEND_BUILD, count: results.length, results });
  } catch (error) {
    return res.status(error.statusCode || 500).json({ success: false, error: error.message, detail: error.response?.data || null });
  }
});

app.post("/admin/crm/automation/process-ai-auto", async (req, res) => {
  try {
    const { user } = await requireCrmAdmin(req);
    const db = await readCrmDb();
    const limit = Math.max(1, Math.min(20, Number(req.body?.limit || 5)));

    // Full AI Auto is now the default for new conversations unless a human explicitly set Manual or AI Draft.
    const leads = ngAffArray(db, "leads")
      .map(ngNormalizeLeadAiMode)
      .filter((lead) => String(lead.ai_mode || lead.automation_mode || "auto").toLowerCase() === "auto")
      .slice(0, limit);

    const results = [];

    for (const lead of leads) {
      const messages = ngLeadConversationMessages(db, lead.id);
      const inbound = ngLatestInbound(messages);
      const outbound = ngLatestOutbound(messages);
      if (!inbound) { results.push({ lead_id: lead.id, skipped: true, reason: "no_inbound" }); continue; }

      const channel = resolveCrmChannelForConversation({
        requestedChannel: lead.current_channel || lead.last_channel || lead.source_platform || lead.platform || "auto",
        lead,
        latestInbound: inbound,
        fallback: "whatsapp",
      });

      const inboundFingerprint = ngAiAutoMessageFingerprint(inbound);
      const hasOutboundAfterInbound = ngHasOutboundAfterInbound(messages, inbound);
      if (
        lead.last_ai_auto_replied_message_id &&
        String(lead.last_ai_auto_replied_message_id) === String(inboundFingerprint) &&
        !hasOutboundAfterInbound
      ) {
        // v93: if Ayla's fingerprint says replied but no real outbound exists after this inbound,
        // the old guard was blocking the student forever. Clear the stale guard and let Ayla answer.
        lead.last_ai_auto_replied_message_id = null;
        lead.last_ai_auto_replied_at = null;
      }

      const duplicateGuard = ngShouldSkipAiAutoForInbound(lead, inbound, {
        channel,
        forceReprocess: req.body?.force === true || req.body?.force_reprocess === true || req.body?.reset_guard === true,
      });
      if (duplicateGuard.skip) {
        results.push({
          lead_id: lead.id,
          skipped: true,
          reason: duplicateGuard.reason,
          wait_ms: duplicateGuard.wait_ms || 0,
          last_inbound_text: ngMessageText(inbound).slice(0, 120),
          last_outbound_text: ngMessageText(outbound || {}).slice(0, 120),
          has_outbound_after_inbound: hasOutboundAfterInbound,
          last_ai_auto_replied_message_id: lead.last_ai_auto_replied_message_id || null,
          inbound_fingerprint: inboundFingerprint || null,
        });
        continue;
      }

      const inboundTime = new Date(inbound.created_at || inbound.received_at || inbound.timestamp || 0).getTime();
      const outboundTime = new Date(outbound?.created_at || outbound?.sent_at || outbound?.timestamp || 0).getTime();
      if (outbound && outboundTime > inboundTime + 1000) { ngReleaseAiAutoLock(duplicateGuard.lock_key); results.push({ lead_id: lead.id, skipped: true, reason: "already_replied", last_outbound_text: ngMessageText(outbound || {}).slice(0, 120), has_outbound_after_inbound: true }); continue; }

      if (channel === "whatsapp" && !ngWithinHours(inbound.created_at || inbound.received_at || inbound.timestamp, 24)) {
        ngReleaseAiAutoLock(duplicateGuard.lock_key);
        ngAffArray(db, "ai_actions").unshift({ id: uuid(), title: "WhatsApp template required for Full AI Auto", area: "whatsapp", type: "template_required", status: "pending_approval", lead_id: lead.id, payload: { lead_id: lead.id, channel }, created_at: ngAffNow(), updated_at: ngAffNow() });
        results.push({ lead_id: lead.id, skipped: true, reason: "whatsapp_template_required" });
        continue;
      }

      try {
        const ai = await ngGenerateStudentAutoReply({ db, lead, messages, channel });
        const to = getBestRecipientForChannel({ channel, lead, message: inbound });
        const aylaMediaAsset = channel === "whatsapp"
          ? ngPickAylaMediaAssetForReply(db, { lead, reply: ai.reply, latestInboundText: ngMessageText(inbound || {}), messages })
          : null;
        const sendResult = await sendCrmMessage({
          db,
          brandId: lead.brand_id || getCrmBrandId(req, db),
          channel,
          to,
          text: ai.reply,
          leadId: lead.id,
          mediaUrl: aylaMediaAsset?.public_url || aylaMediaAsset?.relative_url || "",
          mediaId: aylaMediaAsset?.whatsapp_media_id || "",
          mediaType: aylaMediaAsset?.asset_type || "image",
          caption: aylaMediaAsset ? ngRenderAylaMediaCaption(aylaMediaAsset, { lead, reply: ai.reply }) : "",
          metadata: { source: "process_ai_auto", ai_auto: true, triggered_by: user.id, latest_inbound_id: inbound.id || null, ayla_media_asset_id: aylaMediaAsset?.id || null, ayla_media_usage_area: aylaMediaAsset?.usage_area || null }
        });
        if (aylaMediaAsset) ngMarkAylaMediaSent(db, lead, aylaMediaAsset, { source: "process_ai_auto", result: sendResult });
        const adminAlert = await ngAylaMaybeSendConversationAdminAlert({
          db,
          lead,
          appointment: typeof ngAylaFindActiveGoogleMeetAppointment === "function" ? ngAylaFindActiveGoogleMeetAppointment(db, lead) : null,
          ai,
          latestInbound: inbound,
          source: "process_ai_auto",
        });
        const deliveryActuallySent = ngAylaMarkProcessedOnlyIfDelivered({ lead, inbound, channel, reply: ai.reply, sendResult });
        if (typeof aylaLogCost === "function") await aylaLogCost({ db, actor: user, model: ai.model, usage: ai.usage, action: "process_ai_auto_send", meta: { lead_id: lead.id, channel } }).catch(() => null);
        ngAffArray(db, "ai_auto_runs").unshift({ id: uuid(), lead_id: lead.id, inbound_message_id: ngAiAutoMessageFingerprint(inbound), channel, reply: ai.reply, sent: deliveryActuallySent, result: sendResult, model: ai.model, usage: ai.usage, admin_alert: adminAlert, created_by: user.id, created_at: ngAffNow() });
        ngReleaseAiAutoLock(duplicateGuard.lock_key);
        results.push({ lead_id: lead.id, sent: deliveryActuallySent, reply: ai.reply, channel, admin_alert: adminAlert, result: sendResult });
      } catch (err) {
        ngReleaseAiAutoLock(duplicateGuard.lock_key);
        results.push({ lead_id: lead.id, sent: false, error: err.message, channel });
      }
    }

    await writeCrmDb(db);
    res.json({ success: true, processed: results.length, results });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});



function ngCommunityArray(db = {}, key = "") {
  return ensureCrmArray(db, key);
}

function ngCommunityText(value, fallback = "") {
  return String(value ?? fallback).trim();
}

function ngCommunityPlatform(value, fallback = "telegram") {
  const clean = ngCommunityText(value || fallback).toLowerCase();
  if (clean === "x") return "twitter";
  if (clean === "fb") return "facebook";
  if (clean === "ig") return "instagram";
  const allowed = [
    "telegram", "whatsapp", "facebook", "messenger", "instagram", "reddit",
    "linkedin", "youtube", "twitter", "discord", "email", "sms", "webchat", "other"
  ];
  return allowed.includes(clean) ? clean : fallback;
}

function ngCommunityOpportunityText(item = {}) {
  return ngCommunityText(
    item.detected_text ||
    item.source_text ||
    item.summary ||
    item.post_text ||
    item.message ||
    item.title ||
    ""
  );
}

function ngCommunityTrainingContext(db) {
  const direct = [
    ...ngCommunityArray(db, "ai_training"),
    ...ngCommunityArray(db, "ai_training_items"),
  ];

  const useful = direct
    .filter((item) => item && item.active !== false && item.is_active !== false)
    .filter((item) => {
      const haystack = [
        item.category,
        item.audience,
        item.title,
        item.tags,
        item.content,
      ].join(" ").toLowerCase();

      return (
        haystack.includes("education") ||
        haystack.includes("community") ||
        haystack.includes("telegram") ||
        haystack.includes("whatsapp") ||
        haystack.includes("uworld") ||
        haystack.includes("mcq") ||
        haystack.includes("first aid") ||
        haystack.includes("demo") ||
        haystack.includes("qualification") ||
        haystack.includes("old graduate")
      );
    })
    .sort((a, b) => Number(b.priority || 0) - Number(a.priority || 0))
    .slice(0, 14)
    .map((item) => `Title: ${item.title || item.name || "Training"}\nCategory: ${item.category || "general"}\nContent: ${item.content || item.body || item.text || ""}`)
    .join("\n\n---\n\n");

  const baseContext = useful || "Use NextGen USMLE rules: educational first, no spam, ask Step 1/Step 2, exam date, graduation year, main difficulty, then offer free 2-day LMS demo only after qualification.";
  const learningContext = ngLearningRulesPromptBlock(db, "community");
  return [learningContext, baseContext].filter(Boolean).join("\n\n---\n\n");
}

function ngBuildCommunityFallbackContent(body = {}) {
  const type = ngCommunityText(body.content_type || body.post_type || "daily_mcq");
  const exam = ngCommunityText(body.exam_type || "Step 1");
  const topic = ngCommunityText(body.topic || "UWorld + First Aid integrated learning");
  const cta = ngCommunityText(body.cta || "Reply with your answer or your main difficulty.");

  if (type === "daily_mcq") {
    return `Daily ${exam} MCQ\n\nA student is reviewing ${topic}. Which next step best improves retention and exam performance?\n\nA. Read the explanation once and move on\nB. Memorize isolated facts without questions\nC. Review the incorrect concept, connect it with First Aid, and retest with similar UWorld-style questions\nD. Delay review until the final week\nE. Avoid NBME-style self-assessment\n\nCorrect Answer: C\n\nExplanation:\nThe highest-yield approach is active recall plus error correction. For USMLE preparation, each wrong question should be converted into a First Aid-linked concept, then retested with similar clinical reasoning questions.\n\n${cta}`;
  }

  if (type === "poll") {
    return `Quick ${exam} poll:\n\nWhat is your biggest difficulty right now?\n\n1. UWorld explanations\n2. First Aid retention\n3. NBME score not improving\n4. Study schedule\n5. Revision before exam\n\nVote and comment your exam date if you want guidance.`;
  }

  if (type === "strategy_tip") {
    return `${exam} Strategy Tip\n\nDo not study randomly. Pick one weak area, solve a focused UWorld block, review every wrong option, then write the First Aid concept beside it.\n\nFor students near exam date: your revision should be based on mistakes, NBME trend, and weak systems — not just rereading.\n\n${cta}`;
  }

  if (type === "demo_invite_soft") {
    return `For serious ${exam} students:\n\nIf you are confused about UWorld, First Aid integration, NBME scores, or a clear daily schedule, you can request the free 2-day NextGen LMS demo.\n\nNo pressure — first tell us your exam date and main difficulty so we can guide you properly.`;
  }

  if (type === "weekly_plan") {
    return `${exam} Weekly Study Plan\n\nDay 1-2: Weak system UWorld blocks\nDay 3: First Aid integration and notes cleanup\nDay 4: Mixed timed questions\nDay 5: Review incorrects and make micro-targets\nDay 6: NBME-style review / self-assessment\nDay 7: Light revision + planning next week\n\n${cta}`;
  }

  return `${exam} Educational Post\n\nTopic: ${topic}\n\nKey idea: connect every question mistake to a testable First Aid concept. The goal is not only finishing resources, but learning how the exam asks the concept.\n\n${cta}`;
}

async function ngGenerateCommunityAiContent({ db, body, mode = "content" }) {
  const trainingContext = ngCommunityTrainingContext(db);
  const platform = ngCommunityPlatform(body.platform || body.channel || "telegram");
  const type = ngCommunityText(body.content_type || body.post_type || "daily_mcq");
  const exam = ngCommunityText(body.exam_type || "Step 1");
  const topic = ngCommunityText(body.topic || body.detected_text || body.source_text || "USMLE preparation");
  const audience = ngCommunityText(body.audience || "USMLE students preparing for Step 1 or Step 2 CK");
  const cta = ngCommunityText(body.cta || "Ask one helpful question and avoid direct sales pressure.");

  if (!isAIConfigured()) {
    return {
      content: ngBuildCommunityFallbackContent({ ...body, platform, content_type: type, exam_type: exam, topic, audience, cta }),
      model: "local-community-fallback",
      usage: {},
      ai_configured: false,
    };
  }

  const systemPrompt =
    mode === "outreach"
      ? `You are the NextGen USMLE Community Study Helper. You write friendly, non-spammy, approval-first outreach drafts. Do not pretend to be a random friend. Be warm and human. Ask only useful qualification questions first. Do not push payment.`
      : `You are the NextGen USMLE Community Content AI. Create educational, medically careful USMLE community content using the provided training rules. For MCQs include stem, options A-E, answer, and concise explanation. Do not make false guarantees.`;

  const userPrompt = [
    `AI Training Center context:\n${trainingContext}`,
    `Platform: ${platform}`,
    `Mode: ${mode}`,
    `Content type: ${type}`,
    `Exam: ${exam}`,
    `Audience: ${audience}`,
    `Topic/source:\n${topic}`,
    `CTA/instruction:\n${cta}`,
    `Rules: educational first, no spam, no aggressive sales, no guaranteed score/result claims, qualify before demo offer.`,
  ].join("\n\n");

  const result = await callOpenAIResponsesAPI({
    model: getAIModel("gpt-4o-mini"),
    systemPrompt,
    userPrompt,
    maxOutputTokens: mode === "outreach" ? 700 : 1400,
  });

  return {
    content: result.text || ngBuildCommunityFallbackContent(body),
    model: result.model,
    usage: result.usage || {},
    ai_configured: true,
  };
}

function ngNormalizeCommunityRecord(body = {}, existing = {}, brandId = null, user = null) {
  return withTimestamps({
    ...existing,
    ...(body || {}),
    id: existing.id || body.id || uuid(),
    brand_id: body.brand_id || existing.brand_id || brandId || null,
    platform: ngCommunityPlatform(body.platform || existing.platform || "telegram"),
    name: ngCommunityText(body.name || body.community_name || existing.name || existing.community_name || "Community"),
    community_name: ngCommunityText(body.community_name || body.name || existing.community_name || existing.name || "Community"),
    community_url: ngCommunityText(body.community_url || body.url || existing.community_url || existing.url || ""),
    ownership_type: ngCommunityText(body.ownership_type || existing.ownership_type || "owned"), // owned | partner | external_watch
    posting_frequency: ngCommunityText(body.posting_frequency || body.frequency || existing.posting_frequency || "daily"),
    community_goal: ngCommunityText(body.community_goal || existing.community_goal || "Build trust, educate daily, capture qualified USMLE leads."),
    status: ngCommunityText(body.status || existing.status || "active"),
    notes: ngCommunityText(body.notes || existing.notes || ""),
    created_by: existing.created_by || user?.id || null,
    updated_by: user?.id || existing.updated_by || null,
  }, existing);
}

function ngNormalizeCommunityTask(body = {}, existing = {}, brandId = null, user = null) {
  const keywords = Array.isArray(body.keywords)
    ? body.keywords
    : String(body.keywords || existing.keywords || "")
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean);

  return withTimestamps({
    ...existing,
    ...(body || {}),
    id: existing.id || body.id || uuid(),
    brand_id: body.brand_id || existing.brand_id || brandId || null,
    platform: ngCommunityPlatform(body.platform || existing.platform || "telegram"),
    name: ngCommunityText(body.name || existing.name || body.community_name || "Community watch task"),
    community_name: ngCommunityText(body.community_name || existing.community_name || ""),
    community_url: ngCommunityText(body.community_url || existing.community_url || ""),
    keywords,
    status: ngCommunityText(body.status || existing.status || "active"),
    frequency: ngCommunityText(body.frequency || existing.frequency || "daily"),
    approval_required: body.approval_required !== undefined ? Boolean(body.approval_required) : existing.approval_required !== false,
    outreach_style: ngCommunityText(body.outreach_style || existing.outreach_style || "friendly_helpful_no_pitch"),
    notes: ngCommunityText(body.notes || existing.notes || ""),
    created_by: existing.created_by || user?.id || null,
    updated_by: user?.id || existing.updated_by || null,
  }, existing);
}

function ngNormalizeCommunityOpportunity(body = {}, existing = {}, brandId = null, user = null) {
  const text = ngCommunityText(body.detected_text || body.source_text || body.post_text || body.message || existing.detected_text || "");
  return withTimestamps({
    ...existing,
    ...(body || {}),
    id: existing.id || body.id || uuid(),
    brand_id: body.brand_id || existing.brand_id || brandId || null,
    platform: ngCommunityPlatform(body.platform || body.source_platform || existing.platform || existing.source_platform || "telegram"),
    source_platform: ngCommunityPlatform(body.source_platform || body.platform || existing.source_platform || existing.platform || "telegram"),
    community_id: body.community_id || existing.community_id || null,
    community_name: ngCommunityText(body.community_name || existing.community_name || ""),
    post_url: ngCommunityText(body.post_url || body.source_url || existing.post_url || existing.source_url || ""),
    author_name: ngCommunityText(body.author_name || body.username || existing.author_name || existing.username || ""),
    username: ngCommunityText(body.username || body.author_name || existing.username || existing.author_name || ""),
    title: ngCommunityText(body.title || existing.title || "Community opportunity"),
    detected_text: text,
    intent: ngCommunityText(body.intent || existing.intent || "exam_difficulty"),
    priority: ngCommunityText(body.priority || existing.priority || "medium"),
    status: ngCommunityText(body.status || existing.status || "new"),
    suggested_reply: ngCommunityText(body.suggested_reply || existing.suggested_reply || ""),
    consent_to_contact: body.consent_to_contact !== undefined ? Boolean(body.consent_to_contact) : Boolean(existing.consent_to_contact),
    created_by: existing.created_by || user?.id || null,
    updated_by: user?.id || existing.updated_by || null,
  }, existing);
}

function ngCreateCommunityApprovalItem(db, { brandId, draft, kind = "community_content", user = null }) {
  const approval = withTimestamps({
    id: `approval_${draft.id || uuid()}`,
    brand_id: brandId || draft.brand_id || null,
    type: kind,
    action_type: draft.action_type || kind,
    title: draft.title || draft.name || (kind === "community_content" ? "Community content draft" : "Community outreach draft"),
    platform: draft.platform || draft.channel || "telegram",
    status: "pending",
    approval_status: "pending",
    draft_content: draft.draft_content || draft.message || draft.content || "",
    payload: draft,
    created_by: user?.id || draft.created_by || null,
  });
  ngCommunityArray(db, "approval_queue").unshift(approval);
  return approval;
}

function ngCreateLeadFromCommunityOpportunity(db, req, opp, user = null) {
  const brandId = opp.brand_id || getCrmBrandId(req, db);
  const payload = parseInboundSocialPayload({
    platform: opp.platform || "telegram",
    payload: {
      ...(opp.raw_payload || {}),
      ...(req.body || {}),
      text: req.body?.message || opp.detected_text || opp.summary || "",
      username: opp.username || opp.author_name || req.body?.username || "",
      name: opp.author_name || opp.username || req.body?.name || "",
      chat_id: opp.telegram_chat_id || opp.chat_id || req.body?.telegram_chat_id || req.body?.chat_id || "",
      email: req.body?.email || opp.email || "",
      phone: req.body?.phone || opp.phone || opp.whatsapp || "",
    },
    integration: null,
  });

  const { lead, created } = upsertSocialLead(db, payload.platform || opp.platform || "telegram", {
    ...payload,
    brand_id: brandId,
    source: "community_intelligence",
    source_platform: opp.platform || "telegram",
    source_community_id: opp.community_id || null,
    source_community_name: opp.community_name || "",
    source_opportunity_id: opp.id,
    exam_type: opp.exam_type || req.body?.exam_type || null,
    exam_date: opp.exam_date || req.body?.exam_date || null,
    graduation_year: opp.graduation_year || req.body?.graduation_year || null,
    gap_type: opp.gap_type || req.body?.gap_type || null,
    pain_points: opp.pain_points || opp.detected_text || "",
    interest_level: opp.interest_level || req.body?.interest_level || "medium",
    consent_to_contact: opp.consent_to_contact || req.body?.consent_to_contact === true,
  });

  opp.lead_id = lead.id;
  opp.converted_lead_id = lead.id;
  opp.status = "lead_created";
  opp.updated_by = user?.id || opp.updated_by || null;
  opp.updated_at = nowIso();

  return { lead, created };
}

function ngRegisterCommunityCollectionRoutes(baseRoutes, collection, responseKey, normalizer) {
  for (const baseRoute of baseRoutes) {
    app.get(baseRoute, async (req, res) => {
      try {
        await requireCrmAdmin(req);
        const db = await readCrmDb();
        const brandId = getCrmBrandId(req, db);
        const rows = filterCrmRecords(req, ngCommunityArray(db, collection), brandId).sort(sortNewestFirst);
        res.json({ success: true, [responseKey]: rows, items: rows, records: rows, count: rows.length });
      } catch (error) {
        res.status(error.statusCode || 500).json({ success: false, error: error.message });
      }
    });

    app.post(baseRoute, async (req, res) => {
      try {
        const { user } = await requireCrmAdmin(req);
        const db = await readCrmDb();
        const brandId = getCrmBrandId(req, db);
        const record = normalizer(req.body || {}, {}, brandId, user);
        ngCommunityArray(db, collection).unshift(record);
        await writeCrmDb(db);
        res.json({ success: true, [responseKey.replace(/s$/, "")]: record, record, item: record });
      } catch (error) {
        res.status(error.statusCode || 500).json({ success: false, error: error.message });
      }
    });

    app.put(`${baseRoute}/:id`, async (req, res) => {
      try {
        const { user } = await requireCrmAdmin(req);
        const db = await readCrmDb();
        const brandId = getCrmBrandId(req, db);
        const rows = ngCommunityArray(db, collection);
        const index = rows.findIndex((item) => String(item.id) === String(req.params.id));
        if (index < 0) return res.status(404).json({ success: false, error: "Record not found" });
        rows[index] = normalizer(req.body || {}, rows[index], brandId, user);
        await writeCrmDb(db);
        res.json({ success: true, [responseKey.replace(/s$/, "")]: rows[index], record: rows[index], item: rows[index] });
      } catch (error) {
        res.status(error.statusCode || 500).json({ success: false, error: error.message });
      }
    });

    app.delete(`${baseRoute}/:id`, async (req, res) => {
      try {
        const { user } = await requireCrmAdmin(req);
        const db = await readCrmDb();
        const rows = ngCommunityArray(db, collection);
        const item = rows.find((row) => String(row.id) === String(req.params.id));
        if (!item) return res.status(404).json({ success: false, error: "Record not found" });
        item.status = "deleted";
        item.deleted_at = nowIso();
        item.deleted_by = user.id;
        item.updated_at = nowIso();
        await writeCrmDb(db);
        res.json({ success: true, deleted: true, item });
      } catch (error) {
        res.status(error.statusCode || 500).json({ success: false, error: error.message });
      }
    });
  }
}

