app.post("/admin/crm/community-content/scheduled-posts/generate-all", async (req, res) => {
  try {
    const ctx = await ngRequireContentAccess(req, "generate");
    const db = ctx.crmDb;
    const limit = Math.min(100, Math.max(1, Number(req.body?.limit || req.query?.limit || 50)));
    const scopedScheduledPosts = ngContentScope(ngContentArray(db, "community_scheduled_posts"), ctx);
    const posts = ngFilterScheduledPostsForBulk(
        scopedScheduledPosts,
        req.body || {},
        req.query || {}
      )
      .filter((post) => !post.deleted_at && !["deleted", "posted", "published"].includes(String(post.status || "").toLowerCase()))
      .filter((post) => !ngContentClean(post.message || post.draft_content || ""))
      .filter((post) => ngCanGenerateScheduledPostNow(post, scopedScheduledPosts))
      .slice(0, limit);

    const results = [];
    for (const post of posts) {
      try {
        const roadmap = ngContentArray(db, "community_content_roadmaps").find((item) => String(item.id || "") === String(post.roadmap_id || "")) || {};
        await ngGenerateAutopilotPostContent({ db, post, roadmap });
        results.push({ id: post.id, success: true, status: post.status });
      } catch (error) {
        post.status = "failed";
        post.last_error = error.message;
        post.updated_at = nowIso();
        results.push({ id: post.id, success: false, error: error.message });
      }
    }

    await writeCrmDb(db);
    res.json({ success: true, processed: posts.length, results });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/crm/community-content/scheduled-posts/approve-all", async (req, res) => {
  try {
    const ctx = await ngRequireContentAccess(req, "approve");
    const db = ctx.crmDb;
    const limit = Math.min(200, Math.max(1, Number(req.body?.limit || req.query?.limit || 100)));
    const posts = ngFilterScheduledPostsForBulk(
        ngContentScope(ngContentArray(db, "community_scheduled_posts"), ctx),
        req.body || {},
        req.query || {}
      )
      .filter((post) => !post.deleted_at && !["deleted", "posted", "published"].includes(String(post.status || "").toLowerCase()))
      .filter((post) => ngContentClean(post.message || post.draft_content || ""))
      .filter((post) => String(post.approval_status || "").toLowerCase() !== "approved" || post.ready_to_post !== true)
      .slice(0, limit);

    for (const post of posts) {
      post.approval_status = "approved";
      post.medical_review_status = ngContentIsMedicalType(post) ? "approved" : (post.medical_review_status || "not_required");
      post.ready_to_post = true;
      post.status = post.scheduled_at ? "scheduled" : "ready_to_post";
      post.approved_at = post.approved_at || nowIso();
      post.approved_by = ctx.user.id;
      post.updated_at = nowIso();
      post.updated_by = ctx.user.id;
    }

    await writeCrmDb(db);
    res.json({ success: true, approved_count: posts.length, posts });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/crm/community-content/scheduled-posts/publish-all", async (req, res) => {
  try {
    const ctx = await ngRequireContentAccess(req, "publish");
    const db = ctx.crmDb;
    const limit = Math.min(50, Math.max(1, Number(req.body?.limit || req.query?.limit || 25)));
    const posts = ngFilterScheduledPostsForBulk(
        ngContentScope(ngContentArray(db, "community_scheduled_posts"), ctx),
        req.body || {},
        req.query || {}
      )
      .filter((post) => !post.deleted_at && ngContentCanPublish(post))
      .filter((post) => !["posted", "published", "publishing"].includes(String(post.status || "").toLowerCase()) && !post.posted_at)
      .slice(0, limit);

    const results = [];
    for (const post of posts) {
      try {
        const publish = await ngPublishScheduledPost(db, post, ctx.user);
        results.push({ id: post.id, success: true, skipped: publish.skipped || false, status: post.status, results: publish.results });
      } catch (error) {
        post.status = "failed";
        post.last_error = error.message;
        post.publish_lock_until = null;
        post.updated_at = nowIso();
        results.push({ id: post.id, success: false, error: error.message });
      }
    }

    await writeCrmDb(db);
    res.json({ success: true, processed: posts.length, results });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/crm/community-content/cleanup-deleted", async (req, res) => {
  try {
    const ctx = await ngRequireContentAccess(req, "schedule");
    const db = ctx.crmDb;
    const hard = req.body?.hard === true || req.query.hard === "true";

    const roadmaps = ngContentArray(db, "community_content_roadmaps");
    const posts = ngContentArray(db, "community_scheduled_posts");
    const hiddenRoadmaps = roadmaps.filter((item) => String(item.status || "").toLowerCase() === "deleted" || item.deleted_at);
    const hiddenRoadmapIds = new Set(hiddenRoadmaps.map((item) => String(item.id || "")).filter(Boolean));
    const hiddenPosts = posts.filter((item) => {
      const status = String(item.status || "").toLowerCase();
      const approval = String(item.approval_status || "").toLowerCase();
      const linkedToDeletedRoadmap = item.roadmap_id && hiddenRoadmapIds.has(String(item.roadmap_id));
      return status === "deleted" || item.deleted_at || status === "rejected" || status === "failed" || status === "error" || approval === "rejected" || linkedToDeletedRoadmap;
    });

    if (hard) {
      const roadIds = new Set(hiddenRoadmaps.map((item) => String(item.id || "")));
      const postIds = new Set(hiddenPosts.map((item) => String(item.id || "")));
      db.community_content_roadmaps = roadmaps.filter((item) => !roadIds.has(String(item.id || "")));
      db.community_scheduled_posts = posts.filter((item) => !postIds.has(String(item.id || "")));
      db.approval_queue = ensureCrmArray(db, "approval_queue").filter((item) => {
        const payload = item.payload || {};
        const linkedPostId = String(item.scheduled_post_id || item.action_id || payload.scheduled_post_id || payload.id || "");
        return !postIds.has(linkedPostId);
      });
    } else {
      for (const post of hiddenPosts) {
        post.status = "deleted";
        post.deleted_at = post.deleted_at || nowIso();
        post.deleted_by = ctx.user.id;
      }
      for (const roadmap of hiddenRoadmaps) {
        roadmap.status = "deleted";
        roadmap.deleted_at = roadmap.deleted_at || nowIso();
        roadmap.deleted_by = ctx.user.id;
      }
    }

    await writeCrmDb(db);
    res.json({ success: true, hard_deleted: hard, roadmaps_matched: hiddenRoadmaps.length, posts_matched: hiddenPosts.length });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

app.post("/admin/crm/community-content/run-due", async (req, res) => {
  try {
    const ctx = await ngRequireContentAccess(req, "publish");
    const db = ctx.crmDb;
    const now = Date.now();

    let due = ngContentArray(db, "community_scheduled_posts")
      .filter((post) => ["scheduled", "ready_to_post"].includes(String(post.status || "").toLowerCase()))
      .filter((post) => post.scheduled_at && new Date(post.scheduled_at).getTime() <= now)
      .filter((post) => ngContentCanPublish(post));

    due = ngContentScope(due, ctx);

    const limit = Math.min(25, Math.max(1, Number(req.body?.limit || req.query?.limit || 10)));
    const selected = due.slice(0, limit);
    const results = [];

    for (const post of selected) {
      try {
        const publish = await ngPublishScheduledPost(db, post, ctx.user);
        results.push({ id: post.id, success: true, status: post.status, results: publish.results });
      } catch (error) {
        post.status = "failed";
        post.last_error = error.message;
        post.updated_at = nowIso();
        results.push({ id: post.id, success: false, error: error.message });
      }
    }

    await writeCrmDb(db);
    res.json({ success: true, processed: selected.length, results });
  } catch (error) {
    res.status(error.statusCode || 500).json({ success: false, error: error.message });
  }
});

