// -----------------------------------------------------------------------------
// DISCORD COMMUNITY POSTING EXTENSION
// Added safely as an extension layer. It does not change Telegram, WhatsApp,
// Stripe, Zoom, LMS demo, or existing CRM flows.
// -----------------------------------------------------------------------------

function getNextGenDiscordWebhookUrl(examTrack = "", fallbackUrl = "") {
  const trackUrl = ngDiscordWebhookUrlForExamTrack(examTrack);
  return (
    fallbackUrl ||
    trackUrl ||
    process.env.DISCORD_STEP1_WEBHOOK_URL ||
    process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL ||
    process.env.DISCORD_WEBHOOK_URL ||
    ""
  );
}

function buildNextGenDiscordMessage(body = {}, sourcePost = null) {
  const rawContent =
    body.content ||
    body.message ||
    body.text ||
    sourcePost?.discord_content ||
    sourcePost?.content ||
    sourcePost?.post_text ||
    sourcePost?.generated_text ||
    sourcePost?.output_text ||
    sourcePost?.caption ||
    "";

  if (String(rawContent || "").trim()) {
    return String(rawContent).trim();
  }

  const title = body.title || sourcePost?.title || "Daily MCQ";
  const topic = body.topic || sourcePost?.topic || "";
  const question = body.question || sourcePost?.question || "";
  const explanation = body.explanation || sourcePost?.explanation || "";
  const answer = body.answer || sourcePost?.answer || sourcePost?.correct_answer || "";
  const cta = body.cta || sourcePost?.cta || "";

  const options = Array.isArray(body.options)
    ? body.options
    : Array.isArray(sourcePost?.options)
      ? sourcePost.options
      : [];

  const lines = [];

  lines.push(`**${title}**`);
  if (topic) lines.push(`Topic: ${topic}`);
  if (question) {
    lines.push("");
    lines.push(question);
  }

  if (options.length) {
    lines.push("");
    for (const option of options) {
      lines.push(String(option));
    }
  }

  if (answer) {
    lines.push("");
    lines.push(`**Answer:** ${answer}`);
  }

  if (explanation) {
    lines.push("");
    lines.push(`**Explanation:** ${explanation}`);
  }

  if (cta) {
    lines.push("");
    lines.push(String(cta));
  }

  if (lines.length <= 1) {
    lines.push("High-yield NextGen medical licensing exam practice post.");
  }

  return lines.join("\n").trim();
}

async function sendNextGenDiscordWebhookMessage({ content, username = "", exam_track = "", webhook_url = "" }) {
  const track = ngNormalizeExamTrack(exam_track);
  const webhookUrl = getNextGenDiscordWebhookUrl(track, webhook_url);
  const finalUsername = username || ngDiscordUsernameForExamTrack(track);

  if (!webhookUrl) {
    const e = new Error("Discord webhook URL is missing. Add DISCORD_STEP1_WEBHOOK_URL / DISCORD_STEP2_CK_WEBHOOK_URL / DISCORD_NCLEX_WEBHOOK_URL / DISCORD_MCCQE_WEBHOOK_URL / DISCORD_AMC_WEBHOOK_URL in Render Environment.");
    e.statusCode = 400;
    throw e;
  }

  const cleanContent = String(content || "").trim();

  if (!cleanContent) {
    const e = new Error("Discord message content is required.");
    e.statusCode = 400;
    throw e;
  }

  // Discord content limit is 2000 chars. Keep a safe margin.
  const finalContent =
    cleanContent.length > 1900
      ? `${cleanContent.slice(0, 1880)}\n\n...(continued in next post)`
      : cleanContent;

  const response = await axios.post(
    webhookUrl,
    {
      username: finalUsername,
      content: finalContent,
      allowed_mentions: { parse: [] },
    },
    {
      headers: { "Content-Type": "application/json" },
      timeout: 30000,
    }
  );

  return {
    status: response.status,
    statusText: response.statusText,
  };
}

