app.post("/admin/crm/leads/:id/flow-status", async (req, res) => {
  try {
    await requireCrmAdmin(req);
    const db = await readCrmDb();
    const lead = getLeadByAnyId(db, req.params.id);
    if (!lead) return res.status(404).json({ success: false, error: "Lead not found" });
    const allowed = ["pending_payment", "payment_promise_date", "payment_promise_note", "payment_followup_status", "added_to_free_community", "free_community_invited", "program_explained", "website_link_sent", "demo_link_sent", "live_session_invited", "session_attended", "session_missed", "recording_sent", "google_meet_requested", "google_meet_booked", "mentor_handoff_needed", "paid", "manual_paid", "unpaid_active", "opted_out", "do_not_message", "admin_suppressed"];
    for (const key of allowed) if (req.body[key] !== undefined) lead[key] = req.body[key];
    if (req.body.labels) ngEnsureLeadFlowLabels(lead, Array.isArray(req.body.labels) ? req.body.labels : normalizeArray(req.body.labels));
    if (lead.payment_promise_date) {
      lead.pending_payment = true;
      lead.payment_followup_status = lead.payment_followup_status || "pending_payment";
      ngEnsureLeadFlowLabels(lead, ["pending_payment", "payment_promise_date", "payment_followup_due"]);
      ensureCrmArray(db, "tasks").push(normalizeCrmCollectionPayload("tasks", {
        title: `Payment follow-up: ${ng41LeadName(lead) || "Student"}`,
        description: lead.payment_promise_note || "Student promised payment. Follow up on promised date.",
        due_at: lead.payment_promise_date,
        lead_id: lead.id,
        task_type: "payment_promise_followup",
        status: "open",
        priority: "high",
      }, null, lead.brand_id || db.settings?.default_brand_id || null));
    }
    if (lead.added_to_free_community) ngEnsureLeadFlowLabels(lead, ["added_to_free_community"]);
    if (lead.paid || lead.manual_paid) {
      lead.stage = "paid_enrolled";
      lead.lead_stage = "paid_enrolled";
      lead.unpaid_active = false;
      lead.exclude_daily_live_session = true;
      ngEnsureLeadFlowLabels(lead, ["paid"]);
    }
    if (lead.opted_out || lead.do_not_message || lead.admin_suppressed) {
      lead.unsubscribe_status = "suppressed";
      lead.suppressed = true;
      ngEnsureLeadFlowLabels(lead, [lead.opted_out ? "opted_out" : "do_not_message"]);
    }
    lead.updated_at = nowIso();
    await writeCrmDb(db);
    res.json({ success: true, lead: ensureLeadIdentityFields(lead) });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});


const NEXTGEN_MASTER_MAP_TEMPLATE_KEY = "nextgen_120_day_usmle_step_1_marathon";

function ngNormalizeMasterMapSystemName(value = "") {
  const raw = String(value || "").trim();
  const clean = raw.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  if (!clean) return "General";
  if (clean.includes("cardio") || clean.includes("heart")) return "Cardiology";
  if (clean === "msk" || clean.includes("musculoskeletal") || clean.includes("bone") || clean.includes("joint")) return "MSK";
  if (clean.includes("central nervous") || clean === "cns" || clean.includes("neuro")) return "Central Nervous System";
  if (clean.includes("repro")) return "Reproductive";
  if (clean.includes("endo")) return "Endocrinology";
  if (clean === "git" || clean.includes("gastro") || clean.includes("gi ") || clean === "gi") return "GIT";
  if (clean.includes("renal") || clean.includes("kidney")) return "Renal";
  if (clean.includes("pulm") || clean.includes("resp")) return "Pulmonology";
  if (clean.includes("immun")) return "Immunology";
  if (clean.includes("hem") || clean.includes("heme")) return "Hematology";
  if (clean.includes("psych")) return "Psychiatry";
  return raw;
}

function ngSystemOrderIndex(system = "") {
  const normalized = ngNormalizeMasterMapSystemName(system);
  const index = NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE.findIndex((item) => item === normalized);
  return index >= 0 ? index : 999;
}

function ngSafeJsonArrayFromBody(value) {
  if (Array.isArray(value)) return value;
  if (value && Array.isArray(value.rows)) return value.rows;
  if (value && Array.isArray(value.days)) return value.days;
  if (typeof value === "string") {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && Array.isArray(parsed.rows)) return parsed.rows;
    if (parsed && Array.isArray(parsed.days)) return parsed.days;
  }
  return [];
}

function ngNormalizeMasterMapRows(value) {
  const rows = ngSafeJsonArrayFromBody(value);
  const systemCounters = new Map();
  return rows.map((row, index) => {
    const dayNumber = Number(row.day_number ?? row.day ?? row.day_no ?? row.order ?? row.sequence ?? index + 1) || (index + 1);
    const system = ngNormalizeMasterMapSystemName(row.system ?? row.chapter ?? row.subject ?? row.organ_system ?? "");
    const topic = String(row.topic ?? row.daily_topic ?? row.title_topic ?? row.focus ?? row.first_aid_topics ?? row.fa_topic ?? "").trim();
    const qids = ngNormalizeQidList(row.uworld_qids ?? row.qids ?? row.question_ids ?? row.qid_list ?? row.uworld_target ?? "");
    const firstAidPages = String(row.first_aid_pages ?? row.fa_pages ?? row.pages ?? row.page_range ?? "").trim();
    const firstAidTopics = String(row.first_aid_topics ?? row.fa_topics ?? row.fa_topic ?? topic ?? "").trim();
    const lectureTitle = String(row.video_library_lecture ?? row.lecture_title ?? row.video_lecture ?? row.library_lecture ?? row.recorded_lecture ?? "").trim();
    const explicitSystemDay = Number(row.system_day ?? row.day_in_system ?? row.systemDay ?? 0) || null;
    const nextSystemDay = Number(systemCounters.get(system) || 0) + 1;
    const systemDay = explicitSystemDay || nextSystemDay;
    systemCounters.set(system, Math.max(nextSystemDay, systemDay));
    const title = String(row.title ?? row.day_title ?? "").trim() || `${system} Day ${systemDay} — ${topic || firstAidTopics || "Daily Review"}`;
    return {
      ...row,
      source_index: index + 1,
      day_number: dayNumber,
      week_number: Number(row.week_number ?? row.week ?? Math.ceil(dayNumber / 7)) || Math.ceil(dayNumber / 7),
      system,
      system_day: systemDay,
      day_in_system: systemDay,
      chapter: String(row.chapter ?? system ?? "").trim() || system,
      topic,
      title,
      description: String(row.description ?? row.summary ?? "").trim(),
      first_aid_pages: firstAidPages || null,
      first_aid_topics: firstAidTopics,
      live_teaching_topic: String(row.live_teaching_topic ?? row.live_topic ?? topic ?? firstAidTopics ?? "").trim(),
      lecture_id: row.lecture_id || row.video_library_lecture_id || row.video_id || null,
      lecture_title: lectureTitle,
      video_library_lecture: lectureTitle,
      uworld_qids: qids,
      mapped_uworld_qids: qids,
      qid_count: Number(row.qid_count ?? qids.length) || qids.length,
      uworld_target: String(row.uworld_target ?? row.uworld_task ?? "").trim() || (qids.length ? `Complete mapped QIDs: ${qids.join(", ")}` : "Complete assigned mapped UWorld QIDs"),
      homework: String(row.homework ?? row.task ?? row.daily_task ?? "").trim(),
      flashcard_tags: normalizeArray(row.flashcard_tags ?? row.tags ?? [system, topic].filter(Boolean)),
      community_prompt: String(row.community_prompt ?? row.qna_prompt ?? "").trim(),
      assessment_task: String(row.assessment_task ?? row.assessment_type ?? "").trim(),
      assessment_day: row.assessment_day === true || String(row.assessment_type || "").toLowerCase().includes("assessment"),
      is_published: row.is_published !== false,
    };
  }).filter((row) => row.system && (row.topic || row.first_aid_topics || row.title || row.uworld_qids.length));
}

function ngNormalizeSystemSequence(values = []) {
  const list = Array.isArray(values) ? values : typeof values === "string" ? values.split(/[\n,>→]+/) : [];
  const normalized = list.map((item) => ngNormalizeMasterMapSystemName(item)).filter(Boolean);
  const unique = [];
  for (const item of normalized) if (!unique.includes(item)) unique.push(item);
  return unique.length ? unique : [...NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE];
}

function ngSystemOrderIndexFromSequence(system = "", sequence = NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE) {
  const normalized = ngNormalizeMasterMapSystemName(system);
  const list = ngNormalizeSystemSequence(sequence);
  const index = list.findIndex((item) => item === normalized);
  return index >= 0 ? index : 999;
}

function ngSortMasterRowsForSequence(rows = [], systemSequence = NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE) {
  return [...rows].sort((a, b) => {
    const ai = ngSystemOrderIndexFromSequence(a.system, systemSequence);
    const bi = ngSystemOrderIndexFromSequence(b.system, systemSequence);
    if (ai !== bi) return ai - bi;
    const ad = Number(a.system_day ?? a.day_in_system ?? a.source_index ?? a.day_number ?? 0) || 0;
    const bd = Number(b.system_day ?? b.day_in_system ?? b.source_index ?? b.day_number ?? 0) || 0;
    return ad - bd;
  });
}

function ngExtractMasterMapSystemSequence(body = {}, rows = []) {
  const explicit = body.system_order || body.system_sequence || body.sequence || body.systems_order;
  if (explicit) return ngNormalizeSystemSequence(explicit);
  const seen = [];
  for (const row of rows || []) {
    const system = ngNormalizeMasterMapSystemName(row.system || row.chapter || row.subject || "");
    if (system && !seen.includes(system)) seen.push(system);
  }
  return seen.length ? seen : [...NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE];
}

function ngGetStoredMasterMapItem(db, template = NEXTGEN_MASTER_MAP_TEMPLATE_KEY) {
  const store = db.roadmapMasterMaps || {};
  return store[String(template || NEXTGEN_MASTER_MAP_TEMPLATE_KEY)] || store[NEXTGEN_MASTER_MAP_TEMPLATE_KEY] || null;
}

function ngGetStoredMasterRows(db, template = NEXTGEN_MASTER_MAP_TEMPLATE_KEY) {
  const item = ngGetStoredMasterMapItem(db, template);
  return ngNormalizeMasterMapRows(item?.rows || []);
}

function ngGetStoredMasterSystemSequence(db, template = NEXTGEN_MASTER_MAP_TEMPLATE_KEY) {
  const item = ngGetStoredMasterMapItem(db, template);
  return ngNormalizeSystemSequence(item?.system_sequence || item?.system_order || NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE);
}

function ngBuildStudyDates(startDateRaw, count, skipSundays = true) {
  const dates = [];
  let cursor = ngNextStudyDate(new Date(`${startDateRaw}T00:00:00`), skipSundays);
  while (dates.length < Number(count || 0)) {
    cursor = ngNextStudyDate(cursor, skipSundays);
    dates.push(dateOnly(cursor));
    cursor.setDate(cursor.getDate() + 1);
  }
  return dates;
}

function ngBuildTaskItemsForMasterDay(row = {}) {
  const base = ngBuildDefaultTaskItems(row);
  const descriptions = {
    live_attendance: "Attend the scheduled live class for this day.",
    video_library_watch: row.video_library_lecture ? `Watch: ${row.video_library_lecture}.` : "Watch the matching video-library lecture when assigned.",
    assigned_qids_completed: row.uworld_qids?.length ? `Complete QIDs: ${row.uworld_qids.join(", ")}.` : "Complete the assigned mapped QIDs.",
    weak_concepts_logged: "Log wrong QIDs or weak concepts after review.",
    flashcards_reviewed: "Review the daily review cards prepared for this topic.",
    community_confusion_post: row.community_prompt || "Post one confusing point in Community Q&A.",
    daily_task_submitted: "Submit the daily task after the study work is finished.",
    assessment_completed: row.assessment_task || "Complete the assigned assessment or correction task.",
  };
  return base.map((item) => ({ ...item, description: descriptions[item.key] || item.description || "" }));
}

function ngBuildMarathonDayFromMasterRow({ courseId, courseName, row, dayNumber, date, classTime, template }) {
  const qids = Array.isArray(row.uworld_qids) ? row.uworld_qids : ngNormalizeQidList(row.uworld_qids || row.mapped_uworld_qids || []);
  const topic = row.topic || row.first_aid_topics || row.system || "Daily Review";
  const readLine = row.first_aid_pages ? `Read assigned book pages: ${row.first_aid_pages}.` : "Read the assigned book pages for today’s topic.";
  const watchLine = row.video_library_lecture ? `Watch matching video-library lecture: ${row.video_library_lecture}.` : "Watch the matching video-library lecture if assigned.";
  const qidLine = qids.length ? `Complete mapped QIDs: ${qids.join(", ")}.` : "Complete the mapped UWorld QIDs assigned for this topic.";
  const description = row.description || `${readLine} ${watchLine} ${qidLine} Review cards and post one confusion point in Community Q&A.`;
  return {
    id: `${courseId}:day:${dayNumber}:${uuid()}`,
    course_id: courseId,
    week_number: Math.ceil(dayNumber / 7),
    day_number: dayNumber,
    date,
    system: row.system,
    chapter: row.chapter || row.system,
    system_day: row.system_day || row.day_in_system || null,
    day_in_system: row.system_day || row.day_in_system || null,
    topic,
    title: ngDayFirstContentTitle(row.title || topic, {
      systemDay: row.system_day || row.day_in_system,
      dayNumber,
      system: row.system,
    }),
    description,
    first_aid_pages: row.first_aid_pages || null,
    first_aid_topics: row.first_aid_topics || topic,
    live_teaching_topic: row.live_teaching_topic || topic,
    lecture_id: row.lecture_id || null,
    lecture_title: row.lecture_title || row.video_library_lecture || "",
    video_library_lecture: row.video_library_lecture || row.lecture_title || "",
    uworld_qids: qids,
    mapped_uworld_qids: qids,
    qid_count: qids.length,
    uworld_target: row.uworld_target || (qids.length ? `Complete mapped QIDs: ${qids.join(", ")}` : "Complete assigned mapped UWorld QIDs"),
    resources: Array.isArray(row.resources) && row.resources.length ? row.resources : ["Assigned book pages", "Mapped UWorld QIDs", "Live class", "Video Library", "Class notes", "Review cards", "Community Q&A"],
    resource_links: Array.isArray(row.resource_links) ? row.resource_links : [],
    homework: row.homework || `${readLine} ${watchLine} ${qidLine}`,
    task_items: ngBuildTaskItemsForMasterDay(row),
    flashcard_tags: row.flashcard_tags || [row.system, topic].filter(Boolean),
    community_prompt: row.community_prompt || "Post one confusing concept from today’s topic.",
    assessment_task: row.assessment_task || "",
    assessment_day: Boolean(row.assessment_day),
    class_time: classTime,
    status: "scheduled",
    roadmap_status: "scheduled",
    is_published: row.is_published !== false,
    source_master_map_index: row.source_index || null,
    template,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

function ngRoadmapDayIsNoClass(day = {}) {
  const status = String(day.status || day.roadmap_status || "").trim().toLowerCase();
  return status === "holiday" || status === "cancelled" || day.is_schedule_placeholder === true;
}

function ngRoadmapSequenceEntries(days = []) {
  let instructionalDay = 0;
  const systemCounters = new Map();

  return (Array.isArray(days) ? days : []).map((day, index) => {
    const noClass = ngRoadmapDayIsNoClass(day);
    const scheduleSlotNumber = index + 1;
    if (noClass) {
      return { day, index, noClass, scheduleSlotNumber, instructionalDayNumber: null, systemDay: null };
    }

    instructionalDay += 1;
    const normalizedSystem = ngNormalizeMasterMapSystemName(day.system || day.chapter || "") || String(day.system || day.chapter || "Unspecified").trim().toLowerCase();
    const systemDay = Number(systemCounters.get(normalizedSystem) || 0) + 1;
    systemCounters.set(normalizedSystem, systemDay);
    return { day, index, noClass, scheduleSlotNumber, instructionalDayNumber: instructionalDay, systemDay };
  });
}

function ngRoadmapCanonicalDayTitle(day = {}) {
  const rawTitle = String(day.title || day.topic || day.first_aid_topics || day.system || "Live Class").trim();
  if (ngRoadmapDayIsNoClass(day)) return rawTitle || "No Live Class";

  const firstAidPages = String(day.first_aid_pages || day.fa_pages || "").trim();
  const titleKey = rawTitle.toLowerCase().replace(/[^a-z0-9]+/g, "");
  const pagesKey = firstAidPages.toLowerCase().replace(/[^a-z0-9]+/g, "");
  const formattedPages = firstAidPages && !/(?:\bfa\b|\bfirst\s+aid\b|\bpp?\.)/i.test(firstAidPages)
    ? `FA pp. ${firstAidPages}`
    : firstAidPages;
  const titleWithPages = formattedPages && pagesKey && !titleKey.includes(pagesKey)
    ? `${rawTitle} — ${formattedPages}`
    : rawTitle;

  return ngDayFirstContentTitle(titleWithPages, {
    systemDay: day.system_day || day.day_in_system,
    dayNumber: day.day_number,
    system: day.system || day.chapter,
  });
}

function ngRoadmapCourseId(roadmap = {}) {
  return String(roadmap.course_id || roadmap.courseId || "").trim();
}

function ngRoadmapClassTime(roadmap = {}, day = {}) {
  return String(
    day.class_time ||
    day.scheduled_time ||
    roadmap.class_time ||
    roadmap.settings?.class_time ||
    "13:00"
  ).trim() || "13:00";
}

function ngRoadmapTimezone(roadmap = {}, day = {}) {
  return String(
    day.scheduled_timezone ||
    roadmap.scheduled_timezone ||
    roadmap.timezone ||
    roadmap.settings?.timezone ||
    DEFAULT_TIMEZONE
  ).trim() || DEFAULT_TIMEZONE;
}

function ngBuildLiveSessionTitleFromRoadmap(db, roadmap = {}, day = {}) {
  return ngRoadmapCanonicalDayTitle(day);
}

function ngCanMoveOrReuseLiveSession(session = {}) {
  const status = String(session.status || "scheduled").trim().toLowerCase();
  if (status === "completed") return false;
  if (session.recording_url || session.recording_id || session.transcript_url) return false;
  return true;
}

function ngGetSessionsByRoadmapDayId(db = {}, courseId = "") {
  const map = new Map();
  for (const session of Object.values(db.liveSessions || {})) {
    if (!session?.id) continue;
    if (courseId && String(session.course_id || "") !== String(courseId)) continue;
    const dayId = String(session.roadmap_day_id || "").trim();
    if (!dayId) continue;
    if (!map.has(dayId)) map.set(dayId, []);
    map.get(dayId).push(session);
  }
  return map;
}

function ngPickRoadmapSessionCandidate(db, roadmap, day, usedSessionIds = new Set(), byRoadmapDayId = new Map()) {
  const courseId = ngRoadmapCourseId(roadmap);
  const candidateIds = [
    day.live_session_id,
    day.session_id,
    day.pushed_live_session_id,
    day.pushed_from_live_session_id,
    day.original_day_snapshot?.live_session_id,
    day.original_day_snapshot?.session_id,
  ].map((value) => String(value || "").trim()).filter(Boolean);

  const pushedFromDayId = String(day.pushed_from_day_id || day.original_day_id || "").trim();
  const candidateSessions = [];

  for (const id of candidateIds) {
    if (db.liveSessions?.[id]) candidateSessions.push(db.liveSessions[id]);
  }

  for (const linkedDayId of [day.id, pushedFromDayId].map((value) => String(value || "").trim()).filter(Boolean)) {
    for (const session of byRoadmapDayId.get(linkedDayId) || []) candidateSessions.push(session);
  }

  const seen = new Set();
  for (const session of candidateSessions) {
    if (!session?.id) continue;
    if (seen.has(session.id)) continue;
    seen.add(session.id);
    if (usedSessionIds.has(session.id)) continue;
    if (courseId && String(session.course_id || "") !== courseId) continue;
    if (ngSessionIsInternalTestOrHidden(session)) continue;

    const sameRoadmapDay = String(session.roadmap_day_id || "") === String(day.id || "");
    const sameScheduledDate = !day.date || String(session.scheduled_date || "") === String(day.date || "");

    // Reuse an already-recorded session only when it is still linked to the same roadmap day/date.
    // This prevents holiday/roadmap sync from creating an empty duplicate for a real recorded day,
    // while still avoiding unsafe movement of old recorded sessions to a new date.
    if (!ngCanMoveOrReuseLiveSession(session) && !(sameRoadmapDay && sameScheduledDate)) continue;
    return session;
  }

  return null;
}

function ngSyncLinkedLiveSessionsForRoadmap(db, roadmap, options = {}) {
  if (!roadmap || !Array.isArray(roadmap.days)) {
    return { synced: 0, created: 0, cancelled: 0, skipped: 0 };
  }

  db.liveSessions = db.liveSessions || {};

  const courseId = ngRoadmapCourseId(roadmap);
  const course = courseId ? db.courses?.[courseId] || null : null;
  const byRoadmapDayId = ngGetSessionsByRoadmapDayId(db, courseId);
  const usedSessionIds = new Set();
  const activeDayIds = new Set();
  const now = new Date().toISOString();
  const counts = { synced: 0, created: 0, cancelled: 0, skipped: 0 };

  // First pass: every scheduled roadmap day must have exactly one live session.
  for (const day of roadmap.days) {
    if (!day?.id) {
      counts.skipped += 1;
      continue;
    }

    if (ngRoadmapDayIsNoClass(day)) {
      day.live_session_id = null;
      day.session_id = null;
      continue;
    }

    activeDayIds.add(String(day.id));

    let session = ngPickRoadmapSessionCandidate(db, roadmap, day, usedSessionIds, byRoadmapDayId);

    if (!session) {
      const sessionId = uuid();
      session = {
        id: sessionId,
        course_id: courseId,
        created_by: options.actorId || options.userId || day.created_by || roadmap.created_by || null,
        created_at: now,
      };
      db.liveSessions[sessionId] = session;
      counts.created += 1;
    }

    const title = ngBuildLiveSessionTitleFromRoadmap(db, roadmap, day);
    const scheduledTime = ngRoadmapClassTime(roadmap, day);
    const timezone = ngRoadmapTimezone(roadmap, day);

    session.course_id = courseId;
    session.topic = title;
    session.title = title;
    session.description = day.description || day.homework || session.description || "";
    session.scheduled_date = day.date || session.scheduled_date || null;
    session.scheduled_time = scheduledTime;
    session.scheduled_timezone = timezone;
    session.duration_minutes = Number(session.duration_minutes || DEFAULT_ZOOM_DURATION_MINUTES) || DEFAULT_ZOOM_DURATION_MINUTES;
    session.instructor_id = session.instructor_id || null;
    session.instructor_name = session.instructor_name || course?.instructor_name || "Dr. Ahmad";
    session.status = String(session.status || "scheduled").toLowerCase() === "completed" ? session.status : "scheduled";
    session.roadmap_day_id = day.id;
    session.day_number = day.day_number || null;
    session.instructional_day_number = day.instructional_day_number || day.day_number || null;
    session.system_day = day.system_day || day.day_in_system || null;
    session.system = day.system || day.chapter || session.system || "";
    session.source = session.source || "roadmap_sync";
    session.updated_by = options.actorId || options.userId || session.updated_by || null;
    session.updated_at = now;

    day.live_session_id = session.id;
    day.session_id = session.id;
    day.scheduled_date = day.date || day.scheduled_date || null;
    day.scheduled_time = scheduledTime;
    day.class_time = scheduledTime;
    day.updated_at = now;

    usedSessionIds.add(session.id);
    counts.synced += 1;
  }

  // Second pass: holiday/cancelled placeholder days must not keep an active classroom.
  for (const day of roadmap.days) {
    if (!day?.id || !ngRoadmapDayIsNoClass(day)) continue;

    const candidateIds = [day.live_session_id, day.session_id]
      .map((value) => String(value || "").trim())
      .filter(Boolean);

    for (const linkedSession of byRoadmapDayId.get(String(day.id)) || []) {
      if (linkedSession?.id) candidateIds.push(linkedSession.id);
    }

    for (const sessionId of Array.from(new Set(candidateIds))) {
      const session = db.liveSessions?.[sessionId];
      if (!session?.id) continue;
      if (usedSessionIds.has(session.id)) continue;
      if (String(session.course_id || "") !== courseId) continue;
      if (!ngCanMoveOrReuseLiveSession(session)) continue;

      session.status = "cancelled";
      session.cancelled_reason = day.status === "holiday" ? "roadmap_holiday" : "roadmap_cancelled";
      session.archived_from_active = true;
      session.no_class_placeholder = true;
      session.roadmap_day_id = day.id;
      session.day_number = null;
      session.instructional_day_number = null;
      session.system_day = null;
      session.scheduled_date = day.date || session.scheduled_date || null;
      session.scheduled_time = ngRoadmapClassTime(roadmap, day);
      session.scheduled_timezone = ngRoadmapTimezone(roadmap, day);
      session.title = ngBuildLiveSessionTitleFromRoadmap(db, roadmap, day);
      session.topic = session.title;
      session.updated_by = options.actorId || options.userId || session.updated_by || null;
      session.updated_at = now;
      counts.cancelled += 1;
    }

    day.live_session_id = null;
    day.session_id = null;
    day.updated_at = now;
  }

  roadmap.updated_at = now;
  return counts;
}


function ngClearNoClassRoadmapFields(day = {}) {
  const clearValues = {
    resources: [],
    resource_links: [],
    uworld_qids: [],
    mapped_uworld_qids: [],
    qid_list: [],
    qids: [],
    uworld_target: "",
    homework: "",
    task_items: [],
    tasks: [],
    first_aid_topics: "",
    first_aid_pages: null,
    video_library_lecture: "",
    lecture_title: "",
    live_teaching_topic: "",
    assessment_task: "",
    assessment_day: false,
    assessment_id: null,
    weekly_assessment_id: null,
    weekly_assessment_ready: false,
    grand_assessment_id: null,
    grand_assessment_ready: false,
    live_session_id: null,
    session_id: null,
    session_notes_id: null,
    session_notes_ready: false,
    session_notes_draft_ready: false,
    notes_status: "",
    recording_link: "",
    notes_link: "",
    session_flashcards_ready: false,
    session_flashcards_draft_ready: false,
    session_flashcards_count: 0,
    session_flashcards_draft_count: 0,
    flashcard_tags: [],
    flashcards_enabled: false,
    community_prompt: "",
  };

  for (const [key, value] of Object.entries(clearValues)) {
    day[key] = Array.isArray(value) ? [...value] : value;
  }

  return day;
}

function ngReplaceRoadmapDayIdList(values, fromDayId, toDayId) {
  if (!Array.isArray(values)) return values;
  return Array.from(new Set(values.map((item) => String(item || "") === String(fromDayId) ? toDayId : item).filter(Boolean)));
}

function ngRelinkRoadmapDayDependencies(db, { courseId = "", fromDayId = "", toDay = null, actorId = null } = {}) {
  const cleanCourseId = String(courseId || "").trim();
  const oldDayId = String(fromDayId || "").trim();
  const newDayId = String(toDay?.id || "").trim();
  const now = new Date().toISOString();
  const counts = {
    flashcards: 0,
    flashcard_progress: 0,
    assessments: 0,
    assessment_attempts: 0,
    notes: 0,
    roadmap_progress: 0,
    daily_task_progress: 0,
    point_events: 0,
    weak_concepts: 0,
    leaderboards_rebuilt: 0,
  };
  const affectedUsers = new Set();

  if (!oldDayId || !newDayId || oldDayId === newDayId) return counts;

  const courseMatches = (item = {}) => {
    if (!cleanCourseId) return true;
    const itemCourseId = String(item.course_id || item.courseId || "").trim();
    return !itemCourseId || itemCourseId === cleanCourseId;
  };

  const relinkDayFields = (item = {}) => {
    let changed = false;
    if (String(item.roadmap_day_id || "") === oldDayId) {
      item.roadmap_day_id = newDayId;
      changed = true;
    }
    if (String(item.day_id || "") === oldDayId) {
      item.day_id = newDayId;
      changed = true;
    }
    if (Array.isArray(item.source_roadmap_day_ids)) {
      const next = ngReplaceRoadmapDayIdList(item.source_roadmap_day_ids, oldDayId, newDayId);
      if (JSON.stringify(next) !== JSON.stringify(item.source_roadmap_day_ids)) {
        item.source_roadmap_day_ids = next;
        changed = true;
      }
    }
    return changed;
  };

  const applySequenceFields = (item = {}) => {
    item.day_number = toDay.day_number || null;
    item.instructional_day_number = toDay.instructional_day_number || toDay.day_number || null;
    item.system_day = toDay.system_day || toDay.day_in_system || null;
    item.day_in_system = toDay.system_day || toDay.day_in_system || null;
    item.system = toDay.system || toDay.chapter || item.system || "";
  };

  for (const card of Object.values(db.flashcards || {})) {
    if (!card?.id || !courseMatches(card)) continue;
    if (!relinkDayFields(card)) continue;
    applySequenceFields(card);
    card.scheduled_date = toDay.date || card.scheduled_date || null;
    card.due_date = card.due_date && String(card.due_date) === String(toDay.original_day_snapshot?.date || "") ? toDay.date : (card.due_date || toDay.date || null);
    card.updated_by = actorId || card.updated_by || null;
    card.updated_at = now;
    counts.flashcards += 1;
  }

  for (const item of Object.values(db.flashcardProgress || {})) {
    if (!item || !courseMatches(item)) continue;
    if (!relinkDayFields(item)) continue;
    applySequenceFields(item);
    if (item.user_id) affectedUsers.add(String(item.user_id));
    item.updated_at = now;
    counts.flashcard_progress += 1;
  }

  for (const assessment of Object.values(db.assessments || {})) {
    if (!assessment?.id || !courseMatches(assessment)) continue;
    if (!relinkDayFields(assessment)) continue;
    applySequenceFields(assessment);
    assessment.title = ngDayFirstContentTitle(assessment.title, { systemDay: assessment.system_day, dayNumber: assessment.day_number, system: assessment.system });
    assessment.updated_by = actorId || assessment.updated_by || null;
    assessment.updated_at = now;
    counts.assessments += 1;
  }

  for (const attempt of Object.values(db.assessmentAttempts || {})) {
    if (!attempt || !courseMatches(attempt)) continue;
    if (!relinkDayFields(attempt)) continue;
    applySequenceFields(attempt);
    if (attempt.user_id) affectedUsers.add(String(attempt.user_id));
    attempt.updated_at = now;
    counts.assessment_attempts += 1;
  }

  for (const note of Object.values(db.notes || {})) {
    if (!note || !courseMatches(note)) continue;
    if (!relinkDayFields(note)) continue;
    applySequenceFields(note);
    note.updated_by = actorId || note.updated_by || null;
    note.updated_at = now;
    counts.notes += 1;
  }

  const rekeyBucketByDay = (bucketName) => {
    const bucket = db[bucketName] || {};
    const nextEntries = [];
    for (const [id, item] of Object.entries(bucket)) {
      if (!item || !courseMatches(item)) continue;
      const matches = String(item.day_id || item.roadmap_day_id || "") === oldDayId || String(id).includes(oldDayId);
      if (!matches) continue;
      relinkDayFields(item);
      applySequenceFields(item);
      item.updated_at = now;
      if (item.user_id) affectedUsers.add(String(item.user_id));

      let nextId = String(item.id || id).replace(oldDayId, newDayId);
      if (nextId === String(item.id || id) && cleanCourseId && item.user_id) nextId = `${cleanCourseId}:${item.user_id}:${newDayId}`;
      item.id = nextId;
      nextEntries.push([id, nextId, item]);
    }

    for (const [oldKey, newKey, item] of nextEntries) {
      if (oldKey !== newKey) {
        if (bucket[newKey]) {
          bucket[newKey] = {
            ...bucket[newKey],
            ...item,
            tasks: { ...(bucket[newKey].tasks || {}), ...(item.tasks || {}) },
            updated_at: now,
          };
        } else {
          bucket[newKey] = item;
        }
        delete bucket[oldKey];
      } else {
        bucket[oldKey] = item;
      }
    }

    db[bucketName] = bucket;
    return nextEntries.length;
  };

  counts.roadmap_progress += rekeyBucketByDay("roadmapProgress");
  counts.daily_task_progress += rekeyBucketByDay("dailyTaskProgress");

  for (const event of Object.values(db.pointEvents || {})) {
    if (!event || !courseMatches(event)) continue;
    if (!relinkDayFields(event)) continue;
    applySequenceFields(event);
    event.updated_at = now;
    if (event.user_id) affectedUsers.add(String(event.user_id));
    counts.point_events += 1;
  }

  for (const weak of Object.values(db.weakConceptLogs || {})) {
    if (!weak || !courseMatches(weak)) continue;
    if (!relinkDayFields(weak)) continue;
    applySequenceFields(weak);
    weak.updated_at = now;
    if (weak.user_id) affectedUsers.add(String(weak.user_id));
    counts.weak_concepts += 1;
  }

  if (cleanCourseId) {
    for (const userId of affectedUsers) {
      const user = db.users?.[userId] || null;
      updateLeaderboard(db, { courseId: cleanCourseId, userId, userName: user?.name || user?.email || "Student" });
      counts.leaderboards_rebuilt += 1;
    }
  }

  return counts;
}

function ngRoadmapActiveScheduleException(roadmap = {}, day = {}) {
  const exceptions = Array.isArray(roadmap.schedule_exceptions)
    ? roadmap.schedule_exceptions
    : Array.isArray(roadmap.settings?.schedule_exceptions)
      ? roadmap.settings.schedule_exceptions
      : [];

  return exceptions.find((item) => {
    return item?.active !== false &&
      String(item.anchor_day_id || item.day_id || "") === String(day.id || "") &&
      /^\d{4}-\d{2}-\d{2}$/.test(String(item.override_date || item.move_to_date || ""));
  }) || null;
}

function ngReplaceScheduledDateValue(value, fromDate, toDate) {
  if (typeof value !== "string" || !fromDate || !toDate) return { changed: false, value };
  if (value === fromDate) return { changed: true, value: toDate };
  if (value.startsWith(`${fromDate}T`)) return { changed: true, value: `${toDate}${value.slice(fromDate.length)}` };
  return { changed: false, value };
}

function ngShiftLinkedScheduleMetadata(db, { courseId = "", day = null, fromDate = "", toDate = "", actorId = null } = {}) {
  const cleanCourseId = String(courseId || "").trim();
  const dayId = String(day?.id || "").trim();
  const sessionIds = new Set([
    day?.live_session_id,
    day?.session_id,
    day?.pushed_live_session_id,
    day?.pushed_from_live_session_id,
  ].map((value) => String(value || "").trim()).filter(Boolean));
  const now = new Date().toISOString();
  const scheduleFields = [
    "date",
    "scheduled_date",
    "schedule_date",
    "assignment_date",
    "available_date",
    "target_date",
    "due_date",
    "scheduled_for",
    "starts_at",
    "start_at",
    "opens_at",
    "available_at",
    "due_at",
    "ends_at",
    "closes_at",
    "deadline",
  ];
  const buckets = [
    "flashcards",
    "flashcardProgress",
    "assessments",
    "assessmentAttempts",
    "notes",
    "recordings",
    "roadmapProgress",
    "dailyTaskProgress",
    "pointEvents",
    "weakConceptLogs",
    "adaptiveAssignments",
    "adaptiveFlashcardQueues",
  ];
  const counts = Object.fromEntries(buckets.map((key) => [key, 0]));

  const isLinked = (item = {}, key = "") => {
    const itemCourseId = String(item.course_id || item.courseId || "").trim();
    if (itemCourseId && cleanCourseId && itemCourseId !== cleanCourseId) return false;
    if (String(item.roadmap_day_id || "") === dayId) return true;
    if (String(item.day_id || "") === dayId) return true;
    if (Array.isArray(item.source_roadmap_day_ids) && item.source_roadmap_day_ids.some((id) => String(id || "") === dayId)) return true;
    if (sessionIds.has(String(item.session_id || item.live_session_id || ""))) return true;
    return Boolean(dayId && String(key || "").includes(dayId));
  };

  for (const bucketName of buckets) {
    const bucket = db[bucketName] || {};
    for (const [key, item] of Object.entries(bucket)) {
      if (!item || typeof item !== "object" || !isLinked(item, key)) continue;
      let changed = false;
      for (const field of scheduleFields) {
        if (item[field] === undefined || item[field] === null) continue;
        const replacement = ngReplaceScheduledDateValue(item[field], fromDate, toDate);
        if (!replacement.changed) continue;
        item[field] = replacement.value;
        changed = true;
      }
      if (!changed) continue;
      item.updated_by = actorId || item.updated_by || null;
      item.updated_at = now;
      counts[bucketName] += 1;
    }
  }

  return counts;
}

function ngSyncRoadmapSequenceMetadata(db, roadmap, { actorId = null } = {}) {
  if (!roadmap || !Array.isArray(roadmap.days)) return { changed: 0, buckets: {} };

  const courseId = ngRoadmapCourseId(roadmap);
  const activeDays = roadmap.days.filter((day) => day?.id && !ngRoadmapDayIsNoClass(day));
  const dayById = new Map(activeDays.map((day) => [String(day.id), day]));
  const dayBySessionId = new Map();

  for (const day of activeDays) {
    for (const sessionId of [day.live_session_id, day.session_id]) {
      if (sessionId) dayBySessionId.set(String(sessionId), day);
    }
  }
  for (const session of Object.values(db.liveSessions || {})) {
    const day = dayById.get(String(session?.roadmap_day_id || ""));
    if (day && session?.id) dayBySessionId.set(String(session.id), day);
  }

  const assessmentDayById = new Map();
  for (const assessment of Object.values(db.assessments || {})) {
    const day = dayById.get(String(assessment?.roadmap_day_id || assessment?.day_id || "")) ||
      dayBySessionId.get(String(assessment?.session_id || ""));
    if (day && assessment?.id) assessmentDayById.set(String(assessment.id), day);
  }

  const resolveDay = (item = {}, key = "") => {
    const itemCourseId = String(item.course_id || item.courseId || "").trim();
    if (courseId && itemCourseId && itemCourseId !== courseId) return null;

    for (const id of [item.roadmap_day_id, item.day_id]) {
      const day = dayById.get(String(id || ""));
      if (day) return day;
    }
    for (const id of Array.isArray(item.source_roadmap_day_ids) ? item.source_roadmap_day_ids : []) {
      const day = dayById.get(String(id || ""));
      if (day) return day;
    }
    for (const id of [item.session_id, item.live_session_id, key]) {
      const day = dayBySessionId.get(String(id || ""));
      if (day) return day;
    }
    const assessmentDay = assessmentDayById.get(String(item.assessment_id || ""));
    if (assessmentDay) return assessmentDay;
    return null;
  };

  const bucketNames = [
    "flashcards",
    "flashcardProgress",
    "assessments",
    "assessmentAttempts",
    "notes",
    "recordings",
    "roadmapProgress",
    "dailyTaskProgress",
    "pointEvents",
    "weakConceptLogs",
    "adaptiveAssignments",
    "adaptiveFlashcardQueues",
    "attendance",
  ];
  const counts = Object.fromEntries(bucketNames.map((name) => [name, 0]));
  const now = new Date().toISOString();
  let changedTotal = 0;

  for (const bucketName of bucketNames) {
    for (const [key, item] of Object.entries(db[bucketName] || {})) {
      if (!item || typeof item !== "object") continue;
      const day = resolveDay(item, key);
      if (!day) continue;

      const wanted = {
        day_number: day.day_number || null,
        instructional_day_number: day.instructional_day_number || day.day_number || null,
        system_day: day.system_day || day.day_in_system || null,
        day_in_system: day.system_day || day.day_in_system || null,
        system: day.system || day.chapter || "",
      };
      let changed = false;
      for (const [field, value] of Object.entries(wanted)) {
        if (item[field] === value) continue;
        item[field] = value;
        changed = true;
      }

      if (bucketName === "assessments" && item.title) {
        const title = ngDayFirstContentTitle(item.title, { systemDay: wanted.system_day, dayNumber: wanted.day_number, system: wanted.system });
        if (title && title !== item.title) {
          item.title = title;
          changed = true;
        }
      }
      if (bucketName === "recordings" && item.topic) {
        const topic = ngDayFirstContentTitle(item.topic, { systemDay: wanted.system_day, dayNumber: wanted.day_number, system: wanted.system });
        if (topic && topic !== item.topic) {
          item.topic = topic;
          changed = true;
        }
      }

      if (!changed) continue;
      item.sequence_metadata_updated_at = now;
      item.sequence_metadata_updated_by = actorId || item.sequence_metadata_updated_by || null;
      counts[bucketName] += 1;
      changedTotal += 1;
    }
  }

  return { changed: changedTotal, buckets: counts };
}

function ngRecalculateRoadmapSchedule(db, roadmap, { startDate = "", skipSundays = true, actorId = null } = {}) {
  if (!roadmap || !Array.isArray(roadmap.days) || !roadmap.days.length) return roadmap;
  const firstDate = startDate || roadmap.start_date || roadmap.settings?.start_date || roadmap.days[0]?.date || todayKey();
  let cursor = ngNextStudyDate(new Date(`${firstDate}T00:00:00`), skipSundays);
  const sequenceEntries = ngRoadmapSequenceEntries(roadmap.days);
  sequenceEntries.forEach(({ day, scheduleSlotNumber, instructionalDayNumber, systemDay, noClass }) => {
    cursor = ngNextStudyDate(cursor, skipSundays);
    const scheduleException = ngRoadmapActiveScheduleException(roadmap, day);
    const scheduledDate = String(scheduleException?.override_date || scheduleException?.move_to_date || "").trim();
    const effectiveCursor = scheduledDate ? new Date(`${scheduledDate}T00:00:00`) : new Date(cursor);
    day.schedule_slot_number = scheduleSlotNumber;
    day.order = scheduleSlotNumber;
    day.day_number = noClass ? null : instructionalDayNumber;
    day.instructional_day_number = noClass ? null : instructionalDayNumber;
    day.system_day = noClass ? null : systemDay;
    day.day_in_system = noClass ? null : systemDay;
    day.week_number = noClass ? Math.ceil(scheduleSlotNumber / 7) : Math.ceil(instructionalDayNumber / 7);
    day.date = dateOnly(effectiveCursor);
    day.scheduled_date = day.date;
    day.schedule_exception_id = scheduleException?.id || null;
    day.schedule_exception_active = Boolean(scheduleException);
    if (!noClass) day.title = ngRoadmapCanonicalDayTitle(day);
    day.updated_at = new Date().toISOString();
    cursor = new Date(effectiveCursor);
    cursor.setDate(cursor.getDate() + 1);
  });
  const activeCount = sequenceEntries.filter((entry) => !entry.noClass).length;
  roadmap.instructional_days = activeCount;
  roadmap.schedule_slots = roadmap.days.length;
  roadmap.settings = roadmap.settings || {};
  roadmap.settings.duration_days = activeCount;
  roadmap.settings.schedule_slots = roadmap.days.length;
  roadmap.sequence_metadata_sync = ngSyncRoadmapSequenceMetadata(db, roadmap, { actorId });
  ngSyncLinkedLiveSessionsForRoadmap(db, roadmap, { actorId });
  roadmap.updated_at = new Date().toISOString();
  return roadmap;
}

function ngKnownScheduleDate(value) {
  return String(value || "").trim().slice(0, 10);
}

function ngKnownScheduleSessionHasRecording(db, session = {}) {
  const sessionId = String(session.id || "").trim();
  if (!sessionId) return false;
  if (session.recording_url || session.recording_key || session.recording_id || session.transcript_url) return true;
  return Object.values(db.recordings || {}).some((recording) => {
    return recording?.published === true && String(recording.session_id || "").trim() === sessionId;
  });
}

function ngKnownScheduleDayAt(roadmap = {}, date = "") {
  return (roadmap.days || []).find((day) => ngKnownScheduleDate(day.date || day.scheduled_date) === date) || null;
}

function ngKnownScheduleIsMskDay(day = {}, systemDay) {
  const system = ngNormalizeMasterMapSystemName(day.system || day.chapter || "");
  return system === "MSK" && Number(day.system_day || day.day_in_system || 0) === Number(systemDay);
}

function ngKnownScheduleRecordingAttachment(recording = {}) {
  return {
    recording_key: String(recording.recording_key || recording.id || ""),
    meeting_id: String(recording.meeting_id || ""),
    session_id: String(recording.session_id || ""),
    recording_url: String(recording.recording_url || ""),
    share_url: String(recording.share_url || ""),
    transcript_url: String(recording.transcript_url || ""),
    transcript_download_url: String(recording.transcript_download_url || ""),
    published: recording.published === true,
  };
}

function ngKnownScheduleAttachmentsEqual(before = {}, after = {}) {
  return Object.entries(before).every(([key, value]) => {
    if (key === "published") return after.published === value;
    return String(after[key] || "") === String(value || "");
  });
}

function ngReconcileKnownMskMissedHolidaySchedule(db = {}, {
  actorId = "system:known-missed-holiday-schedule-repair",
  now = new Date().toISOString(),
} = {}) {
  const rule = NEXTGEN_MSK_2026_07_29_SCHEDULE_REPAIR;
  const protectedBuckets = [
    "users", "enrollments", "payments", "plans", "recordings", "notes", "flashcards",
    "flashcardProgress", "assessments", "assessmentAttempts", "roadmapProgress",
    "dailyTaskProgress", "pointEvents", "weakConceptLogs", "adaptiveAssignments",
    "adaptiveFlashcardQueues", "attendance", "leaderboard", "liveSessions",
  ];
  const result = {
    build: LMS_KNOWN_SCHEDULE_REPAIR_BUILD,
    checked: true,
    changed: false,
    repaired: false,
    already_correct: false,
    safe_stop: false,
    course_id: rule.course_id,
    holiday_date: rule.holiday_date,
    taught_date: rule.taught_date,
    current_date: rule.current_date,
    current_system_day: null,
    final_teaching_date: null,
    recording_preserved: false,
    recording_session_preserved: false,
    session_ids_preserved: false,
    session_urls_preserved: false,
    roadmap_days_preserved: false,
    restored_prefix_days: 0,
    live_sessions_reused_by_date: 0,
    new_tail_sessions_created: 0,
    redundant_sessions_archived: 0,
    deleted_records: 0,
    reason: null,
  };

  const safeStop = (reason) => {
    result.safe_stop = true;
    result.reason = reason;
    return result;
  };
  const normalizedPages = (value) => String(value || "")
    .replace(/\b20\d{2}\b/g, "")
    .match(/\d+/g)?.join("-") || "";
  const identityAndUrls = (item = {}) => {
    const snapshot = {};
    for (const [key, value] of Object.entries(item || {})) {
      if (
        key === "id" || key === "recording_key" || key === "recording_id" ||
        key === "meeting_id" || key === "zoom_meeting_id" || key === "session_id" ||
        key.endsWith("_url") || key.endsWith("_urls")
      ) snapshot[key] = value ?? null;
    }
    return snapshot;
  };
  const sameSnapshot = (left, right) => JSON.stringify(left) === JSON.stringify(right);
  const setDayDate = (day, date) => {
    day.date = date;
    day.scheduled_date = date;
    day.updated_by = actorId;
    day.updated_at = now;
  };
  const nextScheduleDate = (date) => {
    const cursor = new Date(`${date}T00:00:00Z`);
    do cursor.setUTCDate(cursor.getUTCDate() + 1);
    while (cursor.getUTCDay() === 0);
    return cursor.toISOString().slice(0, 10);
  };

  const roadmapEntry = Object.entries(db.roadmaps || {}).find(([key, item]) => (
    String(key) === rule.course_id || String(item?.course_id || item?.courseId || "") === rule.course_id
  ));
  const roadmapKey = roadmapEntry?.[0] || rule.course_id;
  const roadmap = roadmapEntry?.[1] || null;
  if (!roadmap || !Array.isArray(roadmap.days) || !roadmap.days.length) {
    result.reason = "roadmap_not_found";
    return result;
  }

  db.liveSessions = db.liveSessions || {};
  db.recordings = db.recordings || {};
  const dayById = new Map(roadmap.days.map((day) => [String(day?.id || ""), day]));
  const prefixRows = rule.prefix_rows.map((row) => ({ ...row, day: dayById.get(row.day_id) || null }));
  const mskRows = rule.msk_rows.map((row) => ({ ...row, day: dayById.get(row.day_id) || null }));
  const holidayDay = dayById.get(rule.holiday_day_id) || null;
  const exactRecording = db.recordings[rule.recording_key] || null;
  const exactSession = db.liveSessions[rule.taught_session_id] || null;

  const missing = [
    ...prefixRows.filter((row) => !row.day).map((row) => `prefix_day:${row.day_id}`),
    ...mskRows.filter((row) => !row.day).map((row) => `msk_day:${row.system_day}`),
    !holidayDay ? "holiday_day" : null,
    !exactSession ? "recorded_session" : null,
    !exactRecording ? "recording" : null,
  ].filter(Boolean);
  if (missing.length) return safeStop(`known_records_missing:${missing.join(",")}`);

  for (const row of prefixRows) {
    if (row.holiday && !ngRoadmapDayIsNoClass(row.day)) return safeStop(`prefix_holiday_precondition_failed:${row.day_id}`);
    if (row.session_id && !db.liveSessions[row.session_id]) return safeStop(`prefix_session_missing:${row.session_id}`);
  }
  for (const row of mskRows) {
    if (normalizedPages(row.day.first_aid_pages || row.day.fa_pages || row.day.first_aid_topics) !== row.pages) {
      return safeStop(`msk_packet_precondition_failed:day_${row.system_day}`);
    }
    if (row.session_id && !db.liveSessions[row.session_id]) return safeStop(`msk_session_missing:${row.session_id}`);
  }

  const recordingBefore = ngKnownScheduleRecordingAttachment(exactRecording);
  if (
    recordingBefore.recording_key !== rule.recording_key ||
    recordingBefore.session_id !== rule.taught_session_id ||
    ngKnownScheduleDate(exactRecording.start_time) !== rule.taught_date ||
    recordingBefore.published !== true ||
    !recordingBefore.recording_url
  ) return safeStop("recording_precondition_failed");

  const prefixAlreadyCorrect = prefixRows.every((row) => (
    ngKnownScheduleDate(row.day.date || row.day.scheduled_date) === row.date &&
    (row.holiday || String(row.day.live_session_id || row.day.session_id || "") === String(row.session_id || ""))
  ));
  const mskAlreadyCorrect = mskRows.every((row) => (
    ngKnownScheduleDate(row.day.date || row.day.scheduled_date) === row.date &&
    ngKnownScheduleIsMskDay(row.day, row.system_day)
  ));
  const scheduleAlreadyCorrect = Boolean(
    prefixAlreadyCorrect &&
    mskAlreadyCorrect &&
    ngKnownScheduleDate(holidayDay.date || holidayDay.scheduled_date) === rule.holiday_date &&
    ngRoadmapDayIsNoClass(holidayDay) &&
    String(mskRows[3].day.live_session_id || mskRows[3].day.session_id || "") === rule.taught_session_id &&
    String(mskRows[4].day.live_session_id || mskRows[4].day.session_id || "") === rule.current_session_id &&
    String(exactSession.roadmap_day_id || "") === rule.moved_day_id &&
    String(exactRecording.session_id || "") === rule.taught_session_id
  );
  if (scheduleAlreadyCorrect) {
    const teachingDays = roadmap.days.filter((day) => !ngRoadmapDayIsNoClass(day));
    result.already_correct = true;
    result.recording_preserved = true;
    result.recording_session_preserved = true;
    result.session_ids_preserved = true;
    result.session_urls_preserved = true;
    result.roadmap_days_preserved = true;
    result.current_system_day = 5;
    result.final_teaching_date = teachingDays.map((day) => ngKnownScheduleDate(day.date)).sort().at(-1) || null;
    result.reason = "already_correct";
    return result;
  }

  const expectedPrefixIds = new Set(prefixRows.map((row) => row.day_id));
  const expectedMskIds = new Set(mskRows.map((row) => row.day_id));
  const knownIds = new Set([...expectedPrefixIds, ...expectedMskIds, rule.holiday_day_id]);
  const suffixDays = roadmap.days.filter((day) => !knownIds.has(String(day?.id || "")));
  if (suffixDays.some((day) => ngKnownScheduleDate(day.date || day.scheduled_date) < "2026-08-11")) {
    return safeStop("unexpected_day_outside_known_recovery_span");
  }

  const originalRoadmapDayIds = roadmap.days.map((day) => String(day?.id || ""));
  const originalSessionIds = Object.keys(db.liveSessions);
  const originalSessionSnapshots = new Map(originalSessionIds.map((id) => [id, identityAndUrls(db.liveSessions[id])]));
  const originalRecordingSnapshots = new Map(Object.entries(db.recordings).map(([id, recording]) => [id, identityAndUrls(recording)]));
  const originalCounts = Object.fromEntries(protectedBuckets.map((name) => [name, Object.keys(db[name] || {}).length]));
  const originalDateByDayId = new Map(roadmap.days.map((day) => [String(day?.id || ""), ngKnownScheduleDate(day.date || day.scheduled_date)]));
  const originalPrimarySessionByDayId = new Map(roadmap.days.map((day) => [
    String(day?.id || ""),
    String(day?.live_session_id || day?.session_id || "").trim(),
  ]));

  const desiredMskOrder = [mskRows[0].day, mskRows[1].day, mskRows[2].day, holidayDay, ...mskRows.slice(3).map((row) => row.day)];
  const desiredRoadmapDays = [...prefixRows.map((row) => row.day), ...desiredMskOrder, ...suffixDays];
  roadmap.days = desiredRoadmapDays;

  for (const row of prefixRows) setDayDate(row.day, row.date);
  for (const row of mskRows) {
    Object.assign(row.day, {
      course_id: rule.course_id,
      status: "scheduled",
      roadmap_status: "scheduled",
      is_schedule_placeholder: false,
    });
    delete row.day.pushed_content_day_id;
    setDayDate(row.day, row.date);
  }

  const day4 = mskRows[3].day;
  const holidaySnapshot = holidayDay.original_day_snapshot || JSON.parse(JSON.stringify(day4));
  ngClearNoClassRoadmapFields(holidayDay);
  Object.assign(holidayDay, {
    course_id: rule.course_id,
    title: "Holiday / No Live Class",
    description: "No live class was held on 29 July 2026. The MSK teaching sequence is pushed by one teaching day.",
    status: "holiday",
    roadmap_status: "holiday",
    is_schedule_placeholder: true,
    pushed_content_day_id: day4.id,
    original_day_snapshot: holidaySnapshot,
    live_session_id: null,
    session_id: null,
    updated_by: actorId,
    updated_at: now,
  });
  setDayDate(holidayDay, rule.holiday_date);
  Object.assign(day4, {
    pushed_from_day_id: rule.holiday_day_id,
    original_day_id: rule.holiday_day_id,
  });

  let cursorDate = mskRows.at(-1).date;
  for (const day of suffixDays) {
    cursorDate = nextScheduleDate(cursorDate);
    setDayDate(day, cursorDate);
  }

  // Reassert the content order after the legacy holiday snapshots have been
  // normalized. Some historical rows retain stale order fields, so array order
  // is the only schedule source of truth for the transactional recovery.
  roadmap.days = desiredRoadmapDays;
  const sequenceEntries = ngRoadmapSequenceEntries(roadmap.days);
  for (const { day, scheduleSlotNumber, instructionalDayNumber, systemDay, noClass } of sequenceEntries) {
    day.schedule_slot_number = scheduleSlotNumber;
    day.order = scheduleSlotNumber;
    day.day_number = noClass ? null : instructionalDayNumber;
    day.instructional_day_number = noClass ? null : instructionalDayNumber;
    day.system_day = noClass ? null : systemDay;
    day.day_in_system = noClass ? null : systemDay;
    day.week_number = noClass ? Math.ceil(scheduleSlotNumber / 7) : Math.ceil(instructionalDayNumber / 7);
    if (!noClass) day.title = ngRoadmapCanonicalDayTitle(day);
    day.updated_by = actorId;
    day.updated_at = now;
  }

  const shiftedScheduleMetadata = {};
  for (const day of roadmap.days) {
    const beforeDate = originalDateByDayId.get(String(day.id || "")) || "";
    const afterDate = ngKnownScheduleDate(day.date || day.scheduled_date);
    if (!beforeDate || !afterDate || beforeDate === afterDate) continue;
    const partial = ngShiftLinkedScheduleMetadata(db, {
      courseId: rule.course_id,
      day,
      fromDate: beforeDate,
      toDate: afterDate,
      actorId,
    });
    for (const [name, count] of Object.entries(partial)) {
      shiftedScheduleMetadata[name] = Number(shiftedScheduleMetadata[name] || 0) + Number(count || 0);
    }
  }

  const selectedSessionByDayId = new Map();
  for (const row of prefixRows) {
    if (row.session_id) selectedSessionByDayId.set(row.day_id, row.session_id);
  }
  for (const row of mskRows.slice(0, 4)) selectedSessionByDayId.set(row.day_id, row.session_id);

  const tailActiveDays = [mskRows[4].day, ...mskRows.slice(5).map((row) => row.day), ...suffixDays]
    .filter((day) => day?.id && !ngRoadmapDayIsNoClass(day));
  if (tailActiveDays.length < 2) return safeStop("tail_schedule_precondition_failed");
  selectedSessionByDayId.set(String(tailActiveDays[0].id), rule.current_session_id);
  for (let index = 1; index < tailActiveDays.length - 1; index += 1) {
    const nextDayId = String(tailActiveDays[index + 1].id || "");
    const sessionId = originalPrimarySessionByDayId.get(nextDayId) || "";
    if (!sessionId || !db.liveSessions[sessionId]) return safeStop(`tail_session_missing:${nextDayId}`);
    if (ngKnownScheduleSessionHasRecording(db, db.liveSessions[sessionId])) {
      return safeStop(`tail_recorded_session_move_blocked:${sessionId}`);
    }
    selectedSessionByDayId.set(String(tailActiveDays[index].id), sessionId);
  }

  const lastTailDay = tailActiveDays.at(-1);
  const lastOriginalSessionId = originalPrimarySessionByDayId.get(String(lastTailDay.id || "")) || "";
  if (!lastOriginalSessionId || !db.liveSessions[lastOriginalSessionId]) {
    return safeStop(`final_tail_session_missing:${lastTailDay.id}`);
  }
  if (ngKnownScheduleSessionHasRecording(db, db.liveSessions[lastOriginalSessionId])) {
    return safeStop(`final_tail_recorded_session_move_blocked:${lastOriginalSessionId}`);
  }
  const newTailSessionId = uuid();
  db.liveSessions[newTailSessionId] = {
    id: newTailSessionId,
    course_id: rule.course_id,
    created_by: actorId,
    source: "known_missed_holiday_tail_extension",
    created_at: now,
  };
  selectedSessionByDayId.set(String(lastTailDay.id), newTailSessionId);
  result.new_tail_sessions_created = 1;

  const selectedSessionIds = new Set();
  for (const day of roadmap.days) {
    if (!day?.id || ngRoadmapDayIsNoClass(day)) {
      if (day) {
        day.live_session_id = null;
        day.session_id = null;
      }
      continue;
    }
    const sessionId = selectedSessionByDayId.get(String(day.id || ""));
    const session = sessionId ? db.liveSessions[sessionId] : null;
    if (!session?.id) throw new Error(`Known schedule recovery has no preserved classroom for ${day.id}`);
    if (selectedSessionIds.has(String(session.id))) throw new Error(`Known schedule recovery selected classroom ${session.id} twice`);

    const title = ngBuildLiveSessionTitleFromRoadmap(db, roadmap, day);
    const completed = ngKnownScheduleSessionHasRecording(db, session) || String(session.status || "").toLowerCase() === "completed";
    Object.assign(session, {
      course_id: rule.course_id,
      roadmap_day_id: day.id,
      scheduled_date: day.date,
      scheduled_time: ngRoadmapClassTime(roadmap, day),
      scheduled_timezone: ngRoadmapTimezone(roadmap, day),
      title,
      topic: title,
      status: completed ? "completed" : "scheduled",
      day_number: day.day_number || null,
      instructional_day_number: day.instructional_day_number || day.day_number || null,
      system: day.system || day.chapter || session.system || "",
      system_day: day.system_day || day.day_in_system || null,
      archived_from_active: false,
      no_class_placeholder: false,
      cancelled_reason: null,
      updated_by: actorId,
      updated_at: now,
    });
    day.live_session_id = session.id;
    day.session_id = session.id;
    day.updated_by = actorId;
    day.updated_at = now;
    selectedSessionIds.add(String(session.id));
    result.live_sessions_reused_by_date += 1;
  }

  const holidaySession = db.liveSessions[rule.holiday_session_id] || null;
  if (holidaySession) {
    Object.assign(holidaySession, {
      roadmap_day_id: holidayDay.id,
      scheduled_date: holidayDay.date,
      scheduled_time: ngRoadmapClassTime(roadmap, holidayDay),
      scheduled_timezone: ngRoadmapTimezone(roadmap, holidayDay),
      title: "Holiday / No Live Class",
      topic: "Holiday / No Live Class",
      status: "cancelled",
      day_number: null,
      instructional_day_number: null,
      system_day: null,
      cancelled_reason: "roadmap_holiday_2026_07_29",
      archived_from_active: true,
      no_class_placeholder: true,
      updated_by: actorId,
      updated_at: now,
    });
    selectedSessionIds.add(String(holidaySession.id));
  }

  const roadmapDayIds = new Set(roadmap.days.map((day) => String(day?.id || "")).filter(Boolean));
  for (const session of Object.values(db.liveSessions)) {
    if (!session?.id || String(session.course_id || "") !== rule.course_id) continue;
    if (selectedSessionIds.has(String(session.id))) continue;
    if (ngKnownScheduleSessionHasRecording(db, session)) continue;
    if (!roadmapDayIds.has(String(session.roadmap_day_id || ""))) continue;
    session.status = "cancelled";
    session.cancelled_reason = "known_schedule_repair_superseded_session";
    session.archived_from_active = true;
    session.no_class_placeholder = true;
    session.updated_by = actorId;
    session.updated_at = now;
    result.redundant_sessions_archived += 1;
  }

  const activeDayBySessionId = new Map();
  for (const day of roadmap.days) {
    if (!day?.id || ngRoadmapDayIsNoClass(day)) continue;
    activeDayBySessionId.set(String(day.live_session_id || day.session_id || ""), day);
  }
  for (const bucketName of [
    "recordings", "notes", "flashcards", "flashcardProgress", "assessments",
    "assessmentAttempts", "roadmapProgress", "dailyTaskProgress", "pointEvents",
    "weakConceptLogs", "adaptiveAssignments", "adaptiveFlashcardQueues", "attendance",
  ]) {
    for (const item of Object.values(db[bucketName] || {})) {
      if (!item || typeof item !== "object") continue;
      const day = activeDayBySessionId.get(String(item.session_id || item.live_session_id || ""));
      if (!day) continue;
      const itemCourseId = String(item.course_id || item.courseId || "").trim();
      if (itemCourseId && itemCourseId !== rule.course_id) continue;
      item.roadmap_day_id = day.id;
      if (item.day_id) item.day_id = day.id;
      item.updated_by = actorId;
      item.updated_at = now;
    }
  }

  const sequenceMetadataSync = ngSyncRoadmapSequenceMetadata(db, roadmap, { actorId });
  roadmap.days = desiredRoadmapDays;
  const teachingDays = roadmap.days.filter((day) => !ngRoadmapDayIsNoClass(day));
  roadmap.instructional_days = teachingDays.length;
  roadmap.schedule_slots = roadmap.days.length;
  roadmap.settings = roadmap.settings || {};
  roadmap.settings.duration_days = teachingDays.length;
  roadmap.settings.schedule_slots = roadmap.days.length;
  roadmap.updated_by = actorId;
  roadmap.updated_at = now;
  db.roadmaps[roadmapKey] = roadmap;

  const finalHoliday = dayById.get(rule.holiday_day_id);
  const finalTaught = dayById.get(rule.moved_day_id);
  const finalCurrent = mskRows[4].day;
  const recordingAfter = db.recordings[rule.recording_key] || null;
  const attachmentAfter = ngKnownScheduleRecordingAttachment(recordingAfter || {});
  const finalTaughtSession = db.liveSessions[rule.taught_session_id] || null;
  const finalCurrentSession = db.liveSessions[rule.current_session_id] || null;
  const preservedSessionIds = originalSessionIds.every((id) => Boolean(db.liveSessions[id]));
  const preservedSessionUrls = originalSessionIds.every((id) => (
    sameSnapshot(originalSessionSnapshots.get(id), identityAndUrls(db.liveSessions[id]))
  ));
  const preservedRecordings = Array.from(originalRecordingSnapshots.entries()).every(([id, snapshot]) => (
    Boolean(db.recordings[id]) && sameSnapshot(snapshot, identityAndUrls(db.recordings[id]))
  ));
  const preservedRoadmapDays = originalRoadmapDayIds.length === roadmap.days.length &&
    originalRoadmapDayIds.every((id) => roadmap.days.some((day) => String(day?.id || "") === id));
  const protectedCountsPreserved = protectedBuckets.every((name) => (
    Object.keys(db[name] || {}).length >= Number(originalCounts[name] || 0)
  ));
  const dateCount = new Set(roadmap.days.map((day) => ngKnownScheduleDate(day.date || day.scheduled_date))).size;
  const checks = {
    july_29_is_holiday: Boolean(finalHoliday && ngKnownScheduleDate(finalHoliday.date) === rule.holiday_date && ngRoadmapDayIsNoClass(finalHoliday)),
    july_30_is_msk_day_4: Boolean(finalTaught && ngKnownScheduleDate(finalTaught.date) === rule.taught_date && ngKnownScheduleIsMskDay(finalTaught, 4)),
    july_30_kept_recorded_session: String(finalTaught?.live_session_id || finalTaught?.session_id || "") === rule.taught_session_id,
    july_30_session_matches_day_4: Boolean(finalTaughtSession && String(finalTaughtSession.roadmap_day_id || "") === rule.moved_day_id && Number(finalTaughtSession.system_day || 0) === 4),
    july_31_is_msk_day_5: Boolean(finalCurrent && ngKnownScheduleDate(finalCurrent.date) === rule.current_date && ngKnownScheduleIsMskDay(finalCurrent, 5)),
    july_31_kept_exact_classroom: Boolean(finalCurrentSession && String(finalCurrentSession.roadmap_day_id || "") === String(finalCurrent?.id || "") && Number(finalCurrentSession.system_day || 0) === 5),
    recording_attachment_preserved: ngKnownScheduleAttachmentsEqual(recordingBefore, attachmentAfter),
    recording_session_preserved: String(recordingAfter?.session_id || "") === rule.taught_session_id,
    all_recording_identities_and_urls_preserved: preservedRecordings,
    all_session_ids_preserved: preservedSessionIds,
    all_session_identities_and_urls_preserved: preservedSessionUrls,
    all_roadmap_day_ids_preserved: preservedRoadmapDays,
    protected_record_counts_not_decreased: protectedCountsPreserved,
    one_schedule_row_per_date: dateCount === roadmap.days.length,
  };
  const failed = Object.entries(checks).filter(([, passed]) => passed !== true).map(([name]) => name);
  if (failed.length) {
    const diagnostic = {
      taught: finalTaught ? {
        id: finalTaught.id,
        date: finalTaught.date,
        system: finalTaught.system,
        system_day: finalTaught.system_day,
        session_id: finalTaught.live_session_id || finalTaught.session_id || null,
      } : null,
      current: finalCurrent ? {
        id: finalCurrent.id,
        date: finalCurrent.date,
        system: finalCurrent.system,
        system_day: finalCurrent.system_day,
        session_id: finalCurrent.live_session_id || finalCurrent.session_id || null,
      } : null,
      taught_session: finalTaughtSession ? {
        id: finalTaughtSession.id,
        roadmap_day_id: finalTaughtSession.roadmap_day_id,
        system_day: finalTaughtSession.system_day,
      } : null,
      current_session: finalCurrentSession ? {
        id: finalCurrentSession.id,
        roadmap_day_id: finalCurrentSession.roadmap_day_id,
        system_day: finalCurrentSession.system_day,
      } : null,
      msk_order: roadmap.days
        .filter((day) => ngNormalizeMasterMapSystemName(day?.system || day?.chapter || "") === "MSK")
        .map((day) => ({ id: day.id, date: day.date, system_day: day.system_day, holiday: ngRoadmapDayIsNoClass(day) })),
    };
    throw new Error(`Known MSK holiday transactional recovery verification failed: ${failed.join(", ")}; ${JSON.stringify(diagnostic)}`);
  }

  result.changed = true;
  result.repaired = true;
  result.reason = "repaired_transactionally";
  result.current_system_day = 5;
  result.final_teaching_date = teachingDays.map((day) => ngKnownScheduleDate(day.date)).sort().at(-1) || null;
  result.recording_preserved = true;
  result.recording_session_preserved = true;
  result.session_ids_preserved = true;
  result.session_urls_preserved = true;
  result.roadmap_days_preserved = true;
  result.restored_prefix_days = prefixRows.filter((row) => originalDateByDayId.get(row.day_id) !== row.date).length;
  result.shifted_schedule_metadata = shiftedScheduleMetadata;
  result.sequence_metadata_sync = sequenceMetadataSync;
  result.checks = checks;
  return result;
}

function ngResetObjectByCourse(db, key, courseId, shouldRemove = null) {
  const bucket = db[key] || {};
  let removed = 0;
  for (const [id, item] of Object.entries(bucket)) {
    const itemCourseId = String(item?.course_id || item?.courseId || "");
    const keyMatches = String(id).startsWith(`${courseId}:`) || String(id).includes(`:${courseId}:`);
    const courseMatches = itemCourseId === String(courseId) || keyMatches;
    if (!courseMatches) continue;
    if (typeof shouldRemove === "function" && !shouldRemove(item, id)) continue;
    delete bucket[id];
    removed += 1;
  }
  db[key] = bucket;
  return removed;
}

function ngResetCourseAcademicContent(db, options = {}) {
  const courseId = String(options.courseId || options.course_id || "").trim();
  if (!courseId) return { error: "course_id is required" };

  const counts = {
    roadmap_days_removed: 0,
    live_sessions_removed: 0,
    flashcards_archived: 0,
    assessments_removed: 0,
    daily_task_progress_removed: 0,
    weak_concepts_removed: 0,
    flashcard_progress_removed: 0,
    point_events_removed: 0,
  };

  const roadmap = db.roadmaps?.[courseId] || null;
  const roadmapDayIds = new Set((Array.isArray(roadmap?.days) ? roadmap.days : []).map((day) => String(day.id || "")).filter(Boolean));

  if (options.clearGeneratedLiveSessions !== false || options.clearAllCourseLiveSessions === true) {
    db.liveSessions = db.liveSessions || {};
    for (const [id, session] of Object.entries(db.liveSessions)) {
      const isCourseSession = String(session?.course_id || "") === courseId;
      const isLinkedToRoadmap = session?.roadmap_day_id && roadmapDayIds.has(String(session.roadmap_day_id));
      const isGenerated = isLinkedToRoadmap || String(session?.source || "").includes("roadmap") || String(session?.topic || "").includes("Day ");
      if (isCourseSession && (options.clearAllCourseLiveSessions === true || isGenerated)) {
        delete db.liveSessions[id];
        counts.live_sessions_removed += 1;
      }
    }
  }

  if (options.archiveGeneratedFlashcards !== false || options.archiveAllCourseFlashcards === true) {
    db.flashcards = db.flashcards || {};
    const systemFilter = String(options.system || "").trim();
    for (const card of Object.values(db.flashcards)) {
      if (!card || String(card.course_id || "") !== courseId) continue;
      if (systemFilter && ngNormalizeMasterMapSystemName(card.system || card.topic || "") !== ngNormalizeMasterMapSystemName(systemFilter)) continue;
      const isLinkedToRoadmap = card.roadmap_day_id && roadmapDayIds.has(String(card.roadmap_day_id));
      const isGenerated = isLinkedToRoadmap || /generated|roadmap|weak_area|daily_topic/i.test(String(card.source || card.scope || ""));
      if (options.archiveAllCourseFlashcards === true || isGenerated) {
        card.status = "archived";
        card.is_published = false;
        card.archived_reason = options.reason || "course_academic_reset";
        card.archived_at = nowIso();
        card.updated_by = options.actorId || card.updated_by || null;
        card.updated_at = nowIso();
        counts.flashcards_archived += 1;
      }
    }
  }

  if (options.clearAssessments !== false) {
    counts.assessments_removed = ngResetObjectByCourse(db, "assessments", courseId, (assessment) => {
      return options.clearAllCourseAssessments === true || (assessment?.roadmap_day_id && roadmapDayIds.has(String(assessment.roadmap_day_id))) || /roadmap|marathon|system_end/i.test(String(assessment?.source_type || assessment?.assessment_type || ""));
    });
  }

  if (options.clearProgress !== false) {
    counts.daily_task_progress_removed = ngResetObjectByCourse(db, "dailyTaskProgress", courseId);
    counts.weak_concepts_removed = ngResetObjectByCourse(db, "weakConceptLogs", courseId);
    counts.flashcard_progress_removed = ngResetObjectByCourse(db, "flashcardProgress", courseId);
    counts.point_events_removed = ngResetObjectByCourse(db, "pointEvents", courseId);
  }

  if (options.resetRoadmap === true && db.roadmaps?.[courseId]) {
    counts.roadmap_days_removed = Array.isArray(db.roadmaps[courseId].days) ? db.roadmaps[courseId].days.length : 0;
    delete db.roadmaps[courseId];
  }

  return counts;
}

