async function aylaPublicationResourceSnapshot(db, panel) {
  const storedResources = aylaValues(db, "aylaResources").map((resource) => ({
    id: String(resource.id || ""),
    type: aylaPublicationResourceType(resource),
    exam_track_id: aylaCanonicalExamTrack(resource.examTrackId || resource.exam_track_id || resource.exam),
    title: String(resource.title || resource.bookTitle || resource.provider || "Untitled resource"),
    folder_id: String(resource.folderId || resource.folder_id || resource.sourceData?.folder_id || "") || null,
    folder_name: String(resource.folderName || resource.folder_name || resource.sourceData?.folder_name || "") || null,
    collection_id: String(resource.collectionId || resource.collection_id || resource.sourceData?.collection_id || "") || null,
    source_namespace: String(resource.sourceNamespace || resource.source_namespace || resource.sourceData?.source_namespace || "") || null,
    source_provider: String(resource.provider || resource.sourceProvider || resource.source_provider || "") || null,
    source_bank_collection_key: String(resource.sourceBankCollectionKey || resource.source_bank_collection_key || resource.sourceData?.source_bank_collection_key || "") || null,
    case_count: aylaPublicationResourceType(resource) === "cdm_program" ? 1 : Number(resource.caseCount || resource.case_count || 0),
    step_count: Number(resource.cdmStepCount || resource.cdm_step_count || resource.stepCount || resource.step_count || resource.sourceData?.step_count || 0),
    block_count: Number(resource.blockCount || resource.block_count || resource.sourceData?.block_count || 0),
    approved: resource.approved,
    authorization_status: String(resource.authorizationStatus || resource.authorization_status || "") || null,
    verification_status: String(resource.verificationStatus || resource.verification_status || resource.reviewStatus || resource.review_status || "") || null,
    required_media_missing_count: Number(resource.requiredMediaMissingCount || resource.required_media_missing_count || resource.blockingMediaMissingCount || resource.blocking_media_missing_count || 0),
    media_ambiguous_count: Number(resource.mediaAmbiguousCount || resource.media_ambiguous_count || resource.ambiguousMediaCount || resource.ambiguous_media_count || 0),
    status: resource.status || "active",
  }));
  const vimeoDrafts = aylaValues(db, "aylaVimeoCatalogDrafts");
  const vimeoFolders = aylaValues(db, "aylaVimeoCatalogSources").map((source) => {
    const summary = vimeoCatalogSummary(vimeoDrafts.filter((row) => aylaVimeoCatalogDraftSourceMatches(row, source)));
    return {
      id: String(source.folderId || source.folder_id || ""),
      type: "vimeo_folder",
      exam_track_id: aylaCanonicalExamTrack(source.examTrackId || source.exam_track_id || source.exam),
      title: String(source.folderName || source.folder_name || `Vimeo folder ${source.folderId || source.folder_id || ""}`),
      folder_id: String(source.folderId || source.folder_id || "") || null,
      status: source.enabled === false ? "disabled" : "active",
      video_count: Number(source.folderVideoCount || source.folder_video_count || summary.total || 0),
      review_incomplete_count: Math.max(0, Number(summary.total || 0) - Number(summary.approved || 0)),
      taxonomy_incomplete_count: Number(summary.hierarchyIncomplete || 0),
      missing_from_folder_count: Number(summary.missingFromFolder || 0),
    };
  });
  let qbankCollections = [];
  let publicationRegistryWarning = null;
  if (contentRegistryStatus().configured) {
    try {
      qbankCollections = (await aylaListPublicationPanelContentCollections()).map((collection) => {
        const destinationControls = Array.isArray(collection.destination_controls) ? collection.destination_controls : [];
        const qbankDestinationEnabled = destinationControls.some((control) =>
          String(control.destination || "") === "aylamed_qbank"
          && String(control.destination_scope || "") === ""
          && control.enabled === true);
        const hasQbankDestination = destinationControls.some((control) => String(control.destination || "") === "aylamed_qbank");
        const hasNbmeDestination = destinationControls.some((control) => String(control.destination || "") === "aylamed_nbme");
        return {
          id: String(collection.id || ""),
          type: "qbank_collection",
          exam_track_id: aylaCanonicalExamTrack(collection.exam_track),
          title: String(collection.title || collection.collection_key || "QBank collection"),
          folder_id: String(collection.source_namespace || "") || null,
          folder_name: String(collection.source_namespace || "") || null,
          source_namespace: String(collection.source_namespace || "") || null,
          source_provider: String(collection.source_provider || "") || null,
          source_profile: String(collection.source_profile || "") || null,
          source_year: collection.source_year || null,
          collection_key: String(collection.collection_key || "") || null,
          delivery_channel: aylaQbankCollectionDeliveryChannel(collection, {
            hasQbankDestination,
            hasNbmeDestination,
          }),
          publication_default_enabled: String(collection.status || "") === "approved" && qbankDestinationEnabled,
          destination_controls: destinationControls,
          status: collection.status || "draft",
          question_count: Number(collection.question_count || 0),
          valid_question_count: Number(collection.valid_question_count ?? collection.question_count ?? 0),
          taxonomy_complete_count: Number(collection.taxonomy_complete_count || 0),
          delivery_media_ready_count: Number(collection.delivery_media_ready_count || 0),
          required_media_missing_count: Number(collection.required_media_missing_count || 0),
          media_ambiguous_count: Number(collection.media_ambiguous_count || 0),
        };
      });
    } catch (error) {
      publicationRegistryWarning = {
        code: error.code === "AYLA_PUBLICATION_REGISTRY_TIMEOUT" ? "qbank_registry_timeout" : "qbank_registry_unavailable",
        message: "QBank collections could not be loaded. Exam, video, book and flashcard publication controls remain available.",
      };
    }
  }
  const nativeResources = [...new Map(
    [...storedResources, ...vimeoFolders, ...qbankCollections]
      .filter((resource) => resource.id && resource.exam_track_id && resource.type)
      .map((resource) => [`${resource.exam_track_id}:${resource.type}:${resource.id}`, resource]),
  ).values()];
  const supplementalResources = panel.exams.flatMap((exam) => listAylaExamSupplements(exam.examTrackId)
    .flatMap((supplement) => nativeResources
      .filter((resource) => resource.exam_track_id === supplement.source_exam_track
        && supplement.resource_types.includes(resource.type)
        && (resource.type !== "qbank_collection" || resource.delivery_channel === "qbank"))
      .map((resource) => ({
        ...resource,
        exam_track_id: exam.examTrackId,
        source_exam_track_id: supplement.source_exam_track,
        title: `${resource.title} · ${supplement.label}`,
        supplemental: true,
        scoring_allowed: false,
      }))));
  const availableResources = [...new Map(
    [...nativeResources, ...supplementalResources]
      .map((resource) => [`${resource.exam_track_id}:${resource.type}:${resource.id}`, resource]),
  ).values()];
  return { availableResources, publicationRegistryWarning };
}

app.get("/api/ayla/admin/publication-controls", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const db = await readAylaDb();
    aylaEnsureSeedData(db);
    const panel = buildAylaPublicationControlPanel({
      examControls: aylaValues(db, "aylaExamPublicationControls"),
      resourceControls: aylaValues(db, "aylaResourcePublicationControls"),
    });
    const { availableResources, publicationRegistryWarning } = await aylaPublicationResourceSnapshot(db, panel);
    const publicationGroups = buildAylaCompactPublicationGroups({
      exams: panel.exams,
      resourceControls: panel.resources,
      availableResources,
    });
    return aylaSendOk(res, {
      multiexam_build: AYLA_MULTIEXAM_BUILD,
      ...panel,
      available_resources: availableResources,
      publication_groups: publicationGroups,
      supplements: Object.fromEntries(panel.exams.map((exam) => [exam.examTrackId, listAylaExamSupplements(exam.examTrackId)])),
      publication_registry_warning: publicationRegistryWarning,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to load publication controls");
  }
});

app.put("/api/ayla/admin/publication-controls/exams/:examTrack", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    const result = await mutateAylaDb(async (db) => {
      aylaEnsureSeedData(db);
      const examTrackId = aylaCanonicalExamTrack(req.params.examTrack);
      const id = `AYLA-EXAM-PUBLICATION-${examTrackId}`;
      const existing = aylaGetItem(db, "aylaExamPublicationControls", id) || {};
      const previous = normalizeAylaExamPublicationControl({ examTrackId, ...existing }, existing);
      const control = normalizeAylaExamPublicationControl({
        ...req.body,
        examTrackId,
      }, existing);
      control.updatedAt = aylaNow();
      control.updatedBy = admin.user?.id || admin.method || "admin";
      control.createdAt = existing.createdAt || control.updatedAt;
      aylaSetItem(db, "aylaExamPublicationControls", control);
      const changed = previous.enabled !== control.enabled;
      if (changed) await aylaLog(db, "exam-publication-control", `${examTrackId} master publication ${control.enabled ? "enabled" : "disabled"}`, {
        exam_track_id: examTrackId,
        previous_enabled: previous.enabled,
        enabled: control.enabled,
        resource_states_preserved: true,
        progress_and_history_preserved: true,
        actor: control.updatedBy,
      });
      return { control, changed };
    });
    return aylaSendOk(res, { control: result.control, changed: result.changed, idempotent_replay: !result.changed, resource_states_preserved: true, progress_and_history_preserved: true });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to update exam publication");
  }
});

app.put("/api/ayla/admin/publication-controls/resources/:resourceType/:resourceId", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    const requestedEnabled = req.body.enabled === true || req.body.published === true;
    const requestedType = String(req.params.resourceType || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_");
    const requestedExam = aylaCanonicalExamTrack(req.body.examTrackId || req.body.exam_track_id || req.body.examTrack);
    let validatedGroup = null;
    if (AYLA_PUBLICATION_GROUP_ORDER.includes(requestedType)) {
      const validationDb = await readAylaDb();
      aylaEnsureSeedData(validationDb);
      const validationPanel = buildAylaPublicationControlPanel({
        examControls: aylaValues(validationDb, "aylaExamPublicationControls"),
        resourceControls: aylaValues(validationDb, "aylaResourcePublicationControls"),
      });
      const { availableResources } = await aylaPublicationResourceSnapshot(validationDb, validationPanel);
      validatedGroup = buildAylaCompactPublicationGroups({
        exams: validationPanel.exams,
        resourceControls: validationPanel.resources,
        availableResources,
      }).find((group) => group.exam_track_id === requestedExam
        && group.type === requestedType
        && String(group.resource_id) === String(req.params.resourceId));
      if (requestedEnabled) assertAylaPublicationGroupMutationAllowed(validatedGroup, true);
    }
    const targetResources = validatedGroup?.type === "qbank_collection"
      ? validatedGroup.resources.map((resource) => ({
        resourceType: "qbank_collection",
        resourceId: String(resource.id),
        sourceExamTrackId: validatedGroup.source_exam_track_id || validatedGroup.exam_track_id,
      }))
      : [{
        resourceType: req.params.resourceType,
        resourceId: req.params.resourceId,
        sourceExamTrackId: req.body.sourceExamTrackId || req.body.source_exam_track_id || requestedExam,
      }];
    const actorId = admin.user?.id || admin.method || "admin";
    if (requestedEnabled && validatedGroup?.type === "qbank_collection") {
      // Fail closed while PostgreSQL approval/destination controls are made
      // student-ready. If registry activation fails, these explicit false
      // controls prevent a partially activated bank from leaking through the
      // legacy inherited-default path.
      await mutateAylaDb(async (db) => {
        aylaEnsureSeedData(db);
        for (const target of targetResources) {
          const existing = aylaValues(db, "aylaResourcePublicationControls").find((row) =>
            aylaCanonicalExamTrack(row.examTrackId) === requestedExam
            && String(row.resourceType) === target.resourceType
            && String(row.resourceId) === target.resourceId) || {};
          const control = normalizeAylaResourcePublicationControl({
            ...existing,
            examTrackId: requestedExam,
            resourceType: target.resourceType,
            resourceId: target.resourceId,
            sourceExamTrackId: target.sourceExamTrackId,
            enabled: false,
            note: `Fail-closed activation for ${validatedGroup.title}`,
          }, existing);
          control.updatedAt = aylaNow();
          control.updatedBy = actorId;
          control.createdAt = existing.createdAt || control.updatedAt;
          aylaSetItem(db, "aylaResourcePublicationControls", control);
        }
      });
      for (const target of targetResources) {
        await updateContentCollectionControls({
          collectionId: target.resourceId,
          status: "approved",
          destinations: [{
            destination: "aylamed_qbank",
            destination_scope: "",
            enabled: true,
            settings: { publication_group_id: validatedGroup.resource_id, bank_name: validatedGroup.title },
          }],
          actorId: String(actorId),
        });
      }
    }
    const result = await mutateAylaDb(async (db) => {
      aylaEnsureSeedData(db);
      const controls = [];
      let changed = false;
      for (const target of targetResources) {
        const existing = aylaValues(db, "aylaResourcePublicationControls").find((row) =>
          aylaCanonicalExamTrack(row.examTrackId) === requestedExam
          && String(row.resourceType) === target.resourceType
          && String(row.resourceId) === target.resourceId) || {};
        const previous = Object.keys(existing).length
          ? normalizeAylaResourcePublicationControl(existing, existing)
          : null;
        const control = normalizeAylaResourcePublicationControl({
          ...req.body,
          examTrackId: requestedExam,
          resourceType: target.resourceType,
          resourceId: target.resourceId,
          sourceExamTrackId: target.sourceExamTrackId,
          enabled: requestedEnabled,
        }, existing);
        control.updatedAt = aylaNow();
        control.updatedBy = actorId;
        control.createdAt = existing.createdAt || control.updatedAt;
        aylaSetItem(db, "aylaResourcePublicationControls", control);
        const targetChanged = !previous
          || previous.enabled !== control.enabled
          || JSON.stringify(previous.destinations) !== JSON.stringify(control.destinations);
        changed = changed || targetChanged;
        controls.push(control);
      }
      if (changed) await aylaLog(db, "resource-publication-control", `${requestedType}:${req.params.resourceId} ${requestedEnabled ? "enabled" : "disabled"}`, {
        exam_track_id: requestedExam,
        source_exam_track_id: validatedGroup?.source_exam_track_id || requestedExam,
        resource_type: requestedType,
        resource_id: req.params.resourceId,
        member_resource_ids: targetResources.map((target) => target.resourceId),
        enabled: requestedEnabled,
        actor: actorId,
      });
      return { controls, changed };
    });
    return aylaSendOk(res, {
      control: result.controls[0] || null,
      controls: result.controls,
      changed: result.changed,
      idempotent_replay: !result.changed,
      readiness_gate: validatedGroup ? {
        passed: true,
        group_id: validatedGroup.id,
        bank_name: validatedGroup.title,
        member_count: targetResources.length,
        blockers: [],
      } : null,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to update resource publication");
  }
});

app.post("/api/ayla/pathway-estimate", (req, res) => {
  try {
    const estimate = estimateAylaExamPathway(req.body || {});
    return aylaSendOk(res, { estimate });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 400, error.message || "Failed to estimate the exam pathway");
  }
});

app.post("/api/ayla/pathway-compare", (req, res) => {
  try {
    const pathways = compareAylaExamPathways(req.body || {});
    return aylaSendOk(res, {
      pathways,
      comparisonOnly: true,
      passPrediction: false,
      message: "Compare the workload and tradeoffs for each horizon, then confirm a date only after reviewing verified assessment evidence.",
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 400, error.message || "Failed to compare exam pathways");
  }
});

app.post("/api/ayla/students/:studentId/pathway-estimate", async (req, res) => {
  try {
    const { student, db } = await aylaV189RequireStudent(req, req.params.studentId, "roadmap");
    const questionAttempts = aylaValues(db, "aylaQuestionAttempts")
      .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student, { verifiedOnly: true }))
      .filter(aylaScoredQuestionAttempt);
    const completedQuestionIds = new Set(questionAttempts.map((row) => String(row.resourceId || row.contentQuestionId || row.sourceQuestionId || row.id)));
    const assessmentAttempts = aylaValues(db, "aylaAssessmentAttempts")
      .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student, { verifiedOnly: true }))
      .sort((left, right) => String(right.submittedAt || right.createdAt || "").localeCompare(String(left.submittedAt || left.createdAt || "")));
    const assignedVideos = aylaValues(db, "aylaResourceAssignments")
      .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student) && String(row.category || "").toLowerCase() === "video");
    const completedVideos = assignedVideos.filter((row) => String(row.status || "").toLowerCase() === "completed");
    const assignedReadings = aylaValues(db, "aylaResourceAssignments")
      .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student) && String(row.category || "").toLowerCase() === "reading");
    const completedReadings = assignedReadings.filter((row) => String(row.status || "").toLowerCase() === "completed");
    const verifiedQbankPercent = completedQuestionIds.size
      ? Math.min(100, Math.round((completedQuestionIds.size / 3600) * 100))
      : null;
    const latestAssessment = assessmentAttempts[0] || null;
    const estimateInput = {
      ...student,
      ...req.body,
      examTrackId: aylaCanonicalExamTrack(student.examTrackId || student.exam_track_id || student.exam),
      qbankCompletedPercent: verifiedQbankPercent ?? aylaNumber(student.qbankCompleted, 0),
      lectureCompletedPercent: assignedVideos.length
        ? Math.round((completedVideos.length / assignedVideos.length) * 100)
        : aylaNumber(req.body.lectureCompletedPercent ?? req.body.lecture_completed_percent, 0),
      readingCompletedPercent: assignedReadings.length
        ? Math.round((completedReadings.length / assignedReadings.length) * 100)
        : aylaNumber(req.body.readingCompletedPercent ?? req.body.reading_completed_percent, 0),
      latestAssessmentPercent: latestAssessment
        ? aylaNumber(latestAssessment.scorePercent ?? latestAssessment.score, 0)
        : aylaNumber(student.currentScore, 0),
      baselineVerified: Boolean(latestAssessment || student.serverVerifiedBaseline),
    };
    const pathways = req.body.compare === true
      ? compareAylaExamPathways(estimateInput)
      : [estimateAylaExamPathway(estimateInput)];
    return aylaSendOk(res, {
      studentId: student.id,
      pathways,
      inputEvidence: {
        verifiedQuestionAttempts: questionAttempts.length,
        uniqueVerifiedQuestions: completedQuestionIds.size,
        verifiedAssessmentId: latestAssessment?.id || null,
        assignedVideos: assignedVideos.length,
        completedVideos: completedVideos.length,
        assignedReadings: assignedReadings.length,
        completedReadings: completedReadings.length,
        selfReportedQbankFallback: verifiedQbankPercent === null,
      },
      passPrediction: false,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to estimate the student exam pathway");
  }
});

async function aylaContinuityOwnedContext(req, studentId = "") {
  const auth = await aylaGetAuthenticatedUser(req);
  const student = aylaGetItem(auth.db, "aylaStudents", studentId);
  if (!student) throw Object.assign(new Error("AylaMed student profile not found"), { statusCode: 404 });
  if (!aylaV189StudentOwned(student, auth.user) && auth.user.role !== "admin") {
    throw Object.assign(new Error("This AylaMed student profile does not belong to the signed-in user"), { statusCode: 403 });
  }
  return { ...auth, student };
}

function aylaContinuityTargetContext(db, user, sourceStudent, targetExamTrack) {
  const target = normalizeAylaContinuityExamTrack(targetExamTrack);
  const ownedProfiles = aylaOwnedStudentsForUser(db, user.id);
  const targetStudent = ownedProfiles.find((student) => (
    aylaCanonicalExamTrack(student.examTrackId || student.exam_track_id || student.exam) === target
  )) || null;
  let access = { allowed: false, reason: "no_active_exam_entitlement" };
  if (target) {
    access = resolveAylaExamFeatureEntitlement({
      enrollments: aylaValues(db, "aylaEnrollments"),
      plansById: db.aylaPlans || {},
      userId: user.id,
      requestedExamTrack: target,
      feature: "diagnostic",
      legacyExamTrack: target,
      legacyStudentId: targetStudent?.id || `new:${target}`,
      defaultStudentId: sourceStudent.id,
      enforceStudentScope: true,
    });
  }
  return {
    targetExamTrack: target,
    targetStudent,
    access,
    targetEntitled: access.allowed === true
      && access.explicitly_scoped === true
      && String(access.exam_track_id || "") === String(target || ""),
    targetBaselineVerified: targetStudent?.serverVerifiedBaseline === true,
  };
}

function aylaContinuitySourceCompletion(student = {}, requested = {}) {
  if (student.examCompletionVerifiedAt || student.exam_completion_verified_at) return "verified";
  if (student.examCompletedAt || student.exam_completed_at) return "confirmed";
  const value = String(
    requested.sourceCompletionStatus || requested.source_completion_status || "",
  ).trim().toLowerCase();
  const acknowledged = requested.confirmSourceExamCompleted === true
    || requested.confirm_source_exam_completed === true;
  if (acknowledged && ["confirmed", "completed", "self_reported_completed", "self_reported_passed"].includes(value)) {
    return value;
  }
  return "unconfirmed";
}

function aylaContinuityCarryContext(db, student) {
  const assignments = aylaValues(db, "aylaResourceAssignments")
    .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student));
  const completedDates = new Set(assignments
    .filter((row) => String(row.status || "").toLowerCase() === "completed")
    .map((row) => String(row.completedDate || row.completedAt || row.date || "").slice(0, 10))
    .filter(Boolean));
  const missedDates = new Set(assignments
    .filter((row) => ["missed", "overdue"].includes(String(row.status || "").toLowerCase()))
    .map((row) => String(row.date || row.scheduledDate || row.dueDate || "").slice(0, 10))
    .filter(Boolean));
  const completedMinutes = assignments
    .filter((row) => String(row.status || "").toLowerCase() === "completed")
    .map((row) => aylaNumber(row.actualMinutes || row.durationMinutes || row.minutes, 0))
    .filter((value) => value > 0);
  const revisionItems = aylaValues(db, "aylaRevisionQueue")
    .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student))
    .filter((row) => !["removed", "deleted", "cancelled"].includes(String(row.status || "").toLowerCase()));
  return buildAylaCarryContext({
    sourceStudent: student,
    behaviorEvidence: {
      completedStudyDays: completedDates.size,
      missedStudyDays: missedDates.size,
      averageCompletedMinutes: completedMinutes.length
        ? Math.round(completedMinutes.reduce((sum, value) => sum + value, 0) / completedMinutes.length)
        : 0,
    },
    revisionItems,
  });
}

function aylaContinuityEnrollment(db, user, student) {
  const examTrackId = aylaCanonicalExamTrack(
    student.examTrackId || student.exam_track_id || student.exam,
  );
  return aylaValues(db, "aylaEnrollments")
    .filter((row) => String(row.user_id || row.ayla_user_id || "") === String(user.id))
    .filter((row) => (
      String(row.student_id || row.studentId || "") === String(student.id)
      || aylaCanonicalExamTrack(row.exam_track_id || row.examTrackId || row.exam_track || row.exam) === examTrackId
    ))
    .sort((left, right) => {
      const activeDifference = Number(aylaEnrollmentActive(right)) - Number(aylaEnrollmentActive(left));
      return activeDifference || String(right.updatedAt || right.createdAt || "")
        .localeCompare(String(left.updatedAt || left.createdAt || ""));
    })[0] || null;
}

function aylaContinuityProgressFacts(db, student, now = new Date()) {
  const dateKey = aylaDateOnly(now);
  const weekStart = new Date(now.getTime() - 6 * 86400000).toISOString().slice(0, 10);
  const assignments = aylaValues(db, "aylaResourceAssignments")
    .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student))
    .filter((row) => !["cancelled", "superseded", "abandoned"].includes(String(row.status || "").toLowerCase()));
  const assignmentDate = (row) => String(
    row.date || row.scheduledDate || row.scheduled_date || row.dueDate || row.due_date || "",
  ).slice(0, 10);
  const today = assignments.filter((row) => assignmentDate(row) === dateKey);
  const thisWeek = assignments.filter((row) => {
    const date = assignmentDate(row);
    return date && date >= weekStart && date <= dateKey;
  });
  const completed = (row) => String(row.status || "").toLowerCase() === "completed";
  const assessments = aylaValues(db, "aylaAssessmentAttempts")
    .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student, { verifiedOnly: true }))
    .sort((left, right) => String(left.createdAt || left.submittedAt || "")
      .localeCompare(String(right.createdAt || right.submittedAt || "")));
  const firstScore = assessments.length
    ? aylaNumber(assessments[0].scorePercent ?? assessments[0].score, 0)
    : null;
  const lastScore = assessments.length
    ? aylaNumber(assessments[assessments.length - 1].scorePercent ?? assessments[assessments.length - 1].score, 0)
    : null;
  const estimate = aylaV258TutorPathwayEstimate(db, student, dateKey, {
    assessmentAttempts: [...assessments].reverse(),
  });
  const estimatedRange = Array.isArray(estimate?.workload?.estimatedRangeHours)
    ? estimate.workload.estimatedRangeHours
    : [];
  const weeklyAvailableHours = aylaNumber(estimate?.inputs?.dailyHoursAvailable, 0)
    * aylaNumber(estimate?.inputs?.weeklyStudyDays, 0);
  const readinessDaysLow = weeklyAvailableHours > 0 && estimatedRange.length === 2
    ? Math.max(1, Math.ceil((aylaNumber(estimatedRange[0], 0) / weeklyAvailableHours) * 7))
    : null;
  const readinessDaysHigh = weeklyAvailableHours > 0 && estimatedRange.length === 2
    ? Math.max(readinessDaysLow || 1, Math.ceil((aylaNumber(estimatedRange[1], 0) / weeklyAvailableHours) * 7))
    : null;
  return {
    totalTasksToday: today.length,
    completedTasksToday: today.filter(completed).length,
    minutesRemainingToday: today
      .filter((row) => !completed(row))
      .reduce((sum, row) => sum + aylaNumber(row.durationMinutes || row.minutes, 0), 0),
    plannedTasksThisWeek: thisWeek.length,
    completedTasksThisWeek: thisWeek.filter(completed).length,
    verifiedImprovementPercent: firstScore !== null && lastScore !== null
      ? Math.round((lastScore - firstScore) * 10) / 10
      : null,
    readinessDaysLow,
    readinessDaysHigh,
  };
}

function aylaContinuityPreferenceForStudent(db, student) {
  const row = aylaValues(db, "aylaEngagementPreferences")
    .find((item) => String(item.studentId || item.student_id || "") === String(student.id));
  return normalizeAylaEngagementPreferences(row || {}, {
    timezone: student.timezone || "UTC",
  });
}

function aylaContinuityHandoffView(db, user, sourceStudent, record) {
  const target = aylaContinuityTargetContext(db, user, sourceStudent, record.targetExamTrack);
  const state = buildAylaExamHandoffState({
    sourceExamTrack: record.sourceExamTrack,
    targetExamTrack: record.targetExamTrack,
    sourceCompletionStatus: record.sourceCompletionStatus,
    targetEntitled: target.targetEntitled,
    targetProfileExists: Boolean(target.targetStudent),
    targetBaselineVerified: target.targetBaselineVerified,
  });
  return {
    ...record,
    status: state.state,
    nextAction: state.nextAction,
    targetStudentId: target.targetStudent?.id || record.targetStudentId || null,
    targetEntitled: state.targetEntitled,
    targetBaselineVerified: state.targetBaselineVerified,
    targetRoadmapMayUseCarryContext: state.targetRoadmapMayUseCarryContext,
    sourceScoresCopied: false,
    sourceAnswersCopied: false,
    sourceBaselineCopied: false,
  };
}

function aylaContinuityLatestHandoff(db, user, student) {
  const record = aylaValues(db, "aylaExamHandoffs")
    .filter((row) => String(row.userId || row.user_id || "") === String(user.id))
    .filter((row) => String(row.sourceStudentId || row.source_student_id || "") === String(student.id))
    .sort((left, right) => String(right.updatedAt || right.createdAt || "")
      .localeCompare(String(left.updatedAt || left.createdAt || "")))[0] || null;
  return record ? aylaContinuityHandoffView(db, user, student, record) : null;
}

function aylaContinuityIncomingHandoff(db, user, targetExamTrack) {
  const target = normalizeAylaContinuityExamTrack(targetExamTrack);
  if (!target || !user?.id) return null;
  const records = aylaValues(db, "aylaExamHandoffs")
    .filter((row) => String(row.userId || row.user_id || "") === String(user.id))
    .filter((row) => normalizeAylaContinuityExamTrack(
      row.targetExamTrack || row.target_exam_track,
    ) === target)
    .sort((left, right) => String(right.updatedAt || right.createdAt || "")
      .localeCompare(String(left.updatedAt || left.createdAt || "")));
  for (const record of records) {
    const sourceStudent = aylaGetItem(
      db,
      "aylaStudents",
      record.sourceStudentId || record.source_student_id,
    );
    if (!sourceStudent) continue;
    const view = aylaContinuityHandoffView(db, user, sourceStudent, record);
    if (["target_setup_required", "baseline_required", "activated"].includes(view.status)) {
      return { record, view, sourceStudent };
    }
  }
  return null;
}

function aylaContinuityPrefillTargetSetup(input = {}, incoming = null) {
  if (!incoming?.view || incoming.view.status !== "target_setup_required") {
    return { input: { ...(input || {}) }, appliedFields: [] };
  }
  const behavior = incoming.record?.carryContext?.studyBehavior || {};
  const next = { ...(input || {}) };
  const appliedFields = [];
  const setIfMissing = (field, aliases, value) => {
    const keys = [field, ...aliases];
    const supplied = keys.some((key) => {
      const current = next[key];
      return current !== undefined
        && current !== null
        && (!(Array.isArray(current)) || current.length > 0)
        && String(current).trim() !== "";
    });
    if (supplied || value === undefined || value === null || value === "") return;
    next[field] = value;
    appliedFields.push(field);
  };
  setIfMissing("timezone", [], behavior.timezone);
  setIfMissing("dailyHours", ["daily_hours"], behavior.dailyHours);
  setIfMissing("weeklyStudyDays", ["weekly_study_days"], behavior.weeklyStudyDays);
  setIfMissing("preferredStudyDays", ["preferred_study_days"], behavior.preferredStudyDays);
  setIfMissing("sessionLength", ["session_length"], behavior.sessionLengthMinutes);
  setIfMissing("restDay", ["rest_day"], behavior.restDay);
  next.onboardingPath = "diagnostic_test";
  next.onboarding_path = "diagnostic_test";
  next.incomingHandoffId = incoming.record.id;
  next.incoming_handoff_id = incoming.record.id;
  return { input: next, appliedFields };
}

function aylaContinuityActivatedCarryForStudent(db, student) {
  if (student.serverVerifiedBaseline !== true) return null;
  const examTrack = aylaCanonicalExamTrack(
    student.examTrackId || student.exam_track_id || student.exam,
  );
  const userId = student.ayla_user_id || student.aylaUserId || student.user_id || student.userId;
  const user = aylaSanitizeUser(aylaGetItem(db, "aylaUsers", userId));
  if (!user) return null;
  const incoming = aylaContinuityIncomingHandoff(db, user, examTrack);
  if (!incoming || incoming.view.status !== "activated") return null;
  if (String(incoming.view.targetStudentId || "") !== String(student.id)) return null;
  return {
    handoffId: incoming.record.id,
    sourceExamTrack: incoming.record.sourceExamTrack,
    revisionReferences: Array.isArray(incoming.record.carryContext?.revisionReferences)
      ? incoming.record.carryContext.revisionReferences
      : [],
    sourceScoresCopied: false,
    sourceBaselineCopied: false,
  };
}

function aylaContinuityEngagementForStudent(db, student, now = new Date()) {
  const userId = student.ayla_user_id || student.aylaUserId || student.user_id || student.userId;
  const rawUser = aylaGetItem(db, "aylaUsers", userId);
  if (!rawUser) return null;
  const user = aylaSanitizeUser(rawUser);
  const status = String(user.status || "active").toLowerCase();
  const email = aylaNormalizeEmail(user.email);
  if (["disabled", "deleted", "blocked", "suspended"].includes(status) || !email || !email.includes("@")) {
    return {
      studentId: student.id,
      userId: user.id,
      email: "",
      examTrackId: aylaCanonicalExamTrack(student.examTrackId || student.exam_track_id || student.exam),
      preview: {
        generatedAt: (now instanceof Date ? now : new Date(now)).toISOString(),
        messages: [],
        suppressed: [{
          kind: "all",
          reason: email ? "user_account_inactive" : "valid_email_required",
          messageKey: null,
        }],
      },
    };
  }
  return {
    studentId: student.id,
    userId: user.id,
    email,
    examTrackId: aylaCanonicalExamTrack(student.examTrackId || student.exam_track_id || student.exam),
    preview: buildAylaEngagementMessages({
      now,
      student,
      user,
      enrollment: aylaContinuityEnrollment(db, user, student),
      progress: aylaContinuityProgressFacts(db, student, now),
      handoff: aylaContinuityLatestHandoff(db, user, student),
      preferences: aylaContinuityPreferenceForStudent(db, student),
      deliveries: aylaValues(db, "aylaEngagementDeliveries")
        .filter((row) => String(row.studentId || row.student_id || "") === String(student.id)),
    }),
  };
}

function aylaContinuityEmailEnvironmentEnabled() {
  return String(process.env.AYLA_CONTINUITY_EMAIL_DELIVERY_ENABLED || "false").toLowerCase() === "true";
}

function aylaContinuityEmailRuntimeStatus(db = {}) {
  const provider = ngResolveEmailProvider();
  const runnerEnabled = String(
    process.env.AYLA_CONTINUITY_EMAIL_RUNNER_ENABLED || "false",
  ).toLowerCase() === "true";
  return {
    environment_enabled: aylaContinuityEmailEnvironmentEnabled(),
    setting_enabled: db.aylaSettings?.continuity?.email_delivery_enabled === true,
    provider_configured: Boolean(provider.provider),
    provider: provider.provider || null,
    runner_environment_enabled: runnerEnabled,
    ready: aylaContinuityEmailEnvironmentEnabled()
      && db.aylaSettings?.continuity?.email_delivery_enabled === true
      && Boolean(provider.provider),
  };
}

function aylaContinuityDeliveryFingerprint(message = {}) {
  return crypto.createHash("sha256")
    .update(`${String(message.subject || "")}\u001f${String(message.text || "")}`)
    .digest("hex");
}

async function aylaClaimContinuityDelivery({
  studentId,
  messageKey,
  now = new Date(),
  source = "manual",
} = {}) {
  return mutateAylaDb(async (db) => {
    const runtime = aylaContinuityEmailRuntimeStatus(db);
    if (!runtime.ready) return { claimed: false, reason: "delivery_not_enabled", runtime };
    const student = aylaGetItem(db, "aylaStudents", studentId);
    if (!student) return { claimed: false, reason: "student_not_found", runtime };
    const candidate = aylaContinuityEngagementForStudent(db, student, now);
    const message = candidate?.preview?.messages?.find((row) => String(row.messageKey) === String(messageKey));
    if (!candidate?.email || !message) {
      return { claimed: false, reason: "message_no_longer_eligible", runtime };
    }
    const existing = aylaValues(db, "aylaEngagementDeliveries")
      .find((row) => String(row.messageKey || row.message_key || "") === String(message.messageKey)) || null;
    const existingStatus = String(existing?.status || "").toLowerCase();
    const nowMs = (now instanceof Date ? now : new Date(now)).getTime();
    const activeClaimExpiresAt = new Date(
      existing?.claimExpiresAt || existing?.claim_expires_at || 0,
    ).getTime();
    if (
      ["sent", "delivered"].includes(existingStatus)
      || (existingStatus === "queued" && (
        !Number.isFinite(activeClaimExpiresAt)
        || activeClaimExpiresAt > nowMs
      ))
    ) {
      return { claimed: false, reason: "duplicate_or_active_claim", runtime };
    }
    const attempts = Math.max(0, Number(existing?.attemptCount || existing?.attempt_count || 0));
    if (attempts >= 3) return { claimed: false, reason: "retry_limit_reached", runtime };
    const retryAt = new Date(existing?.nextRetryAt || existing?.next_retry_at || 0).getTime();
    if (Number.isFinite(retryAt) && retryAt > nowMs) {
      return { claimed: false, reason: "retry_backoff", runtime };
    }
    const queuedAt = new Date(nowMs).toISOString();
    const delivery = {
      ...(existing || {}),
      id: existing?.id || aylaId("AYLA-ENG-DEL"),
      userId: candidate.userId,
      studentId: candidate.studentId,
      examTrackId: candidate.examTrackId,
      messageKey: message.messageKey,
      kind: message.kind,
      category: message.category,
      channel: "email",
      localDateKey: message.localDateKey,
      subject: message.subject,
      contentFingerprint: aylaContinuityDeliveryFingerprint(message),
      status: "queued",
      source: String(source || "manual").slice(0, 80),
      attemptCount: attempts + 1,
      queuedAt,
      claimExpiresAt: new Date(nowMs + 30 * 60 * 1000).toISOString(),
      nextRetryAt: null,
      lastError: null,
      createdAt: existing?.createdAt || queuedAt,
      updatedAt: queuedAt,
    };
    aylaSetItem(db, "aylaEngagementDeliveries", delivery);
    return {
      claimed: true,
      runtime,
      deliveryId: delivery.id,
      messageKey: delivery.messageKey,
      to: candidate.email,
      subject: message.subject,
      text: message.text,
      kind: message.kind,
      category: message.category,
    };
  });
}

async function aylaFinalizeContinuityDelivery(deliveryId, {
  sent = false,
  provider = null,
  error = null,
  now = new Date(),
} = {}) {
  return mutateAylaDb(async (db) => {
    const delivery = aylaGetItem(db, "aylaEngagementDeliveries", deliveryId);
    if (!delivery) return null;
    const updatedAt = (now instanceof Date ? now : new Date(now)).toISOString();
    const next = {
      ...delivery,
      status: sent ? "sent" : "failed",
      sentAt: sent ? updatedAt : delivery.sentAt || null,
      failedAt: sent ? null : updatedAt,
      provider: sent ? String(provider?.provider || provider?.id || "email").slice(0, 80) : null,
      providerMessageId: sent
        ? String(provider?.messageId || provider?.id || "").slice(0, 240) || null
        : null,
      lastError: sent ? null : String(error?.message || error || "Email delivery failed").slice(0, 500),
      nextRetryAt: sent ? null : new Date(new Date(updatedAt).getTime() + 2 * 60 * 60 * 1000).toISOString(),
      claimExpiresAt: null,
      updatedAt,
    };
    aylaSetItem(db, "aylaEngagementDeliveries", next);
    return next;
  });
}

async function aylaRunContinuityEngagementCycle({
  dryRun = true,
  studentId = "",
  maxMessages = 100,
  source = "manual",
  now = new Date(),
} = {}) {
  const db = await readAylaDb();
  const runtime = aylaContinuityEmailRuntimeStatus(db);
  const cleanStudentId = String(studentId || "").trim();
  const students = aylaValues(db, "aylaStudents")
    .filter((student) => !cleanStudentId || String(student.id) === cleanStudentId)
    .slice(0, 500);
  const previews = students
    .map((student) => aylaContinuityEngagementForStudent(db, student, now))
    .filter(Boolean);
  const messageRefs = previews
    .flatMap((entry) => (entry.preview.messages || []).map((message) => ({
      studentId: entry.studentId,
      messageKey: message.messageKey,
      kind: message.kind,
      category: message.category,
      subject: message.subject,
    })))
    .slice(0, Math.max(1, Math.min(500, Number(maxMessages) || 100)));
  const summary = {
    dry_run: dryRun === true,
    source,
    generated_at: (now instanceof Date ? now : new Date(now)).toISOString(),
    runtime,
    students_checked: students.length,
    eligible_messages: messageRefs.length,
    claimed: 0,
    sent: 0,
    failed: 0,
    skipped: 0,
    deliveries: [],
  };
  if (dryRun === true) {
    summary.previews = previews.map((entry) => ({
      studentId: entry.studentId,
      examTrackId: entry.examTrackId,
      preview: entry.preview,
    }));
    return summary;
  }
  if (!runtime.ready) {
    return { ...summary, skipped: messageRefs.length, skip_reason: "delivery_not_enabled" };
  }
  for (const ref of messageRefs) {
    const claim = await aylaClaimContinuityDelivery({
      studentId: ref.studentId,
      messageKey: ref.messageKey,
      now,
      source,
    });
    if (!claim.claimed) {
      summary.skipped += 1;
      summary.deliveries.push({
        studentId: ref.studentId,
        messageKey: ref.messageKey,
        status: "skipped",
        reason: claim.reason,
      });
      continue;
    }
    summary.claimed += 1;
    try {
      const provider = await sendEmailMessage({
        to: claim.to,
        subject: claim.subject,
        text: claim.text,
      });
      await aylaFinalizeContinuityDelivery(claim.deliveryId, { sent: true, provider });
      summary.sent += 1;
      summary.deliveries.push({
        studentId: ref.studentId,
        messageKey: ref.messageKey,
        deliveryId: claim.deliveryId,
        status: "sent",
      });
    } catch (error) {
      await aylaFinalizeContinuityDelivery(claim.deliveryId, { sent: false, error });
      summary.failed += 1;
      summary.deliveries.push({
        studentId: ref.studentId,
        messageKey: ref.messageKey,
        deliveryId: claim.deliveryId,
        status: "failed",
        error: String(error.message || "Email delivery failed").slice(0, 300),
      });
    }
  }
  return summary;
}

app.get("/api/ayla/students/:studentId/continuity", async (req, res) => {
  try {
    const auth = await aylaContinuityOwnedContext(req, req.params.studentId);
    const sourceExamTrack = aylaCanonicalExamTrack(
      auth.student.examTrackId || auth.student.exam_track_id || auth.student.exam,
    );
    const suggestedTargetExamTrack = suggestAylaNextExam(sourceExamTrack);
    const handoffs = aylaValues(auth.db, "aylaExamHandoffs")
      .filter((row) => String(row.userId || row.user_id || "") === String(auth.user.id))
      .filter((row) => String(row.sourceStudentId || row.source_student_id || "") === String(auth.student.id))
      .sort((left, right) => String(right.updatedAt || right.createdAt || "")
        .localeCompare(String(left.updatedAt || left.createdAt || "")))
      .map((row) => aylaContinuityHandoffView(auth.db, auth.user, auth.student, row));
    const preferences = aylaContinuityPreferenceForStudent(auth.db, auth.student);
    const deliveries = aylaValues(auth.db, "aylaEngagementDeliveries")
      .filter((row) => String(row.studentId || row.student_id || "") === String(auth.student.id));
    const engagement = buildAylaEngagementMessages({
      student: auth.student,
      user: auth.user,
      enrollment: aylaContinuityEnrollment(auth.db, auth.user, auth.student),
      progress: aylaContinuityProgressFacts(auth.db, auth.student),
      handoff: handoffs[0] || null,
      preferences,
      deliveries,
    });
    return aylaSendOk(res, {
      sourceStudentId: auth.student.id,
      sourceExamTrack,
      suggestedTargetExamTrack,
      supportedTargetExamTracks: Object.keys(AYLA_EXAM_REGISTRY)
        .filter((examTrackId) => examTrackId !== sourceExamTrack),
      handoffs,
      preferences,
      engagementPreview: {
        ...engagement,
        deliveryEnabled: auth.db.aylaSettings?.continuity?.email_delivery_enabled === true,
        previewOnly: true,
      },
      policy: {
        targetEntitlementRequired: true,
        newTargetBaselineRequired: true,
        sourceScoresCopied: false,
        sourceAnswersCopied: false,
        sourceBaselineCopied: false,
        revisionContextReferenceOnly: true,
      },
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

