app.get("/api/ayla/admin/resources/coverage", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const db = await readAylaDb();
    const resources = aylaValues(db, "aylaResources");
    const byType = {};
    const bySystem = {};
    resources.forEach((row) => {
      byType[aylaV189ResourceType(row.type)] = (byType[aylaV189ResourceType(row.type)] || 0) + 1;
      bySystem[row.system || "General"] = (bySystem[row.system || "General"] || 0) + 1;
    });
    const unverified = resources.filter((row) => row.approved === false || !String(row.verificationStatus || "").toLowerCase().includes("verified") && !String(row.verificationStatus || "").toLowerCase().includes("approved"));
    const questionResources = resources.filter((row) => ["external_question", "internal_mcq"].includes(aylaV189ResourceType(row.type)));
    const enrichedQuestions = questionResources.map((row) => aylaV189EnrichResourceMappings(db, row));
    const mappedQuestions = enrichedQuestions.filter((row) => Boolean(row.mappedBookPages || row.mappedBookResourceId || row.mappedVideoResourceId || row.mappedVimeoId || row.mappedVimeoUrl));
    return aylaSendOk(res, { total: resources.length, byType, bySystem, unverified: unverified.length, questionMappings: { total: questionResources.length, mapped: mappedQuestions.length, unmapped: Math.max(0, questionResources.length - mappedQuestions.length) }, missingTypes: ["reading", "vimeo_video", "external_question", "internal_mcq", "flashcard", "assessment"].filter((type) => !byType[type] && !(type === "reading" && byType.book)) });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message);
  }
});

const AYLA_STEP1_PILOT_COLLECTION_NAMESPACE = "uworld-step-1";
const AYLA_STEP1_PILOT_QBANK_DESTINATIONS = Object.freeze([
  "aylamed_qbank",
  "aylamed_roadmap",
  "aylamed_auto_assessment",
  "baseline_diagnostic",
  "revision",
  "flashcards",
]);

function aylaStep1PilotCollectionMatches(collection = {}) {
  const namespace = String(collection.source_namespace || "").toLowerCase();
  if (namespace === AYLA_STEP1_PILOT_COLLECTION_NAMESPACE) return true;
  const label = [
    namespace,
    collection.source_provider,
    collection.collection_title,
    collection.title,
    collection.name,
  ].map((value) => String(value || "").toLowerCase()).join(" ");
  return /\buworld\b/.test(label) && /\bstep[\s_-]*1\b/.test(label);
}

function aylaStep1OwnerApprovedPublicRelease(collection = {}) {
  const controls = Array.isArray(collection.destination_controls)
    ? collection.destination_controls
    : [];
  return AYLA_STEP1_PILOT_QBANK_DESTINATIONS.every((destination) =>
    controls.some((row) =>
      row.destination === destination
      && String(row.destination_scope || "") === ""
      && row.enabled === true
      && row.settings?.authorized_external_release === true
      && row.settings?.published_with_bulk_control === true
      && Boolean(row.settings?.owner_approved_at)));
}

function aylaStep1PilotCollectionNeedsActivation(collection = {}) {
  if (String(collection.status || "") !== "approved") return true;
  // Once an owner-approved, fully gated collection is explicitly released to
  // every required student destination, the private-pilot reconciler must not
  // silently turn that public release off during its next scheduled pass.
  if (aylaStep1OwnerApprovedPublicRelease(collection)) return false;
  const controls = Array.isArray(collection.destination_controls)
    ? collection.destination_controls
    : [];
  return AYLA_STEP1_PILOT_QBANK_DESTINATIONS.some((destination) => {
    const scoped = controls.some((row) =>
      row.destination === destination
      && String(row.destination_scope || "") === AYLA_STEP1_PILOT_DESTINATION_SCOPE
      && row.enabled === true);
    const unsafeUnscoped = controls.some((row) =>
      row.destination === destination
      && String(row.destination_scope || "") === ""
      && row.enabled === true);
    return !scoped || unsafeUnscoped;
  });
}

function aylaStep1PilotCollectionControls() {
  return AYLA_STEP1_PILOT_QBANK_DESTINATIONS.flatMap((destination) => ([
    {
      destination,
      destination_scope: "",
      enabled: false,
      settings: {
        private_pilot_guard: true,
        ordinary_student_delivery: false,
      },
    },
    {
      destination,
      destination_scope: AYLA_STEP1_PILOT_DESTINATION_SCOPE,
      enabled: true,
      settings: {
        private_pilot_guard: true,
        ordinary_student_delivery: false,
        plan_id: AYLA_STEP1_PILOT.planId,
      },
    },
  ]));
}

function aylaPrivatePilotVimeoEmbedDomains() {
  const configured = String(process.env.AYLA_VIMEO_EMBED_ALLOWED_DOMAINS || "")
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean);
  return configured.length
    ? configured
    : [
        "https://paleturquoise-quail-255896.hostingersite.com",
        "https://aylamedapp.com",
        "https://live.nextgenusmlelms.com",
      ];
}

function aylaStep1PilotVimeoNeedsResearch(row = {}) {
  if (!aylaStep1PilotVimeoSourceMatches(row)) return false;
  if (row.folderMembershipStatus === "missing_from_folder") return false;
  if (row.readyForClassification === false || !row.sourceTitle || !row.vimeoId) return false;
  if (String(row.reviewStatus || "").toLowerCase() === "approved") return false;
  const classification = row.classification || {};
  const alreadyWebGrounded = classification.webSearchPerformed === true
    && Array.isArray(classification.evidenceSources)
    && classification.evidenceSources.length > 0;
  if (alreadyWebGrounded) return false;
  return [
    "pending_classification",
    "classification_failed",
    "needs_reapproval",
    "needs_review",
  ].includes(String(row.status || "").toLowerCase())
    || ["pending", "failed", "cancelled"].includes(String(row.classificationStatus || "").toLowerCase());
}

async function aylaQueuePrivatePilotVimeoClassificationRecovery() {
  if (!AYLA_VIMEO_CLASSIFIER_SAFETY_POLICY.scheduledClassificationRetriesEnabled) {
    return {
      eligible: 0,
      queued: 0,
      disabled: true,
      skippedReason: "scheduled_vimeo_classification_retries_disabled",
      safetyBuild: AYLA_VIMEO_CLASSIFIER_SAFETY_BUILD,
    };
  }
  aylaVimeoTaxonomyCache.delete("usmle-step-1");
  if (!isAIConfigured()) {
    return {
      eligible: 0,
      queued: 0,
      skippedReason: getAIConfigError(),
    };
  }
  const db = await readAylaDb();
  const activeDraftIds = new Set(
    aylaValues(db, "aylaVimeoCatalogJobs")
      .filter((row) => ["queued", "running"].includes(String(row.status || "").toLowerCase()))
      .flatMap((row) => Array.isArray(row.draftIds) ? row.draftIds : [])
      .map(String),
  );
  const limit = Math.max(
    1,
    Math.min(100, Number(process.env.AYLA_PRIVATE_PILOT_VIMEO_RECOVERY_BATCH || 50) || 50),
  );
  const candidates = aylaValues(db, "aylaVimeoCatalogDrafts")
    .filter((row) => aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id) === "usmle_step_1")
    .filter(aylaStep1PilotVimeoNeedsResearch)
    .filter((row) => Number(row.privatePilotClassificationRecoveryCount || 0) < 3)
    .filter((row) => !activeDraftIds.has(String(row.id)))
    .sort((left, right) =>
      Number(left.privatePilotClassificationRecoveryCount || 0)
        - Number(right.privatePilotClassificationRecoveryCount || 0)
      || String(left.sourceTitle || "").localeCompare(String(right.sourceTitle || "")))
    .slice(0, limit);
  if (!candidates.length) {
    return { eligible: 0, queued: 0, skippedReason: "no_failed_drafts_need_recovery" };
  }
  const queued = await aylaQueueVimeoCatalogClassification({
    examTrackId: "usmle_step_1",
    drafts: candidates,
    actor: {
      id: "system:private-step1-pilot-activation",
      email: "",
      name: "AylaMed private pilot content activation",
    },
    catalogSourceId: AYLA_STEP1_PILOT_VIMEO_SOURCE_ID,
    trigger: "private_pilot_taxonomy_recovery",
  });
  const failedIds = new Set((queued?.enqueueErrors || []).map((row) => String(row.draftId || "")));
  const queuedIds = new Set(candidates.map((row) => String(row.id)).filter((id) => !failedIds.has(id)));
  if (queuedIds.size) {
    await mutateAylaDb(async (current) => {
      for (const draftId of queuedIds) {
        const draft = aylaGetItem(current, "aylaVimeoCatalogDrafts", draftId);
        if (!draft) continue;
        draft.privatePilotClassificationRecoveryCount = Number(
          draft.privatePilotClassificationRecoveryCount || 0,
        ) + 1;
        draft.privatePilotClassificationRecoveryQueuedAt = aylaNow();
        draft.privatePilotClassificationRecoveryReason = "qbank_taxonomy_now_available";
        draft.updatedAt = aylaNow();
        aylaSetItem(current, "aylaVimeoCatalogDrafts", draft);
      }
    });
  }
  return {
    eligible: candidates.length,
    queued: queued?.queued || 0,
    enqueueErrors: queued?.enqueueErrors?.length || 0,
    jobId: queued?.job?.id || null,
    skippedReason: null,
  };
}

async function ngRunAylaPrivatePilotContentActivation(reason = "startup") {
  if (aylaPrivatePilotContentActivationState.running) {
    return { skipped: true, reason: "already_running" };
  }
  if (ngBackgroundMemoryIsHigh("ayla_private_pilot_content_activation")) {
    const skipped = {
      skipped: true,
      reason: "memory_pressure",
      memory: ngMemoryStatus(),
    };
    aylaPrivatePilotContentActivationState.lastResult = skipped;
    return skipped;
  }
  aylaPrivatePilotContentActivationState.running = true;
  aylaPrivatePilotContentActivationState.lastStartedAt = aylaNow();
  try {
    if (!contentRegistryStatus().configured) {
      const skipped = { skipped: true, reason: "content_registry_not_configured" };
      aylaPrivatePilotContentActivationState.lastResult = skipped;
      return skipped;
    }
    const snapshot = await readAylaDb();
    const cohort = aylaValues(snapshot, "aylaPilotCohorts")
      .filter((row) => row.private === true && String(row.status || "") === "active")
      .filter((row) => aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id) === "usmle_step_1")
      .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0];
    if (!cohort) {
      const skipped = { skipped: true, reason: "no_active_private_step1_pilot" };
      aylaPrivatePilotContentActivationState.lastResult = skipped;
      return skipped;
    }

    const collections = await listContentCollections({
      examTrack: "usmle-step-1",
      limit: 200,
    });
    const namespaceCollections = collections.filter((row) =>
      aylaStep1PilotCollectionMatches(row)
      && Number(row.question_count || 0) > 0);
    const verifiedCollections = namespaceCollections.filter((row) =>
      String(row.source_format || "single_best_answer_v1") === "single_best_answer_v1");
    let collectionsOwnerAuthorized = 0;
    let collectionsActivated = 0;
    for (const collection of verifiedCollections) {
      const rightsAlreadyVerified = ["owned", "licensed", "authorized"].includes(
        String(collection.source_rights_status || "").toLowerCase(),
      );
      const needsActivation = aylaStep1PilotCollectionNeedsActivation(collection);
      if (rightsAlreadyVerified && !needsActivation) continue;
      await updateContentCollectionControls({
        collectionId: collection.id,
        status: "approved",
        destinations: aylaStep1PilotCollectionControls(),
        sourceRightsStatus: AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION.status,
        actorId: AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION.actorId,
      });
      if (!rightsAlreadyVerified) collectionsOwnerAuthorized += 1;
      collectionsActivated += 1;
    }

    const catalog = await getContentQbankCatalog({
      examTrack: "usmle-step-1",
      destination: "aylamed_qbank",
      destinationScope: AYLA_STEP1_PILOT_DESTINATION_SCOPE,
    });
    const qbankQuestionCount = catalog.reduce(
      (sum, row) => sum + Number(row.question_count || 0),
      0,
    );
    let registryFlashcardQuestions = [];
    let registryFlashcardError = null;
    try {
      registryFlashcardQuestions = await listContentRegistryFlashcardQuestions({
        examTrack: "usmle-step-1",
        destinationScope: AYLA_STEP1_PILOT_DESTINATION_SCOPE,
        limit: 100,
        offset: 0,
      });
    } catch (error) {
      registryFlashcardError = String(error.message || error).slice(0, 500);
    }
    const vimeoEmbedDomains = normalizeVimeoEmbedDomains(
      aylaPrivatePilotVimeoEmbedDomains(),
    );
    const vimeoEmbedDomainFingerprint = crypto.createHash("sha256")
      .update(`${AYLA_PRIVATE_PILOT_BUILD}\n${vimeoEmbedDomains.slice().sort().join("\n")}`)
      .digest("hex");
    const privatePilotContentFingerprint = crypto.createHash("sha256")
      .update(JSON.stringify({
        build: AYLA_PRIVATE_PILOT_BUILD,
        cohortId: cohort.id,
        collections: verifiedCollections.map((row) => String(row.id || "")).sort(),
        qbankQuestionCount,
        flashcardQuestionIds: registryFlashcardQuestions
          .map((row) => String(row.id || row.question_id || ""))
          .filter(Boolean)
          .sort(),
        vimeoEmbedDomainFingerprint,
      }))
      .digest("hex");
    const activation = await mutateAylaDb(async (db) => {
      const currentCohort = aylaGetItem(db, "aylaPilotCohorts", cohort.id);
      if (!currentCohort || String(currentCohort.status || "") !== "active") {
        return {
          lecturesApproved: 0,
          flashcardsActivated: 0,
          plansRebuilt: 0,
          pilotDatesAligned: 0,
          lectureErrors: [],
          vimeoIds: [],
        };
      }
      const actor = {
        id: AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION.actorId,
        email: "",
        name: "AylaMed owner-authorized private pilot content activation",
      };
      let flashcardsActivated = 0;
      for (const question of registryFlashcardQuestions) {
        const canonicalSystem = classifyStep1DiagnosticQuestion(question);
        const media = auditDiagnosticQuestionMedia(question);
        if (!canonicalSystem || !media.ready) continue;
        const mappedQuestion = applyDiagnosticSystemOverride(question, canonicalSystem);
        const id = `AYLA-PILOT-FC-${crypto.createHash("sha256")
          .update(`${AYLA_STEP1_PILOT_DESTINATION_SCOPE}:${question.id}`)
          .digest("hex")
          .slice(0, 24)}`;
        const existing = aylaGetItem(db, "aylaResources", id) || {};
        const resource = aylaV189NormalizeResource({
          id,
          type: "flashcard",
          examTrackId: "usmle_step_1",
          title: aylaStudentTaxonomyLabel(
            mappedQuestion.topic_key || mappedQuestion.title,
            "AylaMed QBank recall",
          ),
          system: mappedQuestion.system_key,
          subsystem: aylaStudentTaxonomyLabel(
            mappedQuestion.subsystem_key || mappedQuestion.taxonomy?.subsystem_key,
            "",
          ),
          topic: aylaStudentTaxonomyLabel(
            mappedQuestion.topic_key
              || mappedQuestion.taxonomy?.topic_key
              || mappedQuestion.title,
            "QBank recall",
          ),
          subtopic: aylaStudentTaxonomyLabel(
            mappedQuestion.subtopic_key || mappedQuestion.taxonomy?.subtopic_key,
            "",
          ),
          front: flashcardTextOnlyHtml(mappedQuestion.question_html),
          back: flashcardTextOnlyHtml(mappedQuestion.correct_answer_html),
          explanation: flashcardTextOnlyHtml(mappedQuestion.explanation_html),
          media: [],
          videos: [],
          mediaOmittedForFlashcard: true,
          provider: "AylaMed QBank",
          sourceLabel: "AylaMed QBank",
          sourceLabelVisible: true,
          sourceType: "content_registry_flashcard",
          scope: "published_bank",
          bucket: "published_bank",
          readOnly: true,
          answerMode: "reveal_only",
          estimatedMinutes: 1,
          approved: true,
          status: "active",
          verificationStatus: "approved_content_registry",
          authorizationStatus: "approved_registry_collection",
          ownerAuthorization: AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION,
          sourceAccessMode: "protected",
          accessScope: "private_pilot",
          pilotOnly: true,
          pilotCohortId: currentCohort.id,
          pilotStudentIds: [...new Set(currentCohort.studentIds || [])],
        }, existing);
        if (!resource.front || !resource.back) continue;
        resource.accessScope = "private_pilot";
        resource.pilotOnly = true;
        resource.pilotCohortId = currentCohort.id;
        resource.pilotStudentIds = [...new Set(currentCohort.studentIds || [])];
        aylaSetItem(db, "aylaResources", resource);
        if (!existing.id) flashcardsActivated += 1;
      }
      const readyForManualVimeoReview = aylaValues(db, "aylaVimeoCatalogDrafts")
        .filter((row) => aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id) === "usmle_step_1")
        .filter(aylaStep1PilotVimeoSourceMatches)
        .filter((row) => row.folderMembershipStatus !== "missing_from_folder")
        .filter((row) => String(row.reviewStatus || "") !== "approved")
        .filter((row) => row.classification?.approvalReadiness === "ready_for_owner_approval")
        .filter((row) => row.classification?.webSearchPerformed === true)
        .filter((row) => Array.isArray(row.classification?.evidenceSources) && row.classification.evidenceSources.length)
        .slice(0, 100);
      const lecturesReadyForManualReview = readyForManualVimeoReview.length;
      const lecturesApproved = 0;
      const lectureErrors = [];

      const privateLectures = aylaValues(db, "aylaResources")
        .filter((row) => aylaV189ResourceType(row.type) === "vimeo_video")
        .filter(aylaStep1PilotVimeoSourceMatches)
        .filter((row) => row.pilotOnly === true || row.accessScope === "private_pilot")
        .filter((row) =>
          String(row.vimeoEmbedDomainFingerprint || "") !== vimeoEmbedDomainFingerprint)
        .filter((row) => aylaPilotContentVisibleToStudent(row, {
          id: currentCohort.studentIds?.[0],
          pilotTest: true,
          pilotCohortId: currentCohort.id,
        }));
      let plansRebuilt = 0;
      let pilotDatesAligned = 0;
      for (const studentId of currentCohort.studentIds || []) {
        let student = aylaGetItem(db, "aylaStudents", studentId);
        if (!student) continue;
        const beforePilotDate = aylaPilotStudyDate(student);
        const alignedStudent = alignAylaPilotStudyDateToRealDate(student, new Date());
        const afterPilotDate = aylaPilotStudyDate(alignedStudent);
        if (afterPilotDate.dayOffset > beforePilotDate.dayOffset) {
          student = {
            ...alignedStudent,
            updatedAt: aylaNow(),
          };
          aylaSetItem(db, "aylaStudents", student);
          aylaSetItem(db, "aylaPilotAuditEvents", {
            id: aylaId("AYLA-PILOT-EVENT"),
            cohortId: currentCohort.id,
            studentId: student.id,
            action: "pilot_study_date_aligned_to_real_date",
            fromDate: beforePilotDate.date,
            toDate: afterPilotDate.date,
            completedHistoryPreserved: true,
            actorId: actor.id,
            createdAt: aylaNow(),
          });
          pilotDatesAligned += 1;
        }
        const date = aylaV247StudyDate(student);
        const currentPlan = aylaValues(db, "aylaDailyPlans")
          .filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student))
          .filter((row) => String(row.date || "") === String(date))
          .filter((row) => !["cancelled", "superseded"].includes(String(row.status || "").toLowerCase()))
          .sort((left, right) => Number(right.version || 0) - Number(left.version || 0))[0];
        const currentAssignments = currentPlan
          ? aylaValues(db, "aylaResourceAssignments").filter((row) =>
              String(row.dailyPlanId || "") === String(currentPlan.id))
          : [];
        const hasQbank = currentAssignments.some((row) =>
          ["internal_mcq", "internal_mcqs", "qbank"].includes(String(row.category || row.type || "").toLowerCase()));
        const hasVideo = currentAssignments.some((row) =>
          String(row.category || row.type || "").toLowerCase() === "video");
        const hasFlashcards = currentAssignments.some((row) =>
          String(row.category || row.type || "").toLowerCase() === "flashcards");
        const contentNeedsRebuild = collectionsActivated > 0
          || lecturesApproved > 0
          || flashcardsActivated > 0
          || (qbankQuestionCount > 0 && !hasQbank)
          || (privateLectures.length > 0 && !hasVideo)
          || (registryFlashcardQuestions.length > 0 && !hasFlashcards);
        const needsRebuild = contentNeedsRebuild
          && String(student.privatePilotContentActivationFingerprint || "")
            !== privatePilotContentFingerprint;
        if (!contentNeedsRebuild) {
          if (String(student.privatePilotContentActivationFingerprint || "") !== privatePilotContentFingerprint) {
            student.privatePilotContentActivationFingerprint = privatePilotContentFingerprint;
            student.privatePilotContentActivationCheckedAt = aylaNow();
            student.updatedAt = aylaNow();
            aylaSetItem(db, "aylaStudents", student);
          }
          continue;
        }
        if (!needsRebuild) continue;
        const built = await aylaV189BuildDailyPlan(db, student, date, {
          force: true,
          includeAssessment: false,
          skipAi: true,
        });
        student.privatePilotContentActivationFingerprint = privatePilotContentFingerprint;
        student.privatePilotContentActivationCheckedAt = aylaNow();
        student.updatedAt = aylaNow();
        aylaSetItem(db, "aylaStudents", student);
        if (!built.completedHistoryProtected) plansRebuilt += 1;
      }
      aylaSetItem(db, "aylaPilotAuditEvents", {
        id: aylaId("AYLA-PILOT-EVENT"),
        cohortId: currentCohort.id,
        action: "private_step1_content_activation_reconciled",
        actorId: actor.id,
        reason,
        destinationScope: AYLA_STEP1_PILOT_DESTINATION_SCOPE,
        collectionsActivated,
        collectionsOwnerAuthorized,
        ownerAuthorization: AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION,
        qbankQuestionCount,
        lecturesApproved,
        lecturesReadyForManualReview,
        automaticVimeoApprovalEnabled: AYLA_VIMEO_CLASSIFIER_SAFETY_POLICY.automaticApprovalEnabled,
        flashcardsActivated,
        plansRebuilt,
        pilotDatesAligned,
        ordinaryStudentDelivery: false,
        createdAt: aylaNow(),
      });
      return {
        lecturesApproved,
        lecturesReadyForManualReview,
        flashcardsActivated,
        plansRebuilt,
        pilotDatesAligned,
        lectureErrors,
        vimeoIds: [...new Set(privateLectures
          .map((row) => String(row.vimeoId || row.vimeo_id || "").trim())
          .filter(Boolean))],
      };
    });
    let vimeoEmbed = {
      video_count: activation.vimeoIds.length,
      domain_count: 0,
      requested: 0,
      ensured: 0,
      ensured_videos: [],
      failures: [],
    };
    if (activation.vimeoIds.length) {
      try {
        vimeoEmbed = await ensureVimeoEmbedDomains({
          videoIds: activation.vimeoIds,
          domains: vimeoEmbedDomains,
        });
      } catch (error) {
        vimeoEmbed.failures.push({
          video_id: null,
          domain: null,
          status: Number(error.statusCode || 0) || null,
          error: String(error.message || error).slice(0, 500),
        });
      }
    }
    if (vimeoEmbed.verified_videos?.length) {
      const ensuredIds = new Set(vimeoEmbed.verified_videos.map(String));
      const configByVideoId = new Map((vimeoEmbed.video_configs || []).map((row) => [
        String(row.video_id || ""),
        row,
      ]));
      await mutateAylaDb(async (db) => {
        aylaValues(db, "aylaResources")
          .filter((row) => ensuredIds.has(String(row.vimeoId || row.vimeo_id || "")))
          .filter((row) => row.pilotOnly === true || row.accessScope === "private_pilot")
          .forEach((row) => {
            const config = configByVideoId.get(String(row.vimeoId || row.vimeo_id || ""));
            if (config?.embed_url) {
              row.vimeoEmbedUrl = config.embed_url;
              try {
                row.vimeoPrivacyHash = new URL(config.embed_url).searchParams.get("h")
                  || row.vimeoPrivacyHash
                  || "";
              } catch {
                row.vimeoPrivacyHash = row.vimeoPrivacyHash || "";
              }
            }
            row.vimeoEmbedDomainFingerprint = vimeoEmbedDomainFingerprint;
            row.vimeoEmbedDomainsEnsuredAt = aylaNow();
            row.vimeoEmbedPrivacyMode = config?.privacy_embed || "whitelist";
            row.ownerAuthorization = AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION;
            row.updatedAt = aylaNow();
            aylaSetItem(db, "aylaResources", row);
          });
      });
    }
    let classificationRecovery;
    try {
      classificationRecovery = await aylaQueuePrivatePilotVimeoClassificationRecovery();
    } catch (error) {
      classificationRecovery = {
        eligible: 0,
        queued: 0,
        skippedReason: String(error.message || error).slice(0, 500),
      };
    }
    const vimeoEmbedDomainFailureCounts = vimeoEmbed.failures.reduce((summary, row) => {
      const domain = String(row.domain || "(video-level)").trim() || "(video-level)";
      summary[domain] = Number(summary[domain] || 0) + 1;
      return summary;
    }, {});
    const result = {
      skipped: false,
      reason,
      cohortId: cohort.id,
      collectionsMatched: namespaceCollections.length,
      collectionsVerified: verifiedCollections.length,
      collectionsOwnerAuthorized,
      collectionsActivated,
      unverifiedCollectionsSkipped: namespaceCollections.length - verifiedCollections.length,
      ownerAuthorization: AYLA_STEP1_OWNER_CONTENT_AUTHORIZATION,
      qbankQuestionCount,
      lecturesApproved: activation.lecturesApproved,
      lecturesReadyForManualReview: Number(activation.lecturesReadyForManualReview || 0),
      automaticVimeoApprovalEnabled: AYLA_VIMEO_CLASSIFIER_SAFETY_POLICY.automaticApprovalEnabled,
      registryFlashcardQuestions: registryFlashcardQuestions.length,
      flashcardsActivated: activation.flashcardsActivated,
      registryFlashcardError,
      plansRebuilt: activation.plansRebuilt,
      pilotDatesAligned: activation.pilotDatesAligned,
      lectureErrors: activation.lectureErrors.length,
      vimeoEmbedDomainsRequested: normalizeVimeoEmbedDomains(vimeoEmbedDomains),
      vimeoEmbedDomainsEnsured: vimeoEmbed.ensured,
      vimeoEmbedDomainFailures: vimeoEmbed.failures.length,
      vimeoEmbedDomainFailureCounts,
      classificationRecovery,
      destinationScope: AYLA_STEP1_PILOT_DESTINATION_SCOPE,
      ordinaryStudentDelivery: false,
    };
    aylaPrivatePilotContentActivationState.lastResult = result;
    aylaPrivatePilotContentActivationState.lastSuccessAt = aylaNow();
    aylaPrivatePilotContentActivationState.lastError = null;
    return result;
  } catch (error) {
    aylaPrivatePilotContentActivationState.lastError = String(error.message || error).slice(0, 1000);
    throw error;
  } finally {
    aylaPrivatePilotContentActivationState.running = false;
    aylaPrivatePilotContentActivationState.lastFinishedAt = aylaNow();
  }
}

app.get("/api/ayla/admin/pilot/step1/preview", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const db = await readAylaDb();
    aylaEnsureSeedData(db);
    const scenarios = buildAylaStep1PilotScenarios();
    const qbankCollections = await getContentQbankCatalog({
      examTrack: "usmle-step-1",
      destination: "aylamed_qbank",
      destinationScope: AYLA_STEP1_PILOT_DESTINATION_SCOPE,
    }).catch(() => []);
    const lectureDrafts = aylaValues(db, "aylaVimeoCatalogDrafts")
      .filter((row) => aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id || row.examTrack || row.exam_track || row.exam) === "usmle_step_1");
    const isStep1Resource = (row) =>
      aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id || row.examTrack || row.exam_track || row.exam) === "usmle_step_1";
    const approvedLectures = aylaValues(db, "aylaResources")
      .filter((row) => isStep1Resource(row) && aylaV189ResourceType(row.type) === "vimeo_video" && row.approved !== false);
    const approvedBooks = aylaValues(db, "aylaResources")
      .filter((row) => isStep1Resource(row) && ["reading", "book"].includes(aylaV189ResourceType(row.type)) && row.approved !== false);
    return aylaSendOk(res, {
      writePerformed: false,
      confirmationRequired: AYLA_STEP1_PILOT.confirmation,
      plan: {
        id: AYLA_STEP1_PILOT.planId,
        name: "AylaMed Private Step 1 Pilot",
        public: false,
        examTracks: ["usmle_step_1"],
        features: AYLA_STEP1_PILOT.features,
        leaderboard: false,
        studyPartnerDiscovery: false,
      },
      scenarios,
      readiness: {
        qbankCollections: qbankCollections.length,
        qbankCollectionSummaries: qbankCollections.slice(0, 20).map((row) => ({
          id: row.id || row.collection_id || null,
          name: row.name || row.title || row.source || "Step 1 collection",
          source: row.source || row.provider || "",
          questionCount: Number(row.question_count || row.questionCount || row.total_questions || 0),
        })),
        lectureDrafts: lectureDrafts.length,
        lectureClassified: lectureDrafts.filter((row) => String(row.status || "").includes("classified")).length,
        lectureApproved: approvedLectures.length,
        booksApproved: approvedBooks.length,
        stagedLaunch: {
          qbankAndAdaptiveEngine: qbankCollections.length > 0 ? "ready_for_private_pilot" : "blocked_no_approved_qbank_collection",
          lectures: approvedLectures.length > 0 ? "approved_subset_available" : "classification_or_approval_pending",
          books: approvedBooks.length > 0 ? "approved_subset_available" : "exact_page_import_pending",
        },
      },
      safeguards: [
        "Creates AylaMed-only users, students, plans, enrollments, and pilot audit records.",
        "Does not write LMS or CRM student data.",
        "Does not publish any plan or resource to ordinary students.",
        "Does not invent diagnostic scores or completion history.",
        "Does not seed verified weak-area flashcards before a real verified miss.",
        "Pilot students are excluded from leaderboard and partner discovery.",
      ],
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to preview the private Step 1 pilot");
  }
});

app.post("/api/ayla/admin/pilot/step1/cohorts", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    if (String(req.body.confirmation || "") !== AYLA_STEP1_PILOT.confirmation) {
      return aylaSendError(res, 400, `Type "${AYLA_STEP1_PILOT.confirmation}" to create the private pilot cohort`);
    }
    const result = await mutateAylaDb(async (db) => {
      aylaEnsureSeedData(db);
      const anchorDate = aylaDateOnly();
      const cohortKey = `step1-${anchorDate}`;
      const existing = aylaValues(db, "aylaPilotCohorts")
        .find((row) => row.cohortKey === cohortKey && String(row.status || "active") === "active");
      if (existing) {
        return {
          cohort: existing,
          credentials: [],
          alreadyExists: true,
          message: "The active Step 1 pilot cohort already exists. Passwords are intentionally not stored or re-disclosed.",
        };
      }

      const plan = aylaNormalizePlanPayload({
        id: AYLA_STEP1_PILOT.planId,
        name: "AylaMed Private Step 1 Pilot",
        description: "Hidden evaluation access for evidence-based Step 1 onboarding, roadmap, QBank, notes, progress, and approved content testing.",
        plan_type: "pilot",
        billing_type: "free",
        price_cents: 0,
        access_days: 30,
        included_features: AYLA_STEP1_PILOT.features,
        exam_tracks: ["usmle_step_1"],
        is_active: true,
        is_public: false,
        is_featured: false,
      }, aylaGetItem(db, "aylaPlans", AYLA_STEP1_PILOT.planId) || {}, { strictControls: true });
      aylaSetItem(db, "aylaPlans", plan);

      const cohort = {
        id: aylaId("AYLA-PILOT"),
        cohortKey,
        name: "USMLE Step 1 private launch cohort",
        examTrackId: "usmle_step_1",
        planId: plan.id,
        status: "active",
        private: true,
        anchorDate,
        maxSimulatedDays: AYLA_STEP1_PILOT.maxDays,
        studentIds: [],
        userIds: [],
        scenarioKeys: [],
        studentVisibility: false,
        lmsWrites: false,
        crmWrites: false,
        createdBy: admin.user?.id || admin.method || "aylamed-admin",
        createdAt: aylaNow(),
        updatedAt: aylaNow(),
      };
      const credentials = [];

      for (const scenario of buildAylaStep1PilotScenarios(anchorDate)) {
        const email = `step1.${scenario.key}.${anchorDate.replace(/-/g, "")}@pilot.aylamed.local`;
        if (aylaFindUserByEmail(db, email)) {
          throw Object.assign(new Error(`Pilot account already exists for ${scenario.key}`), { statusCode: 409 });
        }
        const password = `Ayla!${crypto.randomBytes(12).toString("base64url")}9`;
        const hashed = hashPassword(password);
        const user = {
          id: aylaId("AYLA-USER"),
          email,
          name: scenario.name,
          phone: "",
          role: "student",
          status: "active",
          studentId: null,
          activeExamTrackId: "usmle_step_1",
          publicUsername: "",
          profileImageUrl: "",
          timezone: scenario.timezone,
          country: "",
          bio: "",
          authVersion: 1,
          pilotTest: true,
          pilot_test: true,
          pilotCohortId: cohort.id,
          excludeFromLeaderboard: true,
          ...hashed,
          createdAt: aylaNow(),
          updatedAt: aylaNow(),
        };
        const examDefinition = AYLA_EXAM_REGISTRY.usmle_step_1;
        const onboarding = normalizeAylaOnboardingSubmission({
          onboardingPath: scenario.onboardingPath,
          studyStage: scenario.onboardingPath === "starting_fresh" ? "not_started" : "first_pass_in_progress",
          selectedWeakAreas: scenario.selectedWeakAreas,
          qbankCompleted: scenario.qbankCompleted || 0,
          qbankAverage: scenario.qbankAverage || 0,
        }, { examDefinition });
        const diagnosticInput = {
          ...scenario,
          ...onboarding,
          aylaUserId: user.id,
          ayla_user_id: user.id,
          user_id: user.id,
          email,
          examTrackId: "usmle_step_1",
          exam: examDefinition.label,
          studentName: scenario.name,
          goalType: "Exam Day",
          preferredStudyDays: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"].slice(0, scenario.weeklyStudyDays),
          studyPartnerOptIn: false,
        };
        const recommendation = aylaRecommendation(diagnosticInput);
        const student = {
          ...aylaStudentFromDiagnostic(diagnosticInput, recommendation),
          ayla_user_id: user.id,
          user_id: user.id,
          pilotTest: true,
          pilot_test: true,
          pilotCohortId: cohort.id,
          pilotScenarioKey: scenario.key,
          pilotIntendedDiagnosticProfile: scenario.diagnosticProfile,
          excludeFromLeaderboard: true,
          studyPartnerOptIn: false,
          examDatePolicy: scenario.examDatePolicy,
          timezonePolicy: scenario.timezonePolicy,
          pilotSimulation: {
            enabled: true,
            anchorDate,
            dayOffset: 0,
            simulatedDate: anchorDate,
            maxAdvanceDays: AYLA_STEP1_PILOT.maxDays,
          },
        };
        user.studentId = student.id;
        aylaSetItem(db, "aylaUsers", user);
        aylaSetItem(db, "aylaStudents", student);

        const submission = {
          ...diagnosticInput,
          id: aylaId("DX"),
          studentId: student.id,
          examTrackId: "usmle_step_1",
          status: onboarding.onboardingStatus === "diagnostic_pending" ? "Diagnostic Pending" : "Received",
          recommendation,
          pilotTest: true,
          createdAt: aylaNow(),
          updatedAt: aylaNow(),
        };
        aylaSetItem(db, "aylaDiagnosticSubmissions", submission);
        const roadmapTasks = aylaBuildRoadmapTasks(student, recommendation);
        aylaV229StoreFutureRoadmapOutline(db, student, roadmapTasks, {
          fromDate: anchorDate,
          reason: `private_pilot_${scenario.key}`,
        });
        const qbankBlock = aylaBuildQbankBlock(student, recommendation, { scheduledDate: anchorDate });
        aylaSetItem(db, "aylaQbankBlocks", qbankBlock);
        aylaBuildWeakAreaLogs(student, recommendation).forEach((row) => aylaSetItem(db, "aylaWeakAreaLogs", row));
        const enrollment = aylaCreateOrUpdateEnrollment(db, {
          userId: user.id,
          plan,
          type: "pilot",
          source: "admin_private_step1_pilot",
          accessGranted: true,
          startsAt: aylaNow(),
          examTrack: "usmle_step_1",
          studentId: student.id,
        });
        aylaSetItem(db, "aylaCommunityProfiles", {
          id: aylaId("AYLA-CP"),
          userId: user.id,
          studentId: student.id,
          username: `Private Pilot ${cohort.studentIds.length + 1}`,
          profileVisibility: "hidden",
          discoverable: false,
          allowRequests: false,
          studyPartnerOptIn: false,
          leaderboardHidden: true,
          banned: false,
          strikes: 0,
          createdAt: aylaNow(),
          updatedAt: aylaNow(),
        });

        cohort.studentIds.push(student.id);
        cohort.userIds.push(user.id);
        cohort.scenarioKeys.push(scenario.key);
        credentials.push({
          scenarioKey: scenario.key,
          name: scenario.name,
          email,
          password,
          studentId: student.id,
          enrollmentId: enrollment.id,
          onboardingPath: scenario.onboardingPath,
          examDate: scenario.examDate || null,
          timezone: scenario.timezone || null,
          dashboardRoute: "/?signin=1",
        });
      }

      aylaSetItem(db, "aylaPilotCohorts", cohort);
      aylaSetItem(db, "aylaPilotAuditEvents", {
        id: aylaId("AYLA-PILOT-EVENT"),
        cohortId: cohort.id,
        action: "private_step1_cohort_created",
        actorId: admin.user?.id || admin.method || "aylamed-admin",
        studentIds: cohort.studentIds,
        studentVisibility: false,
        lmsWrites: false,
        crmWrites: false,
        createdAt: aylaNow(),
      });
      return { cohort, credentials, alreadyExists: false };
    });
    return aylaSendOk(res, {
      ...result,
      credentialDisclosure: result.credentials.length ? "one_time" : "not_repeated",
      message: result.message || "Five private Step 1 pilot students were created. No diagnostic result or completion history was fabricated.",
    }, result.alreadyExists ? 200 : 201);
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to create the private Step 1 pilot cohort");
  }
});

app.post("/api/ayla/admin/pilot/students/:studentId/advance", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    if (String(req.body.confirmation || "") !== String(req.params.studentId)) {
      return aylaSendError(res, 400, "Type the exact pilot student ID to advance its simulated study date");
    }
    const result = await mutateAylaDb(async (db) => {
      const existing = aylaGetItem(db, "aylaStudents", req.params.studentId);
      if (!existing) throw Object.assign(new Error("AylaMed pilot student not found"), { statusCode: 404 });
      const before = aylaPilotStudyDate(existing);
      const student = {
        ...advanceAylaPilotStudyDate(existing, req.body.days || 1),
        updatedAt: aylaNow(),
      };
      const after = aylaPilotStudyDate(student);
      aylaSetItem(db, "aylaStudents", student);
      const built = await aylaV189BuildDailyPlan(db, student, after.date, { force: false });
      const event = {
        id: aylaId("AYLA-PILOT-EVENT"),
        cohortId: student.pilotCohortId,
        studentId: student.id,
        action: "pilot_study_date_advanced",
        days: after.dayOffset - before.dayOffset,
        fromDate: before.date,
        toDate: after.date,
        completedHistoryPreserved: true,
        actorId: admin.user?.id || admin.method || "aylamed-admin",
        createdAt: aylaNow(),
      };
      aylaSetItem(db, "aylaPilotAuditEvents", event);
      return {
        student,
        before,
        after,
        plan: aylaV189SanitizePlanBundle(db, built.plan, built.assignments),
        event,
      };
    });
    return aylaSendOk(res, {
      ...result,
      productionClockChanged: false,
      completedHistoryPreserved: true,
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to advance the pilot study date");
  }
});

function aylaV258PilotFlowRepairPlan(db, cohort) {
  return buildAylaPilotFlowRepairPlan({
    cohort,
    students: aylaValues(db, "aylaStudents"),
    dailyPlans: aylaValues(db, "aylaDailyPlans"),
    assignments: aylaValues(db, "aylaResourceAssignments"),
    revisionQueue: aylaValues(db, "aylaRevisionQueue"),
    qbankSessions: aylaValues(db, "aylaQbankSessions"),
  });
}

function aylaV258SupersedePilotRecord(
  db,
  collection,
  id,
  { actorId, reason },
) {
  const row = aylaGetItem(db, collection, id);
  if (!row) return false;
  const previousStatus = String(row.status || "pending");
  if (["completed", "cancelled", "superseded", "abandoned"].includes(
    previousStatus.toLowerCase(),
  )) return false;
  row.previousStatus = previousStatus;
  row.status = "superseded";
  row.supersededReason = reason;
  row.supersededBy = actorId;
  row.supersededAt = aylaNow();
  row.updatedAt = row.supersededAt;
  aylaSetItem(db, collection, row);
  return true;
}

app.get("/api/ayla/admin/pilot/cohorts/:cohortId/repair-preview", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const db = await readAylaDb();
    const cohort = aylaGetItem(db, "aylaPilotCohorts", req.params.cohortId);
    if (!cohort) return aylaSendError(res, 404, "AylaMed pilot cohort not found");
    const repair = aylaV258PilotFlowRepairPlan(db, cohort);
    return aylaSendOk(res, {
      writePerformed: false,
      repair,
      confirmationRequired: `REPAIR ${cohort.id}`,
      message: repair.blocked
        ? "The preview found a blocker. No pilot record was changed."
        : repair.alreadyApplied
          ? "This exact pilot-flow repair version is already recorded on the cohort."
          : "Preview only. Completed history, attempts, scores, notebooks, payments, LMS and CRM data will be preserved.",
    });
  } catch (error) {
    return aylaSendError(
      res,
      error.statusCode || 500,
      error.message || "Failed to preview the pilot-flow repair",
    );
  }
});

app.post("/api/ayla/admin/pilot/cohorts/:cohortId/repair", async (req, res) => {
  try {
    const admin = await aylaRequireAdmin(req);
    const requiredConfirmation = `REPAIR ${req.params.cohortId}`;
    if (String(req.body.confirmation || "") !== requiredConfirmation) {
      return aylaSendError(
        res,
        400,
        `Type "${requiredConfirmation}" to repair this private pilot cohort`,
      );
    }
    const actorId = admin.user?.id || admin.method || "aylamed-admin";
    const result = await mutateAylaDb(async (db) => {
      const cohort = aylaGetItem(db, "aylaPilotCohorts", req.params.cohortId);
      if (!cohort) {
        throw Object.assign(
          new Error("AylaMed pilot cohort not found"),
          { statusCode: 404 },
        );
      }
      const repair = aylaV258PilotFlowRepairPlan(db, cohort);
      if (!repair.eligible) {
        throw Object.assign(
          new Error(
            repair.blocked === "answered_legacy_diagnostic_requires_manual_review"
              ? "A legacy diagnostic contains answers and must be reviewed manually. No pilot record was changed."
              : "This cohort is not eligible for the private Step 1 pilot-flow repair.",
          ),
          {
            statusCode: 409,
            details: {
              repairVersion: repair.version,
              blocked: repair.blocked,
              counts: repair.counts,
            },
          },
        );
      }
      if (repair.alreadyApplied) {
        return {
          writePerformed: false,
          alreadyApplied: true,
          repair,
          rebuilt: [],
        };
      }

      const reason = AYLA_PILOT_FLOW_REPAIR_VERSION;
      let plansSuperseded = 0;
      let assignmentsSuperseded = 0;
      let diagnosticsSuperseded = 0;
      let revisionsSuperseded = 0;
      let revisionsCanonicalized = 0;

      for (const id of repair.activePlanIds) {
        if (aylaV258SupersedePilotRecord(
          db,
          "aylaDailyPlans",
          id,
          { actorId, reason },
        )) plansSuperseded += 1;
      }
      for (const id of repair.unfinishedAssignmentIds) {
        if (aylaV258SupersedePilotRecord(
          db,
          "aylaResourceAssignments",
          id,
          { actorId, reason },
        )) assignmentsSuperseded += 1;
      }
      for (const id of repair.zeroAnswerInvalidDiagnosticIds) {
        if (aylaV258SupersedePilotRecord(
          db,
          "aylaQbankSessions",
          id,
          { actorId, reason },
        )) diagnosticsSuperseded += 1;
      }

      const revisionSupersedeIds = new Set([
        ...repair.unsafeRevisionIds,
        ...repair.duplicateRevisionIds,
      ]);
      for (const update of repair.canonicalRevisionUpdates) {
        const revision = aylaGetItem(db, "aylaRevisionQueue", update.id);
        if (!revision || revisionSupersedeIds.has(String(update.id))) continue;
        const previousSystem = revision.system || revision.system_key || null;
        revision.system = update.system;
        revision.systemKey = update.system;
        revision.taxonomyRepair = {
          version: reason,
          previousSystem,
          canonicalSystem: update.system,
          actorId,
          repairedAt: aylaNow(),
        };
        revision.updatedAt = aylaNow();
        aylaSetItem(db, "aylaRevisionQueue", revision);
        revisionsCanonicalized += 1;
      }
      for (const id of revisionSupersedeIds) {
        if (aylaV258SupersedePilotRecord(
          db,
          "aylaRevisionQueue",
          id,
          { actorId, reason },
        )) revisionsSuperseded += 1;
      }

      const rebuilt = [];
      for (const studentId of repair.studentIds) {
        const student = aylaGetItem(db, "aylaStudents", studentId);
        if (!student) continue;
        const date = aylaV247StudyDate(student);
        const built = await aylaV189BuildDailyPlan(db, student, date, {
          force: false,
          includeAssessment: false,
          skipAi: true,
        });
        rebuilt.push({
          studentId,
          scenarioKey: student.pilotScenarioKey || null,
          date,
          planId: built.plan?.id || null,
          planReused: built.reused === true,
          completedHistoryProtected: built.completedHistoryProtected === true,
          assignmentCount: built.assignments?.length || 0,
          assignmentCategories: [...new Set(
            (built.assignments || []).map((row) =>
              String(row.category || row.type || "").toLowerCase()),
          )],
          focusSystem: built.plan?.focusSystem
            || built.plan?.systemFocus
            || null,
        });
      }

      cohort.pilotFlowRepairVersion = AYLA_PILOT_FLOW_REPAIR_VERSION;
      cohort.pilotFlowRepairAt = aylaNow();
      cohort.pilotFlowRepairBy = actorId;
      cohort.updatedAt = cohort.pilotFlowRepairAt;
      aylaSetItem(db, "aylaPilotCohorts", cohort);
      const event = {
        id: aylaId("AYLA-PILOT-EVENT"),
        cohortId: cohort.id,
        action: "private_step1_pilot_flow_repaired",
        repairVersion: AYLA_PILOT_FLOW_REPAIR_VERSION,
        actorId,
        plansSuperseded,
        assignmentsSuperseded,
        diagnosticsSuperseded,
        revisionsSuperseded,
        revisionsCanonicalized,
        completedAssignmentsPreserved: repair.counts.completedAssignmentsPreserved,
        questionAttemptsPreserved: true,
        assessmentAttemptsPreserved: true,
        scoresPreserved: true,
        notebooksPreserved: true,
        paymentsUntouched: true,
        lmsUntouched: true,
        crmUntouched: true,
        ordinaryStudentsUntouched: true,
        rebuilt,
        createdAt: aylaNow(),
      };
      aylaSetItem(db, "aylaPilotAuditEvents", event);
      return {
        writePerformed: true,
        alreadyApplied: false,
        repair,
        applied: {
          plansSuperseded,
          assignmentsSuperseded,
          diagnosticsSuperseded,
          revisionsSuperseded,
          revisionsCanonicalized,
        },
        rebuilt,
        event,
      };
    });
    return aylaSendOk(res, result);
  } catch (error) {
    return aylaSendError(
      res,
      error.statusCode || 500,
      error.message || "Failed to repair the private Step 1 pilot flow",
      error.details,
    );
  }
});

app.get("/api/ayla/admin/pilot/cohorts/:cohortId/report", async (req, res) => {
  try {
    await aylaRequireAdmin(req);
    const db = await readAylaDb();
    const cohort = aylaGetItem(db, "aylaPilotCohorts", req.params.cohortId);
    if (!cohort) return aylaSendError(res, 404, "AylaMed pilot cohort not found");
    const students = cohort.studentIds.map((id) => aylaGetItem(db, "aylaStudents", id)).filter(Boolean);
    const report = students.map((student) => {
      const filter = (collection) => aylaValues(db, collection).filter((row) => aylaAdaptiveEvidenceMatchesStudent(row, student));
      const systemProgress = aylaV189SystemProgress(db, student);
      const aylaMedFeed = buildAylaMateActivityFeed({
        student,
        date: aylaV247StudyDate(student),
        systemProgress,
        activityHistory: filter("aylaActivityHistory"),
        questionAttempts: filter("aylaQuestionAttempts").filter(aylaScoredQuestionAttempt),
        flashcardReviews: filter("aylaFlashcardReviews"),
        assessmentAttempts: filter("aylaAssessmentAttempts"),
        resources: aylaValues(db, "aylaResources"),
        revisionQueue: filter("aylaRevisionQueue"),
      });
      return {
        studentId: student.id,
        name: student.name,
        scenarioKey: student.pilotScenarioKey,
        onboardingPath: student.onboardingPath,
        examDate: student.examDate || null,
        timezone: student.timezone || null,
        pilotTime: aylaPilotStudyDate(student),
        counts: {
          dailyPlans: filter("aylaDailyPlans").length,
          assignments: filter("aylaResourceAssignments").length,
          verifiedQuestions: filter("aylaQuestionAttempts").filter((row) => row.serverVerified === true).length,
          assessments: filter("aylaAssessmentAttempts").filter((row) => row.serverVerified === true).length,
          notebooks: filter("aylaNotebooks").length,
          videoProgress: filter("aylaVideoProgress").length,
          readingProgress: filter("aylaReadingProgress").length,
          flashcardReviews: filter("aylaFlashcardReviews").length,
          weakAreaCards: aylaValues(db, "aylaResources").filter((row) => String(row.ownerStudentId || row.studentId || "") === String(student.id) && row.bucket === "weak_area").length,
        },
        systemProgress,
        aylaMedFeed,
        aylaMeFeed: aylaMedFeed,
        aylaMateFeed: aylaMedFeed,
      };
    });
    return aylaSendOk(res, {
      cohort,
      report,
      warnings: {
        noFabricatedHistory: true,
        lectureApprovalPending: !aylaValues(db, "aylaResources").some((row) =>
          aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id || row.examTrack || row.exam_track || row.exam) === "usmle_step_1"
          && aylaV189ResourceType(row.type) === "vimeo_video"
          && row.approved !== false),
        bookImportPending: !aylaValues(db, "aylaResources").some((row) =>
          aylaCanonicalExamTrack(row.examTrackId || row.exam_track_id || row.examTrack || row.exam_track || row.exam) === "usmle_step_1"
          && ["reading", "book"].includes(aylaV189ResourceType(row.type))
          && row.approved !== false),
      },
    });
  } catch (error) {
    return aylaSendError(res, error.statusCode || 500, error.message || "Failed to load the pilot cohort report");
  }
});

